  function interpolerBaremeFraisActe(table, prix) {
    const paliers = Object.keys(table).map(Number).sort((a, b) => a - b);
    if (prix <= paliers[0]) return table[paliers[0]];
    if (prix >= paliers[paliers.length - 1]) return table[paliers[paliers.length - 1]];
    for (let i = 1; i < paliers.length; i++) {
      if (prix <= paliers[i]) {
        const bas = paliers[i - 1], haut = paliers[i];
        const t = (prix - bas) / (haut - bas);
        return table[bas] + (table[haut] - table[bas]) * t;
      }
    }
  }

  // Le calcul de provision, extrait de calculerFraisActe() (qui lit le DOM) pour être réutilisable
  // et testable : le générateur d'appel de fonds s'en sert pour CONTRÔLER le montant de frais
  // annoncé sur un décompte. Une seule formule pour les deux usages — deux copies divergeraient.
  // `eligiblePrimoAccedant` : primo-accédant ET résidence principale, seul cas où la hausse
  // départementale temporaire ne s'applique pas (voir la note affichée sous le simulateur).
  function estimerFraisActe(prix, cleDepartement, typeBien, eligiblePrimoAccedant) {
    const dept = DEPARTEMENTS_FRAIS_ACTE[cleDepartement];
    const bareme = BAREME_FRAIS_ACTE[typeBien];
    const montant = Number(prix);
    if (!dept || !bareme || !Number.isFinite(montant) || montant <= 0) return null;
    const tauxApplique = eligiblePrimoAccedant ? dept.base : dept.temp;
    const emoluments = interpolerBaremeFraisActe(Object.fromEntries(Object.entries(bareme).map(([k, v]) => [k, v[0]])), montant);
    const tresor45 = interpolerBaremeFraisActe(Object.fromEntries(Object.entries(bareme).map(([k, v]) => [k, v[1]])), montant);
    const tresor50 = tresor45 + montant * 0.0051185;
    const tresor = tresor45 + ((tauxApplique - 0.045) / 0.005) * (tresor50 - tresor45);
    return { emoluments, tresor, tauxApplique, total: emoluments + 200 + tresor + 200 };
  }

  function formaterPourcentageFraisActe(x) {
    return (x * 100).toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 5 }) + ' %';
  }

  // Recalculée à chaque changement de champ (voir les attributs oninput/onchange sur
  // #onglet-calculateur dans index.html) — aucune sauvegarde, purement une estimation à la volée.
  function calculerFraisActe() {
    const prixEl = document.getElementById('calc-price');
    const deptEl = document.getElementById('calc-dept');
    const typeEl = document.getElementById('calc-type');
    if (!prixEl || !deptEl || !typeEl || !deptEl.value) return;

    // Le champ part vide (demandé par l'étude) : tant qu'aucun prix n'est saisi, on n'affiche pas
    // un résultat calculé sur une valeur de repli — il aurait l'air d'une vraie provision.
    const prixSaisi = Number(prixEl.value);
    if (!prixEl.value.trim() || !Number.isFinite(prixSaisi) || prixSaisi <= 0) {
      document.getElementById('calc-tag').textContent = '';
      document.getElementById('calc-total').textContent = '—';
      for (const id of ['calc-emol', 'calc-tre', 'calc-total2', 'calc-base-rate', 'calc-applied-rate', 'calc-dmt-rate']) {
        document.getElementById(id).textContent = '—';
      }
      document.getElementById('calc-saving').textContent = '';
      document.getElementById('calc-regime').textContent = 'Saisissez un prix pour obtenir la provision.';
      return;
    }

    // Le mobilier compris dans le prix sort de l'assiette des droits de mutation (art. 735 CGI) :
    // le barème s'applique au seul prix de l'immeuble.
    const mobilierEl = document.getElementById('calc-mobilier');
    const mobilier = mobilierEl ? Number(mobilierEl.value) : 0;
    const prix = assietteImmobiliere(Math.max(1, prixSaisi), mobilier);
    const mobilierDeduit = prix < prixSaisi;
    const primoAccedant = document.querySelector('input[name="calc-first"]:checked').value === 'yes';
    const residencePrincipale = document.querySelector('input[name="calc-rp"]:checked').value === 'yes';
    const type = typeEl.value;
    const dept = DEPARTEMENTS_FRAIS_ACTE[deptEl.value];

    // Hausse temporaire du taux départemental (loi de finances 2025, jusqu'à 5 %) non appliquée au
    // primo-accédant achetant sa résidence principale (art. L. 31-10-3 du CCH) — voir la note
    // affichée sous le résultat.
    const eligiblePrimoAccedant = primoAccedant && residencePrincipale;
    const estimation = estimerFraisActe(prix, deptEl.value, type, eligiblePrimoAccedant);
    if (!estimation) return;
    const { emoluments, tresor, tauxApplique, total } = estimation;
    const dmto = tauxApplique + 0.012 + tauxApplique * 0.0237;

    const libelleType = type === 'house' ? 'Immeuble hors copropriété' : type === 'condo' ? 'Immeuble en copropriété' : 'Terrain à bâtir';
    document.getElementById('calc-tag').textContent = libelleType + ' · ' + (eligiblePrimoAccedant ? 'Primo-accédant éligible' : 'Régime sans exonération de la hausse')
      + (mobilierDeduit ? ' · assiette hors mobilier : ' + formaterPrix(prix) : '');
    document.getElementById('calc-emol').textContent = formaterPrix(emoluments);
    document.getElementById('calc-tre').textContent = formaterPrix(tresor);
    document.getElementById('calc-total2').textContent = formaterPrix(total);
    document.getElementById('calc-total').textContent = formaterPrix(total);
    document.getElementById('calc-base-rate').textContent = formaterPourcentageFraisActe(dept.base);
    document.getElementById('calc-applied-rate').textContent = formaterPourcentageFraisActe(tauxApplique);
    document.getElementById('calc-dmt-rate').textContent = formaterPourcentageFraisActe(dmto);

    const economie = (dept.temp - dept.base) * prix * 1.0237;
    document.getElementById('calc-saving').textContent = (eligiblePrimoAccedant && dept.temp > dept.base)
      ? 'Économie liée à la non-application de la hausse départementale : environ ' + formaterPrix(economie) + '.'
      : '';
    document.getElementById('calc-regime').textContent = eligiblePrimoAccedant
      ? 'Primo-accédant : taux départemental de droit commun ' + formaterPourcentageFraisActe(dept.base) + ' ; la hausse temporaire de ' + formaterPourcentageFraisActe(dept.temp - dept.base) + ' n’est pas appliquée.'
      : 'Taux départemental appliqué : ' + formaterPourcentageFraisActe(dept.temp) + ' au 1er juin 2026.';
  }

  // ==== SIMULATEUR DE PRORATA (taxe foncière, charges de copropriété, loyer) ====
  //
  // Demandé par l'étude : répartir entre vendeur et acquéreur une somme déjà appelée pour une
  // période que la vente coupe en deux. Trois cas, une seule règle de calcul.
  //
  // CONVENTION IMPOSÉE PAR L'ÉTUDE, à ne pas changer sans nouvelle demande explicite :
  //   - jours RÉELS sur la période réelle (365 jours, 366 une année bissextile — pas de mois de
  //     30 jours ni d'année de 360) ;
  //   - le JOUR DE L'ACTE est à la charge de l'ACQUÉREUR. Il compte donc dans sa part.
  // Tout le reste en découle : la part du vendeur est le complément, jamais recalculée à part
  // (sans quoi un arrondi pourrait faire que les deux parts ne totalisent plus la somme appelée).
  //
  // Fonctions pures, déclarées en `function`/`var` : testables depuis tests/helpers/load-app.js.

  // Nombre de jours entre deux dates ISO, bornes comprises. Passe par Date.UTC plutôt que par des
  // dates locales : sur un changement d'heure (fin mars, fin octobre en France), une différence de
  // millisecondes entre deux dates locales ne fait pas un multiple exact de 86 400 000 et le
  // résultat se décalait d'un jour.
  function joursEntre(debutIso, finIso) {
    if (!debutIso || !finIso) return null;
    const a = new Date(debutIso + 'T00:00:00Z');
    const b = new Date(finIso + 'T00:00:00Z');
    if (isNaN(a) || isNaN(b)) return null;
    return Math.round((b - a) / 86400000) + 1;
  }

  // Répartit `montant`, appelé pour la période [debut, fin], entre le vendeur et l'acquéreur à la
  // date de l'acte. Renvoie null si les données ne permettent pas un calcul sûr — jamais un chiffre
  // approximatif : c'est une somme qui sera réclamée à un client.
  function calculerProrata(montant, debutIso, finIso, dateActeIso) {
    const total = Number(montant);
    if (!Number.isFinite(total) || total <= 0) return null;
    const joursPeriode = joursEntre(debutIso, finIso);
    if (!joursPeriode || joursPeriode <= 0) return null;
    // L'acte doit tomber DANS la période : hors d'elle, il n'y a rien à répartir (la somme est
    // entièrement à l'un ou à l'autre), et le signaler vaut mieux que de rendre 0 % ou 100 % comme
    // si le calcul avait un sens.
    if (dateActeIso < debutIso || dateActeIso > finIso) return null;

    // Jour de l'acte inclus dans la part de l'acquéreur : sa période court de la date de l'acte à
    // la fin, bornes comprises.
    const joursAcquereur = joursEntre(dateActeIso, finIso);
    const joursVendeur = joursPeriode - joursAcquereur;
    const partAcquereur = Math.round(total * joursAcquereur / joursPeriode * 100) / 100;
    return {
      total,
      joursPeriode,
      joursVendeur,
      joursAcquereur,
      // Le complément, pas un second arrondi : les deux parts totalisent toujours exactement la
      // somme appelée, ce qu'un double arrondi ne garantirait pas (écart d'un centime).
      partVendeur: Math.round((total - partAcquereur) * 100) / 100,
      partAcquereur,
      pourcentageAcquereur: joursAcquereur / joursPeriode
    };
  }

  // Bornes de la période contenant `dateIso`, pour le découpage choisi. Le dernier jour est calculé
  // en reculant d'un jour depuis le premier jour de la période suivante : la seule façon sûre de
  // tomber juste sur un 28/29 février ou un mois de 30 jours.
  function bornesPeriodeProrata(dateIso, periode) {
    if (!dateIso) return null;
    const d = new Date(dateIso + 'T00:00:00Z');
    if (isNaN(d)) return null;
    const annee = d.getUTCFullYear();
    const mois = d.getUTCMonth();
    let debutMois;
    let nbMois;
    if (periode === 'mois') { debutMois = mois; nbMois = 1; }
    else if (periode === 'trimestre') { debutMois = Math.floor(mois / 3) * 3; nbMois = 3; }
    else { debutMois = 0; nbMois = 12; }
    const debut = new Date(Date.UTC(annee, debutMois, 1));
    const finExclue = new Date(Date.UTC(annee, debutMois + nbMois, 1));
    const fin = new Date(finExclue.getTime() - 86400000);
    const iso = (x) => `${x.getUTCFullYear()}-${pad(x.getUTCMonth() + 1)}-${pad(x.getUTCDate())}`;
    return { debut: iso(debut), fin: iso(fin) };
  }

  function majPeriodeProrata() {
    const dateActe = document.getElementById('prorata-date').value;
    const periode = document.getElementById('prorata-periode').value;
    const bornes = bornesPeriodeProrata(dateActe, periode);
    if (bornes) {
      document.getElementById('prorata-debut').value = bornes.debut;
      document.getElementById('prorata-fin').value = bornes.fin;
    }
    calculerProrataAffichage();
  }

  function calculerProrataAffichage() {
    const montant = parseFloat(document.getElementById('prorata-montant').value);
    const debut = document.getElementById('prorata-debut').value;
    const fin = document.getElementById('prorata-fin').value;
    const dateActe = document.getElementById('prorata-date').value;
    const resultat = calculerProrata(montant, debut, fin, dateActe);
    const bloc = document.getElementById('prorata-resultat');
    const erreur = document.getElementById('prorata-erreur');

    if (!resultat) {
      bloc.style.display = 'none';
      erreur.style.display = 'block';
      erreur.textContent = (dateActe && debut && fin && (dateActe < debut || dateActe > fin))
        ? 'La date de l’acte doit tomber dans la période appelée : hors d’elle, il n’y a rien à répartir.'
        : 'Renseignez un montant, une période et une date d’acte pour obtenir la répartition.';
      return;
    }
    erreur.style.display = 'none';
    bloc.style.display = 'block';

    document.getElementById('prorata-part-acquereur').textContent = formaterPrixCentimes(resultat.partAcquereur);
    document.getElementById('prorata-part-vendeur').textContent = formaterPrixCentimes(resultat.partVendeur);
    document.getElementById('prorata-jours-acquereur').textContent =
      `${resultat.joursAcquereur} jour${resultat.joursAcquereur > 1 ? 's' : ''} sur ${resultat.joursPeriode}`;
    document.getElementById('prorata-jours-vendeur').textContent =
      `${resultat.joursVendeur} jour${resultat.joursVendeur > 1 ? 's' : ''} sur ${resultat.joursPeriode}`;
    // formaterPourcentageFraisActe() attend un RATIO (elle multiplie par 100 elle-même) et va
    // jusqu'à 5 décimales, utile pour un taux fiscal mais bruyant ici : deux décimales suffisent
    // pour une part de période.
    document.getElementById('prorata-pourcentage').textContent =
      (resultat.pourcentageAcquereur * 100).toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
      + ' % de la période à la charge de l’acquéreur';
    document.getElementById('prorata-detail').textContent =
      `${formaterPrixCentimes(resultat.total)} × ${resultat.joursAcquereur} / ${resultat.joursPeriode} jours`;
  }

  // Positionne la date du jour et la période par défaut au premier affichage, puis calcule.
  let prorataInitialise = false;
  function initProrata() {
    if (prorataInitialise) return;
    prorataInitialise = true;
    const champDate = document.getElementById('prorata-date');
    if (champDate && !champDate.value) champDate.value = isoAujourdHui();
    majPeriodeProrata();
  }
  // ==== ARBITRAGE DU FORFAIT MOBILIER (succession) ====
  // Porté d'un artefact fourni par l'étude ("Arbitrage du forfait mobilier"), dont seule la
  // STRUCTURE est reprise : sa palette bordeaux et ses polices (Fraunces/Source Sans/IBM Plex) ont
  // été jetées au profit des jetons et du gabarit déjà en place ici (.calc-card/.calc-champ/
  // .dash-grid, comme le simulateur de provision et le prorata) — même discipline que pour les
  // maquettes précédentes, un seul système visuel dans tout l'outil.
  //
  // Ce que l'outil répond : à défaut d'inventaire ou de prisée, les meubles meublants d'une
  // succession sont évalués à un FORFAIT de 5 % de l'actif successoral (art. 764 du CGI). Un
  // inventaire notarié avec prisée par un commissaire de justice écarte ce forfait — mais il a un
  // coût. La question du client est donc arithmétique : ce que la prisée fait gagner en droits
  // couvre-t-il ce qu'elle coûte ?
  //
  // Décision structurante, reprise telle quelle de l'artefact et à ne PAS défaire : l'outil ne
  // calcule JAMAIS les droits de succession. Le notaire saisit les deux montants qu'il a déjà
  // simulés de son côté. Construire ici un moteur de droits (abattements, tranches, degré de
  // parenté, assurance-vie…) reviendrait à présenter comme fiable un barème que personne n'a
  // audité — c'est exactement la réserve déjà posée sur le simulateur de provision.

  // Les postes du coût, dans l'ordre où ils apparaissent au décompte. AUCUN n'est affiché tant
  // qu'il n'est pas chiffré : tous les dossiers n'ont ni comparant absent ni déplacement, et une
  // ligne « − 0 € » n'apprend rien à personne — c'est aussi ce que dit l'écran de saisie ("les
  // postes laissés vides ne sont pas comptés").
  var LIGNES_COUT_INVENTAIRE = [
    { cle: 'ouverture', label: "Provision — acte d'inventaire" },
    { cle: 'prisee', label: 'Prisée du commissaire de justice, TTC' },
    { cle: 'cloture', label: 'Provision — acte de clôture' },
    { cle: 'serment', label: 'Prestation(s) de serment des absents' },
    { cle: 'trajet', label: 'Frais de trajet' }
  ];

  // Un champ vide n'est pas un zéro : il vaut `null`, ce qui distingue « pas encore renseigné » de
  // « rien à compter ». C'est cette distinction qui permet de ne pas afficher de verdict tant que
  // les deux simulations de droits n'ont pas été saisies.
  function nombreSaisiInventaire(valeur) {
    if (valeur === null || valeur === undefined) return null;
    const texte = String(valeur).trim();
    if (!texte) return null;
    const n = Number(texte.replace(',', '.'));
    return Number.isFinite(n) ? n : null;
  }

  // Aucun montant négatif n'a de sens ici, et un coût négatif gonflerait silencieusement
  // l'économie affichée : on le ramène à zéro plutôt que de le laisser fausser le résultat.
  function montantPositifInventaire(valeur) {
    const n = nombreSaisiInventaire(valeur);
    return n === null ? 0 : Math.max(0, n);
  }

  // Fonction pure (testable) : ne lit aucun champ, ne touche à rien. `saisie` porte des chaînes
  // telles que les rend un <input>, vides comprises.
  function calculerArbitrageInventaire(saisie) {
    const s = saisie || {};
    const droitsSans = nombreSaisiInventaire(s.droitsSans);
    const droitsAvec = nombreSaisiInventaire(s.droitsAvec);
    // Les deux simulations sont indispensables : sans elles il n'y a pas d'économie à comparer au
    // coût, et un verdict rendu sur des champs vides afficherait « non recommandé » sur un écran
    // où personne n'a encore rien saisi.
    const complet = droitsSans !== null && droitsAvec !== null;
    const brutes = complet ? droitsSans - droitsAvec : 0;

    const serment = montantPositifInventaire(s.sermentNb) * montantPositifInventaire(s.sermentUnit);
    const trajet = s.trajetActif
      ? montantPositifInventaire(s.trajetNb) * montantPositifInventaire(s.trajetUnit)
      : 0;
    const montants = {
      ouverture: montantPositifInventaire(s.fraisOuverture),
      prisee: montantPositifInventaire(s.prisee),
      cloture: montantPositifInventaire(s.fraisCloture),
      serment: serment,
      trajet: trajet
    };

    const lignes = LIGNES_COUT_INVENTAIRE
      .filter(l => montants[l.cle] > 0)
      .map(l => ({ cle: l.cle, label: l.label, montant: montants[l.cle] }));
    const cout = lignes.reduce((total, l) => total + l.montant, 0);

    return {
      complet: complet,
      droitsSans: droitsSans === null ? 0 : droitsSans,
      droitsAvec: droitsAvec === null ? 0 : droitsAvec,
      brutes: brutes,
      lignes: lignes,
      cout: cout,
      net: complet ? brutes - cout : 0
    };
  }

  // Trois états, pas deux. L'artefact d'origine n'en avait que deux (favorable / défavorable), ce
  // qui affichait « Non recommandé » sur un formulaire encore vierge — une réponse tranchée à une
  // question que personne n'a posée, contraire à la règle déjà en place sur les deux autres
  // simulateurs ("une valeur pré-remplie se prend pour un résultat"). D'où `indetermine`.
  //
  // Volontairement PAS de quatrième état « marginal » (une économie nette de quelques dizaines
  // d'euros, techniquement positive mais qui ne vaut pas la démarche) : le seuil à partir duquel
  // l'inventaire cesse d'être intéressant est un jugement que l'étude n'a pas donné, l'inventer
  // reviendrait à poser une règle métier de ma propre initiative.
  var VERDICTS_INVENTAIRE = {
    indetermine: {
      libelle: 'À compléter',
      dl: 'dl-neutre',
      message: 'Saisissez les droits de succession simulés dans les deux hypothèses pour obtenir le verdict.'
    },
    defavorable: {
      libelle: 'Non recommandé',
      dl: 'dl-urgent',
      message: "Le coût de l'inventaire atteint ou dépasse l'économie de droits : la démarche ne fait rien gagner au client et ne peut pas être recommandée sur ce seul critère."
    },
    favorable: {
      libelle: 'Intéressant pour le client',
      dl: 'dl-success',
      message: "L'inventaire fait économiser des droits de succession au client, même une fois son coût déduit : la démarche est financièrement intéressante et peut être recommandée."
    }
  };

  function verdictArbitrageInventaire(resultat) {
    const cle = !resultat || !resultat.complet
      ? 'indetermine'
      : (resultat.net > 0 ? 'favorable' : 'defavorable');
    return Object.assign({ cle: cle }, VERDICTS_INVENTAIRE[cle]);
  }

  function lireSaisieInventaire() {
    const val = id => {
      const el = document.getElementById(id);
      return el ? el.value : '';
    };
    const coche = document.getElementById('inv-trajet-actif');
    return {
      dossier: val('inv-dossier'),
      droitsSans: val('inv-droits-sans'),
      droitsAvec: val('inv-droits-avec'),
      fraisOuverture: val('inv-frais-ouverture'),
      prisee: val('inv-prisee'),
      fraisCloture: val('inv-frais-cloture'),
      sermentNb: val('inv-serment-nb'),
      sermentUnit: val('inv-serment-unit'),
      trajetActif: !!(coche && coche.checked),
      trajetNb: val('inv-trajet-nb'),
      trajetUnit: val('inv-trajet-unit')
    };
  }

  function calculerInventaireAffichage() {
    const saisie = lireSaisieInventaire();
    const r = calculerArbitrageInventaire(saisie);
    const v = verdictArbitrageInventaire(r);

    const badge = document.getElementById('inv-verdict-badge');
    if (badge) badge.innerHTML = `<span class="dot-label ${v.dl}"><span class="dot"></span>${escapeHtml(v.libelle)}</span>`;
    const chiffre = document.getElementById('inv-verdict-montant');
    if (chiffre) {
      chiffre.textContent = r.complet ? formaterPrix(r.net) : '—';
      chiffre.classList.toggle('inv-montant-negatif', r.complet && r.net <= 0);
    }
    const texte = document.getElementById('inv-verdict-texte');
    if (texte) texte.textContent = v.message;

    const decompte = document.getElementById('inv-decompte');
    if (decompte) decompte.style.display = r.complet ? '' : 'none';
    if (r.complet) {
      const pose = (id, montant, signe) => {
        const el = document.getElementById(id);
        if (el) el.textContent = (signe || '') + formaterPrix(montant);
      };
      pose('inv-l-droits-sans', r.droitsSans);
      pose('inv-l-droits-avec', r.droitsAvec);
      pose('inv-l-brutes', r.brutes);
      pose('inv-l-cout', r.cout, '− ');
      pose('inv-l-net', r.net);
      const corps = document.getElementById('inv-decompte-cout');
      if (corps) {
        corps.innerHTML = r.lignes
          .map(l => `<tr><td>${escapeHtml(l.label)}</td><td>− ${formaterPrix(l.montant)}</td></tr>`)
          .join('');
      }
    }

    construireNoteInventaire(saisie, r, v);
  }

  // La note imprimable est reconstruite à chaque saisie plutôt qu'au clic sur « Imprimer » : un
  // Ctrl+P direct depuis l'onglet doit sortir la même feuille que le bouton.
  function construireNoteInventaire(saisie, r, v) {
    const cible = document.getElementById('inv-print');
    if (!cible) return;
    if (!r.complet) { cible.innerHTML = ''; return; }
    const titre = (saisie.dossier || '').trim() || 'Succession';
    const lignes = r.lignes
      .map(l => `<tr><td>${escapeHtml(l.label)}</td><td>− ${formaterPrix(l.montant)}</td></tr>`)
      .join('');
    cible.innerHTML = `
      <h1>${escapeHtml(titre)}</h1>
      <p class="inv-print-sous">Note de calcul — arbitrage forfait mobilier / inventaire avec prisée · ${escapeHtml(formatDateFr(isoAujourdHui()))}</p>
      <table>
        <tr><td>Droits de succession sans prisée (forfait mobilier)</td><td>${formaterPrix(r.droitsSans)}</td></tr>
        <tr><td>Droits de succession avec prisée</td><td>${formaterPrix(r.droitsAvec)}</td></tr>
        <tr class="inv-print-total"><td>Économies brutes</td><td>${formaterPrix(r.brutes)}</td></tr>
        ${lignes}
        <tr class="inv-print-total"><td>Économies nettes estimées</td><td>${formaterPrix(r.net)}</td></tr>
      </table>
      <p class="inv-print-verdict"><strong>${escapeHtml(v.libelle)}</strong> — ${escapeHtml(v.message)}</p>
      <p class="inv-print-note">Simulation indicative établie sur la base des éléments saisis. Le forfait mobilier de 5 % (art. 764 du CGI) s'applique à défaut d'inventaire ou de prisée ; il peut être écarté par un inventaire notarié avec prisée par un commissaire de justice. La fourchette de prisée et le nombre de prestations de serment sont à confirmer avant tout conseil au client.</p>`;
  }

  function basculerTrajetsInventaire() {
    const coche = document.getElementById('inv-trajet-actif');
    const bloc = document.getElementById('inv-trajet-champs');
    if (bloc) bloc.style.display = coche && coche.checked ? '' : 'none';
    calculerInventaireAffichage();
  }

  // Coûts de l'inventaire posés d'office, demandé par l'étude : ce sont toujours les mêmes montants
  // d'un dossier à l'autre (on les retouche parfois), les ressaisir à chaque simulation ne sert à
  // rien. Repris de l'artefact d'origine. Les deux simulations de DROITS restent vides, elles :
  // elles changent à chaque succession, et tant qu'elles manquent aucun verdict n'est affiché —
  // la règle « un montant déjà là se prend pour un résultat » continue donc de protéger ce qui
  // décide réellement de la réponse. Les trajets restent décochés (la plupart des dossiers n'en
  // ont pas), le nombre d'un trajet est seulement prêt si on les coche.
  var COUTS_INVENTAIRE_DEFAUT = {
    'inv-frais-ouverture': 300,
    'inv-prisee': 600,
    'inv-frais-cloture': 300,
    'inv-serment-nb': 1,
    'inv-serment-unit': 240,
    'inv-trajet-nb': 1
  };

  // Remet l'écran dans son état de départ : coûts habituels, droits et intitulé vides.
  function reinitialiserInventaire() {
    ['inv-dossier', 'inv-droits-sans', 'inv-droits-avec', 'inv-frais-ouverture', 'inv-prisee',
      'inv-frais-cloture', 'inv-serment-nb', 'inv-serment-unit', 'inv-trajet-nb', 'inv-trajet-unit']
      .forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = Object.prototype.hasOwnProperty.call(COUTS_INVENTAIRE_DEFAUT, id) ? String(COUTS_INVENTAIRE_DEFAUT[id]) : '';
      });
    const coche = document.getElementById('inv-trajet-actif');
    if (coche) coche.checked = false;
    basculerTrajetsInventaire();
  }

  // Premier passage sur l'onglet seulement : le quitter puis y revenir ne doit pas écraser une
  // simulation en cours (même principe que initProrata / initQuotites).
  var inventaireInitialise = false;
  function initInventaire() {
    if (inventaireInitialise) { calculerInventaireAffichage(); return; }
    inventaireInitialise = true;
    reinitialiserInventaire();
  }

  function imprimerNoteInventaire() {
    const r = calculerArbitrageInventaire(lireSaisieInventaire());
    if (!r.complet) {
      afficherToast('Saisissez les droits de succession dans les deux hypothèses avant d\'imprimer la note.', 'OK', null);
      return;
    }
    window.print();
  }

  // ---- Quotités d'acquisition (onglet indépendant, sans enregistrement) ----
  //
  // Porté de l'artefact « Quotité des acquéreurs » fourni par l'étude. Repris : la structure du
  // formulaire (nature du bien, acquéreurs, montant de l'opération, origine du financement) et,
  // MOT POUR MOT, le texte des clauses de l'annexe — c'est le modèle rédactionnel de l'étude, pas
  // à reformuler sans lui (même règle que PROCEDURE_FONDS). Abandonnés : la palette or/crème et les
  // polices de l'artefact (jetons de CLAIRE à la place), et ses montants d'exemple — un formulaire
  // prérempli se prend pour un résultat (même décision que les deux simulateurs voisins).
  //
  // Deux corrections de fond par rapport à l'artefact, toutes deux vérifiées par des tests :
  //   • les proportions sont réparties au plus fort reste (repartirPourcentages) : arrondies
  //     chacune de leur côté, trois tiers donnaient 33,33 % × 3 = 99,99 %, une annexe qui ne
  //     totalise pas 100 % ne se signe pas ;
  //   • un acquéreur qui ne finance rien est SIGNALÉ (sa quotité serait nulle, il n'acquerrait rien
  //     — presque toujours un montant oublié), là où l'artefact l'aurait écrit « 0,00 % » dans l'acte.

  var TYPES_BIEN_QUOTITES = ['immeuble', 'terrain'];

  // Libellés d'opération proposés selon la nature du bien, montants VIDES. « Prorata de taxes
  // foncières » part en mémoire : son montant n'est connu qu'au décompte de la vente.
  function lignesOperationParDefaut(typeBien) {
    const libelles = typeBien === 'terrain'
      ? ["Prix d'acquisition du terrain", 'Coût de la construction', "Frais et droits de l'acte de vente",
        'Frais de dossier bancaire', 'Frais de garantie']
      : ["Prix d'acquisition", "Frais et droits de l'acte de vente", 'Frais de dossier bancaire', 'Frais de garantie'];
    return libelles.map(libelle => ({ libelle, montant: null, memoire: false }))
      .concat([{ libelle: 'Prorata de taxes foncières', montant: null, memoire: true }]);
  }

  function montantQuotite(v) {
    const n = typeof v === 'number' ? v : parseFloat(String(v == null ? '' : v).replace(/\s/g, '').replace(',', '.'));
    return Number.isFinite(n) && n > 0 ? n : 0;
  }

  // Répartit 100 % entre des montants au centième près, par la méthode du plus fort reste : chaque
  // part est tronquée au centième, puis les centièmes manquants vont aux parts dont le reste est le
  // plus grand. Le total vaut toujours exactement 100 dès qu'un montant est positif.
  function repartirPourcentages(montants) {
    const valeurs = (montants || []).map(montantQuotite);
    const total = valeurs.reduce((a, b) => a + b, 0);
    if (!total) return valeurs.map(() => 0);
    const exacts = valeurs.map(v => v / total * 10000);
    const bases = exacts.map(Math.floor);
    let manquants = 10000 - bases.reduce((a, b) => a + b, 0);
    const ordre = exacts.map((e, i) => ({ i, reste: e - bases[i] }))
      .sort((a, b) => b.reste - a.reste || a.i - b.i);
    for (let k = 0; manquants > 0 && k < ordre.length; k++, manquants--) bases[ordre[k].i] += 1;
    return bases.map(b => b / 100);
  }

  function calculerQuotites(etat) {
    const e = etat || {};
    const acquereurs = Array.isArray(e.acquereurs) ? e.acquereurs : [];
    const lignes = Array.isArray(e.lignes) ? e.lignes : [];
    const sources = Array.isArray(e.sources) ? e.sources : [];
    const arrondi = v => Math.round(v * 100) / 100;

    const totalOperation = arrondi(lignes.reduce((s, l) => s + (l.memoire ? 0 : montantQuotite(l.montant)), 0));
    const totalParSource = {};
    sources.forEach(src => {
      totalParSource[src.id] = arrondi(acquereurs.reduce((s, a) => s + montantQuotite((src.montants || {})[a.id]), 0));
    });
    const totaux = acquereurs.map(a =>
      arrondi(sources.reduce((s, src) => s + montantQuotite((src.montants || {})[a.id]), 0)));
    const totalFinancement = arrondi(totaux.reduce((a, b) => a + b, 0));
    const pourcentages = repartirPourcentages(totaux);
    const ecart = arrondi(totalFinancement - totalOperation);

    return {
      totalOperation,
      totalFinancement,
      totalParSource,
      ecart,
      // Tolérance d'un demi-euro, comme l'artefact : au-delà, ce n'est plus un arrondi.
      couvert: totalOperation > 0 && Math.abs(ecart) < 0.5,
      parAcquereur: acquereurs.map((a, i) => ({ id: a.id, total: totaux[i], pourcentage: pourcentages[i] })),
      // Quotité nulle = l'acquéreur n'acquerrait rien. Signalé seulement quand d'autres financent :
      // tant que rien n'est saisi, tout le monde est à zéro et il n'y a rien à dire.
      sansFinancement: totalFinancement > 0 ? acquereurs.filter((a, i) => totaux[i] === 0).map(a => a.id) : []
    };
  }

  function civiliteAbregee(civilite) {
    if (civilite === 'Madame') return 'Mme';
    if (civilite === 'Monsieur') return 'M.';
    return civilite || '';
  }

  function nomAcquereurQuotite(a) {
    return `${civiliteAbregee(a.civilite)} ${String(a.nom || '').trim() || '……………'}`.trim();
  }

  function formaterPourcentageQuotite(p) {
    return new Intl.NumberFormat('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(p || 0) + ' %';
  }

  function phraseQuotitesAcquisition(acquereurs, calcul) {
    const acq = Array.isArray(acquereurs) ? acquereurs : [];
    if (!acq.length) return '';
    if (acq.length === 1) return `${nomAcquereurQuotite(acq[0])} acquiert le bien ci-dessus désigné en pleine propriété.`;
    const parts = acq.map((a, i) => `${formaterPourcentageQuotite(calcul.parAcquereur[i].pourcentage)} pour ${nomAcquereurQuotite(a)}`);
    return `${acq.map(nomAcquereurQuotite).join(' et ')} acquièrent le bien ci-dessus désigné en indivision, savoir : ${parts.join(', ')}.`;
  }

  // Lignes « Origine du financement » telles qu'elles s'écrivent dans l'annexe : un prêt en une
  // ligne (son total), un apport en une ligne PAR acquéreur.
  function lignesFinancementAnnexe(etat, calcul) {
    const lignes = [];
    (etat.sources || []).forEach(src => {
      if (src.type === 'pret') {
        lignes.push({ libelle: `Prêt${src.banque ? ' de ' + src.banque : ''}`, montant: calcul.totalParSource[src.id] || 0 });
      } else {
        (etat.acquereurs || []).forEach(a => {
          lignes.push({ libelle: `Apport personnel de ${nomAcquereurQuotite(a)}`, montant: montantQuotite((src.montants || {})[a.id]) });
        });
      }
    });
    return lignes;
  }

  function libelleSourceTableau(src) {
    if (src.type !== 'pret') return 'Apport personnel';
    return src.banque ? `PRET ${src.banque}` : 'PRET';
  }

  // Clauses de l'annexe, texte repris à l'identique de l'artefact de l'étude. `section` = amorce
  // soulignée suivie d'un tiret, `sous` = sous-titre en italique, `texte` = paragraphe simple.
  function clausesQuotites(etat) {
    const acq = etat.acquereurs || [];
    const indivision = acq.length >= 2;
    const prets = (etat.sources || []).filter(s => s.type === 'pret' && (s.banque || s.numero));
    const c = [];
    if (indivision) {
      if (prets.length) {
        const frag = prets.map(p => `le prêt${p.numero ? ' n°' + p.numero : ''} consenti par ${p.banque || '……………'}`).join(' et ');
        c.push({ type: 'section', amorce: 'Convention des acquéreurs - sort des prêts souscrits', texte: `Les acquéreurs ont convenu de rembourser ${frag} dans les proportions sus indiquées le tout sans que cette clause puisse être opposable au prêteur pour lequel la solidarité entre les emprunteurs a été expressément stipulée aux termes de l'emprunt.` });
      }
      c.push({ type: 'texte', texte: "Les acquéreurs entendent en outre écarter toute présomption de libéralité indirecte, si la contribution effective de chacun des membres du couple ne correspondait pas aux quote-parts indivises, cette différence constituera en toute hypothèse une créance entre eux." });
      c.push({ type: 'texte', texte: "En cas de dérogation à cette convention, il en sera tenu compte le jour de la liquidation de l'indivision ainsi qu'il est dit ci-dessous." });
      c.push({ type: 'texte', texte: "L'assurance décès-invalidité, dans la mesure où elle serait mise en œuvre, profitera en toute hypothèse à l'indivision et ne sera pas constitutive d'une créance." });
    }
    c.push({ type: 'section', amorce: "Prise en charge d'un financement extérieur ultérieur", texte: "En cas de financement extérieur ultérieur pour des travaux, il est conseillé aux acquéreurs d'établir également une convention de ce type afin de prévenir toute difficulté lors de la liquidation de l'indivision. A défaut le financement sera présumé proportionnel aux quotités acquises." });
    c.push({ type: 'section', amorce: "Prise en charge d'un financement personnel ultérieur", texte: "Si l'un des indivisaires améliore l'état du bien indivis, ou si l'indivision retire un profit des dépenses nécessaires à la conservation de l'immeuble réalisées par l'un des indivisaires seul, ou pour un montant supérieur à sa part dans l'immeuble, il lui en sera tenu compte conformément aux dispositions de l'article 815-13 du Code civil." });
    c.push({ type: 'section', amorce: 'Industrie personnelle', texte: "Il est fait observer que l'industrie personnelle des acquéreurs (leur travail) et celle de leurs ayants droit dans les travaux effectués, qu'ils soient d'entretien ou non, ne seront ni cause de créance ni cause d'indemnité." });
    if (indivision) {
      const fraction = acq.length === 2 ? 'à concurrence de la moitié chacun' : 'à parts égales entre eux';
      c.push({ type: 'section', amorce: 'Vie courante', texte: `Les dépenses d'entretien, les charges courantes, les assurances, les impôts locaux, taxes et autres directement liés à l'usage de l'immeuble, seront supportés, au titre de l'obligation à la dette, par les acquéreurs ${fraction}, sauf à tenir compte de la solidarité en matière fiscale. Il sera tenu compte de la contribution effective de chacun d'entre eux lors de la liquidation de l'indivision, à charge pour le demandeur d'en justifier.` });
    }
    c.push({ type: 'section', amorce: 'Répartition lors de la revente', texte: "Il conviendra de distinguer si les sommes empruntées lors de l'acquisition seront ou non remboursées au moment de la revente." });
    c.push({ type: 'sous', texte: "Les sommes empruntées lors de l'acquisition sont remboursées" });
    c.push({ type: 'texte', texte: "La proportion de propriété telle qu'arrêtée entre les indivisaires aux présentes sera celle qui sera utilisée pour la répartition du prix de revente, sous réserve de l'apurement des comptes pouvant exister entre eux." });
    c.push({ type: 'sous', texte: "Les sommes empruntées lors de l'acquisition ne sont pas remboursées" });
    c.push({ type: 'texte', texte: "Avant toute répartition entre les indivisaires, seront prélevés sur le prix de vente : l'impôt sur la plus-value éventuelle, les impôts locaux et taxes exigibles ou à valoir, le solde des sommes empruntées, en capital, intérêts et accessoires, ainsi que les charges de toutes sortes exigibles ou estimées liées au bien indivis et à son utilisation, en ce compris le cas échéant les frais attachés à la radiation des inscriptions." });
    c.push({ type: 'texte', texte: "Le reliquat du prix sera ensuite réparti de la manière suivante." });
    c.push({ type: 'texte', texte: "Chaque indivisaire se verra attribuer une quote-part sur le disponible du prix de revente qui correspondra à son financement réel par rapport au financement global, selon la formule suivante :" });
    c.push({ type: 'texte', texte: "Solde du prix multiplié par Apports personnels + montant des mensualités pris à sa charge divisée par le Total des apports + total des mensualités réglées." });
    c.push({ type: 'texte', texte: "Il est ici précisé qu'en cas de réalisation ultérieure de travaux financés dans des proportions différentes de celles convenues ci-dessus, il devra en être tenu compte dans la répartition du prix." });
    c.push({ type: 'texte', texte: "De même, en cas de modifications des proportions de remboursement d'emprunts, et sous réserve d'en justifier, il devra être tenu compte de la contribution réelle de chacun." });
    c.push({ type: 'section', amorce: 'Répartition lors du partage', texte: "Il conviendra là aussi de distinguer si les sommes empruntées lors de l'acquisition seront ou non remboursées au moment du partage." });
    c.push({ type: 'sous', texte: "Les sommes empruntées lors de l'acquisition sont remboursées" });
    c.push({ type: 'texte', texte: "La proportion de propriété telle qu'arrêtée entre les indivisaires aux présentes sera celle qui sera utilisée par rapport à la valeur du bien au jour du partage pour déterminer la soulte, sous réserve de l'apurement des comptes pouvant exister entre eux." });
    c.push({ type: 'sous', texte: "Les sommes empruntées lors de l'acquisition ne sont pas remboursées" });
    c.push({ type: 'texte', texte: "Avant toute répartition entre les indivisaires, les impôts locaux et taxes exigibles ou à valoir, le solde des sommes empruntées, en capital, intérêts et accessoires, ainsi que les charges de toutes sortes exigibles ou estimées liées au bien indivis et à son utilisation, seront déduits de la valeur du bien indivis au jour de ce partage, en ce compris le cas échéant les frais attachés à la radiation des inscriptions si l'attributaire venait à ne pas reprendre le prêt." });
    c.push({ type: 'texte', texte: "La soulte sera déterminée de la manière suivante." });
    c.push({ type: 'texte', texte: "Chaque indivisaire se verra déterminer sa quote-part sur la valeur du bien indivis qui correspondra à son financement réel par rapport au financement global, selon la formule suivante :" });
    c.push({ type: 'texte', texte: "Valeur nette du bien indivis multipliée par Apports personnels + montant des mensualités pris à sa charge divisée par le Total des apports + total des mensualités réglées." });
    c.push({ type: 'texte', texte: "Il est ici précisé qu'en cas de réalisation ultérieure de travaux financés dans des proportions différentes de celles convenues ci-dessus, il devra en être tenu compte dans la répartition du prix." });
    c.push({ type: 'texte', texte: "De même, en cas de modifications des proportions de remboursement d'emprunts, et sous réserve d'en justifier, il devra être tenu compte de la contribution réelle de chacun." });
    return c;
  }

  // Ce qu'un dossier d'Outil 1 permet de reprendre, et ce qu'il ne dit pas. Les acquéreurs viennent
  // de clientsDepuisDossier (partagée avec l'appel de fonds) ; la civilité n'est jamais lue dans
  // l'acte, elle est donc mise par défaut ET signalée. Le montant du prêt n'est reporté sur un
  // acquéreur que s'il est seul : à plusieurs, sa répartition ne se devine pas.
  function prefillQuotites(d) {
    if (!d) return null;
    const clients = clientsDepuisDossier(d);
    const repris = [];
    const aCompleter = [];
    const acquereurs = clients.map(c => ({
      civilite: c.civilite === 'SCI' ? 'SCI' : 'Monsieur',
      nom: String(c.nom || '').trim()
    }));
    if (acquereurs.length) {
      repris.push(acquereurs.length > 1 ? `${acquereurs.length} acquéreurs` : 'Acquéreur');
      if (clients.some(c => c.aCompleter)) aCompleter.push('Civilité et prénom de chaque acquéreur — l’acte n’en donne que le nom.');
    } else {
      aCompleter.push('Acquéreurs — aucun n’a pu être lu sur ce dossier.');
    }
    const typeBien = d.typeVente === 'terrain' ? 'terrain' : 'immeuble';
    repris.push(typeBien === 'terrain' ? 'Nature du bien : terrain à bâtir' : 'Nature du bien');
    const prix = montantQuotite(d.prixVente);
    if (prix) repris.push('Prix d’acquisition'); else aCompleter.push('Prix d’acquisition.');
    if (typeBien === 'terrain') aCompleter.push('Coût de la construction.');
    aCompleter.push('Frais et droits de l’acte, frais bancaires et de garantie.');

    const montantPret = d.sansPret ? 0 : montantQuotite(d.montantPret);
    if (d.sansPret) repris.push('Achat sans prêt');
    else if (montantPret && acquereurs.length === 1) repris.push('Montant du prêt (offre reçue)');
    else if (montantPret) aCompleter.push(`Répartition du prêt de ${formaterPrixCentimes(montantPret)} entre les acquéreurs.`);
    else aCompleter.push('Montant et établissement du prêt.');
    aCompleter.push('Apport personnel de chacun.');
    return { typeBien, acquereurs, prix, montantPret, sansPret: !!d.sansPret, repris, aCompleter };
  }

  // --- état et rendu ------------------------------------------------------------------------
  let qtEtat = null;
  let qtCompteur = 0;
  let qtDossierLie = null;
  function qtId() { qtCompteur += 1; return 'q' + qtCompteur; }

  function etatQuotitesVierge() {
    const a1 = { id: qtId(), civilite: 'Monsieur', nom: '' };
    const a2 = { id: qtId(), civilite: 'Madame', nom: '' };
    return {
      typeBien: 'immeuble',
      acquereurs: [a1, a2],
      lignes: lignesOperationParDefaut('immeuble').map(l => Object.assign({ id: qtId() }, l)),
      sources: [
        { id: qtId(), type: 'apport', banque: '', numero: '', montants: {} },
        { id: qtId(), type: 'pret', banque: '', numero: '', montants: {} }
      ]
    };
  }

  function initQuotites() {
    if (qtEtat) return;
    qtEtat = etatQuotitesVierge();
    renderQuotites();
  }

  function reinitialiserQuotites() {
    qtEtat = etatQuotitesVierge();
    qtDossierLie = null;
    renderPillDossierQuotites();
    const recap = document.getElementById('qt-recap-prefill');
    if (recap) { recap.className = 'af-recap'; recap.innerHTML = ''; }
    renderQuotites();
  }

  function valeurChampQuotite(v) {
    return v == null || v === '' ? '' : String(v);
  }

  function renderQuotites() {
    if (!qtEtat) return;
    document.querySelectorAll('input[name="qt-type-bien"]').forEach(r => { r.checked = r.value === qtEtat.typeBien; });

    const plusieurs = qtEtat.acquereurs.length > 1;
    document.getElementById('qt-acquereurs').innerHTML = qtEtat.acquereurs.map((a, i) => `
      <div class="qt-ligne qt-ligne-acquereur">
        <select aria-label="Civilité de l'acquéreur ${i + 1}" onchange="modifierAcquereurQuotites('${a.id}', 'civilite', this.value, true)">
          ${['Monsieur', 'Madame', 'SCI'].map(c => `<option value="${c}"${a.civilite === c ? ' selected' : ''}>${c}</option>`).join('')}
        </select>
        <input type="text" aria-label="Prénom et nom de l'acquéreur ${i + 1}" placeholder="Prénom NOM" value="${escapeAttr(a.nom)}" oninput="modifierAcquereurQuotites('${a.id}', 'nom', this.value, false)">
        ${plusieurs ? `<button type="button" class="qt-suppr" title="Retirer cet acquéreur" aria-label="Retirer cet acquéreur" onclick="retirerAcquereurQuotites('${a.id}')">${icone('x')}</button>` : '<span></span>'}
      </div>`).join('');

    document.getElementById('qt-lignes').innerHTML = qtEtat.lignes.map(l => `
      <div class="qt-ligne qt-ligne-operation${l.memoire ? ' qt-memoire' : ''}">
        <input type="text" aria-label="Libellé" placeholder="Libellé" value="${escapeAttr(l.libelle)}" oninput="modifierLigneQuotites('${l.id}', 'libelle', this.value, false)">
        <input type="number" min="0" step="0.01" aria-label="Montant de ${escapeAttr(l.libelle || 'la ligne')}" placeholder="${l.memoire ? 'Mémoire' : '0,00'}" value="${l.memoire ? '' : valeurChampQuotite(l.montant)}" ${l.memoire ? 'disabled' : ''} oninput="modifierLigneQuotites('${l.id}', 'montant', this.value, false)">
        <label class="qt-memoire-coche" title="Montant non encore connu : écrit « MEMOIRE » dans l'annexe et exclu du total"><input type="checkbox" ${l.memoire ? 'checked' : ''} onchange="modifierLigneQuotites('${l.id}', 'memoire', this.checked, true)">Mémoire</label>
        <button type="button" class="qt-suppr" title="Supprimer la ligne" aria-label="Supprimer la ligne" onclick="retirerLigneQuotites('${l.id}')">${icone('x')}</button>
      </div>`).join('');

    document.getElementById('qt-sources').innerHTML = qtEtat.sources.map(src => `
      <div class="qt-source">
        <div class="qt-source-entete">
          <span class="dot-label ${src.type === 'pret' ? 'dl-acte' : 'dl-success'}"><span class="dot"></span>${src.type === 'pret' ? 'Prêt' : 'Apport personnel'}</span>
          <strong class="qt-source-total" id="qt-source-total-${src.id}"></strong>
          <button type="button" class="qt-suppr" title="Supprimer cette source" aria-label="Supprimer cette source" onclick="retirerSourceQuotites('${src.id}')">${icone('x')}</button>
        </div>
        ${src.type === 'pret' ? `<div class="qt-source-pret">
          <input type="text" aria-label="Établissement prêteur" placeholder="Établissement prêteur" value="${escapeAttr(src.banque)}" oninput="modifierSourceQuotites('${src.id}', 'banque', this.value)">
          <input type="text" aria-label="Numéro de prêt" placeholder="N° de prêt" value="${escapeAttr(src.numero)}" oninput="modifierSourceQuotites('${src.id}', 'numero', this.value)">
        </div>` : ''}
        <div class="qt-source-montants">
          ${qtEtat.acquereurs.map(a => `<label class="qt-part">
            <span class="qt-part-nom" id="qt-part-nom-${src.id}-${a.id}">${escapeHtml(nomAcquereurQuotite(a))}</span>
            <input type="number" min="0" step="0.01" placeholder="0,00" value="${valeurChampQuotite((src.montants || {})[a.id])}" oninput="modifierMontantSourceQuotites('${src.id}', '${a.id}', this.value)">
          </label>`).join('')}
        </div>
      </div>`).join('');

    majResultatsQuotites();
  }

  // Rendu partiel appelé à chaque frappe : ne reconstruit JAMAIS les champs de saisie (le focus
  // serait perdu à chaque caractère), seulement les totaux, le contrôle, les quotités et l'aperçu.
  function majResultatsQuotites() {
    if (!qtEtat) return;
    const r = calculerQuotites(qtEtat);
    document.getElementById('qt-total-operation').textContent = formaterPrixCentimes(r.totalOperation);
    document.getElementById('qt-total-financement').textContent = formaterPrixCentimes(r.totalFinancement);
    qtEtat.sources.forEach(src => {
      const el = document.getElementById(`qt-source-total-${src.id}`);
      if (el) el.textContent = formaterPrixCentimes(r.totalParSource[src.id] || 0);
      qtEtat.acquereurs.forEach(a => {
        const nom = document.getElementById(`qt-part-nom-${src.id}-${a.id}`);
        if (nom) nom.textContent = nomAcquereurQuotite(a);
      });
    });

    const controle = document.getElementById('qt-controle');
    const alertes = [];
    if (!r.totalOperation && !r.totalFinancement) {
      alertes.push(`<div class="qt-alerte qt-alerte-neutre">${icone('info')}<span>Saisissez le montant de l'opération et l'origine du financement.</span></div>`);
    } else if (r.couvert) {
      alertes.push(`<div class="qt-alerte qt-alerte-ok">${icone('check')}<span>Le financement couvre exactement le montant de l'opération.</span></div>`);
    } else {
      const sens = r.ecart > 0 ? 'Le financement dépasse le coût de l’opération' : 'Le financement ne couvre pas le coût de l’opération';
      alertes.push(`<div class="qt-alerte qt-alerte-ecart">${icone('alert-triangle')}<span>${sens} de <strong>${formaterPrixCentimes(Math.abs(r.ecart))}</strong> (${formaterPrixCentimes(r.totalFinancement)} pour ${formaterPrixCentimes(r.totalOperation)}).</span></div>`);
    }
    r.sansFinancement.forEach(id => {
      const a = qtEtat.acquereurs.find(x => x.id === id);
      if (a) alertes.push(`<div class="qt-alerte qt-alerte-ecart">${icone('alert-triangle')}<span>${escapeHtml(nomAcquereurQuotite(a))} ne finance rien : sa quotité serait nulle.</span></div>`);
    });
    controle.innerHTML = alertes.join('');

    document.getElementById('qt-quotites').innerHTML = qtEtat.acquereurs.map((a, i) => {
      const p = r.parAcquereur[i];
      return `<div class="qt-quotite">
        <div class="qt-quotite-nom">${escapeHtml(nomAcquereurQuotite(a))}</div>
        <div class="qt-quotite-pct">${formaterPourcentageQuotite(p.pourcentage)}</div>
        <div class="qt-barre" aria-hidden="true"><span style="width:${Math.min(100, p.pourcentage)}%"></span></div>
        <div class="qt-quotite-montant">${formaterPrixCentimes(p.total)}</div>
      </div>`;
    }).join('');

    document.getElementById('qt-feuille').innerHTML = htmlAnnexeQuotites(qtEtat, r);
  }

  function htmlAnnexeQuotites(etat, r) {
    const e = s => escapeHtml(s);
    let h = `<p class="qt-doc-titre">NATURE ET QUOTITES DES DROITS ACQUIS</p>`;
    h += `<p>${e(phraseQuotitesAcquisition(etat.acquereurs, r))}</p>`;
    h += `<p><u>Détermination des proportions acquises</u> - Les acquéreurs déclarent que la proportionnalité indiquée ci-dessus a été fixée en fonction des éléments suivants :</p>`;
    h += `<p class="qt-doc-rubrique">MONTANT DE L'OPERATION :</p>`;
    etat.lignes.forEach(l => {
      h += `<div class="qt-doc-ligne"><span>${e(l.libelle || '—')}</span><span>${l.memoire ? 'MEMOIRE' : e(formaterPrixCentimes(montantQuotite(l.montant)))}</span></div>`;
    });
    h += `<div class="qt-doc-ligne qt-doc-total"><span>Total</span><span>${e(formaterPrixCentimes(r.totalOperation))}</span></div>`;
    h += `<p class="qt-doc-rubrique">ORIGINE DU FINANCEMENT :</p>`;
    lignesFinancementAnnexe(etat, r).forEach(l => {
      h += `<div class="qt-doc-ligne"><span>${e(l.libelle)}</span><span>${e(formaterPrixCentimes(l.montant))}</span></div>`;
    });
    h += `<div class="qt-doc-ligne qt-doc-total"><span>Total</span><span>${e(formaterPrixCentimes(r.totalFinancement))}</span></div>`;
    h += `<p>Récapitulatif des financements de chacun :</p>`;
    h += `<table class="qt-doc-table"><thead><tr><th></th>${etat.acquereurs.map(a => `<th>${e(nomAcquereurQuotite(a))}</th>`).join('')}<th>TOTAL</th></tr></thead><tbody>`;
    etat.sources.forEach(src => {
      h += `<tr><td>${e(libelleSourceTableau(src))}</td>${etat.acquereurs.map(a => `<td class="num">${e(formaterPrixCentimes(montantQuotite((src.montants || {})[a.id])))}</td>`).join('')}<td class="num">${e(formaterPrixCentimes(r.totalParSource[src.id] || 0))}</td></tr>`;
    });
    h += `<tr class="gras"><td>TOTAL</td>${r.parAcquereur.map(p => `<td class="num">${e(formaterPrixCentimes(p.total))}</td>`).join('')}<td class="num">${e(formaterPrixCentimes(r.totalFinancement))}</td></tr>`;
    h += `<tr class="gras"><td>Proportions</td>${r.parAcquereur.map(p => `<td class="num">${e(formaterPourcentageQuotite(p.pourcentage))}</td>`).join('')}<td class="num">100 %</td></tr>`;
    h += `</tbody></table>`;
    clausesQuotites(etat).forEach(c => {
      if (c.type === 'section') h += `<p><u>${e(c.amorce)}</u> - ${e(c.texte)}</p>`;
      else if (c.type === 'sous') h += `<p class="qt-doc-sous">${e(c.texte)}</p>`;
      else h += `<p>${e(c.texte)}</p>`;
    });
    return h;
  }

  // --- modifications -------------------------------------------------------------------------
  function changerTypeBienQuotites(type) {
    if (!qtEtat || !TYPES_BIEN_QUOTITES.includes(type) || type === qtEtat.typeBien) return;
    // Les lignes ne sont remplacées que si personne n'y a encore rien saisi : changer de nature du
    // bien ne doit jamais effacer un montant déjà tapé.
    const vierges = qtEtat.lignes.every(l => !montantQuotite(l.montant));
    qtEtat.typeBien = type;
    if (vierges) {
      const prix = qtEtat.lignes.find(l => /prix d'acquisition/i.test(l.libelle));
      qtEtat.lignes = lignesOperationParDefaut(type).map(l => Object.assign({ id: qtId() }, l));
      if (prix && montantQuotite(prix.montant)) qtEtat.lignes[0].montant = prix.montant;
    }
    renderQuotites();
  }

  function ajouterAcquereurQuotites() {
    if (!qtEtat) return;
    qtEtat.acquereurs.push({ id: qtId(), civilite: 'Monsieur', nom: '' });
    renderQuotites();
  }
  function retirerAcquereurQuotites(id) {
    if (!qtEtat || qtEtat.acquereurs.length <= 1) return;
    qtEtat.acquereurs = qtEtat.acquereurs.filter(a => a.id !== id);
    qtEtat.sources.forEach(s => { delete s.montants[id]; });
    renderQuotites();
  }
  function modifierAcquereurQuotites(id, champ, valeur, reconstruire) {
    const a = qtEtat && qtEtat.acquereurs.find(x => x.id === id);
    if (!a) return;
    a[champ] = valeur;
    if (reconstruire) renderQuotites(); else majResultatsQuotites();
  }

  function ajouterLigneQuotites() {
    if (!qtEtat) return;
    qtEtat.lignes.push({ id: qtId(), libelle: '', montant: null, memoire: false });
    renderQuotites();
  }
  function retirerLigneQuotites(id) {
    if (!qtEtat) return;
    qtEtat.lignes = qtEtat.lignes.filter(l => l.id !== id);
    renderQuotites();
  }
  function modifierLigneQuotites(id, champ, valeur, reconstruire) {
    const l = qtEtat && qtEtat.lignes.find(x => x.id === id);
    if (!l) return;
    l[champ] = champ === 'montant' ? (valeur === '' ? null : valeur) : valeur;
    if (reconstruire) renderQuotites(); else majResultatsQuotites();
  }

  function ajouterSourceQuotites(type) {
    if (!qtEtat) return;
    qtEtat.sources.push({ id: qtId(), type: type === 'pret' ? 'pret' : 'apport', banque: '', numero: '', montants: {} });
    renderQuotites();
  }
  function retirerSourceQuotites(id) {
    if (!qtEtat) return;
    qtEtat.sources = qtEtat.sources.filter(s => s.id !== id);
    renderQuotites();
  }
  function modifierSourceQuotites(id, champ, valeur) {
    const s = qtEtat && qtEtat.sources.find(x => x.id === id);
    if (!s) return;
    s[champ] = valeur;
    majResultatsQuotites();
  }
  function modifierMontantSourceQuotites(idSource, idAcquereur, valeur) {
    const s = qtEtat && qtEtat.sources.find(x => x.id === idSource);
    if (!s) return;
    s.montants[idAcquereur] = valeur === '' ? null : valeur;
    majResultatsQuotites();
  }

  // --- dossier suivi (Outil 1) ---------------------------------------------------------------
  function rechercherDossierQuotites(valeur) {
    const boite = document.getElementById('qt-dossier-resultats');
    if (!boite) return;
    const q = normaliserPourRecherche(String(valeur || '').trim());
    if (!q) { boite.style.display = 'none'; boite.innerHTML = ''; return; }
    const trouves = dossiers.filter(d => !d.archive &&
      (normaliserPourRecherche(libelleDossierAffiche(d)).includes(q) || normaliserPourRecherche(d.responsable || '').includes(q)))
      .slice(0, 8);
    boite.innerHTML = trouves.length
      ? trouves.map(d => `<button type="button" class="dash-recherche-ligne" onclick="choisirDossierQuotites('${escapeOnclickArg(d.id)}')">
          <span class="dash-recherche-nom">${escapeHtml(libelleDossierAffiche(d))}</span>
          <span class="dash-recherche-resp">${escapeHtml(d.responsable || '')}</span>
        </button>`).join('')
      : '<div class="dash-recherche-vide">Aucun dossier ne correspond.</div>';
    boite.style.display = 'block';
  }

  function choisirDossierQuotites(id) {
    const d = dossiers.find(x => x.id === id);
    if (!d) return;
    const champ = document.getElementById('qt-dossier-recherche');
    if (champ) champ.value = '';
    const boite = document.getElementById('qt-dossier-resultats');
    if (boite) { boite.style.display = 'none'; boite.innerHTML = ''; }
    const p = prefillQuotites(d);
    qtEtat = etatQuotitesVierge();
    qtEtat.typeBien = p.typeBien;
    qtEtat.lignes = lignesOperationParDefaut(p.typeBien).map(l => Object.assign({ id: qtId() }, l));
    if (p.prix) qtEtat.lignes[0].montant = p.prix;
    if (p.acquereurs.length) qtEtat.acquereurs = p.acquereurs.map(a => Object.assign({ id: qtId() }, a));
    if (p.sansPret) qtEtat.sources = qtEtat.sources.filter(s => s.type !== 'pret');
    else if (p.montantPret && qtEtat.acquereurs.length === 1) {
      const pret = qtEtat.sources.find(s => s.type === 'pret');
      if (pret) pret.montants[qtEtat.acquereurs[0].id] = p.montantPret;
    }
    qtDossierLie = d.id;
    renderPillDossierQuotites();
    const recap = document.getElementById('qt-recap-prefill');
    if (recap) {
      recap.className = 'af-recap af-recap-visible';
      recap.innerHTML = `<div class="af-recap-bloc"><div class="af-recap-titre">Repris du dossier</div><ul>${p.repris.map(x => `<li>${escapeHtml(x)}</li>`).join('')}</ul></div>
        <div class="af-recap-bloc af-recap-manquant"><div class="af-recap-titre">À compléter</div><ul>${p.aCompleter.map(x => `<li>${escapeHtml(x)}</li>`).join('')}</ul></div>`;
    }
    renderQuotites();
  }

  function renderPillDossierQuotites() {
    const cible = document.getElementById('qt-dossier-pill');
    if (!cible) return;
    const d = qtDossierLie ? dossiers.find(x => x.id === qtDossierLie) : null;
    cible.innerHTML = d ? `<div class="dash-recherche-pill">
      <span class="dot-label dl-success"><span class="dot"></span>${escapeHtml(libelleDossierAffiche(d))}</span>
      <button type="button" class="action-rapide" onclick="reinitialiserQuotites()">Détacher</button>
    </div>` : '';
  }

  // --- annexe .docx --------------------------------------------------------------------------
  // Bibliothèque `docx` (la même que l'artefact d'origine), chargée à la demande depuis
  // cdn.jsdelivr.net comme pizzip/docxtemplater pour l'appel de fonds : rien n'est chargé tant que
  // personne ne télécharge d'annexe. Mise en page de l'artefact conservée à l'identique (Times New
  // Roman 11, marges 2,5 cm, points de conduite vers le montant).
  async function telechargerQuotitesDocx(btn) {
    if (!qtEtat) return;
    const r = calculerQuotites(qtEtat);
    if (!r.totalFinancement) {
      afficherToast('Saisissez l’origine du financement avant de télécharger l’annexe.', 'OK', null);
      return;
    }
    const libelle = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = 'Préparation…'; }
    try {
      if (!window.docx) await afChargerScript('https://cdn.jsdelivr.net/npm/docx@9.7.1/dist/index.iife.min.js');
      const D = window.docx;
      const POLICE = 'Times New Roman';
      const TAILLE = 22;
      const P = o => new D.Paragraph(Object.assign({ spacing: { after: 160, line: 259, lineRule: 'auto' } }, o));
      const R = (text, o) => new D.TextRun(Object.assign({ text, font: POLICE, size: TAILLE }, o || {}));
      const taquets = [{ type: D.TabStopType.RIGHT, position: 8220, leader: D.LeaderType.DOT }];
      const ligne = (lib, mt, gras, apres) => P({ tabStops: taquets, spacing: { after: apres || 60 }, children: [R(lib + ' \t' + mt, { bold: !!gras })] });
      const enfants = [];
      enfants.push(P({ alignment: D.AlignmentType.CENTER, spacing: { after: 220 }, children: [R('NATURE ET QUOTITES DES DROITS ACQUIS', { bold: true })] }));
      enfants.push(P({ alignment: D.AlignmentType.JUSTIFIED, children: [R(phraseQuotitesAcquisition(qtEtat.acquereurs, r))] }));
      enfants.push(P({ alignment: D.AlignmentType.JUSTIFIED, children: [R('Détermination des proportions acquises', { underline: { type: 'single' } }), R(' - Les acquéreurs déclarent que la proportionnalité indiquée ci-dessus a été fixée en fonction des éléments suivants :')] }));
      enfants.push(P({ spacing: { before: 160, after: 120 }, children: [R("MONTANT DE L'OPERATION : ", { bold: true, underline: { type: 'single' } })] }));
      qtEtat.lignes.forEach(l => enfants.push(ligne(l.libelle || '—', l.memoire ? 'MEMOIRE' : formaterPrixCentimes(montantQuotite(l.montant)))));
      enfants.push(ligne('Total', formaterPrixCentimes(r.totalOperation), true, 220));
      enfants.push(P({ spacing: { before: 100, after: 120 }, children: [R('ORIGINE DU FINANCEMENT : ', { bold: true, underline: { type: 'single' } })] }));
      lignesFinancementAnnexe(qtEtat, r).forEach(l => enfants.push(ligne(l.libelle, formaterPrixCentimes(l.montant))));
      enfants.push(ligne('Total', formaterPrixCentimes(r.totalFinancement), true, 220));
      enfants.push(P({ children: [R('Récapitulatif des financements de chacun : ')] }));

      const bord = { style: 'single', size: 6, color: '000000' };
      const cellule = (text, o) => new D.TableCell({
        margins: { top: 60, bottom: 60, left: 100, right: 100 },
        verticalAlign: D.VerticalAlign.CENTER,
        children: [P({ alignment: (o && o.droite) ? D.AlignmentType.RIGHT : D.AlignmentType.CENTER, spacing: { after: 0 }, children: [R(text, { bold: !!(o && o.gras) })] })]
      });
      const rangees = [new D.TableRow({ children: [cellule('', { gras: true }), ...qtEtat.acquereurs.map(a => cellule(nomAcquereurQuotite(a), { gras: true })), cellule('TOTAL', { gras: true })] })];
      qtEtat.sources.forEach(src => rangees.push(new D.TableRow({ children: [cellule(libelleSourceTableau(src)), ...qtEtat.acquereurs.map(a => cellule(formaterPrixCentimes(montantQuotite((src.montants || {})[a.id])), { droite: true })), cellule(formaterPrixCentimes(r.totalParSource[src.id] || 0), { droite: true })] })));
      rangees.push(new D.TableRow({ children: [cellule('TOTAL', { gras: true }), ...r.parAcquereur.map(p => cellule(formaterPrixCentimes(p.total), { droite: true, gras: true })), cellule(formaterPrixCentimes(r.totalFinancement), { droite: true, gras: true })] }));
      rangees.push(new D.TableRow({ children: [cellule('Proportions', { gras: true }), ...r.parAcquereur.map(p => cellule(formaterPourcentageQuotite(p.pourcentage), { droite: true, gras: true })), cellule('100 %', { droite: true, gras: true })] }));
      enfants.push(new D.Table({ width: { size: 100, type: D.WidthType.PERCENTAGE }, borders: { top: bord, bottom: bord, left: bord, right: bord, insideHorizontal: bord, insideVertical: bord }, rows: rangees }));
      enfants.push(P({ spacing: { before: 220, after: 0 }, children: [R('')] }));

      clausesQuotites(qtEtat).forEach(c => {
        if (c.type === 'section') enfants.push(P({ alignment: D.AlignmentType.JUSTIFIED, children: [R(c.amorce, { underline: { type: 'single' } }), R(' - ' + c.texte)] }));
        else if (c.type === 'sous') enfants.push(P({ alignment: D.AlignmentType.JUSTIFIED, spacing: { before: 120, after: 100 }, children: [R(c.texte, { italics: true })] }));
        else enfants.push(P({ alignment: D.AlignmentType.JUSTIFIED, children: [R(c.texte)] }));
      });

      const doc = new D.Document({
        styles: { default: { document: { run: { font: POLICE, size: TAILLE } } } },
        sections: [{ properties: { page: { margin: { top: 1417, bottom: 1417, left: 1417, right: 1417 } } }, children: enfants }]
      });
      const blob = await D.Packer.toBlob(doc);
      const noms = qtEtat.acquereurs.map(a => String(a.nom || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9]+/g, '')).filter(Boolean).join('_');
      const lien = document.createElement('a');
      lien.href = URL.createObjectURL(blob);
      lien.download = `Quotites_acquisition_${noms || 'acte'}.docx`;
      document.body.appendChild(lien);
      lien.click();
      ouvrirApresTelechargement(lien.download);
      lien.remove();
      setTimeout(() => URL.revokeObjectURL(lien.href), 5000);
    } catch (e) {
      console.error(e);
      afficherToast('Génération impossible : la bibliothèque Word n’a pas pu être chargée (accès internet requis).', 'OK', null);
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = libelle; }
    }
  }

  // Peuple le <select> des départements une seule fois au démarrage (le calculateur est toujours
  // dans le DOM, comme les autres onglets — voir definirOnglet) et calcule un premier résultat par
  // défaut, visible dès le premier passage sur l'onglet. Un simple drapeau plutôt qu'une lecture de
  // `deptEl.options` : le faux document des tests (tests/helpers/load-app.js) ne modélise pas les
  // `<select>`/`<option>` du DOM réel, `.options` y est `undefined`.
  let calculateurFraisActeInitialise = false;
  function initCalculateurFraisActe() {
    if (calculateurFraisActeInitialise) return;
    const deptEl = document.getElementById('calc-dept');
    if (!deptEl) return;
    for (const [code, d] of Object.entries(DEPARTEMENTS_FRAIS_ACTE)) {
      const option = document.createElement('option');
      option.value = code;
      option.textContent = code + ' — ' + d.name;
      if (code === '41') option.selected = true;
      deptEl.appendChild(option);
    }
    calculateurFraisActeInitialise = true;
    calculerFraisActe();
  }

  // Le même barème sert au CONTRÔLE de la ligne de frais du décompte d'appel de fonds. Le select
  // y part volontairement vide (« — à choisir — ») et non sur le 41 comme le simulateur : tant
  // qu'aucun département n'est choisi, aucun contrôle n'est affiché — mieux vaut ne rien dire que
  // de comparer au barème du mauvais département.
  var selectDepartementAppelFondsInitialise = false;
  function initSelectDepartementAppelFonds() {
    if (selectDepartementAppelFondsInitialise) return;
    const el = document.getElementById('af-frais-departement');
    if (!el) return;
    const vide = document.createElement('option');
    vide.value = '';
    vide.textContent = '— à choisir —';
    el.appendChild(vide);
    for (const [code, d] of Object.entries(DEPARTEMENTS_FRAIS_ACTE)) {
      const option = document.createElement('option');
      option.value = code;
      option.textContent = code + ' — ' + d.name;
      el.appendChild(option);
    }
    selectDepartementAppelFondsInitialise = true;
  }

  // ---- Outil 2 — Audit intelligent des actes notariaux : import du projet (compromis/promesse ou
  // acte de vente) + pièces séparées, relecture croisée par le modèle local (Ollama, voir
  // server/src/llm.js, server/src/audit/ et CLAUDE.md, section "Outil 2") ----
  // Distinct du wizard "Nouveau dossier" (Outil 1, qui crée/tient la fiche de suivi à partir d'un
  // compromis SIGNÉ) : ici on compare des PROJETS de documents entre eux pour un audit, sans jamais
  // créer ni modifier un dossier de suivi — un dossier CLAIRE peut être lié en lecture seule pour
  // réutiliser ses données déjà vérifiées (voir auditDossierLie), jamais en écriture.
  // N'existe QUE sur `claude/serveur-intranet` (a besoin d'un backend pour parler à Ollama, jamais
  // appelé sans `fetchAvecAuth()`/l'écran de connexion, absents de `main`) — contrairement au reste
  // de ce fichier, cette section (et celle de l'extraction IA du wizard "Nouveau dossier", voir
  // lancerExtractionIa) n'est PAS portée sur `main`, qui n'a pas de backend pour l'exécuter.
  // Chaque fichier déposé n'existe qu'en mémoire le temps de l'audit — jamais enregistré, aucun
  // dossier créé. Seul le TEXTE déjà extrait dans le navigateur est envoyé au serveur, jamais le
  // PDF lui-même (voir lireTextePdfParPage, déjà utilisée pour vérifier un dossier local).
  let fichiersAnalyseIa = []; // { id, file, nom, type, statut, texte, pages, erreurTexte }
  let compteurFichierAnalyseIa = 0;

  // Mode choisi EXPLICITEMENT au dépôt (jamais deviné, demande de l'étude) : « lecture du
  // compromis » (chercher les dangers dans un avant-contrat) ou « lecture d'un projet de vente »
  // (comparer ce projet à l'avant-contrat déjà signé et vérifier que les engagements ont été
  // tenus). auditDossierLie (mode 'acte' seulement) évite de redéposer l'avant-contrat quand le
  // dossier est déjà suivi dans CLAIRE — jamais modifié, lu seul.
  let auditMode = 'compromis';
  let auditDossierLie = null;

  function changerAuditMode(valeur) {
    auditMode = (valeur === 'acte') ? 'acte' : 'compromis';
    const aide = document.getElementById('audit-aide-mode');
    if (aide) {
      aide.textContent = auditMode === 'acte'
        ? `Le projet est relu point par point (${grillePourModeOutil2('acte').length} points) et comparé à l'avant-contrat signé : parties, prix, désignation, conditions levées, engagements du vendeur tenus.`
        : `Le projet d'avant-contrat est relu point par point (${grillePourModeOutil2('compromis').length} points) : parties, bien, diagnostics, copropriété, délais et clauses, urbanisme, volet financier.`;
    }
    for (const f of fichiersAnalyseIa) if (auditMode !== 'acte' && f.type === 'reference_compromis') f.type = 'justificatif';
    invaliderSuiteRelecture();
    renderListeFichiersAnalyseIa();
    calculerPropositionsDossierAudit();
  }

  // Recherche d'un dossier CLAIRE à lier à l'audit (mode "projet d'acte de vente" uniquement) —
  // même patron que renderRechercheDashboard() (Tableau de bord), un menu de résultats sous le
  // champ plutôt qu'un filtre sur une liste déjà affichée, qui n'existe pas ici.
  function ligneResultatDossierAudit(d) {
    return `<button type="button" class="dash-recherche-ligne" onclick="choisirDossierAudit('${d.id}')">
          ${renderBadgeStatut(d)}
          <span class="dash-recherche-nom">${escapeHtml(libelleDossierAffiche(d))}</span>
          <span class="dash-recherche-resp">${escapeHtml(d.responsable || '')}</span>
        </button>`;
  }

  function rechercherDossierAudit(valeur) {
    const bloc = document.getElementById('audit-dossier-resultats');
    if (!bloc) return;
    const q = normaliserPourRecherche(String(valeur || '').trim());
    if (!q) { renderPropositionsDossierAudit(); return; }
    const resultats = dossiers
      .filter(d => !d.archive && normaliserPourRecherche(libelleDossierAffiche(d) + ' ' + (d.responsable || '')).includes(q))
      .slice(0, 8);
    bloc.innerHTML = resultats.length === 0
      ? '<div class="dash-recherche-vide">Aucun dossier ne correspond.</div>'
      : resultats.map(ligneResultatDossierAudit).join('');
    bloc.style.display = 'block';
  }

  // Dossiers proposés d'après les parties lues dans le document principal (voir
  // proposerDossiersDepuisParties) : affichés sous le champ de recherche tant qu'il est vide et
  // qu'aucun dossier n'est lié — une proposition à confirmer d'un clic, jamais une liaison faite
  // toute seule. Recalculés dès que le principal est lu, change de type, ou que le mode passe à
  // « projet d'acte de vente » (le bloc n'existe pas dans l'autre mode).
  let auditDossiersProposes = [];

  function calculerPropositionsDossierAudit() {
    // Le type de bien choisi à la main se rapporte à l'acte analysé : dès que les documents ou le
    // mode changent, il n'a plus de sens et la déduction doit reprendre la main.
    typeBienAuditChoisi = null;
    auditDossiersProposes = [];
    const principal = fichiersAnalyseIa.find(f => f.type === 'principal' && f.statut === 'ok');
    if (principal && principal.texte) {
      const typeActe = detecterTypeActe(principal.texte);
      const parties = detecterParties(principal.texte, typeActe && typeActe.valeur);
      auditDossiersProposes = proposerDossiersDepuisParties(parties, dossiers).slice(0, 5);
    }
    renderPropositionsDossierAudit();
  }

  function renderPropositionsDossierAudit() {
    const bloc = document.getElementById('audit-dossier-resultats');
    if (!bloc) return;
    if (auditDossierLie || auditDossiersProposes.length === 0) {
      bloc.style.display = 'none';
      bloc.innerHTML = '';
      return;
    }
    bloc.innerHTML = `<div class="dash-recherche-vide">${icone('sparkle')} Dossier(s) dont les parties correspondent au projet — cliquez pour lier :</div>`
      + auditDossiersProposes.map(ligneResultatDossierAudit).join('');
    bloc.style.display = 'block';
  }

  function renderDossierLieAudit() {
    const pill = document.getElementById('audit-dossier-pill');
    if (!pill) return;
    const d = auditDossierLie;
    const aae = d && d.nasDossier
      ? `<button type="button" class="action-rapide audit-aae-btn" onclick="ouvrirParcoursNasRelecture()" title="Affiche tout le dossier du client sur le NAS, rubrique par rubrique, pour choisir les pièces à joindre à la relecture">${icone('folder')}Parcourir le dossier du NAS</button>`
      : (d ? '<span class="hint">Dossier non relié au NAS.</span>' : '');
    pill.innerHTML = d
      ? `<span class="dot-label dl-success">${icone('link')}${escapeHtml(libelleDossierAffiche(d))}<button type="button" class="piece-suppr" onclick="retirerDossierAudit()" title="Ne plus lier ce dossier" aria-label="Ne plus lier ce dossier">${icone('x')}</button></span>${aae}`
      : '';
  }

  function choisirDossierAudit(id) {
    auditDossierLie = dossiers.find(d => d.id === id) || null;
    invaliderSuiteRelecture();
    const champ = document.getElementById('audit-dossier-recherche');
    if (champ) champ.value = '';
    renderPropositionsDossierAudit();
    renderDossierLieAudit();
  }

  function retirerDossierAudit() {
    auditDossierLie = null;
    fermerParcoursNasRelecture();
    invaliderSuiteRelecture();
    renderDossierLieAudit();
    renderPropositionsDossierAudit();
  }

  // Va chercher le compromis/la promesse d'un dossier CLAIRE lié DIRECTEMENT SUR LE NAS déjà relié
  // (même mécanisme que le bouton "Ouvrir le compromis" — d.compromisNomFichier, chercherFichierParNom,
  // ouvrirPdfNas), plutôt que de forcer un second import manuel : le dossier est déjà suivi, son
  // compromis y est déjà. Silencieux en cas d'échec (nom introuvable, dossier non relié au NAS, PDF
  // illisible...) : la comparaison structurée (comparerCompromisEtProjet, plus bas) reste alors
  // disponible, seul le volet "clauses en langage libre" de la comparaison (passes IA) est absent.
  async function recupererTextCompromisDossier(d) {
    if (!d || !d.dossierLie || !d.nasDossier || !window.pdfjsLib) return null;
    try {
      // Même ordre de préférence que le bouton « Ouvrir le compromis » (choisirAvantContratNas) :
      // nom exact, puis racine/rubrique SRU, puis mots « compromis »/« promesse ».
      const trouve = choisirAvantContratNas(await listerFichiersNas(d), d.compromisNomFichier).fichier;
      if (!trouve) return null;
      const pdf = await ouvrirPdfNas(cheminNasComplet(d, trouve.chemin));
      const { texte, pages, pagesLues, pagesTotal, viaOcr, tronque } = await lireTextePdfParPage(pdf);
      if (texte.trim().length < 20) return null;
      return { nom: trouve.nom, texte, pages, pagesLues, pagesTotal, viaOcr, tronque };
    } catch (e) {
      console.error('Audit des actes : compromis du dossier lié introuvable ou illisible', e);
      return null;
    }
  }

  function gererSurvolDepotAnalyseIa(event) {
    event.preventDefault();
    document.getElementById('analyse-ia-dropzone').classList.add('survol');
  }

  function gererQuitteDepotAnalyseIa(event) {
    event.preventDefault();
    document.getElementById('analyse-ia-dropzone').classList.remove('survol');
  }

  function gererDepotAnalyseIa(event) {
    event.preventDefault();
    document.getElementById('analyse-ia-dropzone').classList.remove('survol');
    const fichiers = event.dataTransfer && event.dataTransfer.files;
    if (fichiers && fichiers.length) ajouterFichiersAnalyseIa(fichiers);
  }

  // Devine "principal" pour le premier PDF (sauf s'il évoque un compromis/une promesse alors qu'on
  // est en mode "projet de vente", auquel cas c'est la RÉFÉRENCE, pas le principal), puis
  // "reference_compromis" pour un fichier nommé compromis/promesse ensuite en mode acte. Tout
  // fichier suivant part en "justificatif" : dans les deux modes, c'est ce qu'on dépose en
  // pratique après le document à relire (attestation d'entretien, facture, décennale…), et c'est
  // le seul type dont la date est ensuite contrôlée. Une simple valeur de départ, toujours
  // modifiable via le <select> de chaque ligne (voir changerTypeFichierAnalyseIa).
  function deviserTypeAnalyseIa(nomFichier) {
    const dejaUnPrincipal = fichiersAnalyseIa.some(f => f.type === 'principal');
    const dejaUneReference = fichiersAnalyseIa.some(f => f.type === 'reference_compromis');
    const nommeCompromis = /compromis|promesse/i.test(nomFichier);
    if (!dejaUnPrincipal && (auditMode !== 'acte' || !nommeCompromis)) return 'principal';
    if (auditMode === 'acte' && nommeCompromis && !dejaUneReference) return 'reference_compromis';
    return 'justificatif';
  }

  function ajouterFichiersAnalyseIa(fileList) {
    const fichiers = Array.from(fileList).filter(f => f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf'));
    if (fichiers.length === 0) {
      afficherToast('Seuls les fichiers PDF sont acceptés.', 'OK', null);
      return;
    }
    const nouvelles = fichiers.map(file => ({
      id: `analyse-ia-${++compteurFichierAnalyseIa}`,
      file,
      nom: file.name,
      type: deviserTypeAnalyseIa(file.name),
      nature: classerNaturePieceOutil2(file.name, ''),
      statut: 'lecture',
      texte: '',
      pages: [],
      erreurTexte: '',
      pagesLues: null,
      pagesTotal: null,
      viaOcr: false,
      tronque: false
    }));
    fichiersAnalyseIa = fichiersAnalyseIa.concat(nouvelles);
    invaliderSuiteRelecture();
    renderListeFichiersAnalyseIa();
    for (const entree of nouvelles) extraireTexteFichierAnalyseIa(entree.id);
  }

  // Réutilise lireTextePdfParPage() (variante de lireTextePdfVerification, déjà en place pour
  // vérifier l'offre de prêt/les pièces d'un dossier local relié, qui mémorise en plus les
  // frontières de chaque page) : texte extractible + repli OCR sur les 3 premières pages si le PDF
  // est un scan sans texte — même logique, appliquée ici à un fichier importé via <input> plutôt
  // qu'à un FileSystemFileHandle. Les frontières de page sont indispensables à Outil 2 (Audit des
  // actes) pour citer un numéro de page précis par document, pas seulement pour le compromis en
  // cours d'import.
  async function extraireTexteFichierAnalyseIa(id) {
    const entree = fichiersAnalyseIa.find(f => f.id === id);
    if (!entree) return;
    if (!window.pdfjsLib) {
      entree.statut = 'erreur';
      entree.erreurTexte = 'Lecture PDF indisponible — réessayez dans un instant.';
      renderListeFichiersAnalyseIa();
      return;
    }
    try {
      let pdf;
      if (entree.cheminNas) {
        pdf = await ouvrirPdfNas(entree.cheminNas);
      } else {
        const buffer = await entree.file.arrayBuffer();
        pdf = await pdfjsLib.getDocument({ data: buffer, verbosity: (pdfjsLib.VerbosityLevel ? pdfjsLib.VerbosityLevel.ERRORS : 0) }).promise;
      }
      const { texte, pages, pagesLues, pagesTotal, viaOcr, tronque } = await lireTextePdfParPage(pdf);
      if (texte.trim().length < 20) {
        entree.statut = 'erreur';
        entree.erreurTexte = 'Aucun texte exploitable trouvé (page vide, ou scan illisible même après OCR).';
      } else {
        entree.statut = 'ok';
        entree.texte = texte;
        entree.pages = pages;
        entree.pagesLues = pagesLues;
        entree.pagesTotal = pagesTotal;
        entree.viaOcr = viaOcr;
        entree.tronque = tronque;
        // Nature relue sur la première page (le nom seul ne dit pas toujours ce qu'est la pièce),
        // et pages d'annexes jointes au même PDF repérées pour le projet et l'avant-contrat.
        if (!entree.nature || entree.nature === 'autre') entree.nature = classerNaturePieceOutil2(entree.nom, texte);
        entree.annexesDepuisPage = entree.type !== 'justificatif' ? debutAnnexesDocumentOutil2(texte, pages) : null;
      }
    } catch (e) {
      entree.statut = 'erreur';
      entree.erreurTexte = 'Lecture du PDF impossible.';
      console.error('Analyse IA : échec de lecture de', entree.nom, e);
    }
    renderListeFichiersAnalyseIa();
    if (entree.type === 'principal') calculerPropositionsDossierAudit();
  }

  function changerTypeFichierAnalyseIa(id, valeur) {
    const entree = fichiersAnalyseIa.find(f => f.id === id);
    if (!entree) return;
    const etaitPrincipal = entree.type === 'principal';
    entree.type = valeur;
    entree.annexesDepuisPage = valeur !== 'justificatif' && entree.statut === 'ok' ? debutAnnexesDocumentOutil2(entree.texte, entree.pages) : null;
    invaliderSuiteRelecture();
    renderListeFichiersAnalyseIa();
    if (etaitPrincipal || valeur === 'principal') calculerPropositionsDossierAudit();
  }

  function retirerFichierAnalyseIa(id) {
    const retire = fichiersAnalyseIa.find(f => f.id === id);
    fichiersAnalyseIa = fichiersAnalyseIa.filter(f => f.id !== id);
    cachePdfRelecture.delete(id);
    invaliderSuiteRelecture();
    renderListeFichiersAnalyseIa();
    if (retire && retire.type === 'principal') calculerPropositionsDossierAudit();
  }

  // Pas de demanderConfirmation() ici, volontairement : rien n'est enregistré (voir en tête de
  // section), vider la liste ne perd qu'un import à refaire — un impact bien moindre qu'archiver/
  // supprimer un vrai dossier de suivi, qui garde ce garde-fou.
  function viderAnalyseIa() {
    fichiersAnalyseIa = [];
    cachePdfRelecture.clear();
    termesManuelsRelecture = [];
    valeursEnClairRelecture = [];
    fermerVisionneuseRelecture();
    invaliderSuiteRelecture();
    renderListeFichiersAnalyseIa();
  }

  // Résumé lisible de la couverture de lecture d'un document (pages effectivement lues sur le
  // total, et si la lecture est passée par l'OCR) — voir lireTextePdfParPage(). Signalé par
  // l'étude : sans ce résumé, rien n'indiquait qu'un document scanné volumineux n'avait été lu
  // qu'en partie, ce qui pouvait laisser croire à une analyse complète alors qu'elle ne portait
  // que sur les premières pages. Fonction pure, réutilisée par le badge de la liste de fichiers et
  // par le rapport d'audit final.
  function libelleCouverturePages(entree) {
    if (!entree || entree.pagesTotal == null) return '';
    const via = entree.viaOcr ? ' (OCR)' : '';
    if (!entree.tronque) return `p.${entree.pagesLues}/${entree.pagesTotal}${via}`;
    return `p.${entree.pagesLues}/${entree.pagesTotal}${via} — lecture incomplète`;
  }

  function statutFichierAnalyseIa(entree) {
    if (entree.statut === 'lecture') return `<span class="dot-label dl-neutre">${icone('spinner', null, true)}Lecture…</span>`;
    if (entree.statut === 'erreur') return `<span class="dot-label dl-urgent" title="${escapeAttr(entree.erreurTexte)}">${icone('alert-triangle')}Erreur</span>`;
    const couverture = libelleCouverturePages(entree);
    if (entree.tronque) {
      return `<span class="dot-label dl-pret" title="Seules les ${entree.pagesLues} premières pages sur ${entree.pagesTotal} ont été lues — le reste du document n'a pas pu être analysé.">${icone('alert-triangle')}Lu partiellement (${couverture})</span>`;
    }
    return `<span class="dot-label dl-success" title="${escapeAttr(couverture)}">${icone('file-text')}Lu (${couverture})</span>`;
  }

  // 4 niveaux de gravité (§16 du cahier des charges), sur seulement 3 couleurs déjà réservées dans
  // l'outil (pas de 5ᵉ couleur inventée pour l'occasion, voir CLAUDE.md) : IMPORTANT et A_VERIFIER
  // partagent l'ambre, distingués par leur texte et leur icône plutôt que par la couleur.
  function libelleGraviteAudit(gravite) {
    if (gravite === 'CRITIQUE') return { dl: 'dl-urgent', icone: 'alert-triangle', texte: 'Critique' };
    if (gravite === 'IMPORTANT') return { dl: 'dl-pret', icone: 'alert-triangle', texte: 'Important' };
    if (gravite === 'A_VERIFIER') return { dl: 'dl-pret', icone: 'info', texte: 'À vérifier' };
    return { dl: 'dl-neutre', icone: 'info', texte: 'Information' };
  }

  // Un constat cite TOUJOURS le passage du document dont il vient, avec sa page : c'est ce qui
  // permet de le vérifier en dix secondes plutôt que de relire l'acte. `phrase`/`page` viennent
  // des règles déterministes ; `sources` est l'ancienne forme d'un constat venu du modèle local
  // (bouton « Approfondir », retiré le 23/09/2026) — conservée pour ne pas casser un rendu : une
  // citation non retrouvée reste signalée comme telle.
  function renderSourceConstat(c) {
    if (c.phrase) return citationObligation(c.phrase, c.page, 300);
    const liste = Array.isArray(c.sources) ? c.sources : [];
    if (liste.length === 0) return '';
    return liste.map(s => {
      if (s.extraitTrouve === false) {
        return `<p class="analyse-ia-citation-douteuse">${icone('alert-triangle')}Citation non retrouvée dans le document — à vérifier en priorité</p>`;
      }
      return citationObligation(s.extrait, s.page, 300);
    }).join('');
  }

  // Décision de l'étude sur un constat (voir la mémoire d'audit, memoriserDecisionConstat) :
  // deux boutons sur chaque constat, « Écarter » et « Confirmer », et l'état mémorisé affiché en
  // clair — un constat déjà écarté se replie (jamais supprimé : on le voit toujours, replié), un
  // constat déjà confirmé remonte en tête de sa section. « Annuler » retire la décision mémorisée,
  // pour ne pas laisser une erreur d'un clic peser sur tous les audits suivants.
  function renderDecisionAudit(c) {
    if (!c.uid) return '';
    const m = c.memoire;
    if (m) {
      const nb = m.nb > 1 ? ` (${m.nb} fois)` : '';
      const texte = m.decision === 'ecarte' ? `Déjà écarté précédemment${nb}` : `Confirmé lors d'un audit précédent${nb}`;
      return `<div class="analyse-ia-constat-actions">
        <span class="dot-label ${m.decision === 'ecarte' ? 'dl-neutre' : 'dl-success'}">${icone(m.decision === 'ecarte' ? 'x' : 'check')}${texte}</span>
        <button type="button" class="icon-btn" onclick="annulerDecisionConstatAudit('${c.uid}')" title="Oublier cette décision">${icone('rotate-ccw')} Annuler</button>
      </div>`;
    }
    return `<div class="analyse-ia-constat-actions">
      <button type="button" class="icon-btn" onclick="decisionConstatAudit('${c.uid}', 'ecarte')" title="Ne plus signaler ce constat sur les prochains audits (il restera visible, replié)">${icone('x')} Écarter</button>
      <button type="button" class="icon-btn" onclick="decisionConstatAudit('${c.uid}', 'confirme')" title="Marquer ce constat comme pertinent : il remontera en tête sur les prochains audits">${icone('check')} Confirmer</button>
    </div>`;
  }

  function renderConstatAudit(c) {
    const g = libelleGraviteAudit(c.gravite);
    const graviteCorrigee = c.graviteOrigine
      ? `<span class="hint audit-gravite-corrigee">gravité corrigée par l'étude (initialement : ${escapeHtml(libelleGraviteAudit(c.graviteOrigine).texte.toLowerCase())})</span>` : '';
    // En mode commentaires, le commentaire remplace « Écarter / Confirmer » : ce sont deux façons
    // de donner le même avis, les afficher ensemble ferait douter de celle qui compte.
    const pied = modeCommentairesAudit ? renderCommentaireConstatAudit(c) : (renderRetourResumeAudit(c) || renderDecisionAudit(c));
    const corps = `<div class="analyse-ia-constat-titre"><span class="dot-label ${g.dl}">${icone(g.icone)}${g.texte}</span>${escapeHtml(c.titre)}${graviteCorrigee}</div>
      ${c.description ? `<p class="analyse-ia-constat-desc">${escapeHtml(c.description)}</p>` : ''}
      ${renderSourceConstat(c)}
      ${pied}`;
    const teinte = ` constat-${String(c.gravite || 'INFORMATION').toLowerCase()}`;
    const ancre = c.uid ? ` id="audit-constat-${c.uid}"` : '';
    if (c.retour && c.retour.verdict === 'faux_positif') {
      const portee = c.retour.portee === 'dossier' ? 'pour ce dossier' : 'sur tous les dossiers';
      const ouvert = formCommentaireAudit && formCommentaireAudit.uid === c.uid ? ' open' : '';
      return `<details class="analyse-ia-constat constat-ecarte${teinte}"${ancre}${ouvert}>
        <summary><span class="dot-label dl-neutre">${icone('x')}Faux positif ${portee}</span>${escapeHtml(c.titre)}</summary>
        ${corps}
      </details>`;
    }
    if (c.memoire && c.memoire.decision === 'ecarte') {
      return `<details class="analyse-ia-constat constat-ecarte${teinte}"${ancre}>
        <summary><span class="dot-label dl-neutre">${icone('x')}Déjà écarté</span>${escapeHtml(c.titre)}</summary>
        ${corps}
      </details>`;
    }
    const confirme = (c.memoire && c.memoire.decision === 'confirme') || (c.retour && c.retour.verdict === 'juste');
    return `<div class="analyse-ia-constat${teinte}${confirme ? ' constat-confirme' : ''}"${ancre}>${corps}</div>`;
  }

  // ---- Mode commentaires (Outil 2) ----------------------------------------------------------
  // Hors mode commentaires, un avis déjà donné reste visible (une ligne) : l'étude doit voir
  // pourquoi un constat est replié ou a changé de gravité.
  function renderRetourResumeAudit(c) {
    const r = c.retour;
    if (!r) return '';
    const v = VERDICTS_RETOUR_OUTIL2[r.verdict] || VERDICTS_RETOUR_OUTIL2.juste;
    const portee = r.portee === 'dossier' ? 'ce dossier' : 'tous les dossiers';
    return `<div class="audit-commentaire audit-commentaire-lu">
      <span class="dot-label ${v.dl}">${icone(v.icone)}${v.texte} · ${portee}</span>
      ${r.commentaire ? `<span class="audit-commentaire-texte">« ${escapeHtml(r.commentaire)} »</span>` : ''}
    </div>`;
  }

  function renderCommentaireConstatAudit(c) {
    if (!c.uid) return '';
    const f = formCommentaireAudit && formCommentaireAudit.uid === c.uid ? formCommentaireAudit : null;
    if (f) return renderFormCommentaireAudit(c, f);
    if (c.retour) {
      return `<div class="audit-commentaire">
        ${renderRetourResumeAudit(c)}
        <div class="audit-commentaire-actions">
          <button type="button" class="icon-btn" onclick="modifierCommentaireAudit('${c.uid}')">${icone('pencil')} Modifier</button>
          <button type="button" class="icon-btn" onclick="supprimerCommentaireAudit('${c.uid}')">${icone('x')} Supprimer</button>
        </div>
      </div>`;
    }
    const bouton = (verdict) => {
      const v = VERDICTS_RETOUR_OUTIL2[verdict];
      return `<button type="button" class="audit-verdict-btn" onclick="ouvrirCommentaireAudit('${c.uid}', '${verdict}')">${icone(v.icone)}${v.texte}</button>`;
    };
    return `<div class="audit-commentaire audit-commentaire-choix">
      <span class="audit-commentaire-question">Votre avis :</span>
      ${bouton('juste')}${bouton('faux_positif')}${bouton('mal_formule')}${bouton('gravite')}
    </div>`;
  }

  function renderFormCommentaireAudit(c, f) {
    const choix = ['juste', 'faux_positif', 'mal_formule', 'gravite'].map(verdict => {
      const v = VERDICTS_RETOUR_OUTIL2[verdict];
      return `<button type="button" class="audit-verdict-btn${f.verdict === verdict ? ' actif' : ''}" onclick="changerVerdictCommentaireAudit('${verdict}')">${icone(v.icone)}${v.texte}</button>`;
    }).join('');
    const gravites = ['CRITIQUE', 'IMPORTANT', 'A_VERIFIER', 'INFORMATION']
      .map(gr => `<option value="${gr}" ${f.gravite === gr ? 'selected' : ''}>${escapeHtml(libelleGraviteAudit(gr).texte)}</option>`).join('');
    const aide = {
      juste: 'Pourquoi ce point est utile (facultatif)',
      faux_positif: 'Pourquoi ce point ne devait pas sortir — ex. « la clause parle de la vente précédente »',
      mal_formule: 'Comment le formuler, ou ce qui est inexact dans le texte',
      gravite: 'Pourquoi cette gravité'
    }[f.verdict] || '';
    return `<div class="audit-commentaire audit-commentaire-form">
      <div class="audit-commentaire-choix">${choix}</div>
      ${f.verdict === 'gravite' ? `<label class="audit-commentaire-ligne">Gravité juste : <select id="audit-com-gravite" onchange="formCommentaireAudit.gravite = this.value">${gravites}</select></label>` : ''}
      <div class="audit-commentaire-ligne" role="radiogroup" aria-label="Portée du commentaire">
        <label><input type="radio" name="audit-com-portee" value="dossier" ${f.portee === 'dossier' ? 'checked' : ''} onchange="formCommentaireAudit.portee = 'dossier'"> Ce dossier seulement</label>
        <label><input type="radio" name="audit-com-portee" value="tous" ${f.portee === 'tous' ? 'checked' : ''} onchange="formCommentaireAudit.portee = 'tous'"> Tous les dossiers</label>
      </div>
      <textarea id="audit-com-texte" rows="2" placeholder="${escapeAttr(aide)}" oninput="formCommentaireAudit.texte = this.value">${escapeHtml(f.texte || '')}</textarea>
      <div class="audit-commentaire-actions">
        <button type="button" class="secondary" onclick="fermerCommentaireAudit()">Annuler</button>
        <button type="button" class="primary" onclick="enregistrerCommentaireAudit()">Enregistrer</button>
      </div>
    </div>`;
  }

  // Une obligation du vendeur en mode « projet de vente », rendue en TROIS COLONNES — demande
  // explicite de l'étude : « mettre côte à côte la clause d'engagement de l'avant-contrat et la
  // clause d'engagement de la vente tenue avec le justificatif ». C'est exactement le geste de
  // relecture : lire l'engagement pris, ce que le projet en dit, et ce qui le prouve, sans avoir à
  // faire l'aller-retour entre deux PDF.
  //   1. Avant-contrat : la clause telle qu'elle engage le vendeur (toujours présente, c'est elle
  //      qui a fait naître la ligne) ;
  //   2. Projet de vente : la clause correspondante s'il en porte une, sinon le vide, dit comme tel
  //      — une obligation que le projet ne reprend pas est un signal en soi ;
  //   3. Justificatif : la pièce qui l'établit et sa date contrôlée.
  // Les obligations TENUES sont affichées elles aussi : savoir ce qui est en règle fait partie de
  // la relecture, et c'est ce qui distingue une obligation vérifiée d'une obligation qu'on a
  // simplement oublié de regarder.
  function colonneObligation(titre, corps, vide) {
    return `<div class="obligation-col${vide ? ' obligation-col-vide' : ''}">
      <span class="section-eyebrow">${escapeHtml(titre)}</span>
      <div class="obligation-col-corps">${corps}</div>
    </div>`;
  }

  function citationObligation(texte, page, limite) {
    if (!texte) return '';
    const t = String(texte);
    const coupe = t.length > (limite || 320) ? t.slice(0, (limite || 320) - 3) + '…' : t;
    return `<blockquote class="obligation-clause">${page ? `<span class="obligation-page">p.${page}</span>` : ''}${escapeHtml(coupe)}</blockquote>`;
  }

  function renderObligationAudit(o) {
    const etat = LIBELLES_STATUT_OBLIGATION_OUTIL2[o.statut] || LIBELLES_STATUT_OBLIGATION_OUTIL2.a_verifier;
    const g = libelleGraviteAudit(etat.gravite);
    const badge = `<span class="dot-label ${etat.dl}">${icone(o.statut === 'tenue' ? 'check' : g.icone)}${etat.texte}</span>`;
    const cat = LIBELLES_CAT_OBLIGATION[o.type] ? `<span class="engagement-type ${escapeAttr(o.type)}">${LIBELLES_CAT_OBLIGATION[o.type]}</span>` : '';

    const colAvant = colonneObligation("Avant-contrat — engagement pris",
      o.clause ? citationObligation(o.clause, o.page)
               : `<p class="obligation-vide">Clause non retrouvée.</p>`,
      !o.clause);

    const colProjet = colonneObligation("Projet de vente — ce qu'il en dit",
      o.clauseProjet
        ? citationObligation(o.clauseProjet, o.pageProjet)
        : `<p class="obligation-vide">Le projet de vente ne reprend pas cet engagement.</p>`,
      !o.clauseProjet);

    let justif;
    if (o.preuve && o.preuve.source === 'depot') {
      justif = `<p class="obligation-preuve">${icone('file-text')}<em>${escapeHtml(o.preuve.nom)}</em></p>`
        + (o.preuve.date ? `<p class="obligation-preuve-date">Daté du ${escapeHtml(formatDateFr(o.preuve.date))}</p>` : '');
    } else if (o.preuve && o.preuve.source === 'dossier') {
      justif = `<p class="obligation-preuve">${icone('folder')}Déjà dans le dossier client${o.preuve.nom ? ' : <em>' + escapeHtml(o.preuve.nom) + '</em>' : ''}</p>`
        + `<p class="obligation-preuve-date">Fichier non lu ici : sa date reste à vérifier.</p>`;
    } else if (o.preuve && o.preuve.source === 'projet') {
      justif = `<p class="obligation-preuve">${icone('file-text')}Aucune pièce déposée</p>`
        + `<p class="obligation-preuve-date">Seule la mention du projet de vente l'établit${o.preuve.date ? ', datée du ' + escapeHtml(formatDateFr(o.preuve.date)) : ''}.</p>`;
    } else if (o.statut === 'non_tenue') {
      justif = `<p class="obligation-vide">Aucun justificatif déposé.</p>`;
    } else {
      justif = `<p class="obligation-vide">Engagement sans document type : à contrôler à la main.</p>`;
    }
    if (o.validite && o.validite.message && o.statut !== 'tenue') {
      justif += `<p class="obligation-validite">${escapeHtml(o.validite.message)}</p>`;
    } else if (o.validite && o.validite.statut === 'VALIDE') {
      justif += `<p class="obligation-preuve-date">${escapeHtml(o.validite.message)}</p>`;
    }
    const colJustif = colonneObligation('Justificatif', justif, !o.preuve);

    // Le liseré de gravité s'applique ici aussi : une obligation périmée est un constat critique,
    // elle ne doit pas porter le même filet qu'un simple « à vérifier » (défaut vu au rendu).
    const teinte = o.statut === 'tenue' ? ' obligation-tenue' : ` constat-${String(etat.gravite).toLowerCase()}`;
    const c = o.constatUid ? constatsAuditParUid[o.constatUid] : null;
    const pied = c ? (modeCommentairesAudit ? renderCommentaireConstatAudit(c) : renderRetourResumeAudit(c)) : '';
    const ancre = c ? ` id="audit-constat-${c.uid}"` : '';
    const corps = `<div class="analyse-ia-constat-titre">${badge}${cat}${escapeHtml(o.label || "Engagement du vendeur")}</div>
      <div class="obligation-cols">${colAvant}${colProjet}${colJustif}</div>
      ${pied}`;
    if (c && c.retour && c.retour.verdict === 'faux_positif') {
      const ouvert = formCommentaireAudit && formCommentaireAudit.uid === c.uid ? ' open' : '';
      return `<details class="analyse-ia-constat obligation-carte constat-ecarte${teinte}"${ancre}${ouvert}>
        <summary><span class="dot-label dl-neutre">${icone('x')}Faux positif ${c.retour.portee === 'dossier' ? 'pour ce dossier' : 'sur tous les dossiers'}</span>${escapeHtml(o.label || "Engagement du vendeur")}</summary>
        ${corps}
      </details>`;
    }
    return `<div class="analyse-ia-constat obligation-carte${teinte}"${ancre}>${corps}</div>`;
  }

  function renderSectionAudit(titre, liste, rendreItem, cleRubrique, ancre) {
    const items = Array.isArray(liste) ? liste.slice() : [];
    if (items.length === 0) return '';
    // Confirmés en tête, écartés en queue (repliés), le reste dans l'ordre déjà calculé.
    const rang = c => (c.memoire ? (c.memoire.decision === 'confirme' ? 0 : 2) : 1);
    items.sort((a, b) => rang(a) - rang(b));
    // Le bouton n'est proposé que sur les rubriques de constats : les tableaux (travaux,
    // obligations) portent justement la comparaison avant-contrat / projet, que l'étude a
    // désignée comme l'erreur lui coûtant le plus cher — rien à masquer là.
    const masquer = cleRubrique
      ? `<button type="button" class="audit-masquer" title="Ne plus afficher cette rubrique, sur cet audit et les suivants" onclick="basculerRubriqueAudit('${escapeOnclickArg(cleRubrique)}')">${icone('x')}Masquer</button>`
      : '';
    const id = cleRubrique || ancre;
    return `<section class="audit-section"${id ? ` id="audit-rub-${escapeAttr(id)}"` : ''}>
      <h3 class="audit-section-titre"><span class="section-eyebrow">${escapeHtml(titre)}</span><span class="audit-section-compte">${items.length}</span>${masquer}</h3>
      ${items.map(rendreItem).join('')}
    </section>`;
  }

  // Le rapport est organisé par SOURCE, dans l'ordre de lecture donné par l'étude : « lire le
  // contenu de l'acte de vente, PUIS comparer avec l'avant-contrat, PUIS avec les annexes ».
  //
  // Règle d'affectation, à garder en tête avant d'ajouter une catégorie : une section est définie
  // par le DOCUMENT qu'il faut ouvrir pour trancher le point. Un constat qui touche deux sources
  // n'apparaît QU'UNE fois, dans la section de la source la plus fragile (celle qui peut manquer)
  // — répéter le même constat dans deux sections recréerait la duplication que l'étude a déjà
  // fait retirer une fois.
  var SECTIONS_RAPPORT_OUTIL2 = [
    {
      cle: 'ACTE',
      titre: 'Ce que dit l’acte',
      source: 'Établi à partir du document principal seul.'
    },
    {
      cle: 'AVANT_CONTRAT',
      titre: 'Écarts avec l’avant-contrat',
      source: 'Établi en comparant le projet à l’avant-contrat signé.'
    },
    {
      cle: 'ANNEXES',
      titre: 'Ce que les annexes apportent',
      source: 'Établi à partir des pièces déposées avec l’acte.'
    }
  ];

  // Les catégories restent celles que produisent les détecteurs : seul leur regroupement change.
  // Sous-titres conservés à l'intérieur de chaque section — ils disent ce que le constat concerne,
  // là où la section dit d'où il vient.
  var SOUS_SECTIONS_RAPPORT_OUTIL2 = [
    { cle: 'ACTE', section: 'ACTE', titre: 'Déclarations et cohérence de l’acte' },
    { cle: 'PARTIES', section: 'ACTE', titre: 'Statut et quotités des acquéreurs' },
    { cle: 'TRAVAUX_REALISES', section: 'ACTE', titre: 'Travaux déjà réalisés sur le bien' },
    { cle: 'DIAGNOSTICS', section: 'ACTE', titre: 'Diagnostics' },
    { cle: 'ENTRETIENS', section: 'ACTE', titre: 'Entretiens à justifier' },
    { cle: 'DOCUMENTS', section: 'ACTE', titre: 'Documents à obtenir du vendeur' },
    { cle: 'TRAVAUX_A_FAIRE', section: 'ACTE', titre: 'Travaux à réaliser avant la vente' },
    { cle: 'COMPARAISON_COMPROMIS', section: 'AVANT_CONTRAT', titre: 'Différences relevées' },
    { cle: 'COPROPRIETE', section: 'ANNEXES', titre: 'Assemblées générales de copropriété' },
    { cle: 'CARNET_ENTRETIEN', section: 'ANNEXES', titre: 'Carnet d’entretien de l’immeuble' },
    { cle: 'ETAT_DATE', section: 'ANNEXES', titre: 'État daté / pré-état daté' },
    { cle: 'URBANISME', section: 'ANNEXES', titre: 'Certificat d’urbanisme' },
    { cle: 'PERMIS', section: 'ANNEXES', titre: 'Permis de construire (terrain à bâtir)' }
  ];

  // Le dernier rapport affiché, pour le redessiner après une décision sur un constat (ou après
  // l'arrivée des constats du modèle) sans relancer l'analyse ; chaque constat reçoit un
  // identifiant de rendu (uid) et sa décision mémorisée (memoire), posés par preparerRapportAudit.
  let dernierRapportAudit = null;
  let constatsAuditParUid = {};

  // Tout ce qu'il faut pour REJOUER l'analyse sans refaire le travail asynchrone (lecture des PDF,
  // récupération de l'avant-contrat sur le NAS) : c'est ce qui rend la correction du type de bien
  // instantanée. L'analyse elle-même est purement locale et synchrone, la rejouer ne coûte rien.
  let dernierAuditContexte = null;
  // Type de bien choisi à la main dans le rapport. Remis à zéro dès que les documents ou le mode
  // changent : il se rapporte à l'acte analysé, pas à la session.
  let typeBienAuditChoisi = null;


  function preparerRapportAudit(resultat) {
    constatsAuditParUid = {};
    let n = 0;
    for (const c of (resultat.constats || [])) {
      if (!c || typeof c !== 'object') continue;
      c.uid = `k${++n}`;
      constatsAuditParUid[c.uid] = c;
      const m = decisionPourConstat(c, memoireAuditConstats);
      c.memoire = m ? { id: m.id, decision: m.decision, nb: m.nb || 1 } : null;
    }
    // Les commentaires de l'étude s'appliquent ensuite (gravité corrigée, faux positif replié), et
    // le résumé comme les questions sont recalculés sur ce qui reste réellement retenu : un point
    // jugé faux positif ne doit plus gonfler le compteur ni produire une question au syndic.
    // Les engagements du vendeur s'affichent en cartes à trois colonnes (renderObligationAudit),
    // pas en constats : chaque carte retrouve le constat qu'elle représente pour porter son
    // commentaire et son repli.
    for (const o of (resultat.obligations || [])) {
      const c = (resultat.constats || []).find(x => x && x.categorie === 'OBLIGATIONS' && x.phrase === o.clause);
      o.constatUid = c ? c.uid : null;
    }
    appliquerRetoursAuxConstats(resultat.constats || [], retoursAudit, dernierAuditContexte ? dernierAuditContexte.dossierCle : '');
    resultat.resume = resumeConstatsOutil2(resultat.constats);
  }

  function decisionConstatAudit(uid, decision) {
    const c = constatsAuditParUid[uid];
    if (!c || !dernierRapportAudit) return;
    memoriserDecisionConstat(c, decision);
    preparerRapportAudit(dernierRapportAudit);
    renderRapportAuditActe(dernierRapportAudit);
    afficherToast(decision === 'ecarte'
      ? 'Constat écarté : il sera replié sur les prochains audits d’un acte similaire.'
      : 'Constat confirmé : il remontera en tête sur les prochains audits d’un acte similaire.', 'OK', null);
  }

  function annulerDecisionConstatAudit(uid) {
    const c = constatsAuditParUid[uid];
    if (!c || !c.memoire || !dernierRapportAudit) return;
    oublierDecisionConstat(c.memoire.id);
    preparerRapportAudit(dernierRapportAudit);
    renderRapportAuditActe(dernierRapportAudit);
  }

  // La fiche d'identité, en tête de la section 1 : ce que l'outil a compris de l'acte, TOUJOURS
  // affiché, y compris les lignes qu'il n'a pas trouvées. Sans elle, un rapport sans constat ne
  // dit pas si l'acte a été lu ou seulement traversé — c'est exactement ce qui manquait sur le
  // projet réel envoyé par l'étude, où le rapport ne portait que « vous ne m'avez pas donné le
  // document ». Une valeur absente s'affiche « non trouvé » : jamais devinée, jamais complétée.
  function renderFicheActe(fiche) {
    const lignes = Array.isArray(fiche) ? fiche : [];
    if (lignes.length === 0) return '';
    const cases = lignes.map(l => `<div class="fiche-acte-case">
      <span class="fiche-acte-libelle">${escapeHtml(l.libelle)}</span>
      <span class="fiche-acte-valeur${l.valeur ? '' : ' fiche-acte-absent'}">${escapeHtml(l.valeur || 'non trouvé')}</span>
      ${l.page ? `<span class="fiche-acte-page">p.${escapeHtml(String(l.page))}</span>` : ''}
    </div>`).join('');
    return `<div class="fiche-acte">${cases}</div>`;
  }

  // Le TABLEAU des travaux déclarés — demandé par l'étude : « lister les travaux et vérifier s'ils
  // sont déclarés, s'il y a des factures et s'il y a les assurances décennales ». Les constats ne
  // suffisaient pas : ils ne parlent que du gros œuvre et de l'extérieur, si bien qu'une rénovation
  // intérieure n'apparaissait nulle part — rien n'était « listé ».
  //
  // Les trois colonnes sont lues DANS L'ACTE et lui seul (arbitrage explicite de l'étude : ce que
  // l'acte affirme fait foi, l'outil ne va pas vérifier qu'une autorisation ou une facture est
  // effectivement déposée en pièce). Un tiret « — » signifie « sans objet », un point
  // d'interrogation « impossible à dire », et c'est une information différente d'une croix.
  function celluleTravailAudit(etat, titre) {
    const table = {
      oui: { txt: '✓', cls: 'travaux-oui' },
      non: { txt: '✕', cls: 'travaux-non' },
      na: { txt: '—', cls: 'travaux-na' },
      inconnu: { txt: '?', cls: 'travaux-na' }
    };
    const c = table[etat] || table.inconnu;
    return `<td class="${c.cls}"${titre ? ` title="${escapeAttr(titre)}"` : ''}>${c.txt}</td>`;
  }

  function ligneTravailAudit(t) {
    const autorisation = !t.soumisAutorisation ? 'na' : (t.autorisationMentionnee ? 'oui' : 'non');
    const facture = t.factureMentionnee ? 'oui' : 'non';
    // La décennale ne se pose que sur un travail de moins de dix ans : au-delà elle est éteinte,
    // et réclamer l'attestation n'aurait plus d'objet.
    const decennale = t.sousDecennale === null ? 'inconnu' : (!t.sousDecennale ? 'na' : (t.decennaleMentionnee ? 'oui' : 'non'));
    return `<tr>
      <td class="travaux-libelle">${escapeHtml(t.libelle || t.phrase || '')}${t.page ? `<span class="travaux-page">p.${escapeHtml(String(t.page))}</span>` : ''}</td>
      <td class="travaux-annee">${t.annee ? escapeHtml(String(t.annee)) : '—'}</td>
      ${celluleTravailAudit(autorisation, t.soumisAutorisation ? "Autorisation d'urbanisme mentionnée dans l'acte" : "Travaux sans incidence sur la structure ni l'extérieur : aucune autorisation exigible")}
      ${celluleTravailAudit(facture, "Facture ou devis mentionné dans l'acte")}
      ${celluleTravailAudit(decennale, t.sousDecennale === null ? "Année non précisée : impossible de savoir si la garantie court encore" : (!t.sousDecennale ? 'Travaux de plus de dix ans : garantie décennale éteinte' : "Attestation d'assurance décennale mentionnée dans l'acte"))}
    </tr>`;
  }

  function renderTableauTravauxAudit(titre, travaux, note) {
    const liste = Array.isArray(travaux) ? travaux : [];
    if (liste.length === 0) return '';
    return `<section class="audit-section">
      <h3 class="audit-section-titre"><span class="section-eyebrow">${escapeHtml(titre)}</span><span class="audit-section-compte">${liste.length}</span></h3>
      ${note ? `<p class="hint">${escapeHtml(note)}</p>` : ''}
      <div class="travaux-table-wrap">
        <table class="travaux-table">
          <thead><tr><th>Travaux déclarés</th><th>Année</th><th>Autorisation</th><th>Facture</th><th>Décennale</th></tr></thead>
          <tbody>${liste.map(ligneTravailAudit).join('')}</tbody>
        </table>
      </div>
    </section>`;
  }

  // Un bloc = une SOURCE. Il porte son titre, la phrase qui dit d'où viennent ses constats, puis
  // ses sous-sections. Quand il n'a rien à montrer il ne se tait pas : il dit POURQUOI (aucune
  // annexe déposée, aucun écart relevé…). Se taire ferait lire « rien à signaler » là où il faut
  // lire « rien n'a pu être contrôlé » — la confusion même que l'étude a signalée.
  function renderBlocAudit(bloc, resultat, constats) {
    let corps = '';
    let vide = true;

    if (bloc.cle === 'ACTE') {
      const fiche = renderFicheActe(resultat.fiche);
      if (fiche) { corps += fiche; vide = false; }
      // Le tableau des travaux appartient à la section de la source où ils ont été LUS : ici
      // l'acte relu en mode « compromis », l'avant-contrat en mode « projet de vente » (bloc
      // AVANT_CONTRAT ci-dessous). Un même tableau dans les deux sections dirait deux fois la
      // même chose, et dans la mauvaise moitié du rapport une fois sur deux.
      if (resultat.mode !== 'acte') {
        const t = renderTableauTravauxAudit('Travaux déclarés dans l’acte', resultat.travaux,
          "Lu dans l'acte seul : une colonne cochée signifie que l'acte le mentionne, pas que la pièce est déposée.");
        if (t) { corps += t; vide = false; }
      }
    }

    // Mode « projet de vente » : le tableau des obligations ouvre la section « avant-contrat »
    // — c'est bien une comparaison (l'engagement pris ‖ ce que le projet en dit ‖ le justificatif)
    // et il remplace la catégorie OBLIGATIONS des constats, qui redirait la même chose.
    if (bloc.cle === 'AVANT_CONTRAT' && resultat.mode === 'acte' && (resultat.obligations || []).length) {
      corps += renderSectionAudit('Engagements du vendeur — avant-contrat, projet, justificatif',
        resultat.obligations, renderObligationAudit, null, 'OBLIGATIONS');
      vide = false;
    }

    if (bloc.cle === 'AVANT_CONTRAT' && resultat.mode === 'acte') {
      const t = renderTableauTravauxAudit('Travaux déclarés dans l’avant-contrat', resultat.travaux,
        "Lu dans l'avant-contrat seul : une colonne cochée signifie qu'il le mentionne, pas que la pièce est déposée.");
      if (t) { corps += t; vide = false; }
    }

    if (bloc.cle === 'ANNEXES') {
      const t = renderTableauTravauxAudit('Travaux recensés au carnet d’entretien', resultat.travauxCarnet,
        "Relevés dans le carnet d'entretien de l'immeuble : à croiser avec les assemblées générales et les autorisations d'urbanisme.");
      if (t) { corps += t; vide = false; }
    }

    let nbMasquees = 0;
    for (const sous of SOUS_SECTIONS_RAPPORT_OUTIL2) {
      if (sous.section !== bloc.cle) continue;
      const items = constats.filter(c => c.categorie === sous.cle);
      if (items.length === 0) continue;
      if (rubriqueMasqueeAudit(sous.cle)) { nbMasquees++; continue; }
      const html = renderSectionAudit(sous.titre, items, renderConstatAudit, sous.cle);
      if (html) { corps += html; vide = false; }
    }

    // Une section vidée par un MASQUAGE ne dit pas « rien à signaler » : ce serait faux, et c'est
    // exactement la confusion que ce rapport combat ailleurs (« rien à signaler » lu à la place de
    // « rien n'a pu être contrôlé »).
    if (vide) {
      corps = nbMasquees
        ? `<p class="hint">${nbMasquees} rubrique(s) masquée(s) dans cette section — à réafficher en bas du rapport.</p>`
        : `<p class="hint">${escapeHtml(messageBlocAuditVide(bloc, resultat))}</p>`;
    }

    return `<section class="audit-bloc" id="audit-bloc-${escapeAttr(bloc.cle)}">
      <h2 class="audit-bloc-titre">${escapeHtml(bloc.titre)}</h2>
      <p class="audit-bloc-source">${escapeHtml(bloc.source)}</p>
      ${corps}
    </section>`;
  }

  function messageBlocAuditVide(bloc, resultat) {
    if (bloc.cle === 'AVANT_CONTRAT') {
      // Sans avant-contrat de référence, il n'y a pas « aucun écart » : il n'y a eu AUCUNE
      // comparaison. Les confondre reviendrait à rassurer l'étude sur le point qu'elle a désigné
      // comme lui ayant coûté le plus cher.
      if (!resultat.comparaisonFaite) {
        return "Aucun avant-contrat de référence : liez le dossier CLAIRE ou déposez le compromis signé pour que les parties, le prix, la désignation du bien et les dates soient comparés.";
      }
      return "Aucun écart relevé entre l'avant-contrat et le projet, et aucun engagement du vendeur repéré dans l'avant-contrat.";
    }
    if (bloc.cle === 'ANNEXES') {
      if (resultat.nbJustificatifs) {
        return "Rien à signaler dans les pièces déposées, pour les seuls points contrôlés par l'outil.";
      }
      // La liste des pièces citées dépend du TYPE DE BIEN : annoncer un état daté et des
      // procès-verbaux d'assemblée sur une maison ferait croire à un contrôle qui n'a pas lieu
      // d'être, et taire le carnet d'entretien sur une copropriété en ferait manquer un.
      const attendues = resultat.typeBien === 'copropriete'
        ? "les diagnostics, l'état daté, le certificat d'urbanisme, les procès-verbaux d'assemblée et le carnet d'entretien"
        : resultat.typeBien === 'terrain'
          ? "les diagnostics, le certificat d'urbanisme, le permis de construire et son constat d'affichage"
          : "les diagnostics et le certificat d'urbanisme";
      return `Aucune annexe déposée : ${attendues} n'ont pas pu être contrôlés.`;
    }
    return "Rien à signaler dans le document principal, pour les seuls points contrôlés par l'outil.";
  }

  // Détail des contrôles AUTOMATIQUES de CLAIRE (règles déterministes, sans IA) : il vit désormais
  // dans le tableau de bord de la relecture, sous la grille de Claude (voir renderTableauDeBordRelecture).
  // Le point d'entrée garde son nom : tout ce qui modifie un constat (décision, commentaire, type
  // de bien) le rappelle pour redessiner.
  function renderRapportAuditActe() {
    renderTableauDeBordRelecture();
  }

  function renderPartiesDossierAudit(resultat) {
    const d = auditDossierLie;
    const ctx = dernierAuditContexte;
    if (!d || !ctx || resultat.mode !== 'acte' || !ctx.entree || !ctx.entree.reference) return '';
    const texte = (ctx.entree.reference.parties || []);
    if (!ctx.referenceLueDansTexte || !partiesDivergentes(d.parties, texte)) return '';
    const liste = texte.map(p => `${p.nom} (${String(p.role || '').toLowerCase()})`).join(', ');
    return `<p class="audit-ecarts audit-ecarts-alerte"><span class="dot-label dl-pret">${icone('info')}Fiche à mettre à jour</span>
      Les parties enregistrées sur le dossier ne sont pas celles lues dans l'avant-contrat : ${escapeHtml(liste)}. La relecture s'appuie sur l'avant-contrat.
      <button type="button" class="action-rapide" onclick="mettreAJourPartiesDossierAudit()">Mettre à jour la fiche</button></p>`;
  }

  // Seule écriture sur le dossier lié depuis cet écran, et seulement sur un clic confirmé : la
  // relecture reste en lecture seule sur tout le reste.
  function mettreAJourPartiesDossierAudit() {
    const d = auditDossierLie;
    const ctx = dernierAuditContexte;
    if (!d || !ctx || !ctx.entree || !ctx.entree.reference) return;
    const parties = (ctx.entree.reference.parties || []).map(p => ({
      nom: p.nom, qualiteActe: p.qualiteActe, role: p.role,
      qualitePersonne: p.qualitePersonne || 'physique', representant: p.representant || null,
      ...(p.nomUsage ? { nomUsage: p.nomUsage } : {})
    }));
    if (!parties.length) return;
    demanderConfirmation("Remplacer les parties de la fiche par celles lues dans l'avant-contrat ? Le nom du dossier n'est pas modifié.", () => {
      d.parties = parties;
      ajouterHistorique(d, "Parties mises à jour depuis l'avant-contrat relu (Relecture d'actes)");
      sauvegarder(d);
      afficherToast('Fiche du dossier mise à jour.', 'OK', null);
      if (dernierRapportAudit) renderRapportAuditActe(dernierRapportAudit);
    });
  }

  // ---- Commentaires : état, panneau, actions --------------------------------------------------
  const CLE_MODE_COMMENTAIRES_AUDIT = 'audit-mode-commentaires';
  let modeCommentairesAudit = false;
  try { modeCommentairesAudit = localStorage.getItem(CLE_MODE_COMMENTAIRES_AUDIT) === '1'; } catch (e) { /* navigation privée */ }
  let retoursAudit = [];
  let formCommentaireAudit = null; // { uid, verdict, portee, gravite, texte, id }
  let texteOubliAudit = '';
  let porteeOubliAudit = 'dossier';

  async function chargerRetoursAudit() {
    try {
      const reponse = await fetchAvecAuth('/api/audit-retours');
      if (!reponse.ok) throw new Error('statut ' + reponse.status);
      const data = await reponse.json();
      retoursAudit = Array.isArray(data.retours) ? data.retours : [];
    } catch (e) {
      console.warn('Commentaires de relecture indisponibles', e);
    }
    return retoursAudit;
  }

  async function basculerModeCommentairesAudit(actif) {
    modeCommentairesAudit = !!actif;
    try { localStorage.setItem(CLE_MODE_COMMENTAIRES_AUDIT, actif ? '1' : '0'); } catch (e) { /* sans importance */ }
    formCommentaireAudit = null;
    if (actif) await chargerRetoursAudit();
    if (dernierRapportAudit) { preparerRapportAudit(dernierRapportAudit); renderRapportAuditActe(dernierRapportAudit); }
  }

  function retoursDuDossierAudit() {
    const cle = dernierAuditContexte ? dernierAuditContexte.dossierCle : '';
    return retoursAudit.filter(r => r.verdict === 'manque' && (r.portee === 'tous' || (cle && r.dossierCle === cle)));
  }

  function renderPanneauCommentairesAudit() {
    const oublis = retoursDuDossierAudit();
    return `<section class="audit-panneau-commentaires">
      <div class="audit-panneau-tete">
        <div>
          <strong>Mode commentaires ${infoBulle("Sous chaque point : « Juste », « Faux positif », « Mal formulé » ou « Gravité à revoir », avec votre justification. Un faux positif est replié tout de suite (pour ce dossier ou pour tous) ; l'ensemble sert ensuite à corriger les règles de la relecture.")}</strong>
        </div>
        <button type="button" class="action-rapide" onclick="exporterRetoursAudit()">${icone('download')}Exporter les commentaires (${retoursAudit.length})</button>
      </div>
      <label for="audit-oubli-texte" class="audit-commentaire-question">Ce que la relecture a raté</label>
      <textarea id="audit-oubli-texte" rows="2" placeholder="Ex. « la servitude de passage page 14 n'est pas signalée »" oninput="texteOubliAudit = this.value">${escapeHtml(texteOubliAudit)}</textarea>
      <div class="audit-commentaire-ligne">
        <label><input type="radio" name="audit-oubli-portee" ${porteeOubliAudit === 'dossier' ? 'checked' : ''} onchange="porteeOubliAudit = 'dossier'"> Ce dossier seulement</label>
        <label><input type="radio" name="audit-oubli-portee" ${porteeOubliAudit === 'tous' ? 'checked' : ''} onchange="porteeOubliAudit = 'tous'"> Tous les dossiers</label>
        <button type="button" class="secondary audit-oubli-btn" onclick="enregistrerOubliAudit()">Signaler l'oubli</button>
      </div>
      ${oublis.length ? `<ul class="audit-oublis">${oublis.map(r => `<li><span class="dot-label dl-urgent">${icone('info')}${r.portee === 'dossier' ? 'Ce dossier' : 'Tous'}</span><span>${escapeHtml(r.commentaire)}</span><button type="button" class="piece-suppr" onclick="supprimerRetourAudit('${escapeOnclickArg(r.id)}')" title="Supprimer" aria-label="Supprimer">${icone('x')}</button></li>`).join('')}</ul>` : ''}
    </section>`;
  }

  function ouvrirCommentaireAudit(uid, verdict) {
    const c = constatsAuditParUid[uid];
    if (!c) return;
    formCommentaireAudit = { uid, verdict, portee: 'dossier', gravite: c.gravite, texte: '', id: null };
    if (dernierRapportAudit) renderRapportAuditActe(dernierRapportAudit);
    const champ = document.getElementById('audit-com-texte');
    if (champ) champ.focus();
  }

  function modifierCommentaireAudit(uid) {
    const c = constatsAuditParUid[uid];
    if (!c || !c.retour) return;
    formCommentaireAudit = { uid, verdict: c.retour.verdict, portee: c.retour.portee,
      gravite: c.retour.graviteSouhaitee || c.gravite, texte: c.retour.commentaire || '', id: c.retour.id };
    if (dernierRapportAudit) renderRapportAuditActe(dernierRapportAudit);
  }

  function changerVerdictCommentaireAudit(verdict) {
    if (!formCommentaireAudit) return;
    formCommentaireAudit.verdict = verdict;
    if (dernierRapportAudit) renderRapportAuditActe(dernierRapportAudit);
  }

  function fermerCommentaireAudit() {
    formCommentaireAudit = null;
    if (dernierRapportAudit) renderRapportAuditActe(dernierRapportAudit);
  }

  function contexteRetourAudit() {
    const ctx = dernierAuditContexte || {};
    const r = dernierRapportAudit || {};
    return { dossierCle: ctx.dossierCle || '', dossierNom: ctx.dossierNom || '', document: ctx.documentPrincipal || '',
      mode: r.mode || 'compromis', typeBien: r.typeBien || '', date: new Date().toISOString() };
  }

  async function publierRetourAudit(retour) {
    const reponse = await fetchAvecAuth('/api/audit-retours', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(retour)
    });
    if (!reponse.ok) {
      const corps = await reponse.json().catch(() => ({}));
      throw new Error(corps.erreur || 'statut ' + reponse.status);
    }
    const data = await reponse.json();
    retoursAudit = retoursAudit.filter(x => x.id !== data.retour.id).concat([data.retour]);
    return data.retour;
  }

  function rafraichirApresCommentaireAudit() {
    if (!dernierRapportAudit) return;
    preparerRapportAudit(dernierRapportAudit);
    renderRapportAuditActe(dernierRapportAudit);
  }

  async function enregistrerCommentaireAudit() {
    const f = formCommentaireAudit;
    const c = f && constatsAuditParUid[f.uid];
    if (!c) return;
    const retour = {
      ...contexteRetourAudit(),
      id: f.id || undefined,
      verdict: f.verdict,
      portee: f.portee,
      commentaire: String(f.texte || '').trim(),
      graviteSouhaitee: f.verdict === 'gravite' ? f.gravite : null,
      empreinte: empreinteTexteConstat(c),
      constat: { categorie: c.categorie, gravite: c.graviteOrigine || c.gravite, titre: c.titre,
        description: c.description || '', phrase: c.phrase || '', page: c.page || null }
    };
    try {
      await publierRetourAudit(retour);
      formCommentaireAudit = null;
      rafraichirApresCommentaireAudit();
      afficherToast(f.verdict === 'faux_positif'
        ? (f.portee === 'dossier' ? 'Faux positif noté : replié pour ce dossier.' : 'Faux positif noté : replié sur tous les dossiers.')
        : 'Commentaire enregistré.', 'OK', null);
    } catch (e) {
      afficherToast("Le commentaire n'a pas pu être enregistré : " + e.message, 'OK', null);
    }
  }

  async function supprimerRetourAudit(id) {
    try {
      const reponse = await fetchAvecAuth('/api/audit-retours/' + encodeURIComponent(id), { method: 'DELETE' });
      if (!reponse.ok && reponse.status !== 404) throw new Error('statut ' + reponse.status);
      retoursAudit = retoursAudit.filter(r => r.id !== id);
      rafraichirApresCommentaireAudit();
    } catch (e) {
      afficherToast('Suppression impossible : ' + e.message, 'OK', null);
    }
  }

  function supprimerCommentaireAudit(uid) {
    const c = constatsAuditParUid[uid];
    if (c && c.retour) supprimerRetourAudit(c.retour.id);
  }

  async function enregistrerOubliAudit() {
    const texte = String(texteOubliAudit || '').trim();
    if (!texte) {
      afficherToast("Décrivez ce que la relecture aurait dû signaler.", 'OK', null);
      return;
    }
    try {
      await publierRetourAudit({ ...contexteRetourAudit(), verdict: 'manque', portee: porteeOubliAudit, commentaire: texte });
      texteOubliAudit = '';
      rafraichirApresCommentaireAudit();
      afficherToast('Oubli signalé.', 'OK', null);
    } catch (e) {
      afficherToast("L'oubli n'a pas pu être enregistré : " + e.message, 'OK', null);
    }
  }

  // L'export est ce qui permet de corriger les règles : le fichier est relu, commentaire par
  // commentaire, et chaque correction de règle part de là (jamais une règle réécrite toute seule).
  // Il contient les clauses citées des actes : à transmettre comme les actes eux-mêmes.
  async function exporterRetoursAudit() {
    await chargerRetoursAudit();
    const contenu = JSON.stringify({ application: 'CLAIRE', version: VERSION_APP, exporteLe: new Date().toISOString(), retours: retoursAudit }, null, 2);
    const url = URL.createObjectURL(new Blob([contenu], { type: 'application/json' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `commentaires-relecture-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 5000);
  }

  // ==== OUTIL 2 v3 : RELECTURE EN QUATRE ÉTAPES (Documents → Pseudonymisation → Analyse → Bilan) ====
  //
  // Demande de l'étude (24/09/2026) : reprendre le cœur du prototype « Notariat IA » (API Claude,
  // grille de relecture), l'adapter au projet d'avant-contrat ET au projet de vente, présenter la
  // relecture « sous forme d'étapes », finir sur « une carte de santé de l'acte » (validé / à
  // surveiller / critique) sans e-mail rédigé, permettre de voir le projet en cliquant sur les
  // numéros de page, donner accès à tout le dossier du NAS (pas seulement la rubrique AAE), gérer
  // deux copropriétés dans un même acte, et afficher le coût de l'analyse.
  //
  // Les contrôles AUTOMATIQUES de CLAIRE (règles déterministes, voir analyserCompromisOutil2 /
  // analyserProjetVenteOutil2) tournent toujours, en local et sans coût : ils forment une section
  // du bilan, et restent le seul résultat quand aucune clé API n'est configurée.

  let etapeRelecture = 1;
  let anonymisationRelecture = null;   // { documents, table, sources }
  let termesManuelsRelecture = [];     // [{ terme, categorie }]
  let valeursEnClairRelecture = [];    // valeurs que l'étude a choisi de ne pas masquer
  let etatClaudeRelecture = null;      // { configure, modele }
  let estimationRelecture = null;      // { jetonsEntree, coutEstime } | { erreur }
  let analyseClaudeRelecture = null;   // réponse de Claude, ré-identifiée
  let factureRelecture = null;
  let erreurClaudeRelecture = '';
  let analyseEnCoursRelecture = false;
  let minuteurAnalyseRelecture = null;
  let documentsEnvoyesRelecture = [];  // [{ numero, fichierId }]
  let citationsRelecture = [];         // registre pour les pastilles de page cliquables
  let constatsClaudeRelecture = [];    // lignes de Claude au format « constat » (commentaires)
  let journalCoutRelecture = null;
  let pageApercuRelecture = { doc: 0, page: 0 };
  let typeBienEnvoyeRelecture = '';    // type de bien pour lequel la grille a été posée
  let idRelectureEnregistree = null;   // bilan affiché, tel qu'enregistré dans la base
  let relectureArchiveeOuverte = null; // { id, createdAt } quand on relit une analyse passée
  let historiqueRelectures = null;     // liste des analyses enregistrées (métadonnées)

  var LIBELLES_ETAPES_RELECTURE = ['Documents', 'Pseudonymisation', 'Analyse', 'Bilan'];

  function initRelecture() {
    chargerHistoriqueRelectures();
    renderStepperRelecture();
    renderListeFichiersAnalyseIa();
    renderDossierLieAudit();
    changerAuditModeTexteSeul();
    chargerJournalCoutRelecture();
  }

  function changerAuditModeTexteSeul() {
    const aide = document.getElementById('audit-aide-mode');
    if (aide) aide.textContent = auditMode === 'acte'
      ? `Le projet est relu point par point (${grillePourModeOutil2('acte').length} points) et comparé à l'avant-contrat signé : parties, prix, désignation, conditions levées, engagements du vendeur tenus.`
      : `Le projet d'avant-contrat est relu point par point (${grillePourModeOutil2('compromis').length} points) : parties, bien, diagnostics, copropriété, délais et clauses, urbanisme, volet financier.`;
  }

  function definirEtapeRelecture(n) {
    const cible = Math.max(1, Math.min(4, n));
    // Quitter une analyse enregistrée pour revenir aux étapes : on retrouve la relecture en cours
    // de préparation, jamais un mélange des deux.
    if (relectureArchiveeOuverte && cible < 4) fermerRelectureArchivee();
    if (cible >= 2 && !relectureArchiveeOuverte && !fichiersAnalyseIa.some(f => f.type === 'principal' && f.statut === 'ok')) {
      afficherToast('Ajoutez d’abord le document à relire (type « Document à relire »), et attendez sa lecture.', 'OK', null);
      return;
    }
    if (cible >= 3 && !anonymisationRelecture && !relectureArchiveeOuverte) preparerAnonymisationRelecture();
    if (cible === 4 && !dernierRapportAudit && !relectureArchiveeOuverte) {
      afficherToast("Lancez d'abord l'analyse.", 'OK', null);
      return;
    }
    etapeRelecture = cible;
    for (let i = 1; i <= 4; i++) {
      const panneau = document.getElementById('relecture-etape-' + i);
      if (panneau) panneau.style.display = i === cible ? '' : 'none';
    }
    renderStepperRelecture();
    if (cible === 2) { preparerAnonymisationRelecture(); renderAnonymisationRelecture(); }
    if (cible === 3) renderEtapeAnalyseRelecture();
    if (cible === 4) renderTableauDeBordRelecture();
    const tete = document.getElementById('relecture-stepper');
    if (tete && tete.scrollIntoView && window.scrollY > 200) tete.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function renderStepperRelecture() {
    const el = document.getElementById('relecture-stepper');
    if (!el) return;
    el.innerHTML = LIBELLES_ETAPES_RELECTURE.map((lib, i) => {
      const n = i + 1;
      const etat = n === etapeRelecture ? 'actif' : (n < etapeRelecture ? 'fait' : '');
      return `<button type="button" class="relecture-step ${etat}" onclick="definirEtapeRelecture(${n})" ${n === etapeRelecture ? 'aria-current="step"' : ''}>
        <span class="relecture-step-num">${n < etapeRelecture ? icone('check') : n}</span>
        <span class="relecture-step-libelle">${lib}</span>
      </button>`;
    }).join('<span class="relecture-step-trait" aria-hidden="true"></span>');
  }

  // Un changement de documents (ajout, retrait, type) invalide tout ce qui suit : la table de
  // pseudonymisation et, a fortiori, l'analyse. On ne garde jamais un bilan qui ne correspond plus
  // aux pièces affichées.
  function invaliderSuiteRelecture() {
    anonymisationRelecture = null;
    estimationRelecture = null;
    analyseClaudeRelecture = null;
    factureRelecture = null;
    erreurClaudeRelecture = '';
    dernierRapportAudit = null;
    constatsClaudeRelecture = [];
    idRelectureEnregistree = null;
    if (etapeRelecture > 1) { etapeRelecture = 1; definirEtapeRelecture(1); }
  }

  // ---- Étape 1 : documents -------------------------------------------------------------------

  var ROLES_DOCUMENT_RELECTURE = {
    principal: 'Document à relire',
    reference_compromis: 'Avant-contrat de référence',
    justificatif: 'Annexe / pièce'
  };

  function renderListeFichiersAnalyseIa() {
    const conteneur = document.getElementById('analyse-ia-liste-fichiers');
    if (conteneur) {
      const groupes = [
        { titre: auditMode === 'acte' ? 'Projet d’acte de vente' : 'Projet d’avant-contrat', filtre: f => f.type === 'principal' },
        { titre: 'Avant-contrat signé (référence)', filtre: f => f.type === 'reference_compromis', seulementActe: true },
        { titre: 'Annexes et pièces', filtre: f => f.type !== 'principal' && f.type !== 'reference_compromis' }
      ];
      conteneur.innerHTML = groupes.map(g => {
        if (g.seulementActe && auditMode !== 'acte') return '';
        const liste = fichiersAnalyseIa.filter(g.filtre);
        let corps;
        if (!liste.length) {
          corps = `<p class="hint relecture-vide">${g.seulementActe ? "Aucun : liez le dossier CLAIRE (il est repris du NAS) ou déposez-le ici." : (g.titre.startsWith('Annexes') ? 'Aucune annexe : diagnostics, état daté, certificat d’urbanisme… ajoutez-les ou choisissez-les dans le dossier du NAS.' : 'Déposez le projet à relire.')}</p>`;
        } else if (g.titre.startsWith('Annexes')) {
          // Annexes regroupées par nature : c'est ce qui rend une vingtaine de pièces lisible.
          const parNature = new Map();
          for (const f of liste) {
            const n = f.nature || 'autre';
            if (!parNature.has(n)) parNature.set(n, []);
            parNature.get(n).push(f);
          }
          corps = Array.from(parNature.entries()).map(([n, fs]) => `<div class="relecture-nature">
            <span class="relecture-nature-titre">${escapeHtml(libelleNaturePieceOutil2(n))}<span class="audit-section-compte">${fs.length}</span></span>
            ${fs.map(ligneFichierRelecture).join('')}
          </div>`).join('');
        } else {
          corps = liste.map(ligneFichierRelecture).join('');
        }
        return `<div class="relecture-groupe"><span class="section-eyebrow">${escapeHtml(g.titre)}</span>${corps}</div>`;
      }).join('');
    }
    const viderBtn = document.getElementById('analyse-ia-vider-btn');
    if (viderBtn) viderBtn.style.display = fichiersAnalyseIa.length ? '' : 'none';
    const suivant = document.getElementById('relecture-suivant-1');
    if (suivant) {
      const principalPret = fichiersAnalyseIa.some(f => f.type === 'principal' && f.statut === 'ok');
      const enLecture = fichiersAnalyseIa.some(f => f.statut === 'lecture');
      suivant.disabled = !principalPret || enLecture;
      suivant.title = enLecture ? 'Lecture des documents en cours…' : (principalPret ? '' : 'Ajoutez le document à relire');
    }
  }

  function ligneFichierRelecture(f) {
    const annexes = f.annexesDepuisPage && f.pagesTotal
      ? `<span class="hint relecture-annexes-integrees">annexes jointes p.${f.annexesDepuisPage}–${f.pagesTotal}</span>` : '';
    const source = f.cheminNas ? `<span class="relecture-source" title="${escapeAttr(f.cheminNas)}">${icone('folder')}NAS</span>` : '';
    const options = Object.entries(ROLES_DOCUMENT_RELECTURE)
      .filter(([v]) => v !== 'reference_compromis' || auditMode === 'acte')
      .map(([v, lib]) => `<option value="${v}" ${v === (f.type === 'autre' ? 'justificatif' : f.type) ? 'selected' : ''}>${escapeHtml(lib)}</option>`).join('');
    return `<div class="analyse-ia-fichier">
      ${icone('file-text')}
      <span class="analyse-ia-fichier-nom" title="${escapeAttr(f.nom)}">${escapeHtml(f.nom)}${annexes}</span>
      ${source}
      <select onchange="changerTypeFichierAnalyseIa('${f.id}', this.value)" aria-label="Rôle du document">${options}</select>
      ${statutFichierAnalyseIa(f)}
      <button type="button" class="piece-suppr" onclick="retirerFichierAnalyseIa('${f.id}')" title="Retirer ce fichier" aria-label="Retirer ce fichier">${icone('x')}</button>
    </div>`;
  }

  // Le dossier du NAS en entier, rubrique par rubrique — la version précédente ne proposait que la
  // rubrique AAE. Présélection : la rubrique AAE (les pièces réunies depuis l'avant-contrat) et,
  // sur un projet de vente, l'avant-contrat retrouvé (voir choisirAvantContratNas).
  let parcoursNasRelecture = null; // { fichiers, coches:Set, avantContrat }

  async function ouvrirParcoursNasRelecture() {
    const d = auditDossierLie;
    const zone = document.getElementById('relecture-nas');
    if (!d || !zone) return;
    if (!d.nasDossier) {
      afficherToast("Ce dossier n'est pas encore relié à un dossier du NAS : reliez-le depuis sa fiche.", 'OK', null);
      return;
    }
    zone.style.display = '';
    zone.innerHTML = `<p class="hint">${icone('spinner', null, true)} Lecture du dossier du NAS…</p>`;
    try {
      const fichiers = await listerFichiersNas(d);
      const deja = new Set(fichiersAnalyseIa.map(f => f.cheminNas));
      const avantContrat = choisirAvantContratNas(fichiers, d.compromisNomFichier).fichier;
      const coches = new Set();
      for (const f of fichiers) {
        if (deja.has(cheminNasComplet(d, f.chemin))) continue;
        if (estDansRubriqueAAE(f.chemin)) coches.add(f.chemin);
        if (auditMode === 'acte' && avantContrat && f.chemin === avantContrat.chemin && !fichiersAnalyseIa.some(x => x.type === 'reference_compromis')) coches.add(f.chemin);
      }
      parcoursNasRelecture = { fichiers, coches, avantContrat: avantContrat ? avantContrat.chemin : null, deja };
      renderParcoursNasRelecture();
    } catch (e) {
      zone.innerHTML = `<p class="hint">${icone('alert-triangle')} Lecture du dossier du NAS impossible : ${escapeHtml(e.message)}</p>`;
    }
  }

  function rubriqueCheminNas(chemin) {
    const segments = String(chemin || '').split(/[\\/]/).filter(Boolean);
    return segments.length > 1 ? segments[0] : 'Racine du dossier';
  }

  function renderParcoursNasRelecture() {
    const zone = document.getElementById('relecture-nas');
    const p = parcoursNasRelecture;
    if (!zone || !p) return;
    if (!p.fichiers.length) { zone.innerHTML = '<p class="hint">Aucun PDF dans ce dossier du NAS.</p>'; return; }
    const d = auditDossierLie;
    const rubriques = new Map();
    for (const f of p.fichiers) {
      const r = rubriqueCheminNas(f.chemin);
      if (!rubriques.has(r)) rubriques.set(r, []);
      rubriques.get(r).push(f);
    }
    const noms = Array.from(rubriques.keys()).sort((a, b) => (a === 'Racine du dossier' ? -1 : b === 'Racine du dossier' ? 1 : a.localeCompare(b, 'fr', { numeric: true })));
    const blocs = noms.map((r, i) => {
      const fs = rubriques.get(r);
      const lignes = fs.map(f => {
        const deja = p.deja.has(cheminNasComplet(d, f.chemin));
        const coche = p.coches.has(f.chemin);
        const idCase = 'nas-f-' + i + '-' + fs.indexOf(f);
        const tag = f.chemin === p.avantContrat ? `<span class="dot-label dl-success">${icone('check')}Avant-contrat</span>` : '';
        return `<label class="relecture-nas-ligne${deja ? ' deja' : ''}" for="${idCase}">
          <input type="checkbox" id="${idCase}" ${coche ? 'checked' : ''} ${deja ? 'disabled' : ''} onchange="cocherFichierNasRelecture('${escapeOnclickArg(f.chemin)}', this.checked)">
          <span class="relecture-nas-nom">${escapeHtml(f.nom)}</span>
          <span class="relecture-nas-nature">${escapeHtml(libelleNaturePieceOutil2(classerNaturePieceOutil2(f.nom, '')))}</span>
          ${tag}${deja ? '<span class="hint">déjà ajouté</span>' : ''}
        </label>`;
      }).join('');
      const nbCoches = fs.filter(f => p.coches.has(f.chemin)).length;
      return `<details class="relecture-nas-rubrique" ${nbCoches || r === 'Racine du dossier' ? 'open' : ''}>
        <summary>${icone('folder')}<span>${escapeHtml(r)}</span><span class="audit-section-compte">${fs.length}</span>${nbCoches ? `<span class="hint">${nbCoches} coché(s)</span>` : ''}</summary>
        ${lignes}
      </details>`;
    }).join('');
    zone.innerHTML = `<div class="relecture-nas-tete">
        <span class="section-eyebrow">Dossier du NAS — ${escapeHtml(d.nasDossier || '')} ${infoBulle("Rubrique AAE et avant-contrat cochés d'office. Chaque PDF coché est lu dans ce navigateur (OCR si c'est un scan).")}</span>
        <div class="relecture-nas-actions">
          <button type="button" class="secondary" onclick="fermerParcoursNasRelecture()">Fermer</button>
          <button type="button" class="primary" onclick="ajouterSelectionNasRelecture()" ${p.coches.size ? '' : 'disabled'}>Ajouter la sélection (${p.coches.size})</button>
        </div>
      </div>
      ${blocs}`;
  }

  function cocherFichierNasRelecture(chemin, coche) {
    if (!parcoursNasRelecture) return;
    if (coche) parcoursNasRelecture.coches.add(chemin); else parcoursNasRelecture.coches.delete(chemin);
    renderParcoursNasRelecture();
  }

  function fermerParcoursNasRelecture() {
    parcoursNasRelecture = null;
    const zone = document.getElementById('relecture-nas');
    if (zone) { zone.style.display = 'none'; zone.innerHTML = ''; }
  }

  var MAX_PIECES_NAS_RELECTURE = 40;
  async function ajouterSelectionNasRelecture() {
    const p = parcoursNasRelecture;
    const d = auditDossierLie;
    if (!p || !d) return;
    const choisis = p.fichiers.filter(f => p.coches.has(f.chemin)).slice(0, MAX_PIECES_NAS_RELECTURE);
    const aPrincipal = fichiersAnalyseIa.some(f => f.type === 'principal');
    const nouvelles = choisis.map(f => {
      let type = 'justificatif';
      if (auditMode === 'acte' && f.chemin === p.avantContrat) type = 'reference_compromis';
      else if (!aPrincipal && auditMode === 'compromis' && f.chemin === p.avantContrat) type = 'principal';
      return {
        id: `analyse-ia-${++compteurFichierAnalyseIa}`,
        file: null, cheminNas: cheminNasComplet(d, f.chemin), nom: f.nom, type,
        nature: classerNaturePieceOutil2(f.nom, ''),
        statut: 'lecture', texte: '', pages: [], erreurTexte: '', pagesLues: null, pagesTotal: null, viaOcr: false, tronque: false
      };
    });
    fichiersAnalyseIa = fichiersAnalyseIa.concat(nouvelles);
    fermerParcoursNasRelecture();
    invaliderSuiteRelecture();
    renderListeFichiersAnalyseIa();
    // L'une après l'autre : un dossier de scans lancerait sinon une vingtaine d'OCR en parallèle.
    for (const entree of nouvelles) await extraireTexteFichierAnalyseIa(entree.id);
  }

  // Sur un projet de vente sans avant-contrat déposé, on le reprend du NAS du dossier lié avant de
  // pseudonymiser : Claude doit l'avoir sous les yeux pour comparer, pas seulement nos règles.
  async function completerAvantContratRelecture() {
    if (auditMode !== 'acte' || fichiersAnalyseIa.some(f => f.type === 'reference_compromis')) return;
    const d = auditDossierLie;
    if (!d || !d.nasDossier) return;
    try {
      const trouve = choisirAvantContratNas(await listerFichiersNas(d), d.compromisNomFichier).fichier;
      if (!trouve) return;
      const entree = {
        id: `analyse-ia-${++compteurFichierAnalyseIa}`, file: null, cheminNas: cheminNasComplet(d, trouve.chemin),
        nom: trouve.nom, type: 'reference_compromis', nature: 'avant_contrat', statut: 'lecture', texte: '', pages: [],
        erreurTexte: '', pagesLues: null, pagesTotal: null, viaOcr: false, tronque: false
      };
      fichiersAnalyseIa.push(entree);
      renderListeFichiersAnalyseIa();
      await extraireTexteFichierAnalyseIa(entree.id);
    } catch (e) {
      console.warn('Avant-contrat du dossier lié introuvable', e);
    }
  }

  async function allerEtapePseudonymisationRelecture() {
    const btn = document.getElementById('relecture-suivant-1');
    if (btn) { btn.disabled = true; btn.innerHTML = `${icone('spinner', null, true)} Préparation…`; }
    await completerAvantContratRelecture();
    if (btn) btn.innerHTML = 'Continuer';
    renderListeFichiersAnalyseIa();
    definirEtapeRelecture(2);
  }

  // ---- Étape 2 : pseudonymisation -------------------------------------------------------------

  function documentsOrdonnesRelecture() {
    const ok = fichiersAnalyseIa.filter(f => f.statut === 'ok');
    const rang = f => (f.type === 'principal' ? 0 : f.type === 'reference_compromis' ? 1 : 2);
    return ok.slice().sort((a, b) => rang(a) - rang(b));
  }

  function roleEnvoiRelecture(f) {
    return f.type === 'principal' ? 'principal' : (f.type === 'reference_compromis' ? 'avant_contrat' : 'annexe');
  }

  function preparerAnonymisationRelecture() {
    const docs = documentsOrdonnesRelecture();
    const parties = [];
    const notaires = [];
    for (const f of docs.filter(x => x.type !== 'justificatif' && x.type !== 'autre')) {
      const type = detecterTypeActe(f.texte);
      const valeurType = type && type.valeur;
      parties.push(...detecterParties(f.texte, valeurType));
      notaires.push(...detecterNotaires(f.texte, valeurType));
    }
    const termes = termesConnusAnonymisation(parties, notaires).concat(termesManuelsRelecture.map(t => ({ ...t, source: 'manuel' })));
    const r = anonymiserDocumentsOutil2(docs.map(f => ({ id: f.id, texte: f.texte, pages: f.pages })), { termes, exclus: valeursEnClairRelecture });
    anonymisationRelecture = { documents: r.documents, table: r.table, nbTermesConnus: termes.length };
    return anonymisationRelecture;
  }

  var LIBELLES_CATEGORIE_ANONYMISATION = {
    PERSONNE: 'Personnes', PERSONNE_MORALE: 'Sociétés', ADRESSE: 'Adresses', EMAIL: 'E-mails', TELEPHONE: 'Téléphones',
    NIR: 'N° de sécurité sociale', NAISSANCE: 'Naissances', CADASTRE: 'Références cadastrales',
    IDENTIFIANT_ENTREPRISE: 'SIREN / SIRET', IBAN: 'IBAN'
  };
  var LIBELLES_SOURCE_ANONYMISATION = { partie: 'partie de l’acte', notaire: 'notaire', regle: 'repéré', manuel: 'ajouté' };

  function renderAnonymisationRelecture() {
    const zone = document.getElementById('relecture-anonymisation');
    const a = anonymisationRelecture;
    if (!zone || !a) return;
    const parCat = new Map();
    for (const e of a.table) {
      if (!parCat.has(e.categorie)) parCat.set(e.categorie, []);
      parCat.get(e.categorie).push(e);
    }
    const total = a.table.reduce((s, e) => s + e.occurrences, 0);
    const blocs = Array.from(parCat.entries()).map(([cat, liste]) => `<div class="anon-bloc">
      <span class="relecture-nature-titre">${escapeHtml(LIBELLES_CATEGORIE_ANONYMISATION[cat] || cat)}<span class="audit-section-compte">${liste.length}</span></span>
      <ul class="anon-liste">${liste.map(e => `<li>
        <span class="anon-jeton">${escapeHtml(e.jeton)}</span>
        <span class="anon-valeur">${escapeHtml(e.valeur)}</span>
        <span class="hint">${e.occurrences}× · ${LIBELLES_SOURCE_ANONYMISATION[e.source] || ''}</span>
        <button type="button" class="action-rapide" onclick="laisserEnClairRelecture('${escapeOnclickArg(e.valeur)}')" title="Ne pas masquer cette valeur (par exemple le nom d'une commune utile à l'analyse)">Laisser en clair</button>
      </li>`).join('')}</ul>
    </div>`).join('');
    const enClair = valeursEnClairRelecture.length
      ? `<p class="hint">Laissé en clair : ${valeursEnClairRelecture.map(v => `<button type="button" class="anon-puce" onclick="remasquerRelecture('${escapeOnclickArg(v)}')" title="Masquer à nouveau">${escapeHtml(v)} ${icone('x')}</button>`).join(' ')}</p>` : '';
    zone.innerHTML = `<div class="anon-stats">
        <div><strong>${a.table.length}</strong><span>éléments distincts</span></div>
        <div><strong>${total}</strong><span>occurrences masquées</span></div>
        <div><strong>${a.documents.length}</strong><span>document(s)</span></div>
      </div>
      <div class="anon-ajout">
        <label for="anon-terme">Masquer aussi</label>
        <input type="text" id="anon-terme" placeholder="Un nom, une rue, un lieu-dit…" onkeydown="if(event.key==='Enter'){event.preventDefault();ajouterTermeAnonymisationRelecture();}">
        <button type="button" class="secondary" onclick="ajouterTermeAnonymisationRelecture()">Ajouter</button>
      </div>
      ${enClair}
      <div class="anon-grille">${blocs || '<p class="hint">Aucune donnée identifiante repérée — vérifiez l’aperçu.</p>'}</div>`;
    renderApercuAnonymisationRelecture();
  }

  function ajouterTermeAnonymisationRelecture() {
    const champ = document.getElementById('anon-terme');
    const t = champ ? champ.value.trim() : '';
    if (t.length < 2) return;
    termesManuelsRelecture.push({ terme: t, categorie: 'PERSONNE' });
    valeursEnClairRelecture = valeursEnClairRelecture.filter(v => normaliserPourRecherche(v) !== normaliserPourRecherche(t));
    preparerAnonymisationRelecture();
    renderAnonymisationRelecture();
    estimationRelecture = null;
  }

  function laisserEnClairRelecture(valeur) {
    valeursEnClairRelecture.push(valeur);
    termesManuelsRelecture = termesManuelsRelecture.filter(t => normaliserPourRecherche(t.terme) !== normaliserPourRecherche(valeur));
    preparerAnonymisationRelecture();
    renderAnonymisationRelecture();
    estimationRelecture = null;
  }

  function remasquerRelecture(valeur) {
    valeursEnClairRelecture = valeursEnClairRelecture.filter(v => v !== valeur);
    preparerAnonymisationRelecture();
    renderAnonymisationRelecture();
    estimationRelecture = null;
  }

  // Aperçu d'une page telle qu'elle partira : c'est ce que l'étude doit pouvoir relire avant de
  // valider — un nom resté en clair se voit ici, pas après l'envoi.
  function renderApercuAnonymisationRelecture() {
    const zone = document.getElementById('relecture-apercu-anon');
    const a = anonymisationRelecture;
    if (!zone || !a || !a.documents.length) return;
    const docs = documentsOrdonnesRelecture();
    const iDoc = Math.min(pageApercuRelecture.doc, a.documents.length - 1);
    const doc = a.documents[iDoc];
    const iPage = Math.min(pageApercuRelecture.page, doc.pages.length - 1);
    const p = doc.pages[iPage];
    const extrait = p ? doc.texte.slice(p.debut, p.fin) : doc.texte;
    const html = escapeHtml(extrait).replace(/⟦[A-Z_]+_\d+⟧/g, j => `<mark class="anon-mark">${j}</mark>`);
    const options = docs.map((f, i) => `<option value="${i}" ${i === iDoc ? 'selected' : ''}>${escapeHtml(f.nom)}</option>`).join('');
    zone.innerHTML = `<div class="anon-apercu-tete">
        <select aria-label="Document" onchange="pageApercuRelecture = { doc: Number(this.value), page: 0 }; renderApercuAnonymisationRelecture()">${options}</select>
        <div class="anon-apercu-pages">
          <button type="button" class="icon-btn" ${iPage <= 0 ? 'disabled' : ''} onclick="pageApercuRelecture.page = ${iPage - 1}; renderApercuAnonymisationRelecture()" aria-label="Page précédente">${icone('chevron-up')}</button>
          <span>p.${p ? p.numero : 1} / ${doc.pages.length || 1}</span>
          <button type="button" class="icon-btn" ${iPage >= doc.pages.length - 1 ? 'disabled' : ''} onclick="pageApercuRelecture.page = ${iPage + 1}; renderApercuAnonymisationRelecture()" aria-label="Page suivante">${icone('chevron-down')}</button>
        </div>
      </div>
      <div class="anon-apercu-texte">${html || '<span class="hint">Page vide.</span>'}</div>`;
  }

  // ---- Étape 3 : analyse ----------------------------------------------------------------------

  function consignesEtudeRelecture() {
    const cle = dernierAuditContexte ? dernierAuditContexte.dossierCle : cleDossierAudit(auditDossierLie, (documentsOrdonnesRelecture()[0] || {}).nom);
    return consignesDepuisRetours(retoursAudit, cle);
  }

  // Pure : les commentaires de l'étude transformés en consignes pour le modèle. Un avis « juste »
  // accompagné d'une remarque est transmis lui aussi (« bien vu, et vérifier aussi l'écart de 5 % »
  // est une consigne) ; un avis de gravité l'est même sans commentaire (la gravité voulue suffit) ;
  // un oubli signalé sur plusieurs lignes donne une consigne par ligne, pour qu'aucune ne soit
  // tronquée. Les 30 dernières au plus, dans la portée du dossier en cours.
  function consignesDepuisRetours(retours, cle) {
    const utiles = (retours || []).filter(r => r
      && ['faux_positif', 'mal_formule', 'gravite', 'manque', 'juste'].indexOf(r.verdict) >= 0
      && (r.commentaire || r.verdict === 'gravite')
      && (r.portee === 'tous' || (cle && r.dossierCle === cle)));
    const consignes = [];
    for (const r of utiles) {
      const titre = r.constat && r.constat.titre ? `« ${r.constat.titre} »` : '';
      const commentaire = String(r.commentaire || '').trim();
      if (r.verdict === 'faux_positif') consignes.push(`Ne signale pas comme un problème ${titre} : ${commentaire}`);
      else if (r.verdict === 'manque') {
        commentaire.split(/\n+/).map(l => l.trim()).filter(Boolean).forEach(l => consignes.push(`Vérifie aussi : ${l}`));
      } else if (r.verdict === 'gravite') consignes.push(`${titre} : gravité attendue ${String(r.graviteSouhaitee || '').toLowerCase()}${commentaire ? ` — ${commentaire}` : ''}`);
      else if (r.verdict === 'juste') consignes.push(`Constat jugé juste par l'étude, à conserver ${titre} : ${commentaire}`);
      else consignes.push(`${titre} : ${commentaire}`);
    }
    return consignes.slice(-30).map(t => t.slice(0, 380));
  }

  function corpsRequeteRelecture() {
    const a = anonymisationRelecture || preparerAnonymisationRelecture();
    const docs = documentsOrdonnesRelecture();
    documentsEnvoyesRelecture = docs.map((f, i) => ({ numero: i + 1, fichierId: f.id, nom: f.nom, type: f.type, nature: f.nature || 'autre', cheminNas: f.cheminNas || '' }));
    const typeBien = typeBienRelectureCourante();
    return {
      mode: auditMode,
      typeBien,
      grille: grillePourModeOutil2(auditMode, typeBien),
      consignes: consignesEtudeRelecture().map(c => pseudonymiserTexteLibreOutil2(c, a.table)),
      // Le nom de fichier porte souvent le nom des clients (« VENTE DUPONT MARTIN.pdf ») : il ne
      // part jamais, remplacé par un intitulé neutre.
      libelle: `${auditMode === 'acte' ? "Projet d'acte de vente" : "Projet d'avant-contrat"} — ${docs.length} document(s)`,
      documents: a.documents.map((d, i) => {
        const f = docs[i];
        return {
          nom: `${ROLES_DOCUMENT_RELECTURE[f.type] || 'Annexe'} — ${libelleNaturePieceOutil2(f.nature || 'autre')} (${i + 1})`,
          role: roleEnvoiRelecture(f), nature: f.nature || 'autre', annexesDepuisPage: f.annexesDepuisPage || null,
          texte: d.texte, pages: d.pages
        };
      })
    };
  }

  async function renderEtapeAnalyseRelecture() {
    const zone = document.getElementById('relecture-analyse');
    if (!zone) return;
    const docs = documentsOrdonnesRelecture();
    const pages = docs.reduce((s, f) => s + (f.pagesTotal || f.pages.length || 0), 0);
    if (!etatClaudeRelecture) {
      try {
        const r = await fetchAvecAuth('/api/relecture-claude/etat');
        etatClaudeRelecture = r.ok ? await r.json() : { configure: false };
      } catch (e) { etatClaudeRelecture = { configure: false }; }
    }
    const e = etatClaudeRelecture;
    const modele = LIBELLES_MODELES_CLAUDE[e.modele] || e.modele || '';
    const fournisseur = libelleFournisseurRelecture(e);
    const typeBien = typeBienRelectureCourante();
    const grille = grillePourModeOutil2(auditMode, typeBien);
    let estimation = '';
    if (e.configure) {
      if (!estimationRelecture) {
        estimation = `<p class="hint">${icone('spinner', null, true)} Estimation du coût…</p>`;
        estimerCoutRelecture();
      } else if (estimationRelecture.erreur) {
        estimation = `<p class="hint">${icone('alert-triangle')} ${escapeHtml(estimationRelecture.erreur)}</p>`;
      } else {
        const c = estimationRelecture.coutEstime;
        estimation = `<div class="analyse-estimation"><span class="section-eyebrow">Coût estimé</span><strong>${c ? `${formaterCoutUsd(c.bas)} à ${formaterCoutUsd(c.haut)}` : '—'}</strong>
          <span class="hint">${estimationRelecture.estime ? 'environ ' : ''}${estimationRelecture.jetonsEntree.toLocaleString('fr-FR')} jetons à lire · facturé par ${escapeHtml(fournisseur.societe)} en dollars</span></div>`;
        // Aucune limite de pages : la seule borne est ce que le modèle peut lire en une fois. Dit
        // AVANT le lancement, avec le compte exact, plutôt qu'un refus de l'API après coup.
        if (estimationRelecture.depasse) {
          estimation += `<p class="analyse-erreur">${icone('alert-triangle')} Ce dossier dépasse ce que le modèle peut lire en une seule analyse (${estimationRelecture.jetonsEntree.toLocaleString('fr-FR')} jetons, maximum ${(estimationRelecture.limiteJetons || 0).toLocaleString('fr-FR')}). Retirez les pièces les moins utiles à l'étape 1.</p>`;
        }
      }
    }
    const enCours = analyseEnCoursRelecture
      ? `<div class="analyse-en-cours">${icone('spinner', null, true)}<div><strong>Analyse en cours — <span id="relecture-chrono">0 s</span> ${infoBulle(`${fournisseur.nom} relit ${docs.length} document(s) point par point. Comptez en général une à quatre minutes ; vous pouvez consulter un autre écran en attendant.`)}</strong></div></div>`
      : '';
    const erreur = erreurClaudeRelecture ? `<p class="analyse-erreur">${icone('alert-triangle')} ${escapeHtml(erreurClaudeRelecture)}</p>` : '';
    zone.innerHTML = `<div class="analyse-recap">
        <div><span class="section-eyebrow">Documents</span><strong>${docs.length}</strong><span class="hint">${pages} pages</span></div>
        <div><span class="section-eyebrow">Grille</span><strong>${grille.length} points</strong><span class="hint">${auditMode === 'acte' ? 'projet de vente' : 'avant-contrat'}</span></div>
        <div><span class="section-eyebrow">Données masquées</span><strong>${anonymisationRelecture ? anonymisationRelecture.table.length : 0}</strong><span class="hint">table gardée sur ce poste</span></div>
        <div><span class="section-eyebrow">Modèle</span><strong>${e.configure ? escapeHtml(modele) : '—'}</strong><span class="hint">${e.configure ? escapeHtml(fournisseur.detail) : 'non configuré'}</span></div>
      </div>
      ${renderTypeBienEtapeRelecture(typeBien, grille.length)}
      ${estimation}
      ${e.configure ? '' : `<div class="analyse-non-configure">${icone('key')}<div><strong>Aucune clé API ${escapeHtml(fournisseur.nom)}.</strong> <p class="hint">Renseignez-la dans Réglages → Relecture d'actes. En attendant, les contrôles automatiques de CLAIRE restent disponibles.</p></div></div>`}
      ${enCours}${erreur}
      <div class="relecture-actions">
        <button type="button" class="secondary" onclick="definirEtapeRelecture(2)" ${analyseEnCoursRelecture ? 'disabled' : ''}>Retour</button>
        ${e.configure ? '' : `<button type="button" class="secondary" onclick="lancerAuditActe(false)" ${analyseEnCoursRelecture ? 'disabled' : ''}>Contrôles CLAIRE seuls</button>`}
        <button type="button" class="primary" onclick="lancerAuditActe(true)" ${e.configure && !analyseEnCoursRelecture && !(estimationRelecture && estimationRelecture.depasse) ? '' : 'disabled'}>${icone('sparkle')} Lancer l'analyse</button>
      </div>
      ${renderJournalCoutRelecture()}`;
  }

  // Libellés des modèles de la relecture, tous fournisseurs confondus (le nom historique de la
  // table est conservé). Mistral est le fournisseur par défaut depuis le 27/09/2026.
  var LIBELLES_MODELES_CLAUDE = {
    'claude-sonnet-5': 'Claude Sonnet 5', 'claude-opus-5': 'Claude Opus 5',
    'mistral-medium-3-5': 'Mistral Medium 3.5', 'mistral-large-2512': 'Mistral Large 3'
  };

  // Nom du fournisseur, société facturante et mention du lieu de traitement, pour l'écran.
  function libelleFournisseurRelecture(etat) {
    const e = etat || {};
    if (e.fournisseur === 'claude') return { nom: 'Claude', societe: 'Anthropic', detail: 'API Claude (Anthropic)' };
    return { nom: 'Mistral', societe: 'Mistral AI', detail: e.region === 'global' ? 'API Mistral' : 'API Mistral · Union européenne' };
  }

  async function estimerCoutRelecture() {
    try {
      const r = await fetchAvecAuth('/api/relecture-claude/estimer', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(corpsRequeteRelecture())
      });
      const data = await r.json().catch(() => ({}));
      estimationRelecture = r.ok ? data : { erreur: data.erreur || 'Estimation impossible.' };
    } catch (e) {
      estimationRelecture = { erreur: 'Estimation impossible : serveur injoignable.' };
    }
    if (etapeRelecture === 3) renderEtapeAnalyseRelecture();
  }

  function renderJournalCoutRelecture() {
    const j = journalCoutRelecture;
    if (!j || !j.totalNb) return '';
    return `<p class="hint analyse-journal">${icone('banknote')} Ce mois-ci : ${j.moisNb} analyse(s), ${formaterCoutUsd(j.moisUsd)} · depuis l'installation : ${j.totalNb} analyse(s), ${formaterCoutUsd(j.totalUsd)}.</p>`;
  }

  async function chargerJournalCoutRelecture() {
    try {
      const r = await fetchAvecAuth('/api/relecture-claude/journal');
      if (r.ok) journalCoutRelecture = await r.json();
    } catch (e) { /* sans importance : l'information est complémentaire */ }
  }

  // Les contrôles CLAIRE, calculés en local : c'est l'ancien lancerAuditActe, sans rendu.
  async function preparerControlesClaireRelecture() {
    const fichiersOk = fichiersAnalyseIa.filter(f => f.statut === 'ok');
    const principal = fichiersOk.find(f => f.type === 'principal');
    if (!principal) return false;
    const justificatifs = fichiersOk
      .filter(f => f !== principal && f.type !== 'reference_compromis')
      .map(f => ({ nom: f.nom, texte: f.texte, pages: f.pages }));
    const couverture = fichiersOk.map(f => ({ nom: f.nom, pagesLues: f.pagesLues, pagesTotal: f.pagesTotal, viaOcr: f.viaOcr, tronque: f.tronque }));
    if (auditMode === 'acte') {
      const ref = fichiersOk.find(f => f.type === 'reference_compromis') || (auditDossierLie ? await recupererTextCompromisDossier(auditDossierLie) : null);
      dernierAuditContexte = {
        mode: 'acte',
        referenceLueDansTexte: !!(ref && ref.texte),
        entree: {
          texteAvantContrat: ref ? ref.texte : '',
          pagesAvantContrat: ref ? ref.pages : [],
          texteProjet: principal.texte,
          pagesProjet: principal.pages,
          nomProjet: principal.nom,
          nomAvantContrat: ref ? (ref.nom || 'Avant-contrat') : 'Avant-contrat',
          documentsDeposes: justificatifs,
          dossierLie: auditDossierLie,
          reference: ref ? referenceAudit(ref.texte, ref.nom, auditDossierLie) : (auditDossierLie ? referenceDepuisDossier(auditDossierLie) : null),
          projet: construireExtractionRegex(principal.texte, null, null, principal.nom)
        },
        nbJustificatifs: justificatifs.length,
        couvertureDocuments: couverture
      };
    } else {
      dernierAuditContexte = {
        mode: 'compromis',
        entree: {
          texte: principal.texte, pages: principal.pages, nomTexte: principal.nom, documentsDeposes: justificatifs,
          extraction: construireExtractionRegex(principal.texte, null, null, principal.nom)
        },
        nbJustificatifs: justificatifs.length,
        couvertureDocuments: couverture
      };
    }
    dernierAuditContexte.dossierCle = cleDossierAudit(auditDossierLie, principal.nom);
    dernierAuditContexte.dossierNom = auditDossierLie ? auditDossierLie.nom : '';
    dernierAuditContexte.documentPrincipal = principal.nom;
    const resultat = auditMode === 'acte'
      ? analyserProjetVenteOutil2({ ...dernierAuditContexte.entree, typeBienForce: typeBienAuditChoisi })
      : analyserCompromisOutil2({ ...dernierAuditContexte.entree, typeBienForce: typeBienAuditChoisi });
    resultat.nbJustificatifs = dernierAuditContexte.nbJustificatifs;
    resultat.couvertureDocuments = dernierAuditContexte.couvertureDocuments;
    dernierRapportAudit = resultat;
    return true;
  }

  async function lancerAuditActe(avecClaude) {
    if (analyseEnCoursRelecture) return;
    analyseEnCoursRelecture = true;
    erreurClaudeRelecture = '';
    analyseClaudeRelecture = null;
    factureRelecture = null;
    const debut = Date.now();
    clearInterval(minuteurAnalyseRelecture);
    renderEtapeAnalyseRelecture();
    minuteurAnalyseRelecture = setInterval(() => {
      const el = document.getElementById('relecture-chrono');
      if (el) el.textContent = formaterDureeMs(Date.now() - debut);
    }, 1000);
    try {
      formCommentaireAudit = null;
      diagnosticRelectureOuverts = new Set();
      await chargerRetoursAudit();
      await preparerControlesClaireRelecture();
      typeBienEnvoyeRelecture = typeBienRelectureCourante();
      idRelectureEnregistree = null;
      if (avecClaude) {
        const corps = corpsRequeteRelecture();
        const r = await fetchAvecAuth('/api/relecture-claude/analyser', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(corps)
        });
        const data = await r.json().catch(() => ({}));
        factureRelecture = data.facture || null;
        if (!r.ok) {
          erreurClaudeRelecture = data.erreur || "L'analyse n'a pas abouti.";
        } else {
          analyseClaudeRelecture = desanonymiserOutil2(data.analyse, anonymisationRelecture.table);
        }
      }
      await chargerJournalCoutRelecture();
    } catch (e) {
      console.error('Relecture : échec de l’analyse', e);
      erreurClaudeRelecture = "L'analyse n'a pas pu aboutir (serveur injoignable ?).";
    } finally {
      clearInterval(minuteurAnalyseRelecture);
      analyseEnCoursRelecture = false;
    }
    if (dernierRapportAudit) preparerRapportAudit(dernierRapportAudit);
    if (erreurClaudeRelecture && avecClaude) {
      renderEtapeAnalyseRelecture();
      afficherToast(erreurClaudeRelecture + ' Les contrôles CLAIRE restent consultables dans le bilan.', 'OK', null);
      return;
    }
    definirEtapeRelecture(4);
    enregistrerRelectureCourante();
  }

  // ---- Type de bien : choisi avant l'analyse, il décide des points posés ----------------------
  function typeBienRelectureCourante() {
    if (typeBienAuditChoisi) return typeBienAuditChoisi;
    const principal = fichiersAnalyseIa.find(f => f.type === 'principal' && f.statut === 'ok');
    const ref = fichiersAnalyseIa.find(f => f.type === 'reference_compromis' && f.statut === 'ok');
    return deduireTypeBienOutil2({
      texteProjet: principal ? principal.texte : '', texteAvantContrat: ref ? ref.texte : '', dossierLie: auditDossierLie
    }).type;
  }

  function renderTypeBienEtapeRelecture(typeBien, nbPoints) {
    const options = TYPES_BIEN_AUDIT
      .map(t => `<option value="${t.valeur}" ${t.valeur === typeBien ? 'selected' : ''}>${escapeHtml(t.libelle)}</option>`).join('');
    return `<div class="relecture-type-bien">
      <label for="relecture-type-bien">Type de bien</label>
      <select id="relecture-type-bien" onchange="changerTypeBienRelecture(this.value)" ${analyseEnCoursRelecture ? 'disabled' : ''}>${options}</select>
      <span class="hint">${typeBienAuditChoisi ? 'Choisi à la main' : 'Déduit des documents'} · ${nbPoints} points ${infoBulle("La grille pose des points adaptés à ce type de bien : à corriger avant de lancer l'analyse si la déduction est fausse.")}</span>
    </div>`;
  }

  function changerTypeBienRelecture(valeur) {
    typeBienAuditChoisi = ['maison', 'copropriete', 'terrain'].indexOf(valeur) >= 0 ? valeur : null;
    estimationRelecture = null;
    renderEtapeAnalyseRelecture();
  }

  // ---- Analyses enregistrées : revenir sur une relecture passée --------------------------------
  // Chaque bilan affiché est rangé dans la base du serveur (routes/relectures.js) : on peut le
  // rouvrir plus tard sans relancer l'analyse ni la payer une seconde fois.
  function instantaneRelecture() {
    const r = dernierRapportAudit;
    if (!r) return null;
    const ctx = dernierAuditContexte || {};
    const docs = documentsEnvoyesRelecture.length ? documentsEnvoyesRelecture
      : documentsOrdonnesRelecture().map((f, i) => ({ numero: i + 1, fichierId: f.id, nom: f.nom, type: f.type, nature: f.nature || 'autre', cheminNas: f.cheminNas || '' }));
    return {
      version: 1,
      mode: auditMode,
      typeBien: typeBienEnvoyeRelecture || r.typeBien || '',
      dossierId: auditDossierLie ? auditDossierLie.id : '',
      dossierNom: auditDossierLie ? auditDossierLie.nom : '',
      dossierCle: ctx.dossierCle || '',
      libelle: ctx.documentPrincipal || '',
      sante: derniereSanteRelecture ? derniereSanteRelecture.compte : null,
      analyse: analyseClaudeRelecture,
      erreurClaude: erreurClaudeRelecture || '',
      facture: factureRelecture,
      rapport: r,
      documents: docs.map(d => ({ numero: d.numero, nom: d.nom || '', type: d.type || '', nature: d.nature || '', cheminNas: d.cheminNas || '' }))
    };
  }

  async function enregistrerRelectureCourante() {
    const corps = instantaneRelecture();
    if (!corps) return;
    try {
      const url = idRelectureEnregistree ? '/api/relectures/' + encodeURIComponent(idRelectureEnregistree) : '/api/relectures';
      const r = await fetchAvecAuth(url, {
        method: idRelectureEnregistree ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(corps)
      });
      const data = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(data.erreur || 'statut ' + r.status);
      if (data.id) idRelectureEnregistree = data.id;
      chargerHistoriqueRelectures();
    } catch (e) {
      console.warn('Relecture : enregistrement impossible', e);
      afficherToast("Le bilan n'a pas pu être enregistré dans les analyses passées (serveur injoignable ?).", 'OK', null);
    }
  }

  async function chargerHistoriqueRelectures() {
    try {
      const r = await fetchAvecAuth('/api/relectures');
      if (!r.ok) throw new Error('statut ' + r.status);
      historiqueRelectures = (await r.json()).relectures || [];
    } catch (e) {
      historiqueRelectures = historiqueRelectures || [];
    }
    renderHistoriqueRelectures();
  }

  // Pure, testable : filtre la liste sur le dossier, le document ou le type d'acte, sans accents.
  function filtrerHistoriqueRelectures(liste, recherche) {
    const q = normaliserPourRecherche(String(recherche || '').trim());
    if (!q) return liste || [];
    return (liste || []).filter(h => normaliserPourRecherche([h.dossierNom, h.libelle, h.mode === 'acte' ? "projet d'acte de vente" : 'avant-contrat'].join(' ')).indexOf(q) >= 0);
  }

  function renderHistoriqueRelectures() {
    const zone = document.getElementById('relecture-historique-liste');
    if (!zone) return;
    if (historiqueRelectures === null) { zone.innerHTML = '<p class="hint">Chargement…</p>'; return; }
    const champ = document.getElementById('relecture-historique-recherche');
    const liste = filtrerHistoriqueRelectures(historiqueRelectures, champ ? champ.value : '');
    if (!historiqueRelectures.length) { zone.innerHTML = '<p class="hint">Aucune analyse enregistrée pour l’instant : chaque bilan affiché à l’étape 4 est gardé ici.</p>'; return; }
    if (!liste.length) { zone.innerHTML = '<p class="hint">Aucune analyse ne correspond à cette recherche.</p>'; return; }
    zone.innerHTML = `<ul class="historique-relectures">${liste.slice(0, 60).map(h => {
      const quand = new Date(h.createdAt);
      const date = isNaN(quand) ? '' : quand.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short', year: 'numeric' }) + ' · ' + quand.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
      const type = (TYPES_BIEN_AUDIT.find(t => t.valeur === h.typeBien) || {}).libelle || '';
      const s = h.sante || {};
      return `<li class="historique-ligne">
        <button type="button" class="historique-ouvrir" onclick="ouvrirRelectureArchivee('${escapeOnclickArg(h.id)}')">
          <span class="historique-titre">${escapeHtml(h.dossierNom ? libelleDossierAffiche({ nom: h.dossierNom }) : (h.libelle || 'Relecture sans dossier'))}</span>
          <span class="historique-meta">${escapeHtml([date, h.mode === 'acte' ? "Projet d'acte de vente" : 'Avant-contrat', type, h.avecClaude ? '' : 'contrôles CLAIRE seuls'].filter(Boolean).join(' · '))}</span>
        </button>
        <span class="historique-compteurs">
          ${s.critique ? `<span class="dot-label dl-urgent"><span class="dot"></span>${s.critique}</span>` : ''}
          ${s.surveiller ? `<span class="dot-label dl-pret"><span class="dot"></span>${s.surveiller}</span>` : ''}
          <span class="dot-label dl-success"><span class="dot"></span>${s.valide || 0}</span>
        </span>
        <button type="button" class="icon-btn" onclick="supprimerRelectureArchivee('${escapeOnclickArg(h.id)}')" aria-label="Supprimer cette analyse" title="Supprimer cette analyse">${icone('x')}</button>
      </li>`;
    }).join('')}</ul>`;
  }

  async function ouvrirRelectureArchivee(id) {
    let data;
    try {
      const r = await fetchAvecAuth('/api/relectures/' + encodeURIComponent(id));
      data = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(data.erreur || 'statut ' + r.status);
    } catch (e) {
      afficherToast("Impossible d'ouvrir cette analyse : " + (e.message || 'serveur injoignable'), 'OK', null);
      return;
    }
    const h = data.relecture;
    const d = h.donnees || {};
    relectureArchiveeOuverte = { id: h.id, createdAt: h.createdAt };
    idRelectureEnregistree = h.id;
    auditMode = d.mode === 'acte' ? 'acte' : 'compromis';
    typeBienEnvoyeRelecture = d.typeBien || '';
    analyseClaudeRelecture = d.analyse || null;
    erreurClaudeRelecture = d.erreurClaude || '';
    factureRelecture = d.facture || null;
    dernierRapportAudit = d.rapport || null;
    documentsEnvoyesRelecture = (d.documents || []).map(x => ({ ...x, fichierId: `hist-${h.id}-${x.numero}` }));
    dernierAuditContexte = { mode: auditMode, dossierCle: d.dossierCle || '', dossierNom: d.dossierNom || '', documentPrincipal: d.libelle || '', archive: true };
    fermerVisionneuseRelecture();
    formCommentaireAudit = null;
    await chargerRetoursAudit();
    if (dernierRapportAudit) preparerRapportAudit(dernierRapportAudit);
    definirEtapeRelecture(4);
  }

  function fermerRelectureArchivee() {
    relectureArchiveeOuverte = null;
    idRelectureEnregistree = null;
    analyseClaudeRelecture = null;
    factureRelecture = null;
    erreurClaudeRelecture = '';
    dernierRapportAudit = null;
    dernierAuditContexte = null;
    documentsEnvoyesRelecture = [];
    constatsClaudeRelecture = [];
    fermerVisionneuseRelecture();
    const select = document.getElementById('audit-mode');
    if (select) auditMode = select.value === 'acte' ? 'acte' : 'compromis';
  }

  function quitterRelectureArchivee() {
    fermerRelectureArchivee();
    definirEtapeRelecture(1);
  }

  function supprimerRelectureArchivee(id) {
    demanderConfirmation("Supprimer cette analyse enregistrée ? Elle ne pourra plus être rouverte (les commentaires donnés restent).", async () => {
      try {
        const r = await fetchAvecAuth('/api/relectures/' + encodeURIComponent(id), { method: 'DELETE' });
        if (!r.ok) throw new Error('statut ' + r.status);
      } catch (e) {
        afficherToast("Suppression impossible (serveur injoignable ?).", 'OK', null);
        return;
      }
      if (relectureArchiveeOuverte && relectureArchiveeOuverte.id === id) quitterRelectureArchivee();
      chargerHistoriqueRelectures();
    });
  }

  function renderBandeauArchiveRelecture() {
    if (!relectureArchiveeOuverte) return '';
    const quand = new Date(relectureArchiveeOuverte.createdAt);
    const date = isNaN(quand) ? '' : quand.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' }) + ' à ' + quand.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
    return `<div class="relecture-archive-bandeau">
      <span class="dot-label dl-neutre">${icone('clock')}Analyse enregistrée${date ? ' le ' + escapeHtml(date) : ''}</span>
      <span class="hint">Consultation : rien n'est relancé ni refacturé.</span>
      <button type="button" class="secondary" onclick="quitterRelectureArchivee()">Fermer</button>
    </div>`;
  }

  // ---- Étape 4 : bilan -------------------------------------------------------------------------

  var GRAVITE_PAR_NIVEAU_RELECTURE = { critique: 'CRITIQUE', surveiller: 'A_VERIFIER', valide: 'INFORMATION' };

  function niveauDepuisGraviteRelecture(g) {
    if (g === 'CRITIQUE' || g === 'IMPORTANT') return 'critique';
    if (g === 'A_VERIFIER') return 'surveiller';
    return 'valide';
  }

  // Les lignes de Claude qui demandent une action deviennent des « constats » : même registre, même
  // commentaires (juste / faux positif / mal formulé / gravité) que les contrôles CLAIRE. Leur
  // catégorie est propre à chaque point de la grille, pour qu'un avis ne déborde pas d'un point sur
  // l'autre (appliquerRetoursAuxConstats ne rapproche que dans la même catégorie).
  function construireConstatsClaudeRelecture(sections) {
    constatsClaudeRelecture = [];
    const a = analyseClaudeRelecture;
    if (!a) return;
    for (const s of sections) {
      for (const l of s.lignes) {
        if (l.niveau !== 'critique' && l.niveau !== 'surveiller') continue;
        const cit = l.citations.find(c => c.verifie) || l.citations[0];
        constatsClaudeRelecture.push({ uid: 'g-' + l.id, categorie: 'GRILLE_' + l.id, gravite: GRAVITE_PAR_NIVEAU_RELECTURE[l.niveau],
          titre: l.intitule, description: l.commentaire, phrase: cit ? cit.extrait : '', page: cit ? cit.page : null, ligne: l });
      }
    }
    // Clauses contradictoires : une catégorie à part, pour qu'un avis sur une contradiction ne
    // s'applique jamais à une anomalie (et inversement).
    (a.contradictions || []).forEach((x, i) => {
      const cit = [x.clause_a, x.clause_b].find(c => c && c.verifie) || x.clause_a;
      constatsClaudeRelecture.push({ uid: 'x-' + i, categorie: 'CONTRADICTION_CLAUDE', gravite: x.gravite === 'elevee' ? 'CRITIQUE' : 'A_VERIFIER',
        titre: x.sujet, description: x.explication, phrase: cit ? cit.extrait : '', page: cit ? cit.page : null, contradiction: x });
    });
    (a.anomalies || []).forEach((x, i) => {
      const cit = (x.citations || []).find(c => c.verifie) || (x.citations || [])[0];
      constatsClaudeRelecture.push({ uid: 'a-' + i, categorie: 'ANOMALIE_CLAUDE', gravite: x.gravite === 'elevee' ? 'CRITIQUE' : 'A_VERIFIER',
        titre: x.titre, description: x.description, phrase: cit ? cit.extrait : '', page: cit ? cit.page : null, anomalie: x });
    });
  }

  function pastilleCitationRelecture(c) {
    if (!c) return '';
    const idx = citationsRelecture.push(c) - 1;
    const doc = documentsEnvoyesRelecture.find(d => d.numero === c.document);
    const f = doc ? (fichiersAnalyseIa.find(x => x.id === doc.fichierId) || (doc.nom ? doc : null)) : null;
    const nomDoc = f ? f.nom : 'Document';
    const court = f ? (f.type === 'principal' ? 'Projet' : f.type === 'reference_compromis' ? 'Avant-contrat' : libelleNaturePieceOutil2(f.nature)) : `Doc ${c.document || '?'}`;
    const verif = c.verifie ? '' : ` <span class="page-chip-alerte" title="Extrait introuvable mot pour mot dans le document : à vérifier en priorité">${icone('alert-triangle')}</span>`;
    return `<button type="button" class="page-chip${c.verifie ? '' : ' non-verifiee'}" onclick="ouvrirCitationRelecture(${idx})" title="${escapeAttr(nomDoc)}${c.extrait ? ' — « ' + escapeAttr(c.extrait.slice(0, 160)) + ' »' : ''}">
      ${icone('eye')}${escapeHtml(court)}${c.page ? ` · p.${c.page}` : ''}${verif}</button>`;
  }

  function lignePointRelecture(l) {
    const c = constatsClaudeRelecture.find(x => x.uid === 'g-' + l.id);
    let niveau = l.niveau;
    let exclu = false;
    if (c) {
      if (c.retour && c.retour.verdict === 'faux_positif') exclu = true;
      else niveau = niveauDepuisGraviteRelecture(c.gravite);
    }
    const n = NIVEAUX_RELECTURE_OUTIL2[exclu ? 'na' : niveau];
    const pied = c ? (modeCommentairesAudit ? renderCommentaireConstatAudit(c) : renderRetourResumeAudit(c)) : '';
    const citations = l.citations.map(pastilleCitationRelecture).join('');
    return `<div class="point-ligne niveau-${exclu ? 'na' : niveau}"${c ? ` id="audit-constat-${c.uid}"` : ''}>
      <span class="dot-label ${n.dl}">${icone(n.icone)}${exclu ? 'Faux positif' : n.texte}</span>
      <div class="point-corps">
        <div class="point-intitule">${escapeHtml(l.intitule)}${l.base_legale ? `<span class="hint"> · ${escapeHtml(l.base_legale)}</span>` : ''}</div>
        ${l.commentaire ? `<p class="point-commentaire">${escapeHtml(l.commentaire)}</p>` : ''}
        ${citations ? `<div class="point-citations">${citations}</div>` : ''}
        ${pied}
      </div>
    </div>`;
  }

  // Niveau d'une ligne une fois les commentaires de l'étude appliqués (faux positif = sans objet).
  function niveauEffectifRelecture(l) {
    const c = constatsClaudeRelecture.find(x => x.uid === 'g-' + l.id);
    if (!c) return l.niveau;
    if (c.retour && c.retour.verdict === 'faux_positif') return 'na';
    return niveauDepuisGraviteRelecture(c.gravite);
  }

  function donutSanteRelecture(compte) {
    const segments = [['critique', 'var(--urgent)'], ['surveiller', 'var(--pret)'], ['valide', 'var(--success)']];
    const total = segments.reduce((s, [k]) => s + (compte[k] || 0), 0) || 1;
    const r = 42;
    const circ = 2 * Math.PI * r;
    let decalage = 0;
    const arcs = segments.map(([k, couleur]) => {
      const part = (compte[k] || 0) / total * circ;
      const arc = part > 0 ? `<circle cx="50" cy="50" r="${r}" fill="none" stroke="${couleur}" stroke-width="11" stroke-dasharray="${part.toFixed(2)} ${(circ - part).toFixed(2)}" stroke-dashoffset="${(-decalage).toFixed(2)}" transform="rotate(-90 50 50)"/>` : '';
      decalage += part;
      return arc;
    }).join('');
    return `<svg class="sante-donut" viewBox="0 0 100 100" role="img" aria-label="${compte.critique || 0} critique(s), ${compte.surveiller || 0} à surveiller, ${compte.valide || 0} validé(s)">
      <circle cx="50" cy="50" r="${r}" fill="none" stroke="var(--line-soft)" stroke-width="11"/>${arcs}
    </svg>`;
  }

  var VERDICTS_SANTE_RELECTURE = {
    critique: { titre: 'Points critiques', phrase: 'à régler avant la signature' },
    surveiller: { titre: 'À surveiller', phrase: 'aucun point bloquant, des points restent à vérifier' },
    valide: { titre: 'Validé', phrase: 'aucun point à régler sur la grille' }
  };

  // Catégories de contrôles CLAIRE affichées dans le bilan : « Ce que dit l'acte » seulement.
  // Demande de l'étude : le reste (écarts avec l'avant-contrat, annexes) fait doublon avec la
  // grille relue par Claude, qui couvre les mêmes sujets pièce par pièce, citations à l'appui.
  function categoriesClaireBilanRelecture() {
    return new Set(SOUS_SECTIONS_RAPPORT_OUTIL2.filter(x => x.section === 'ACTE').map(x => x.cle));
  }

  // Validés d'un côté, à traiter de l'autre, pour chaque thème : on voit d'un coup d'œil ce qui est
  // acquis et ce qui reste à faire, sans déplier une liste. Pure, testable.
  function repartirLignesThemeRelecture(lignes) {
    const aTraiter = lignes.filter(l => l.niveau === 'critique' || l.niveau === 'surveiller')
      .sort((x, y) => NIVEAUX_RELECTURE_OUTIL2[x.niveau].rang - NIVEAUX_RELECTURE_OUTIL2[y.niveau].rang);
    return { aTraiter, valides: lignes.filter(l => l.niveau === 'valide'), na: lignes.filter(l => l.niveau === 'na') };
  }

  let derniereSanteRelecture = null;

  // ---- Diagnostic de la relecture ------------------------------------------------------------
  // Ce que la relecture a réellement lu, et surtout ce qu'elle a ÉCARTÉ et pourquoi : pages lues
  // par document, points que le modèle n'a pas traités, citations introuvables mot pour mot, puis,
  // thème par thème, les clauses examinées par les contrôles CLAIRE. Replié par défaut : c'est un
  // outil de dépannage, à ouvrir quand un point attendu manque au bilan.
  let diagnosticRelectureOuverts = new Set();
  let refsDiagnosticRelecture = [];
  var MAX_LIGNES_DIAGNOSTIC_RAISON = 25;

  function basculerDiagnosticRelecture(cle, ouvert) {
    if (ouvert) diagnosticRelectureOuverts.add(cle); else diagnosticRelectureOuverts.delete(cle);
  }

  function ouvrirDiagnosticRelecture(idx) {
    const ref = refsDiagnosticRelecture[idx];
    if (!ref) return;
    ouvrirVisionneuseRelecture(ref.fichierId, ref.page, ref.extrait, true);
    const v = document.getElementById('relecture-visionneuse');
    if (v && v.scrollIntoView) v.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  // Page cliquable quand le document est encore consultable (déposé dans cette session, ou relu
  // depuis le NAS) ; sinon simple mention de la page.
  function pageDiagnosticRelecture(e) {
    if (!e.page) return e.document ? `<span class="diag-doc">${escapeHtml(e.document)}</span>` : '';
    const f = fichiersAnalyseIa.find(x => x.nom === e.document);
    const libelle = `${e.document ? escapeHtml(e.document) + ' · ' : ''}p.${e.page}`;
    if (!f) return `<span class="diag-doc">${libelle}</span>`;
    const idx = refsDiagnosticRelecture.push({ fichierId: f.id, page: e.page, extrait: e.phrase.slice(0, 120) }) - 1;
    return `<button type="button" class="page-chip" onclick="ouvrirDiagnosticRelecture(${idx})">${icone('eye')}${libelle}</button>`;
  }

  function ligneDiagnosticRelecture(e, avecRaison) {
    return `<li>${avecRaison ? `<strong>${escapeHtml(e.raison)}</strong> ` : ''}${e.precision && !avecRaison ? `<strong>${escapeHtml(e.precision)}</strong> ` : ''}${pageDiagnosticRelecture(e)}
      ${e.phrase ? `<blockquote class="diag-clause">${escapeHtml(e.phrase)}</blockquote>` : ''}</li>`;
  }

  function detailsDiagnosticRelecture(cle, resume, corps) {
    const ouvert = diagnosticRelectureOuverts.has(cle) ? ' open' : '';
    return `<details class="diag-groupe"${ouvert} ontoggle="basculerDiagnosticRelecture('${cle}', this.open)">
      <summary>${resume}</summary>${corps}</details>`;
  }

  function listeDiagnosticRelecture(entrees, avecRaison) {
    const vus = entrees.slice(0, MAX_LIGNES_DIAGNOSTIC_RAISON);
    const reste = entrees.length - vus.length;
    return `<ul class="diag-liste">${vus.map(e => ligneDiagnosticRelecture(e, avecRaison)).join('')}</ul>
      ${reste > 0 ? `<p class="hint">… et ${reste} autre(s), non affichée(s).</p>` : ''}`;
  }

  function renderDiagnosticRelecture(r, sections) {
    refsDiagnosticRelecture = [];
    const blocs = [];

    const couverture = r.couvertureDocuments || [];
    if (couverture.length) {
      blocs.push(`<div class="diag-bloc"><span class="section-eyebrow">Documents lus</span>
        <ul class="diag-liste">${couverture.map(c => `<li><strong>${escapeHtml(c.nom || 'Document')}</strong> — ${escapeHtml(libelleCouverturePages(c) || 'lu')}</li>`).join('')}</ul></div>`);
    }

    const lignes = (sections || []).reduce((acc, s) => acc.concat(s.lignes || []), []);
    if (analyseClaudeRelecture) {
      const omis = lignes.filter(l => l.omis);
      const citations = [];
      for (const l of lignes) for (const c of (l.citations || [])) if (!c.verifie) citations.push({ l, c });
      for (const x of (analyseClaudeRelecture.anomalies || [])) for (const c of (x.citations || [])) if (!c.verifie) citations.push({ l: { intitule: x.titre }, c });
      for (const x of (analyseClaudeRelecture.contradictions || [])) for (const c of [x.clause_a, x.clause_b]) if (c && !c.verifie) citations.push({ l: { intitule: 'Contradiction — ' + x.sujet }, c });
      blocs.push(`<div class="diag-bloc"><span class="section-eyebrow">Lecture par l’IA</span>
        <ul class="diag-liste">
          <li>${lignes.length} point(s) posé(s), ${omis.length ? `<strong>${omis.length} non traité(s) par le modèle</strong> (affichés « à vérifier »)` : 'tous traités par le modèle'}.</li>
          <li>${citations.length ? `<strong>${citations.length} citation(s) introuvable(s) mot pour mot</strong> dans les documents : à relire en priorité.` : 'Toutes les citations ont été retrouvées mot pour mot dans les documents.'}</li>
        </ul>
        ${omis.length ? detailsDiagnosticRelecture('omis', `Points non traités (${omis.length})`, `<ul class="diag-liste">${omis.map(l => `<li>${escapeHtml(l.intitule)}</li>`).join('')}</ul>`) : ''}
        ${citations.length ? detailsDiagnosticRelecture('citations', `Citations introuvables (${citations.length})`,
          `<ul class="diag-liste">${citations.map(({ l, c }) => `<li><strong>${escapeHtml(l.intitule)}</strong>${c.page ? ` · p.${c.page}` : ''}<blockquote class="diag-clause">${escapeHtml(c.extrait || '')}</blockquote></li>`).join('')}</ul>`) : ''}
      </div>`);
    }

    const themes = syntheseDiagnosticOutil2(r.diagnostic || []);
    if (themes.length) {
      blocs.push(`<div class="diag-bloc"><span class="section-eyebrow">Contrôles CLAIRE : clauses examinées ${infoBulle("Pour chaque thème, les clauses retenues et celles écartées avec la raison. Un point attendu qui manque au bilan se trouve en général dans une raison d’écart.")}</span>
        ${themes.map(t => detailsDiagnosticRelecture('theme:' + t.cle,
          `<strong>${escapeHtml(t.libelle)}</strong> <span class="diag-compte">${t.retenues.length} retenue(s) · ${t.nbEcartees} écartée(s)</span>`,
          (t.retenues.length ? detailsDiagnosticRelecture(`ret:${t.cle}`, `Retenues (${t.retenues.length})`, listeDiagnosticRelecture(t.retenues, true)) : '')
          + t.ecartees.map((g, i) => detailsDiagnosticRelecture(`ec:${t.cle}:${i}`, `Écartées — ${escapeHtml(g.raison)} (${g.entrees.length})`, listeDiagnosticRelecture(g.entrees, false))).join('')
        )).join('')}
      </div>`);
    } else if (r.diagnostic) {
      blocs.push('<p class="hint">Les contrôles CLAIRE n’ont examiné aucune clause des thèmes suivis.</p>');
    }

    if (!blocs.length) return '';
    const ouvert = diagnosticRelectureOuverts.has('racine') ? ' open' : '';
    return `<details class="diagnostic-parcours diagnostic-relecture"${ouvert} ontoggle="basculerDiagnosticRelecture('racine', this.open)">
      <summary><span class="section-eyebrow">Diagnostic de la relecture</span></summary>
      <div class="diagnostic-corps">${blocs.join('')}</div>
    </details>`;
  }

  function renderTableauDeBordRelecture() {
    const zone = document.getElementById('relecture-bilan');
    if (!zone) return;
    const r = dernierRapportAudit;
    if (!r) { zone.innerHTML = '<p class="hint">Aucune analyse pour l’instant.</p>'; return; }
    citationsRelecture = [];
    const a = analyseClaudeRelecture;
    const typeBien = typeBienEnvoyeRelecture || r.typeBien || '';
    const sections = a ? sectionsTableauDeBordOutil2(a, auditMode, typeBien) : [];
    construireConstatsClaudeRelecture(sections);
    // Les commentaires de l'étude s'appliquent aux lignes de Claude comme aux contrôles CLAIRE.
    for (const c of constatsClaudeRelecture) constatsAuditParUid[c.uid] = c;
    appliquerRetoursAuxConstats(constatsClaudeRelecture, retoursAudit, dernierAuditContexte ? dernierAuditContexte.dossierCle : '');

    const anomalies = constatsClaudeRelecture.filter(c => c.anomalie);
    const contradictions = constatsClaudeRelecture.filter(c => c.contradiction);
    const extras = anomalies.concat(contradictions).filter(c => !(c.retour && c.retour.verdict === 'faux_positif')).map(c => niveauDepuisGraviteRelecture(c.gravite));
    // Les contrôles CLAIRE affichés comptent aussi : une procédure en cours relevée par nos règles
    // est un point critique, qu'une ligne de grille l'ait vue ou non.
    const catsClaire = categoriesClaireBilanRelecture();
    for (const c of (r.constats || [])) {
      if (!catsClaire.has(c.categorie) || constatExcluOutil2(c) || rubriqueMasqueeAudit(c.categorie)) continue;
      if (c.gravite === 'CRITIQUE' || c.gravite === 'IMPORTANT') extras.push('critique');
      else if (c.gravite === 'A_VERIFIER') extras.push('surveiller');
    }
    const sectionsEffectives = sections.map(s => {
      const lignes = s.lignes.map(l => ({ ...l, niveau: niveauEffectifRelecture(l), _source: l }));
      const actives = lignes.filter(l => l.niveau !== 'na');
      const niveau = actives.some(l => l.niveau === 'critique') ? 'critique' : actives.some(l => l.niveau === 'surveiller') ? 'surveiller' : (actives.length ? 'valide' : 'na');
      return { ...s, niveau, lignesEff: lignes };
    });
    const sante = santeRelectureOutil2(sectionsEffectives.map(s => ({ lignes: s.lignesEff })), extras);
    derniereSanteRelecture = sante;
    const v = VERDICTS_SANTE_RELECTURE[sante.niveau];
    const n = NIVEAUX_RELECTURE_OUTIL2[sante.niveau];

    const copros = (a && a.coproprietes) || [];
    const textesCopro = documentsOrdonnesRelecture().filter(f => f.type !== 'justificatif').map(f => f.texte).join('\n');
    const detectees = detecterCoproprietesMultiplesOutil2(textesCopro);
    const bandeauCopro = copros.length > 1 || detectees.multiples ? `<section class="copro-multiples">
        <span class="dot-label dl-pret">${icone('info')}${Math.max(copros.length, detectees.nombre)} copropriétés dans cet acte</span>
        ${copros.length ? `<ul>${copros.map(c => `<li><strong>${escapeHtml(c.designation)}</strong>${c.lots ? ` — lots ${escapeHtml(c.lots)}` : ''}${c.observations ? `<p class="hint">${escapeHtml(c.observations)}</p>` : ''}</li>`).join('')}</ul>` : '<p class="hint">Chaque point copropriété de la grille doit être vérifié pour chacune d’elles.</p>'}
      </section>` : '';

    const tuiles = sectionsEffectives.map(s => {
      const ns = NIVEAUX_RELECTURE_OUTIL2[s.niveau];
      const points = s.lignesEff.map(l => `<span class="tuile-point niveau-${l.niveau}" title="${escapeAttr(l.intitule)} — ${NIVEAUX_RELECTURE_OUTIL2[l.niveau].texte}"></span>`).join('');
      return `<button type="button" class="sante-tuile niveau-${s.niveau}" onclick="allerSectionRelecture('${s.cle}')">
        <span class="sante-tuile-titre">${escapeHtml(s.titre)}</span>
        <span class="dot-label ${ns.dl}"><span class="dot"></span>${ns.texte}</span>
        <span class="sante-tuile-points">${points}</span>
      </button>`;
    }).join('');

    const detailSections = sectionsEffectives.map(s => {
      const { aTraiter, valides, na } = repartirLignesThemeRelecture(s.lignesEff);
      const ns = NIVEAUX_RELECTURE_OUTIL2[s.niveau];
      return `<section class="grille-section niveau-${s.niveau}" id="relecture-section-${s.cle}">
        <h3 class="grille-section-titre"><span>${escapeHtml(s.titre)}</span><span class="dot-label ${ns.dl}"><span class="dot"></span>${ns.texte}</span></h3>
        <div class="grille-colonnes">
          <div class="grille-col grille-col-traiter">
            <span class="section-eyebrow">À surveiller <span class="grille-col-compte">${aTraiter.length}</span></span>
            ${aTraiter.length ? aTraiter.map(l => lignePointRelecture(l._source)).join('') : '<p class="hint grille-col-vide">Rien à surveiller sur ce thème.</p>'}
          </div>
          <div class="grille-col grille-col-valides">
            <span class="section-eyebrow">Validé <span class="grille-col-compte">${valides.length}</span></span>
            ${valides.length ? valides.map(l => lignePointRelecture(l._source)).join('') : '<p class="hint grille-col-vide">Aucun point validé.</p>'}
          </div>
        </div>
        ${na.length ? `<p class="hint grille-na">${na.length} point(s) sans objet : ${escapeHtml(na.map(l => l.intitule.split(' (')[0]).join(' · '))}</p>` : ''}
      </section>`;
    }).join('');

    // Clauses contradictoires : les deux passages côte à côte, chacun avec sa page — c'est en les
    // lisant ensemble que le notaire tranche. Affichée même vide quand l'IA a tourné : « aucune
    // contradiction relevée » est une information, pas un silence.
    const clauseContradiction = (c, lettre) => c ? `<div class="contradiction-clause">
        <span class="contradiction-lettre">${lettre}</span>
        <blockquote class="obligation-clause${c.verifie ? '' : ' non-verifiee'}">${escapeHtml(c.extrait || '')}</blockquote>
        <div class="point-citations">${pastilleCitationRelecture(c)}</div>
      </div>` : '';
    // Une analyse enregistrée avant cette rubrique n'a pas de liste : rien n'y a été cherché, on
    // n'affiche donc pas « aucune contradiction ».
    const contradictionsHtml = a && Array.isArray(a.contradictions) ? `<section class="grille-section" id="relecture-section-contradictions">
        <h3 class="grille-section-titre"><span>Clauses contradictoires</span><span class="audit-section-compte">${contradictions.length}</span></h3>
        ${contradictions.length ? contradictions.map(c => {
          const exclu = c.retour && c.retour.verdict === 'faux_positif';
          const niv = exclu ? 'na' : niveauDepuisGraviteRelecture(c.gravite);
          const nn = NIVEAUX_RELECTURE_OUTIL2[niv];
          const pied = modeCommentairesAudit ? renderCommentaireConstatAudit(c) : renderRetourResumeAudit(c);
          return `<div class="point-ligne niveau-${niv}" id="audit-constat-${c.uid}">
            <span class="dot-label ${nn.dl}">${icone(nn.icone)}${exclu ? 'Faux positif' : nn.texte}</span>
            <div class="point-corps"><div class="point-intitule">${escapeHtml(c.titre)}</div>
              ${c.description ? `<p class="point-commentaire">${escapeHtml(c.description)}</p>` : ''}
              <div class="contradiction-paire">${clauseContradiction(c.contradiction.clause_a, 'A')}${clauseContradiction(c.contradiction.clause_b, 'B')}</div>${pied}</div>
          </div>`;
        }).join('') : '<p class="hint grille-col-vide">Aucune contradiction relevée entre les clauses.</p>'}
      </section>` : '';

    const anomaliesHtml = anomalies.length ? `<section class="grille-section" id="relecture-section-anomalies">
        <h3 class="grille-section-titre"><span>Autres points relevés</span><span class="audit-section-compte">${anomalies.length}</span></h3>
        ${anomalies.map(c => {
          const exclu = c.retour && c.retour.verdict === 'faux_positif';
          const niv = exclu ? 'na' : niveauDepuisGraviteRelecture(c.gravite);
          const nn = NIVEAUX_RELECTURE_OUTIL2[niv];
          const pied = modeCommentairesAudit ? renderCommentaireConstatAudit(c) : renderRetourResumeAudit(c);
          return `<div class="point-ligne niveau-${niv}" id="audit-constat-${c.uid}">
            <span class="dot-label ${nn.dl}">${icone(nn.icone)}${exclu ? 'Faux positif' : nn.texte}</span>
            <div class="point-corps"><div class="point-intitule">${escapeHtml(c.titre)}</div>
              ${c.description ? `<p class="point-commentaire">${escapeHtml(c.description)}</p>` : ''}
              <div class="point-citations">${(c.anomalie.citations || []).map(pastilleCitationRelecture).join('')}</div>${pied}</div>
          </div>`;
        }).join('')}
      </section>` : '';

    // Contrôle automatique CLAIRE, sans IA : seulement ce que dit l'acte lui-même.
    const blocActe = SECTIONS_RAPPORT_OUTIL2.find(b => b.cle === 'ACTE');
    const claire = `<section class="claire-controles claire-acte">
        <div class="claire-acte-tete"><span class="section-eyebrow">Contrôle automatique CLAIRE</span>
          <span class="hint">Règles locales, sans IA</span></div>
        ${renderPartiesDossierAudit(r)}
        ${renderBlocAudit(blocActe, r, r.constats || [])}
      </section>`;

    const f = factureRelecture;
    const cout = f ? `<section class="relecture-cout">
        <span class="section-eyebrow">Coût de l'analyse</span>
        <div class="relecture-cout-grille">
          <div><strong>${formaterCoutUsd(f.coutUsd)}</strong><span>facturé par ${(f.fournisseur || (String(f.modele || '').startsWith('mistral') ? 'mistral' : 'claude')) === 'mistral' ? 'Mistral AI' : 'Anthropic'}</span></div>
          <div><strong>${(f.jetonsEntree || 0).toLocaleString('fr-FR')}</strong><span>jetons lus</span></div>
          <div><strong>${(f.jetonsSortie || 0).toLocaleString('fr-FR')}</strong><span>jetons produits</span></div>
          <div><strong>${formaterDureeMs(f.dureeMs)}</strong><span>${escapeHtml(LIBELLES_MODELES_CLAUDE[f.modele] || f.modele || '')}</span></div>
        </div>
        ${renderJournalCoutRelecture()}
      </section>` : '';

    const libelleType = (TYPES_BIEN_AUDIT.find(t => t.valeur === typeBien) || {}).libelle;
    const entete = `<section class="sante-carte niveau-${sante.niveau}">
        <div class="sante-visuel">${donutSanteRelecture(sante.compte)}<span class="sante-visuel-chiffre">${sante.compte.critique + sante.compte.surveiller}<small>à traiter</small></span></div>
        <div class="sante-texte">
          <span class="dot-label ${n.dl}">${icone(n.icone)}${v.titre}</span>
          <h2 class="sante-titre">${a && a.type_acte ? escapeHtml(a.type_acte) : (auditMode === 'acte' ? "Projet d'acte de vente" : "Projet d'avant-contrat")}</h2>
          ${libelleType ? `<span class="sante-type-bien">${escapeHtml(libelleType)}</span>` : ''}
          <p class="sante-phrase">${sante.compte.critique ? `${sante.compte.critique} point(s) critique(s), ` : ''}${v.phrase}.</p>
          <div class="sante-compteurs">
            <span class="sante-compteur c-critique"><strong>${sante.compte.critique}</strong>critique(s)</span>
            <span class="sante-compteur c-surveiller"><strong>${sante.compte.surveiller}</strong>à surveiller</span>
            <span class="sante-compteur c-valide"><strong>${sante.compte.valide}</strong>validé(s)</span>
            <span class="sante-compteur c-na"><strong>${sante.compte.na}</strong>sans objet</span>
          </div>
          ${a && a.synthese ? `<p class="sante-synthese">${escapeHtml(a.synthese)}</p>` : ''}
          ${a ? '' : `<p class="hint">${erreurClaudeRelecture ? escapeHtml(erreurClaudeRelecture) + ' — ' : ''}Analyse par l'IA non effectuée : ce bilan ne repose que sur les contrôles automatiques de CLAIRE.</p>`}
        </div>
        <label class="audit-bascule-commentaires" title="Donner votre avis sur chaque point : il est retenu pour les prochaines relectures (pour ce dossier ou pour tous).">
          <span class="switch small"><input type="checkbox" ${modeCommentairesAudit ? 'checked' : ''} onchange="basculerModeCommentairesAudit(this.checked)"><span class="slider"></span></span>
          Mode commentaires
        </label>
      </section>`;

    zone.innerHTML = `${renderBandeauArchiveRelecture()}
    <div class="relecture-bilan-haut">
      <div class="relecture-bilan-resume">${entete}${bandeauCopro}</div>
      ${claire}
    </div>
    ${modeCommentairesAudit ? renderPanneauCommentairesAudit() : ''}
    <div class="relecture-bilan-grille">
      <div class="relecture-bilan-principal">
        ${tuiles ? `<div class="sante-tuiles">${tuiles}</div>` : ''}
        ${detailSections}
        ${contradictionsHtml}
        ${anomaliesHtml}
        ${cout}
        ${renderDiagnosticRelecture(r, sections)}
        <p class="hint relecture-cadre">Aide à la relecture ${infoBulle("Chaque point est une proposition, citée page à l'appui, que le notaire vérifie et tranche. Les données identifiantes ont été masquées avant l'envoi et la correspondance est restée sur ce poste.")}</p>
      </div>
      <aside class="relecture-visionneuse" id="relecture-visionneuse" aria-label="Aperçu du document"></aside>
    </div>`;
    // L'aperçu reste toujours ouvert : sur la citation demandée, sinon sur le document relu.
    const v0 = visionneuseRelecture;
    if (v0.ouverte && fichierRelecture(v0.fichierId)) renderVisionneuseRelecture(true);
    else {
      const defaut = premierDocumentVisionneuseRelecture();
      if (defaut) ouvrirVisionneuseRelecture(defaut.id, 1, '', true);
      else renderVisionneuseVideRelecture();
    }
  }

  function allerSectionRelecture(cle) {
    const el = document.getElementById('relecture-section-' + cle);
    if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  // ---- Visionneuse : les pastilles de page ouvrent le document à la bonne page ----------------
  let visionneuseRelecture = { ouverte: false, fichierId: null, page: 1, extrait: '', verifie: true, pdf: null, rendues: new Set() };
  const cachePdfRelecture = new Map();

  async function pdfPourFichierRelecture(f) {
    if (cachePdfRelecture.has(f.id)) return cachePdfRelecture.get(f.id);
    let pdf;
    if (f.cheminNas) {
      pdf = await ouvrirPdfNas(f.cheminNas);
    } else {
      const buffer = await f.file.arrayBuffer();
      pdf = await pdfjsLib.getDocument({ data: buffer, verbosity: (pdfjsLib.VerbosityLevel ? pdfjsLib.VerbosityLevel.ERRORS : 0) }).promise;
    }
    cachePdfRelecture.set(f.id, pdf);
    return pdf;
  }

  // Un document de la relecture tel qu'on peut l'afficher : le fichier déposé ou lu sur le NAS
  // pendant la session, ou — pour une analyse enregistrée rouverte plus tard — son chemin sur le
  // NAS, seul moyen de le retrouver (les PDF déposés depuis le poste ne sont pas conservés).
  function fichierRelecture(fichierId) {
    const f = fichiersAnalyseIa.find(x => x.id === fichierId);
    if (f) return f;
    const d = documentsEnvoyesRelecture.find(x => x.fichierId === fichierId);
    return d && d.cheminNas ? { id: d.fichierId, nom: d.nom, type: d.type, nature: d.nature, cheminNas: d.cheminNas } : null;
  }

  function premierDocumentVisionneuseRelecture() {
    const docs = documentsEnvoyesRelecture.length
      ? documentsEnvoyesRelecture.map(d => fichierRelecture(d.fichierId)).filter(Boolean)
      : documentsOrdonnesRelecture();
    return docs.find(f => f.type === 'principal') || docs[0] || null;
  }

  // Jamais un grand cadre blanc : sans document à montrer, l'aperçu dit pourquoi.
  function fermerVisionneuseRelecture() {
    visionneuseRelecture = { ouverte: false, fichierId: null, page: 1, extrait: '', verifie: true, pdf: null, rendues: new Set() };
  }

  function renderVisionneuseVideRelecture() {
    const aside = document.getElementById('relecture-visionneuse');
    if (!aside) return;
    aside.dataset.fichier = '';
    aside.innerHTML = `<div class="visionneuse-vide">${icone('eye')}<strong>Aucun aperçu disponible</strong>
      <p class="hint">${relectureArchiveeOuverte
        ? "Cette analyse enregistrée ne conserve pas les PDF déposés depuis le poste : seules les pièces lues sur le NAS peuvent être rouvertes."
        : "Le document relu n'est plus disponible dans cette session."}</p></div>`;
  }

  function ouvrirCitationRelecture(idx) {
    const c = citationsRelecture[idx];
    if (!c) return;
    const doc = documentsEnvoyesRelecture.find(d => d.numero === c.document);
    if (!doc || !fichierRelecture(doc.fichierId)) {
      afficherToast(doc ? "Ce document n'est pas conservé avec l'analyse enregistrée : ouvrez-le depuis le NAS." : "Document introuvable pour cette citation.", 'OK', null);
      return;
    }
    ouvrirVisionneuseRelecture(doc.fichierId, c.page || 1, c.extrait || '', c.verifie !== false);
    // Sous 1180 px l'aperçu passe sous les thèmes : on l'amène à l'écran.
    const aside = document.getElementById('relecture-visionneuse');
    if (aside && window.innerWidth <= 1180 && aside.scrollIntoView) aside.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  async function ouvrirVisionneuseRelecture(fichierId, page, extrait, verifie) {
    const changement = visionneuseRelecture.fichierId !== fichierId;
    visionneuseRelecture = { ...visionneuseRelecture, ouverte: true, fichierId, page, extrait, verifie };
    if (changement) { visionneuseRelecture.pdf = null; visionneuseRelecture.rendues = new Set(); }
    await renderVisionneuseRelecture(changement);
  }

  async function renderVisionneuseRelecture(reconstruire) {
    const aside = document.getElementById('relecture-visionneuse');
    const v = visionneuseRelecture;
    const f = fichierRelecture(v.fichierId);
    if (!aside) return;
    if (!f) { renderVisionneuseVideRelecture(); return; }
    const affichables = (documentsEnvoyesRelecture.length
      ? documentsEnvoyesRelecture.map(d => fichierRelecture(d.fichierId))
      : documentsOrdonnesRelecture()).filter(Boolean);
    const options = affichables.map(x => `<option value="${escapeAttr(x.id)}" ${x.id === f.id ? 'selected' : ''}>${escapeHtml(x.nom)}</option>`).join('');
    const existant = aside.querySelector('.visionneuse-pages');
    if (!existant || reconstruire || aside.dataset.fichier !== f.id) {
      aside.dataset.fichier = f.id;
      aside.innerHTML = `<div class="visionneuse-tete">
          <span class="visionneuse-titre">${icone('eye')}Aperçu</span>
          <select aria-label="Document affiché" onchange="ouvrirVisionneuseRelecture(this.value, 1, '', true)">${options}</select>
        </div>
        <div class="visionneuse-extrait" id="visionneuse-extrait"></div>
        <div class="visionneuse-pages" id="visionneuse-pages"><p class="hint">${icone('spinner', null, true)} Ouverture du document…</p></div>`;
      v.rendues = new Set();
    }
    const ex = document.getElementById('visionneuse-extrait');
    if (ex) {
      ex.innerHTML = v.extrait
        ? `<blockquote class="obligation-clause"><span class="obligation-page">p.${v.page}</span>${escapeHtml(v.extrait)}</blockquote>${v.verifie ? '' : `<p class="analyse-ia-citation-douteuse">${icone('alert-triangle')}Extrait introuvable mot pour mot : la page indiquée est celle annoncée par l'analyse, à vérifier.</p>`}`
        : '';
    }
    if (!window.pdfjsLib) {
      document.getElementById('visionneuse-pages').innerHTML = '<p class="hint">Lecture PDF indisponible.</p>';
      return;
    }
    try {
      if (!v.pdf) v.pdf = await pdfPourFichierRelecture(f);
      const conteneur = document.getElementById('visionneuse-pages');
      if (!conteneur.querySelector('.visionneuse-page')) {
        conteneur.innerHTML = '';
        // Les emplacements prennent d'emblée la taille d'une page entière (celle de la page 1) : la
        // position de défilement de chaque page est juste avant même qu'elle soit dessinée.
        const premiere = await v.pdf.getPage(1);
        const taille = tailleVisionneuseRelecture(premiere.getViewport({ scale: 1 }), conteneur);
        for (let i = 1; i <= v.pdf.numPages; i++) {
          const bloc = document.createElement('div');
          bloc.className = 'visionneuse-page';
          bloc.id = 'visionneuse-page-' + i;
          bloc.dataset.page = String(i);
          bloc.style.width = taille.largeur + 'px';
          bloc.style.height = taille.hauteur + 'px';
          bloc.innerHTML = `<span class="visionneuse-num">p.${i}</span>`;
          conteneur.appendChild(bloc);
        }
        // Rendu à la demande : un dossier de 60 pages ne se dessine pas d'un bloc.
        const observateur = new IntersectionObserver(entrees => {
          for (const e of entrees) if (e.isIntersecting) rendrePageVisionneuseRelecture(Number(e.target.dataset.page));
        }, { root: conteneur, rootMargin: '400px 0px' });
        conteneur.querySelectorAll('.visionneuse-page').forEach(b => observateur.observe(b));
      }
      const page = Math.max(1, Math.min(v.page, v.pdf.numPages));
      await rendrePageVisionneuseRelecture(page);
      const conteneurPages = document.getElementById('visionneuse-pages');
      const cible = document.getElementById('visionneuse-page-' + page);
      if (cible) {
        // Défile dans l'aperçu seul : un scrollIntoView ferait aussi bouger toute la page.
        conteneurPages.scrollTop += cible.getBoundingClientRect().top - conteneurPages.getBoundingClientRect().top - 8;
        if (v.extrait || page > 1) {
          cible.classList.remove('flash');
          void cible.offsetWidth;
          cible.classList.add('flash');
        }
      }
      if (v.extrait) surlignerExtraitVisionneuseRelecture(page, v.extrait);
    } catch (e) {
      console.error('Visionneuse : ouverture impossible', e);
      const conteneur = document.getElementById('visionneuse-pages');
      if (conteneur) conteneur.innerHTML = `<p class="hint">${icone('alert-triangle')} Ouverture du document impossible.</p>`;
    }
  }

  async function rendrePageVisionneuseRelecture(numero) {
    const v = visionneuseRelecture;
    if (!v.pdf || v.rendues.has(numero)) return;
    v.rendues.add(numero);
    const bloc = document.getElementById('visionneuse-page-' + numero);
    if (!bloc) return;
    const page = await v.pdf.getPage(numero);
    const base = page.getViewport({ scale: 1 });
    const taille = tailleVisionneuseRelecture(base, document.getElementById('visionneuse-pages'));
    bloc.style.width = taille.largeur + 'px';
    bloc.style.height = taille.hauteur + 'px';
    const viewport = page.getViewport({ scale: taille.echelle * (window.devicePixelRatio || 1) });
    const canvas = document.createElement('canvas');
    canvas.width = viewport.width;
    canvas.height = viewport.height;
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    await page.render({ canvasContext: canvas.getContext('2d'), viewport }).promise;
    bloc.appendChild(canvas);
  }

  // La page ENTIÈRE tient dans la zone visible de la visionneuse, en largeur comme en hauteur :
  // caler seulement la largeur donnait une page A4 plus haute que le panneau, dont on ne voyait
  // jamais le bas sans faire défiler (demande de l'étude au premier essai de la relecture).
  function tailleVisionneuseRelecture(base, conteneur) {
    return tailleAjusteePage(base.width, base.height,
      (conteneur && conteneur.clientWidth) || 540, (conteneur && conteneur.clientHeight) || 760);
  }

  // Pure : dimensions d'une page de largeur l × hauteur h ramenée dans une zone dispoL × dispoH
  // (marges intérieures de la zone déduites), sans jamais la déformer.
  function tailleAjusteePage(l, h, dispoL, dispoH) {
    const marge = 24;
    const largeurDispo = Math.max(160, dispoL - marge);
    const hauteurDispo = Math.max(200, dispoH - marge);
    const echelle = Math.min(largeurDispo / l, hauteurDispo / h);
    return { echelle, largeur: Math.floor(l * echelle), hauteur: Math.floor(h * echelle) };
  }

  // Même principe que voirEngagementDansPdf (Outil 1) : retrouver l'extrait dans le texte de la
  // page et poser un surlignage sur les items pdf.js concernés.
  async function surlignerExtraitVisionneuseRelecture(numero, extrait) {
    try {
      const v = visionneuseRelecture;
      const bloc = document.getElementById('visionneuse-page-' + numero);
      const canvas = bloc && bloc.querySelector('canvas');
      if (!canvas) return;
      const page = await v.pdf.getPage(numero);
      const content = await page.getTextContent();
      const echelleAffichee = canvas.clientWidth / page.getViewport({ scale: 1 }).width;
      const viewport = page.getViewport({ scale: echelleAffichee });
      let texte = '';
      const origines = [];
      content.items.forEach((item, i) => { for (const ch of item.str) { texte += ch; origines.push(i); } texte += ' '; origines.push(-1); });
      const { texte: texteNorm, index } = normaliserAvecIndex(texte);
      const cible = normaliserAvecIndex(extrait).texte;
      let longueur = Math.min(60, cible.length);
      let pos = -1;
      while (longueur >= 15 && pos === -1) { pos = texteNorm.indexOf(cible.slice(0, longueur)); if (pos === -1) longueur -= 10; }
      if (pos === -1) return;
      const debut = index[pos];
      const fin = index[Math.min(pos + cible.length - 1, index.length - 1)];
      const items = new Set();
      for (let i = debut; i <= fin; i++) if (origines[i] >= 0) items.add(origines[i]);
      bloc.querySelectorAll('.pdf-highlight').forEach(h => h.remove());
      items.forEach(i => {
        const item = content.items[i];
        const tx = pdfjsLib.Util.transform(viewport.transform, item.transform);
        const hauteur = Math.hypot(tx[2], tx[3]) || 12;
        const s = document.createElement('div');
        s.className = 'pdf-highlight visionneuse-surlignage';
        s.style.left = Math.max(0, tx[4] - 3) + 'px';
        s.style.top = Math.max(0, tx[5] - hauteur - 2) + 'px';
        s.style.width = ((item.width || 0) * echelleAffichee + 6) + 'px';
        s.style.height = (hauteur + 5) + 'px';
        bloc.appendChild(s);
      });
    } catch (e) {
      console.warn('Surlignage impossible', e);
    }
  }

  // ---- Réglages : fournisseur, clés API et modèles ---------------------------------------------
  // Mistral par défaut (point d'accès de l'Union européenne), Claude en option. Un seul formulaire :
  // seuls les champs du fournisseur choisi sont affichés. Les clés ne reviennent jamais du serveur.
  let reglagesIaCharges = null;

  function afficherChampsFournisseurIa() {
    const sel = document.getElementById('reglages-ia-fournisseur');
    const f = sel ? sel.value : 'mistral';
    const m = document.getElementById('reglages-ia-mistral');
    const c = document.getElementById('reglages-ia-claude');
    // style.display et non l'attribut hidden : .calc-champs pose un display qui l'emporterait.
    if (m) m.style.display = f === 'mistral' ? '' : 'none';
    if (c) c.style.display = f === 'claude' ? '' : 'none';
  }

  async function chargerReglagesClaude() {
    try {
      const r = await fetchAvecAuth('/api/relecture-claude/reglages');
      if (!r.ok) return;
      const data = await r.json();
      reglagesIaCharges = data;
      const valeur = (id, v) => { const el = document.getElementById(id); if (el && v) el.value = v; };
      valeur('reglages-ia-fournisseur', data.fournisseur || 'mistral');
      valeur('reglages-claude-modele', data.modele);
      valeur('reglages-mistral-modele', data.modeleMistral);
      valeur('reglages-mistral-region', data.regionMistral);
      const cleClaude = document.getElementById('reglages-claude-cle');
      if (cleClaude) {
        cleClaude.value = '';
        cleClaude.placeholder = data.cleEnregistree ? '•••••••• enregistrée — saisir pour remplacer' : (data.cleEnvironnement ? 'Clé fournie par le serveur (variable ANTHROPIC_API_KEY)' : 'sk-ant-…');
      }
      const cleMistral = document.getElementById('reglages-mistral-cle');
      if (cleMistral) {
        cleMistral.value = '';
        cleMistral.placeholder = data.cleMistralEnregistree ? '•••••••• enregistrée — saisir pour remplacer' : (data.cleMistralEnvironnement ? 'Clé fournie par le serveur (variable MISTRAL_API_KEY)' : 'Clé API Mistral');
      }
      afficherChampsFournisseurIa();
    } catch (e) { /* écran Réglages : sans connexion, rien à afficher */ }
  }

  async function enregistrerReglagesClaude() {
    const lire = (id) => { const el = document.getElementById(id); return el ? el.value : undefined; };
    const corps = {
      fournisseur: lire('reglages-ia-fournisseur'),
      modele: lire('reglages-claude-modele'),
      modeleMistral: lire('reglages-mistral-modele'),
      regionMistral: lire('reglages-mistral-region')
    };
    // Une clé n'est envoyée que si quelqu'un l'a tapée : sinon celle en place est conservée.
    const cleClaude = (lire('reglages-claude-cle') || '').trim();
    const cleMistral = (lire('reglages-mistral-cle') || '').trim();
    if (cleClaude) corps.cleApi = cleClaude;
    if (cleMistral) corps.cleMistral = cleMistral;
    const res = document.getElementById('reglages-claude-resultat');
    try {
      const r = await fetchAvecAuth('/api/relecture-claude/reglages', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(corps) });
      if (!r.ok) throw new Error('statut ' + r.status);
      etatClaudeRelecture = null;
      estimationRelecture = null;
      await chargerReglagesClaude();
      if (res) res.innerHTML = `<span class="dot-label dl-success">${icone('check')}Enregistré</span>`;
    } catch (e) {
      if (res) res.innerHTML = `<span class="dot-label dl-urgent">${icone('alert-triangle')}Enregistrement impossible</span>`;
    }
  }

  // Efface la clé du fournisseur AFFICHÉ, pas les deux.
  async function effacerCleClaude() {
    const f = (document.getElementById('reglages-ia-fournisseur') || {}).value === 'claude' ? 'claude' : 'mistral';
    const nom = f === 'claude' ? 'Claude' : 'Mistral';
    demanderConfirmation(`Effacer la clé API ${nom} enregistrée sur le serveur ?`, async () => {
      const corps = f === 'claude' ? { cleApi: '' } : { cleMistral: '' };
      await fetchAvecAuth('/api/relecture-claude/reglages', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(corps) });
      etatClaudeRelecture = null;
      await chargerReglagesClaude();
    });
  }

  // Vérifie la clé du fournisseur ENREGISTRÉ (pas celui sélectionné sans avoir été enregistré).
  async function testerCleClaude() {
    const res = document.getElementById('reglages-claude-resultat');
    const choisi = (document.getElementById('reglages-ia-fournisseur') || {}).value;
    if (reglagesIaCharges && choisi && choisi !== reglagesIaCharges.fournisseur) {
      if (res) res.innerHTML = `<span class="dot-label dl-pret">${icone('alert-triangle')}Enregistrez d'abord le changement de fournisseur</span>`;
      return;
    }
    if (res) res.innerHTML = `<span class="hint">${icone('spinner', null, true)} Vérification…</span>`;
    try {
      const r = await fetchAvecAuth('/api/relecture-claude/tester', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
      const data = await r.json().catch(() => ({}));
      const lieu = data.fournisseur === 'mistral' ? (data.region === 'global' ? '' : ' · Union européenne') : '';
      if (res) res.innerHTML = r.ok
        ? `<span class="dot-label dl-success">${icone('check')}Clé valide — ${escapeHtml(LIBELLES_MODELES_CLAUDE[data.modele] || data.libelle || data.modele)} accessible${lieu}</span>`
        : `<span class="dot-label dl-urgent">${icone('alert-triangle')}${escapeHtml(data.erreur || 'Échec')}</span>`;
    } catch (e) {
      if (res) res.innerHTML = `<span class="dot-label dl-urgent">${icone('alert-triangle')}Serveur injoignable</span>`;
    }
  }


  // ==== GÉNÉRATEUR D'APPEL DE FONDS ====
  //
  // Produit la « Convocation au rendez-vous contenant l'appel de fonds » : le courrier que
  // l'étude adresse à l'acquéreur pour lui annoncer la date de signature et le décompte des
  // sommes à virer. Porté d'un artefact fourni par l'étude, avec deux partis pris :
  //
  // 1. **Le CHROME (formulaire, boutons, champs) prend les jetons de CLAIRE** — même gabarit que
  //    le simulateur de provision. **L'APERÇU DE LA LETTRE garde, lui, l'identité PAPIER de
  //    l'étude** (bordeaux #6D2332, Lora, les vrais logos, la colonne de contact) : c'est le
  //    fac-similé d'un document réellement envoyé, et le .docx téléchargé a cet en-tête-là.
  //    Le repeindre en bleu CLAIRE ferait mentir l'aperçu sur ce qui sortira de l'imprimante.
  //    Même principe que imprimerFiche(), dont les couleurs inline ne suivent pas non plus le
  //    thème de l'application.
  // 2. **Rien n'est inventé à partir du dossier.** Le préremplissage ne pose que ce que CLAIRE
  //    sait vraiment (voir prefillAppelFonds), et dit à l'écran ce qu'il n'a pas pu remplir.
  //
  // Tout ce qui suit jusqu'à « fin du socle pur » est PUR et déclaré en `function`/`var` :
  // testable depuis tests/helpers/load-app.js (voir la limite du harnais dans CLAUDE.md).

  // --- montants -----------------------------------------------------------------------------
  // Un décompte de confrère écrit « 1 234,56 € », parfois avec une espace insécable comme
  // séparateur de milliers. parseFloat() ne sait lire ni l'un ni l'autre.
  function montantDepuisTexteFr(texte) {
    if (texte == null) return null;
    const nettoye = String(texte).replace(/[€\s ]/g, '').replace(/\./g, '').replace(',', '.');
    const n = parseFloat(nettoye);
    return Number.isFinite(n) ? n : null;
  }

  function montantVersTexteFr(n) {
    if (n == null || !Number.isFinite(n)) return '';
    return formaterPrixCentimes(n);
  }

  // --- parseur du décompte du confrère --------------------------------------------------------
  //
  // Quand l'étude est notaire PARTICIPANT, le décompte vient du confrère sous forme de PDF et
  // n'a aucune structure exploitable : un tableau mis à plat, une ligne de texte par ligne du
  // tableau. Ces motifs ont été écrits sur de vrais décomptes — ne pas les resserrer sans
  // relire les tests correspondants (tests/appel-de-fonds.test.js), même consigne que pour les
  // regex de détection de dates.
  var AF_MONTANT_FIN_RE = /([0-9]{1,3}(?:[.\s ][0-9]{3})*,[0-9]{2})(?:\s*€)+\s*$/;
  // Un libellé coupé par la mise en page du confrère (« …frais et droits de l’acte de » / « prêt »)
  // laisse sur la ligne SUIVANTE un ou deux mots en minuscules, sans montant : c’est la fin du
  // libellé précédent, pas le début du suivant. Borné à 35 caractères et à des minuscules : un
  // vrai libellé de ligne commence par une majuscule.
  var AF_FIN_LIBELLE_RE = /^[a-zà-ÿ][a-zà-ÿ'’\s-]{0,35}$/;
  var AF_EURO_SEUL_RE = /€\s*$/;
  // « Offerts », « Néant », « pour mémoire »… : une ligne complète, mais sans chiffre.
  var AF_SANS_MONTANT_RE = /[(]?\b(offerts?|n[ée]ant|directement\s+au\s+syndic|sans\s+objet|non\s+concern[ée]|(?:pour\s+)?m[ée]moire)\b[)]?\s*$/i;
  var AF_MEMOIRE_RE = /\bm[ée]moire\b/i;
  // Prorata : « 913 € x 92 jours / 365 jours », ou sa forme compacte « 1829x203/365 ».
  var AF_FORMULE_RE = /^\s*([0-9]+(?:[.\s ][0-9]{3})*(?:,[0-9]+)?)\s*€?\s*(?:jours?)?\s*[x×*]\s*([0-9]{1,4})\s*(?:jours?)?\s*\/\s*([0-9]{1,4})\s*(?:jours?)?\s*$/i;
  // Même motif que AF_FORMULE_RE mais cherché en FIN de libellé plutôt que sur la ligne entière.
  var AF_FORMULE_FIN_RE = /([0-9]+(?:[.\s\u00a0][0-9]{3})*(?:,[0-9]+)?)\s*\u20ac?\s*(?:jours?)?\s*[x\u00d7*]\s*([0-9]{1,4})\s*(?:jours?)?\s*\/\s*([0-9]{1,4})\s*(?:jours?)?\s*$/i;
  var AF_BASCULE_DEBIT_RE = /^(frais\s+(a|à)\s+ajouter|a\s*ajouter|a\s*payer)\b/i;
  var AF_BASCULE_CREDIT_RE = /^(a\s*d[ée]duire|sommes?\s+(a|à)\s+d[ée]duire|sous\s+d[ée]duction)\b/i;
  // Lignes de sous-total du confrère : ce sont des CONTRÔLES, pas des lignes du décompte —
  // les reprendre comme lignes compterait deux fois les mêmes sommes.
  var AF_SOUS_TOTAL_RE = /^(ensemble|total(\s+des\s+d[ée]penses)?|soit\s+au\s+total|total\s+a\s+(payer|d[ée]duire)|reste\s+(a|à)\s+verser(\s+a\s+la\s+signature)?|versement\s+(a|à)\s+la\s+signature|solde(\s+(a|à)\s+(verser|payer))?|solde\s+prix\s+de\s+vente)\b/i;
  var AF_LIGNE_PRIX_RE = /^prix\s+(de\s+vente|d'acquisition)\b/i;

  function afIdLigne() { return 'af' + Math.random().toString(36).slice(2, 9); }

  function afExtraireFormule(libelle) {
    const m = /\(([^()]*)\)\s*$/.exec(libelle);
    if (m && AF_FORMULE_RE.test(m[1].trim())) {
      return { libelle: libelle.slice(0, m.index).trim(), formule: m[1].trim() };
    }
    // Sans parenthèses : « Prorata taxe foncière 913 € x 92 jours / 365 jours ». Mise en page
    // rencontrée en vérifiant le contrôle de prorata de bout en bout — la formule était bien là,
    // mais sortait `null`, donc aucun recalcul n'était tenté. Ancré en FIN de libellé et sur le
    // motif complet (montant × jours / jours) : un libellé ne finit pas par cette suite-là par
    // hasard.
    const nu = AF_FORMULE_FIN_RE.exec(libelle);
    if (nu) {
      return { libelle: libelle.slice(0, nu.index).trim(), formule: nu[0].trim() };
    }
    return { libelle, formule: null };
  }

  // « Ensemble 3 400,00 € 3 400,00 € » : deux montants sur la même ligne = un sous-total reporté.
  function afDeuxMontants(ligne) {
    const m1 = AF_MONTANT_FIN_RE.exec(ligne);
    if (!m1) return null;
    const reste = ligne.slice(0, m1.index).trim().replace(/-\s*$/, '').trim();
    const m2 = AF_MONTANT_FIN_RE.exec(reste);
    if (!m2 || m2.index + m2[0].length !== reste.length) return null;
    return { libelle: reste.slice(0, m2.index).trim(), second: montantDepuisTexteFr(m1[1]) };
  }

  // Les décomptes de confrère préfixent couramment chaque ligne d'un tiret ou d'une puce
  // (« - Frais d'achat ») : c'est une décoration de liste, pas une partie du libellé, et elle
  // partirait telle quelle dans le courrier. Les deux branches du parseur en retiraient déjà un
  // en tête de ligne, mais pas celle où le libellé et son montant sont sur DEUX lignes (le tiret
  // vit alors dans libelleEnAttente), ni les puces et tirets longs. Un seul nettoyage, appliqué
  // au libellé final, couvre tous les chemins.
  var AF_PUCE_DEBUT_RE = /^[\s\u2022\u00b7\u2043\u25aa\u25cf\u2010-\u2015*\u2212-]+/;

  function afNettoyerLibelle(s) {
    // Le deux-points final vient de la mise en page du décompte (« Prix de vente: 220 000,00 € »),
    // où il annonce la colonne des montants : il n'a plus de sens une fois la valeur dans sa
    // propre cellule.
    return String(s || '').replace(AF_PUCE_DEBUT_RE, '').replace(/\s*:\s*$/, '').trim();
  }

  // Vocabulaire de l'étude. Chaque confrère nomme les mêmes lignes à sa façon (« Prix de vente »,
  // « Frais d'achat », « Prorata TF »…) et ces libellés partent tels quels dans le courrier de
  // l'étude : ils sont donc ramenés à la formulation qu'elle emploie, demandée explicitement.
  //
  // La normalisation ne touche QUE le libellé : un montant, un signe ou une formule n'en dépendent
  // jamais. Et elle ne s'applique qu'à un libellé RECONNU — tout ce qui ne l'est pas (une ligne
  // propre à ce dossier, une taxe locale, un honoraire) garde le sien, mot pour mot : renommer ce
  // qu'on n'a pas compris serait pire que de ne rien faire.
  //
  // L'ordre compte : « Provision sur frais » et « Acompte sur frais » sont un acompte sur les
  // FRAIS, pas sur le prix, et doivent donc être testés avant « acompte » tout court ; de même
  // « frais d'acte de prêt » n'est pas « frais d'acte » et doit sortir avant lui.
  var LIBELLES_NORMALISES_DECOMPTE = [
    // À écarter d'abord : ces lignes ressemblent aux suivantes sans être elles.
    { garde: true, motif: /\bfrais\s+d?['’]?\s*acte\s+de\s+pr[êe]t\b|\bacte\s+de\s+pr[êe]t\b|\bfrais\s+de\s+pr[êe]ts?\b|\bfrais\s+de\s+(?:promesse|mainlev[ée]e|n[ée]gociation)\b/i },

    { libelle: 'Acompte sur frais versé à l’étude',
      motif: /\b(?:provision|acompte)\s+sur\s+(?:les\s+)?frais\b|\bprovision\s+(?:d[ée]jà\s+)?vers[ée]e\b/i },
    { libelle: 'Acompte sur prix versé à l’étude',
      motif: /\b(?:acompte|arrhes|s[ée]questre)\b|\bd[ée]p[ôo]t\s+de\s+garantie\b/i },
    { libelle: 'Montant des frais et droits de l’acte de vente',
      motif: /\bfrais\s+et\s+droits\b|\bfrais\s+d?['’]?\s*(?:acte|achat|acquisition)\b|\bfrais\s+de\s+notaire\b|\bfrais\s+notari[ée]s|[ée]moluments\s+et\s+droits\b/i },
    { libelle: 'Quote-part de taxes foncières',
      motif: /\b(?:prorata|quote[\s-]*part|r[ée]partition)\b[^.]{0,30}(?:\bTF\b|taxes?\s+fonci[èe]res?)|taxes?\s+fonci[èe]res?[^.]{0,30}\b(?:prorata|quote[\s-]*part)/i },
    { libelle: 'Prix d’acquisition',
      motif: /\bprix\s+(?:de\s+vente|d?['’]?\s*acquisition|de\s+cession|principal)\b|^prix\b/i }
  ];

  function normaliserLibelleDecompte(libelle) {
    const brut = String(libelle || '').trim();
    if (!brut) return brut;
    for (const r of LIBELLES_NORMALISES_DECOMPTE) {
      if (!r.motif.test(brut)) continue;
      return r.garde ? brut : r.libelle;
    }
    return brut;
  }

  function afMajusculeInitiale(s) {
    s = afNettoyerLibelle(s);
    return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
  }

  // --- date et heure du rendez-vous, lues dans la convocation du confrère ------------------------
  //
  // C'est la SEULE source de l'horaire dans cet écran : le dossier suivi ne porte qu'une date
  // (`d.rendezVousSignature` est un champ date, sans heure), alors que la convocation du confrère
  // écrit le jour ET l'heure en toutes lettres.
  //
  // Ancrage OBLIGATOIRE sur le vocabulaire du rendez-vous. Une convocation est pleine de dates qui
  // n'en sont pas : la date du courrier, les bornes d'un prorata de taxe foncière, la date du
  // compromis. Prendre « la première date du document » donnerait le mauvais jour bien plus
  // souvent que le bon — même prudence que la fenêtre de SEQUESTRE_RE autour de la clause de dépôt.
  var AF_ANCRE_RDV_RE = /rendez[-\s]?vous|convocation|signature|r[ée]it[ée]ration|vous\s+(?:recevoir|attendre|attendons|recevons)/i;
  // La date est cherchée APRÈS l'ancre en priorité (« le rendez-vous est fixé au 14 octobre »),
  // et seulement à défaut avant (« le 14 octobre 2026 à 14 h, rendez-vous en l'étude ») : chercher
  // les deux d'un bloc ferait remonter la date du courrier, qui précède souvent l'objet.
  var AF_APRES_ANCRE_RDV = 240;
  var AF_AVANT_ANCRE_RDV = 60;

  // 14h30 / 14 h 30 / 14:30 / 14 heures 30 / 14 heures / 14h. Le motif exige h / heures /
  // deux-points, ce qui écarte déjà tout montant ; le lookbehind couvre le reste (« 3,14 h » ne
  // donne pas 14 h). Le lookahead ne porte QUE sur un chiffre : y mettre aussi le point rejetait
  // « à 10 h. », c'est-à-dire une heure en fin de phrase — l'écriture la plus courante dans une
  // convocation.
  var AF_HEURE_RDV_RE = /(?<![\d,.])([01]?\d|2[0-3])\s*(?:h(?:eures?)?|:)\s*([0-5]\d)?(?!\d)/i;

  // L'heure se lit AUTOUR de la date retenue, jamais dans toute la fenêtre : « Convocation du
  // 12 octobre 2026. Le rendez-vous est fixé au 14 octobre 2026 à 11 heures » donnerait sinon
  // « 12 octobre à 11 heures » — une date et une heure qui ne vont pas ensemble, le pire résultat
  // possible ici. L'année termine la date dans les deux écritures (14/10/2026 comme
  // 14 octobre 2026) : elle suffit à la situer dans la fenêtre.
  var AF_AVANT_DATE_HEURE = 60;  // « à 11 heures le 14 octobre 2026 »
  var AF_APRES_DATE_HEURE = 44;  // « le 14 octobre 2026 à 11 heures 30 »

  function afZoneHeureAutourDate(fenetre, iso) {
    const annee = String(iso || '').slice(0, 4);
    const pos = fenetre.indexOf(annee);
    if (pos < 0) return fenetre;
    return fenetre.slice(Math.max(0, pos - AF_AVANT_DATE_HEURE), pos + annee.length + AF_APRES_DATE_HEURE);
  }

  function afHeureDansFragment(fragment) {
    const m = AF_HEURE_RDV_RE.exec(String(fragment || ''));
    if (!m) return null;
    return pad(parseInt(m[1], 10)) + ':' + pad(m[2] ? parseInt(m[2], 10) : 0);
  }

  // Renvoie { date, heure, extrait } : date en ISO, heure en HH:MM, l'une comme l'autre nulles si
  // rien de sûr n'a été lu. L'ANNÉE doit figurer dans le texte — « le mardi 14 octobre à 10 heures »
  // ne rend rien plutôt qu'une année devinée, exactement comme « fin septembre » côté détection de
  // dates du compromis.
  function detecterRendezVousDecompte(texte) {
    // Le texte d'un PDF arrive découpé en lignes : sans cet aplatissement, « fixé au\n14 octobre
    // 2026 » ne serait jamais lu comme une seule phrase.
    const src = String(texte || '').replace(/\s+/g, ' ');
    const vide = { date: null, heure: null, extrait: '' };
    if (!src) return vide;
    const ancres = new RegExp(AF_ANCRE_RDV_RE.source, 'gi');
    let sansHeure = null;
    let m;
    while ((m = ancres.exec(src)) !== null) {
      const finAncre = m.index + m[0].length;
      const apres = src.slice(finAncre, Math.min(src.length, finAncre + AF_APRES_ANCRE_RDV));
      const avant = src.slice(Math.max(0, m.index - AF_AVANT_ANCRE_RDV), m.index);
      let fenetre = apres;
      let date = extraireDateDeFragment(apres);
      if (!date) { fenetre = avant; date = extraireDateDeFragment(avant); }
      if (!date) continue;
      const heure = afHeureDansFragment(afZoneHeureAutourDate(fenetre, date));
      // Une mention qui donne l'heure l'emporte sur une mention qui n'a que le jour : un titre
      // (« Convocation du 14 octobre 2026 ») précède souvent la phrase complète, plus précise.
      if (heure) return { date, heure, extrait: fenetre.trim() };
      if (!sansHeure) sansHeure = { date, heure: null, extrait: fenetre.trim() };
    }
    return sansHeure || vide;
  }

  function parserDecompteConfrere(texte) {
    const lignes = String(texte || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    const brut = [];
    const meta = { soldeDeclare: null, refTrouvee: null, avertissements: [] };
    const candidatsPrix = [];
    let signe = 1;
    let libelleEnAttente = null;
    let ligneHorsPrixVue = false;
    // Dernière ligne ajoutée, pour y rattacher une fin de libellé renvoyée à la ligne suivante.
    let derniere = null;

    // Un décompte répète parfois le prix (une fois en tête, une fois dans le corps) : on ne garde
    // que la DERNIÈRE occurrence rencontrée avant la première vraie ligne de frais, et on le dit.
    const viderCandidatsPrix = () => {
      if (!candidatsPrix.length) return;
      if (candidatsPrix.length > 1) {
        meta.avertissements.push(`Plusieurs lignes de prix détectées (${candidatsPrix.map(c => c.libelle).join(' / ')}) — seule « ${candidatsPrix[candidatsPrix.length - 1].libelle} » a été retenue.`);
      }
      const garde = candidatsPrix[candidatsPrix.length - 1];
      brut.push({ libelle: garde.libelle, montant: garde.montant, signe: 1, formule: null, id: afIdLigne() });
      candidatsPrix.length = 0;
    };

    for (const ligne of lignes) {
      if (AF_BASCULE_DEBIT_RE.test(ligne)) { viderCandidatsPrix(); signe = 1; libelleEnAttente = null; derniere = null; continue; }
      if (AF_BASCULE_CREDIT_RE.test(ligne)) { viderCandidatsPrix(); signe = -1; libelleEnAttente = null; derniere = null; continue; }
      if (/^(votre\s+d[ée]compte|d[ée]compte\s+(pr[ée]visionnel|acqu[ée]reur))/i.test(ligne)) continue;

      const mRef = /^r[ée]f[ée]rences?\s+dossier\s*:\s*(.+)$/i.exec(ligne);
      if (mRef) { meta.refTrouvee = mRef[1].trim(); continue; }

      const deux = afDeuxMontants(ligne);
      if (deux && (AF_SOUS_TOTAL_RE.test(deux.libelle) || deux.libelle === '')) {
        viderCandidatsPrix();
        meta.soldeDeclare = deux.second;
        libelleEnAttente = null;
        derniere = null;
        continue;
      }

      const mMontant = AF_MONTANT_FIN_RE.exec(ligne);
      if (!mMontant) {
        if (AF_EURO_SEUL_RE.test(ligne) || AF_SANS_MONTANT_RE.test(ligne)) {
          const estMemoire = AF_MEMOIRE_RE.test(ligne);
          const libelle = afNettoyerLibelle(ligne.replace(AF_EURO_SEUL_RE, '').replace(AF_SANS_MONTANT_RE, ''));
          viderCandidatsPrix();
          ligneHorsPrixVue = true;
          brut.push({ libelle: libelle || '(ligne)', montant: 0, signe, formule: null, id: afIdLigne(), memoire: estMemoire });
          libelleEnAttente = null;
          continue;
        }
        if (!libelleEnAttente && derniere && AF_FIN_LIBELLE_RE.test(ligne)) {
          derniere.libelle = derniere.libelle + ' ' + ligne;
          derniere = null;
          continue;
        }
        // Pas de montant : c'est un libellé dont le montant est sur la ligne suivante.
        libelleEnAttente = libelleEnAttente ? (libelleEnAttente + ' ' + ligne) : ligne;
        continue;
      }

      const montant = montantDepuisTexteFr(mMontant[1]);
      const avantMontant = afNettoyerLibelle(ligne.slice(0, mMontant.index));
      let formule = null;
      let libelle;
      if (/^[(（]/.test(avantMontant) && libelleEnAttente) {
        // Ligne de continuation : « ((913 € x 92 jours) / 365 jours)   230,13 € »
        formule = avantMontant.replace(/[()）（]/g, '').trim();
        libelle = libelleEnAttente;
      } else {
        libelle = avantMontant || libelleEnAttente || '(ligne)';
      }
      libelleEnAttente = null;

      if (!formule) {
        const ex = afExtraireFormule(libelle);
        libelle = ex.libelle;
        formule = ex.formule;
      }
      // Avant les deux tests qui suivent : un « - Ensemble » venu d'un libellé en attente ne
      // matcherait aucun des deux motifs, tous deux ancrés en début de chaîne.
      libelle = afNettoyerLibelle(libelle);

      if (AF_SOUS_TOTAL_RE.test(libelle)) { viderCandidatsPrix(); meta.soldeDeclare = montant; derniere = null; continue; }
      if (AF_LIGNE_PRIX_RE.test(libelle) && !ligneHorsPrixVue) { derniere = { libelle, montant }; candidatsPrix.push(derniere); continue; }

      viderCandidatsPrix();
      ligneHorsPrixVue = true;
      derniere = { libelle, montant, signe, formule, id: afIdLigne() };
      brut.push(derniere);
    }
    viderCandidatsPrix();

    const lignesFinales = { debit: [], credit: [] };
    for (const it of brut) {
      (it.signe >= 0 ? lignesFinales.debit : lignesFinales.credit).push({
        libelle: normaliserLibelleDecompte(afMajusculeInitiale(it.libelle)), montant: it.montant,
        formule: it.formule, id: it.id, memoire: !!it.memoire
      });
    }
    return { lignes: lignesFinales, meta };
  }

  // Recalcule un prorata annoncé par le confrère. Un écart de plus de 2 centimes est signalé :
  // c'est la seule vérification que l'outil peut faire sur un décompte qu'il n'a pas produit.
  function verifierProrataLigne(ligne) {
    if (!ligne || !ligne.formule) return { statut: 'non-verifiable' };
    const m = AF_FORMULE_RE.exec(ligne.formule);
    if (!m) return { statut: 'non-verifiable' };
    const base = montantDepuisTexteFr(m[1]);
    const num = parseFloat(m[2]);
    const den = parseFloat(m[3]);
    if (base == null || !num || !den) return { statut: 'non-verifiable' };
    const attendu = Math.round((base * num / den) * 100) / 100;
    return Math.abs(attendu - ligne.montant) <= 0.02
      ? { statut: 'ok', attendu }
      : { statut: 'ecart', attendu };
  }

  // Le contrôle des frais d'acte, pendant de verifierProrataLigne ci-dessus : la SECONDE chose que
  // l'outil peut vérifier sur un décompte qu'il n'a pas produit. Il compare le montant annoncé au
  // barème du simulateur de provision (via estimerFraisActe, la formule partagée) et dit seulement
  // s'il est au-dessus, en dessous, ou dans la fourchette — il ne REMPLIT jamais la ligne :
  // ce barème n'a jamais été audité (voir l'avertissement du simulateur), et un chiffre annoncé
  // à un client engage l'étude.
  //
  // Le libellé doit désigner les frais de l'acte de VENTE. « Frais d'acte de prêt », « frais de
  // mainlevée », « frais de négociation » relèvent d'autres barèmes : les contrôler contre
  // celui-ci ferait croire à un écart sur une ligne parfaitement juste.
  //
  // « Frais d'achat » / « frais d'acquisition » : ce sont les libellés employés par les confrères
  // dans les décomptes réels (« Frais d'achat (sauf à parfaire ou à diminuer) »), pas
  // « frais d'acte » comme le modèle de l'étude — le contrôle ne se déclenchait donc jamais sur
  // un décompte importé, celui-là même qu'il sert à vérifier. Signalé par l'étude.
  var AF_FRAIS_ACTE_RE = /\b(?:frais\s+et\s+droits|frais\s+d['\u2019]?\s*(?:acte|achat|acquisition)|frais\s+de\s+notaire|frais\s+notari[ée]s|[ée]moluments\s+et\s+droits|provision\s+sur\s+frais)\b/i;
  var AF_FRAIS_HORS_VENTE_RE = /\b(pr[êe]t|mainlev[ée]e|n[ée]gociation|hypoth[èe]que|caution|copropri[ée]t[ée]|syndic|bancaires?|garantie|succession)\b/i;

  function estLigneFraisActeVente(libelle) {
    const t = String(libelle || '');
    return AF_FRAIS_ACTE_RE.test(t) && !AF_FRAIS_HORS_VENTE_RE.test(t);
  }

  // Le code postal donne un département, mais les clés du barème ne suivent pas toutes cette
  // découpe : la Corse y est regroupée sous « 20 », l'Alsace sous « 67/68 », et le 69 est scindé
  // entre Métropole de Lyon et Rhône — impossible à trancher depuis un code postal seul, donc
  // rien n'est proposé dans ce cas plutôt qu'un département pris au hasard entre les deux.
  function cleBaremeDepuisDepartement(dept) {
    if (!dept) return null;
    if (dept === '2A' || dept === '2B') return '20';
    if (dept === '67' || dept === '68') return '67/68';
    if (dept === '69') return null;
    return DEPARTEMENTS_FRAIS_ACTE[dept] ? dept : null;
  }

  var AF_TYPE_BIEN_PAR_TYPE_VENTE = { maison: 'house', copropriete: 'condo', terrain: 'land' };

  // La désignation du bien est un champ LIBRE (« une maison », « un lot de copropriété », « un
  // terrain à bâtir »…) : elle sert au courrier, mais elle dit aussi de quelle nature de bien il
  // s'agit, la seule autre donnée dont le contrôle des frais a besoin. On la lit donc plutôt que de
  // faire ressaisir la même chose deux fois à dix lignes d'écart. L'ordre des tests compte :
  // « lot de copropriété dans un immeuble » est une copropriété, pas un immeuble. Une désignation
  // qui ne tranche pas ne rend rien — le contrôle se tait alors, plutôt que de comparer à un
  // barème qui n'est pas celui du bien.
  function typeBienDepuisDesignation(texte) {
    const t = normaliserPourRecherche(String(texte || ''));
    if (!t) return null;
    if (/\b(?:lot|copropriete|appartement|studio|duplex)\b/.test(t)) return 'condo';
    if (/\b(?:terrain|parcelle|terrains)\b/.test(t)) return 'land';
    if (/\b(?:maison|immeuble|pavillon|villa|longere|batiment)\b/.test(t)) return 'house';
    return null;
  }

  // Le contrôle des frais se nourrit de ce qui est déjà saisi au-dessus (adresse et désignation du
  // bien), sans jamais écraser un choix explicite : dès que quelqu'un touche l'un des deux menus,
  // son drapeau passe à true et l'auto-remplissage le laisse tranquille pour le reste de la
  // session de saisie (remis à zéro par reinitialiserAppelFonds). Sans ce garde-fou, corriger un
  // département à la main serait annulé à la frappe suivante dans l'adresse.
  let afFraisChoisiALaMain = { departement: false, type: false };

  function marquerChoixFraisAppelFonds(quoi) {
    afFraisChoisiALaMain[quoi] = true;
    renderTableAppelFonds();
  }

  // Renvoie true si l'un des deux menus a réellement changé : l'appelant ne reconstruit le tableau
  // du décompte que dans ce cas, plutôt qu'à chaque frappe dans l'adresse.
  function majFraisDepuisBienAppelFonds() {
    let change = false;
    const poser = (id, valeur) => {
      const el = afEl(id);
      if (!el || el.value === valeur) return;
      el.value = valeur;
      change = true;
    };
    if (!afFraisChoisiALaMain.departement) {
      const cp = (afValeur('af-adresse-bien').match(/\b\d{5}\b/) || [null])[0];
      const cle = cleBaremeDepuisDepartement(departementDepuisCodePostal(cp));
      // Une clé absente du menu (69, Corse/Alsace non tranchées) remet le champ à vide plutôt que
      // de laisser le département précédent contrôler une adresse qui n'est plus la sienne.
      poser('af-frais-departement', cle && DEPARTEMENTS_FRAIS_ACTE[cle] ? cle : '');
    }
    if (!afFraisChoisiALaMain.type) {
      poser('af-frais-type', typeBienDepuisDesignation(afValeur('af-designation')) || '');
    }
    return change;
  }

  // Le dossier ne dit pas si l'acquéreur est primo-accédant, et le total change selon le régime
  // (hausse départementale temporaire appliquée ou non). Plutôt que de parier, on calcule les
  // DEUX bornes : un montant qui tombe entre les deux est conforme, quel que soit le régime réel.
  function fourchetteFraisActe(prix, cleDepartement, typeBien) {
    const avantage = estimerFraisActe(prix, cleDepartement, typeBien, true);
    const plein = estimerFraisActe(prix, cleDepartement, typeBien, false);
    if (!avantage || !plein) return null;
    return {
      min: Math.min(avantage.total, plein.total),
      max: Math.max(avantage.total, plein.total)
    };
  }

  // Tolérance au-delà de la fourchette : 1 % du montant attendu, au moins 50 €. Le barème est
  // interpolé entre deux paliers et ne couvre pas les débours variables (copies, formalités) —
  // signaler un écart de quelques dizaines d'euros ferait du bruit sans rien apprendre.
  function verifierFraisActeLigne(montant, fourchette) {
    if (!fourchette || !Number.isFinite(montant) || montant <= 0) return { statut: 'non-verifiable' };
    const tolerance = Math.max(50, fourchette.max * 0.01);
    if (montant < fourchette.min - tolerance) {
      return { statut: 'sous', ecart: Math.round((fourchette.min - montant) * 100) / 100, min: fourchette.min, max: fourchette.max };
    }
    if (montant > fourchette.max + tolerance) {
      return { statut: 'sur', ecart: Math.round((montant - fourchette.max) * 100) / 100, min: fourchette.min, max: fourchette.max };
    }
    return { statut: 'ok', min: fourchette.min, max: fourchette.max };
  }

  // --- clients et formule d'appel ---------------------------------------------------------------
  // La formule d'appel dépend de la civilité de CHAQUE destinataire : c'est pour ça que la
  // civilité est un champ à part entière et jamais devinée depuis un prénom.
  function salutationAppelFonds(clients) {
    const liste = Array.isArray(clients) ? clients : [];
    // Une personne morale n'a pas de civilité : on s'adresse à son gérant, sans présumer son genre.
    if (liste.some(c => c && c.civilite === 'SCI')) return 'Cher Monsieur/Madame le gérant,';
    const civilites = liste.map(c => (c && c.civilite) || 'M');
    if (liste.length <= 1) {
      const c = civilites[0] || 'M';
      return (c === 'Mme' || c === 'Mlle') ? 'Chère Madame,' : 'Cher Monsieur,';
    }
    const hommes = civilites.includes('M');
    const femmes = civilites.some(c => c === 'Mme' || c === 'Mlle');
    if (hommes && femmes) return 'Chers Monsieur et Madame,';
    return hommes ? 'Chers Messieurs,' : 'Chères Mesdames,';
  }

  function ligneClientComplete(c) {
    if (!c) return '';
    if (c.civilite === 'SCI') return String(c.nom || '').trim();
    const civLong = c.civilite === 'M' ? 'Monsieur' : (c.civilite === 'Mlle' ? 'Mademoiselle' : 'Madame');
    return [civLong, c.prenom, c.nom].filter(Boolean).join(' ').trim();
  }

  // --- ce que CLAIRE sait du dossier ------------------------------------------------------------
  //
  // Les acquéreurs du dossier, sous la forme attendue par le générateur. **La civilité et le
  // prénom ne sont PAS devinés** : l'extraction du compromis ne retient que le patronyme (voir
  // detecterParties), et se tromper de civilité produit un courrier qui appelle « Monsieur » une
  // cliente. `aCompleter` dit à l'écran ce qu'il reste à saisir plutôt que de le masquer.
  function clientsDepuisDossier(d) {
    if (!d) return [];
    const parties = Array.isArray(d.parties) ? d.parties.filter(p => p && p.role === 'acquereur') : [];
    if (parties.length) {
      return parties.map(p => p.qualitePersonne === 'morale'
        ? { civilite: 'SCI', prenom: '', nom: p.nom || '', aCompleter: false }
        : { civilite: 'M', prenom: '', nom: p.nom || '', aCompleter: true });
    }
    // Repli pour un dossier créé à la main ou antérieur à l'extraction structurée : le nom du
    // dossier est « VENDEUR / ACQUÉREUR », les couples séparés par « & ».
    const nom = String(d.nom || '');
    const cote = nom.includes('/') ? nom.split('/').pop() : '';
    return cote.split('&').map(s => s.trim()).filter(Boolean)
      .map(n => ({ civilite: 'M', prenom: '', nom: n, aCompleter: true }));
  }

  // La désignation du bien telle qu'elle s'écrit dans le courrier. « Copropriété » ne veut pas
  // dire « appartement » (un garage, une cave ou un local se vendent aussi en lots) : on reste
  // sur le vocabulaire notarial exact.
  function designationDepuisTypeVente(typeVente) {
    if (typeVente === 'copropriete') return 'un lot de copropriété';
    if (typeVente === 'terrain') return 'un terrain à bâtir';
    if (typeVente === 'maison') return 'une maison';
    return '';
  }

  // Le dépôt de garantie est DÉDUIT du virement de l'acquéreur, qu'il soit séquestré à l'étude ou
  // à l'agence. **Corrigé sur retour de l'étude** : la première version excluait le dépôt détenu
  // par l'agence, sur l'idée qu'il se réglait directement entre l'agence et le vendeur. C'est faux
  // — « l'agence nous reverse la somme », donc elle arrive bien dans la comptabilité de l'étude et
  // l'acquéreur ne doit pas la virer une seconde fois. Le DÉTENTEUR reste distingué (`motif`) et
  // affiché dans le récapitulatif : c'est une somme que l'étude devra réclamer à l'agence avant la
  // signature, pas un détail sans conséquence.
  var AF_SEQUESTRE_ETUDE_RE = /\b(notaire|[ée]tude|office\s+notarial|comptabilit[ée]\s+(?:de\s+l['’])?[ée]tude|CARPA|s[ée]questre\s+notari[ée])\b/i;
  var AF_SEQUESTRE_TIERS_RE = /\b(agence|agent\s+immobilier|cabinet|n[ée]gociateur|mandataire)\b/i;

  function depotDeductible(d) {
    if (!d || !d.depotGarantie) return { deductible: false, motif: 'absent' };
    const sequestre = String(d.sequestreDepot || '').trim();
    // L'agence est testée EN PREMIER : « versé à l'agence qui en donnera quittance au notaire »
    // contient les deux mots, et c'est bien l'agence qui détient les fonds.
    if (AF_SEQUESTRE_TIERS_RE.test(sequestre)) return { deductible: true, motif: 'tiers' };
    if (AF_SEQUESTRE_ETUDE_RE.test(sequestre)) return { deductible: true, motif: 'etude' };
    // Détenteur illisible ou absent du dossier : déduit quand même (le dépôt existe et revient à
    // l'étude dans les deux cas connus), mais signalé comme à confirmer — c'est le seul point
    // vraiment incertain.
    return { deductible: true, motif: 'indetermine' };
  }

  // Le courrier ne parle de frais d'acte de prêt que si le prêt est GARANTI PAR UNE HYPOTHÈQUE :
  // un prêt cautionné (Crédit Logement…) ne donne lieu à aucun acte notarié, donc à aucun frais
  // supplémentaire à appeler. CLAIRE lit déjà ces garanties dans l'offre (voir GARANTIES_PRET).
  function pretHypothecaireDossier(d) {
    if (!d || d.sansPret) return false;
    const garanties = Array.isArray(d.garantiesPret) ? d.garantiesPret : [];
    if (!garanties.length) return null; // garanties inconnues : ni oui ni non, l'étude tranche
    return garanties.some(g => g === 'hypothequeLegale' || g === 'hypothequeConventionnelle');
  }

  // Assemble tout ce que le dossier permet de préremplir, et surtout ce qu'il NE permet PAS :
  // `aCompleter` alimente le récapitulatif affiché à l'écran, pour que l'étude sache exactement
  // ce qui a été repris et ce qui reste à sa charge. Fonction pure, testable.
  function prefillAppelFonds(d) {
    if (!d) return null;
    const clients = clientsDepuisDossier(d);
    const depot = depotDeductible(d);
    const hypo = pretHypothecaireDossier(d);
    const repris = [];
    const aCompleter = [];

    if (clients.length) {
      repris.push(clients.length > 1 ? `${clients.length} acquéreurs` : 'Acquéreur');
      if (clients.some(c => c.aCompleter)) aCompleter.push('Civilité et prénom de chaque client — l’acte n’en donne que le nom.');
    } else {
      aCompleter.push('Nom du ou des acquéreurs — aucun n’a pu être lu sur ce dossier.');
    }

    if (d.adresseBien) repris.push('Adresse du bien'); else aCompleter.push('Adresse du bien.');
    if (designationDepuisTypeVente(d.typeVente)) repris.push('Désignation du bien');
    if (d.rendezVousSignature) repris.push('Date du rendez-vous de signature');
    else aCompleter.push('Date du rendez-vous — aucune n’est encore fixée sur le dossier.');
    if (d.prixVente) repris.push('Prix d’acquisition'); else aCompleter.push('Prix d’acquisition.');

    // Le dépôt est déduit dans tous les cas (voir depotDeductible), mais son DÉTENTEUR change ce que
    // l'étude a à faire avant la signature : rien si elle le détient déjà, réclamer les fonds à
    // l'agence sinon — d'où une ligne dans « à compléter » plutôt qu'un simple « repris ».
    if (depot.deductible) {
      repris.push('Dépôt de garantie porté en déduction');
      if (depot.motif === 'tiers') aCompleter.push(`Dépôt de garantie détenu par un tiers (${d.sequestreDepot}) : à réclamer avant la signature, il est déjà déduit du virement demandé.`);
      else if (depot.motif === 'indetermine') aCompleter.push('Dépôt de garantie déduit, mais le dossier ne dit pas clairement qui le détient — à confirmer avant envoi.');
    }

    if (hypo === true) {
      repris.push('Prêt garanti par une hypothèque : montant du prêt déduit, frais de garantie à appeler');
      if (!(d.montantPret > 0)) aCompleter.push('Montant du prêt — l’offre de prêt n’en a pas donné.');
    } else if (hypo === null) aCompleter.push('Garanties du prêt inconnues : à cocher vous-même si un acte de prêt est à recevoir.');

    // Lus dans l'avant-contrat (voir detecterHonorairesNegociation / detecterFondsTravaux).
    const honoraires = d.honoraires && !d.honoraires.direct && d.honoraires.charge === 'ACQUEREUR' ? d.honoraires : null;
    if (honoraires) {
      if (honoraires.montantTTC) repris.push('Honoraires de négociation à la charge de l’acquéreur');
      else aCompleter.push('Honoraires de négociation à la charge de l’acquéreur : montant TTC non lu.');
    }
    const fondsTravaux = d.fondsTravaux && d.fondsTravaux.rembourse ? d.fondsTravaux : null;
    if (fondsTravaux) {
      if (fondsTravaux.montant) repris.push('Remboursement du fonds de travaux (loi ALUR)');
      else aCompleter.push('Fonds de travaux remboursé au vendeur : montant à reprendre de l’état daté.');
    }

    aCompleter.push('Montant des frais et droits de l’acte de vente — à reprendre de votre provision.');

    // Pour le CONTRÔLE des frais (jamais pour les remplir) : le département vient du code postal du
    // bien, le type de bien du type de vente. Ni l'un ni l'autre n'est deviné quand le dossier ne
    // permet pas de trancher (Corse/Alsace regroupées, 69 scindé — voir cleBaremeDepuisDepartement).
    const cpBien = (String(d.adresseBien || '').match(/\b\d{5}\b/) || [null])[0];
    const departementFrais = cleBaremeDepuisDepartement(departementDepuisCodePostal(cpBien));
    const typeBienFrais = AF_TYPE_BIEN_PAR_TYPE_VENTE[d.typeVente] || null;

    return {
      dossierId: d.id,
      // Référence du courrier : « VTE - NOM » pour un dossier de vente (demandé par l'étude, 29/09).
      dossierNom: d.nom ? libelleDossierAffiche(d) : '',
      clients,
      adresseBien: normaliserAdresse(d.adresseBien),
      designation: designationDepuisTypeVente(d.typeVente),
      dateRdv: d.rendezVousSignature || '',
      prixVente: d.prixVente || null,
      prixMobilier: d.prixMobilier || null,
      depotGarantie: depot.deductible ? d.depotGarantie : null,
      depotMotif: depot.motif,
      departementFrais,
      typeBienFrais,
      pretHypothecaire: hypo === true,
      montantPret: hypo === true && d.montantPret > 0 ? d.montantPret : null,
      honoraires: honoraires ? { nom: honoraires.nom || '', negociateur: honoraires.negociateur, montantTTC: honoraires.montantTTC || null } : null,
      fondsTravaux: fondsTravaux ? { montant: fondsTravaux.montant || null } : null,
      // Décompte établi par l'office, ou repris de celui d'un confrère quand l'étude est en
      // participation (demandé par l'étude le 29/09).
      modeDecompte: modeDecompteParDefaut(d),
      sansPret: !!d.sansPret,
      repris,
      aCompleter
    };
  }

  // Les lignes du décompte déduites du dossier. Une ligne à zéro reste affichée : c'est un
  // emplacement à remplir, pas une ligne vide à masquer — la retirer ferait oublier les frais.
  function lignesDecompteDepuisPrefill(p) {
    const debit = [
      { libelle: "Prix d'acquisition", montant: (p && p.prixVente) || 0, formule: null, id: afIdLigne() },
      { libelle: "Montant des frais et droits de l'acte de vente", montant: 0, formule: null, id: afIdLigne() }
    ];
    if (p && p.pretHypothecaire) {
      debit.push({ libelle: "Frais d'acte de prêt (garantie hypothécaire)", montant: 0, formule: null, id: afIdLigne() });
    }
    if (p && p.honoraires) {
      const qui = p.honoraires.nom ? ` (${p.honoraires.nom})` : '';
      debit.push({ libelle: `Honoraires de négociation TTC${qui}`, montant: p.honoraires.montantTTC || 0, formule: null, id: afIdLigne() });
    }
    if (p && p.fondsTravaux) {
      debit.push({ libelle: 'Remboursement du fonds de travaux (loi ALUR)', montant: p.fondsTravaux.montant || 0, formule: null, id: afIdLigne() });
    }
    const credit = [];
    if (p && p.depotGarantie) {
      // Le dépôt est déduit quel que soit son détenteur (voir depotDeductible), mais le libellé ne
      // doit pas affirmer qu'il a été versé à l'étude quand il est chez l'agence.
      const libelleAcompte = p.depotMotif === 'etude'
        ? "Acompte sur prix versé à l'étude"
        : 'Acompte sur prix déjà versé';
      credit.push({ libelle: libelleAcompte, montant: p.depotGarantie, formule: null, id: afIdLigne() });
    }
    // Prêt garanti par une hypothèque : les fonds de la banque transitent par l'étude et viennent en
    // déduction ; les frais de l'acte de prêt (garantie) sont appelés au débit (règle confirmée par
    // l'étude le 29/09).
    if (p && p.pretHypothecaire) {
      credit.push({ libelle: 'Montant du prêt (versé par la banque)', montant: p.montantPret || 0, formule: null, id: afIdLigne() });
    }
    credit.push({ libelle: "Acompte sur frais versé à l'étude", montant: 0, formule: null, id: afIdLigne() });
    return { debit, credit };
  }

  // Pure : l'office établit le décompte, sauf quand l'étude est en participation (le décompte vient
  // alors du confrère qui reçoit l'acte).
  function modeDecompteParDefaut(d) {
    return d && d.roleNotaire === 'participant' ? 'confrere' : 'office';
  }

  // ---- Avis de taxe foncière (demandé par l'étude le 29/09) ----------------------------------
  // « Le montant est toujours en bas à droite, en fin de page deux. » Pure : parmi les items pdf.js
  // de la page ({ str, x, y }, y croissant vers le haut), le montant le plus bas, puis le plus à
  // droite. Un montant est un nombre avec centimes, ou suivi de « € » (l'avis arrondit à l'euro).
  // Entier nu de 4 à 6 chiffres admis aussi (« 1530 » en bas de l'avis 2025 : sans lui, les « 64 »
  // de frais de gestion, plus haut, étaient retenus comme montant de l'avis).
  var RE_ITEM_MONTANT_AVIS = /^(\d{1,3}(?:[ .\u00a0\u202f]\d{3})*|\d{4,6})(,\d{2})?\s*(€)?$/;
  // Sur l'avis réel de 2026 (SDIF de Loir-et-Cher), le total en bas à droite de la page 2 est un
  // entier nu, « 921 », sans centimes ni € : un entier d'au moins 10 € et d'au plus six chiffres,
  // sans zéro de tête, est donc un candidat (jamais un numéro de téléphone ni un « 0 » de colonne).
  var RE_ENTIER_NU_AVIS = /^[1-9]\d{1,5}$/;
  function montantBasDroitePage(items) {
    const liste = (items || []).filter(it => it && typeof it.str === 'string');
    const candidats = [];
    liste.forEach((it, i) => {
      const m = RE_ITEM_MONTANT_AVIS.exec(it.str.trim());
      if (!m) return;
      const suivant = liste[i + 1];
      const euroApres = suivant && suivant.str.trim() === '€' && Math.abs(suivant.y - it.y) < 3;
      if (!m[2] && !m[3] && !euroApres && !RE_ENTIER_NU_AVIS.test(m[1].replace(/[ .\u00a0\u202f]/g, ''))) return;
      const n = montantDepuisTexteFr(m[1] + (m[2] || ''));
      if (n > 0) candidats.push({ n, x: it.x, y: it.y });
    });
    if (!candidats.length) return null;
    const yMin = Math.min(...candidats.map(c => c.y));
    const bas = candidats.filter(c => c.y - yMin < 6);
    return bas.reduce((a, b) => (b.x > a.x ? b : a)).n;
  }

  // Pure : avis portant sur plusieurs biens (étude, 30/09 — remplace la règle du 29/09 sur les
  // ordures ménagères, déjà comprises dans la cotisation de chaque bien) : les « frais de gestion de
  // la fiscalité directe locale », portés une seule fois pour tout l'avis, sont répartis par produit
  // en croix au prorata de la taxe foncière de chaque bien, puis ajoutés à celle du bien vendu.
  // Ex. 838 + 64 × 838 / 1 466 = 874,58 €.
  function montantTfBienAvecFrais(tfBien, tfTousBiens, fraisGestion) {
    const bien = Number(tfBien), total = Number(tfTousBiens), frais = Number(fraisGestion) || 0;
    if (!(bien > 0) || !(total > 0) || bien > total) return null;
    const partFrais = Math.round(frais * bien / total * 100) / 100;
    return { tf: bien, frais: partFrais, total: Math.round((bien + partFrais) * 100) / 100 };
  }

  // Pure : les biens d'un avis de taxe foncière, lus en page 2 par position (les libellés
  // « Adresse », « Cotisation », « Frais de gestion »… sont dessinés, absents du texte). Chaque
  // adresse est suivie, dans la colonne de droite « Total des cotisations », du montant du bien ;
  // en bas à droite, « Montant de votre impôt » (montantBasDroitePage). Frais de gestion = impôt −
  // somme des biens (le « 64 » de l'avis réel). `items` : [{str, x, y}], y croissant vers le haut.
  var RE_ADRESSE_BIEN_AVIS = /[A-Za-zÀ-ÿ]{2}/;
  function biensAvisTaxeFonciere(items) {
    const liste = (items || []).filter(it => it && typeof it.str === 'string' && it.str.trim());
    const montants = liste.map(it => {
      const m = RE_ITEM_MONTANT_AVIS.exec(it.str.trim());
      return m ? { n: montantDepuisTexteFr(m[1] + (m[2] || '')), x: it.x, y: it.y } : null;
    }).filter(c => c && c.n > 0);
    const impot = montantBasDroitePage(liste);
    if (!montants.length) return { biens: [], impot, fraisGestion: 0 };
    const xDroite = Math.max(...montants.map(c => c.x));
    const colonneDroite = montants.filter(c => c.x > xDroite - 40);
    // Adresse d'un bien : texte à gauche, suivi (plus bas, à moins de 60 points) d'un montant dans
    // la colonne de droite — ce qui écarte le nom du propriétaire, les notes et les en-têtes.
    const adresses = liste.filter(it => RE_ADRESSE_BIEN_AVIS.test(it.str) && it.x > 40 && it.x < xDroite - 150 && !/[:€]/.test(it.str))
      .sort((a, b) => b.y - a.y);
    const biens = [];
    adresses.forEach((a, i) => {
      const suivante = adresses[i + 1];
      const montant = colonneDroite
        .filter(c => c.y < a.y && c.y > a.y - 60 && (!suivante || c.y > suivante.y))
        .sort((c1, c2) => c2.y - c1.y)[0];
      if (montant) biens.push({ adresse: a.str.replace(/\s+/g, ' ').trim(), tf: montant.n });
    });
    const somme = biens.reduce((t, b) => t + b.tf, 0);
    const fraisGestion = biens.length > 1 && impot > somme ? Math.round((impot - somme) * 100) / 100 : 0;
    return { biens, impot, fraisGestion };
  }

  // Pure : le bien de l'avis qui correspond à l'adresse du dossier — même numéro et un mot de la voie
  // en commun (« 2 ALL DES VANNEAUX » ↔ « 2 allée des Vanneaux ») ; null si aucun ou plusieurs.
  function bienAvisPourAdresse(biens, adresseDossier) {
    const mots = (s) => normaliserPourRecherche(String(s || '')).replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean);
    const cible = mots(adresseDossier);
    if (!cible.length) return null;
    const vides = new Set(['rue', 'route', 'allee', 'all', 'avenue', 'av', 'chemin', 'impasse', 'place', 'bd', 'boulevard', 'de', 'des', 'du', 'la', 'le', 'les', 'st', 'saint']);
    const trouves = (biens || []).map((b, i) => ({ b, i, m: mots(b.adresse) })).filter(({ m }) => {
      const numero = m.find(x => /^\d+$/.test(x));
      return numero && cible.includes(numero) && m.some(x => !/^\d+$/.test(x) && !vides.has(x) && x.length > 2 && cible.includes(x));
    });
    return trouves.length === 1 ? trouves[0].i : null;
  }

  // Pure : la ligne « prorata de taxe foncière » d'un décompte acquéreur — du jour de l'acte (inclus)
  // au 31 décembre, année civile de l'acte.
  function ligneProrataTaxeFonciere(montantAnnuel, dateActeIso) {
    if (!dateActeIso) return null;
    const annee = dateActeIso.slice(0, 4);
    const r = calculerProrata(montantAnnuel, `${annee}-01-01`, `${annee}-12-31`, dateActeIso);
    if (!r) return null;
    return { libelle: `Prorata de taxe foncière ${annee} (du ${dateActeIso.slice(8, 10) + '/' + dateActeIso.slice(5, 7)} au 31/12)`, montant: r.partAcquereur, detail: r };
  }

  // Page 1 de l'avis : « Montant de vos taxes foncières   921,00 € » (avis mensualisé, où « Somme à
  // prélever » est le net après acomptes — jamais celle-là). Lu sur les lignes reconstruites
  // (lignesDepuisItemsPdf) ; sert de première source, le bas de page 2 de contrôle. Pure.
  var RE_MONTANT_TF_EN_TETE = /Montant\s+de\s+vos\s+taxes\s+fonci[èe]res\s*:?\s*(\d[\d\s  .]*(?:,\d{2})?)\s*€/i;
  function montantAvisTaxeFonciereEnTete(lignes) {
    for (const l of lignes || []) {
      const m = RE_MONTANT_TF_EN_TETE.exec(String(l));
      if (!m) continue;
      const n = montantDepuisTexteFr(m[1]);
      if (n > 0) return n;
    }
    return null;
  }

  // ---- Pièces lues pour l'appel de fonds et le prorata (exemples réels reçus le 30/09) --------
  // Appel de charges d'un syndic, état daté, relevé de compte client de l'étude. Tout ce bloc est
  // pur : il reçoit le texte en LIGNES (lireTextePdfEnLignes / lignesDepuisItemsPdf) et ne touche
  // ni au DOM ni aux dossiers.

  // Les syndics écrivent « 422.13 » (point décimal, CITYA) ou « 122.97 € » (Immo'Zel), l'étude
  // « 1 380,43 » ou « 1.245,00 » : montantDepuisTexteFr lirait 42 213 dans « 422.13 ». Pure.
  var RE_MONTANT_PIECE_SRC = '(\\d{1,3}(?:[ \\u00a0\\u202f.]\\d{3})*(?:[.,]\\d{1,2})?|\\d+(?:[.,]\\d{1,2})?)';
  function montantSyndicDepuisTexte(texte) {
    if (texte == null) return null;
    let t = String(texte).replace(/[€\s  ]/g, '');
    if (!t) return null;
    if (/^\d+\.\d{1,2}$/.test(t)) return parseFloat(t);
    if (/^\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?$/.test(t)) t = t.replace(/\./g, '');
    const n = parseFloat(t.replace(',', '.'));
    return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
  }
  function isoDepuisJjMmAaaa(texte) {
    const m = /(\d{2})\/(\d{2})\/(\d{4})/.exec(String(texte || ''));
    return m ? `${m[3]}-${m[2]}-${m[1]}` : null;
  }
  function arrondiCentimes(n) { return Math.round(n * 100) / 100; }

  // --- appel de charges de copropriété -------------------------------------------------------
  // Structure réelle (appel trimestriel CITYA) : « Période du 01/10/2025 au 31/12/2025 », une ligne
  // par poste et par lot (le dernier nombre de la ligne est la quote-part), « Montant de l'appel
  // de fonds 422.13 € », puis un récapitulatif « MONTANT DE VOTRE APPEL » / « TOTAL A PAYER » (ce
  // dernier peut inclure un solde antérieur : il vient en dernier recours).
  var RE_PERIODE_APPEL_CHARGES = /P[ée]riode\s+(?:du\s+)?(\d{2}\/\d{2}\/\d{4})\s+au\s+(\d{2}\/\d{2}\/\d{4})/i;
  var RE_MONTANTS_APPEL_CHARGES = [
    { source: 'Montant de l’appel', re: new RegExp('Montant\\s+de\\s+l[\'’]appel(?:\\s+de\\s+fonds)?\\s*:?\\s*' + RE_MONTANT_PIECE_SRC + '\\s*€?', 'i') },
    { source: 'Montant de votre appel', re: new RegExp('MONTANT\\s+DE\\s+VOTRE\\s+APPEL\\s*:?\\s*' + RE_MONTANT_PIECE_SRC, 'i') },
    { source: 'Appel TTC', re: new RegExp('Appel\\s+TTC\\s*:?\\s*' + RE_MONTANT_PIECE_SRC, 'i') },
    { source: 'Total à payer', re: new RegExp('TOTAL\\s+(?:DE\\s+L[\'’]APPEL|[ÀA]\\s+PAYER)\\s*:?\\s*' + RE_MONTANT_PIECE_SRC, 'i') }
  ];
  // La cotisation au fonds de travaux (art. 14-2) est attachée au lot : son sort entre vendeur et
  // acquéreur est réglé par l'avant-contrat (voir detecterFondsTravaux), pas par un prorata de
  // charges — elle est donc totalisée à part, pour être retirée du montant à répartir.
  var RE_LIGNE_FONDS_TRAVAUX_APPEL = /(?:^|\s)(?:COTISATIONS?\s+(?:AU\s+)?)?FONDS\s+(?:DE\s+)?TRAVAUX(?:\s+ALUR)?(?![A-Za-z0-9_À-ɏ])/i;
  var RE_NOMBRES_LIGNE = /\d{1,3}(?:[   ]\d{3})*(?:[.,]\d{1,2})?|\d+(?:[.,]\d{1,2})?/g;

  function typePeriodeAppelCharges(periode) {
    if (!periode || !periode.debut || !periode.fin) return null;
    const d = new Date(periode.debut + 'T00:00:00Z'), f = new Date(periode.fin + 'T00:00:00Z');
    if (isNaN(d) || isNaN(f)) return null;
    const lendemain = new Date(f.getTime() + 86400000);
    if (d.getUTCDate() !== 1 || lendemain.getUTCDate() !== 1) return 'autre';
    const mois = (lendemain.getUTCFullYear() - d.getUTCFullYear()) * 12 + lendemain.getUTCMonth() - d.getUTCMonth();
    return mois === 12 && d.getUTCMonth() === 0 ? 'annee' : mois === 3 ? 'trimestre' : mois === 1 ? 'mois' : 'autre';
  }

  function analyserAppelCharges(texte) {
    const lignes = String(texte || '').split('\n').map(l => l.trim()).filter(Boolean);
    const out = { periode: null, typePeriode: null, montant: null, source: null, fondsTravaux: 0, lignesFondsTravaux: 0,
      montantHorsFondsTravaux: null, coproprietaire: null, immeuble: null };
    lignes.forEach(l => {
      if (!out.periode) {
        const m = RE_PERIODE_APPEL_CHARGES.exec(l);
        if (m) out.periode = { debut: isoDepuisJjMmAaaa(m[1]), fin: isoDepuisJjMmAaaa(m[2]) };
      }
      if (!out.coproprietaire) { const m = /Copropri[ée]taire\s*:\s*(.+)$/i.exec(l); if (m) out.coproprietaire = m[1].trim(); }
      if (!out.immeuble) { const m = /Immeuble\s*(?:\([^)]*\))?\s*:\s*(.+)$/i.exec(l); if (m) out.immeuble = m[1].trim(); }
      if (RE_LIGNE_FONDS_TRAVAUX_APPEL.test(l) && !/^(?:Fonds\s+TRV|TOTAL)/i.test(l)) {
        const nombres = l.match(RE_NOMBRES_LIGNE);
        const n = nombres ? montantSyndicDepuisTexte(nombres[nombres.length - 1]) : null;
        if (n != null && n >= 0) { out.fondsTravaux = arrondiCentimes(out.fondsTravaux + n); out.lignesFondsTravaux++; }
      }
    });
    for (const motif of RE_MONTANTS_APPEL_CHARGES) {
      for (const l of lignes) {
        const m = motif.re.exec(l);
        if (!m) continue;
        const n = montantSyndicDepuisTexte(m[1]);
        if (n > 0) { out.montant = n; out.source = motif.source; break; }
      }
      if (out.montant != null) break;
    }
    out.typePeriode = typePeriodeAppelCharges(out.periode);
    if (out.montant != null) out.montantHorsFondsTravaux = arrondiCentimes(Math.max(0, out.montant - out.fondsTravaux));
    return out;
  }

  // Ligne « Prorata de charges » du décompte acquéreur, du jour de l'acte (inclus) à la fin de la
  // période appelée. Null si l'acte tombe hors de la période : rien à répartir. Pure.
  function ligneProrataCharges(montant, periode, dateActeIso) {
    if (!periode || !periode.debut || !periode.fin || !dateActeIso) return null;
    const r = calculerProrata(montant, periode.debut, periode.fin, dateActeIso);
    if (!r) return null;
    const fr = (iso) => iso.slice(8, 10) + '/' + iso.slice(5, 7) + '/' + iso.slice(0, 4);
    return { libelle: `Prorata de charges de copropriété (du ${fr(dateActeIso)} au ${fr(periode.fin)})`, montant: r.partAcquereur, detail: r };
  }

  // --- état daté : fonds de travaux attaché au lot vendu -------------------------------------
  // Cinq états datés réels, quatre formes : rubrique B12 « Montant de la part dudit fonds
  // rattachée au lot principal cédé   662,00 » (le plus courant, y compris scanné et OCRisé :
  // « principa vendu 1 380,431 »), « Fonds travaux attachés aux lots vendus : 1 380,43 € », « Pour
  // information montant du fonds ALUR : 122.97 € » (Immo'Zel), et « Il n'y a pas de fonds ALUR ».
  // La cotisation exigible (« 4.4 Fonds de travaux … 12.49 € ») et l'avance de l'exercice
  // (« L'avance 'Fonds de Travaux - Exercice 2025' d'un montant de 197,97 € ») ne sont PAS le
  // montant attaché au lot : elles sont laissées de côté volontairement.
  var RE_FONDS_ETAT_DATE = [
    { source: 'part du fonds rattachée au lot (B12)', re: new RegExp('part\\s+dudit\\s+fonds\\s+rattach[ée]e?\\s+au\\s+lot[^\\d€]{0,40}?' + RE_MONTANT_PIECE_SRC, 'i') },
    { source: 'fonds travaux attachés aux lots vendus', re: new RegExp('fonds\\s+(?:de\\s+)?travaux\\s+attach[ée]s?\\s+aux?\\s+lots?\\s+(?:vendus?|c[ée]d[ée]s?)\\s*:?\\s*' + RE_MONTANT_PIECE_SRC, 'i') },
    { source: 'montant du fonds ALUR', re: new RegExp('montant\\s+du\\s+fonds\\s+(?:ALUR|de\\s+travaux)(?:\\s*\\(loi\\s+ALUR\\))?\\s*:?\\s*' + RE_MONTANT_PIECE_SRC + '\\s*€', 'i') }
  ];
  var RE_SANS_FONDS_ETAT_DATE = /(?:n['’]y\s+a\s+pas|pas)\s+de\s+fonds\s+(?:ALUR|de\s+travaux|travaux)|aucun\s+fonds\s+(?:de\s+)?travaux|fonds\s+(?:de\s+)?travaux\s*:\s*n[ée]ant/i;
  var RE_DERNIERE_COTISATION_ETAT_DATE = new RegExp('derni[èe]re\\s+cotisation\\s+vers[ée]e\\s+par\\s+le\\s+propri[ée]taire[^\\d]{0,60}?' + RE_MONTANT_PIECE_SRC, 'i');
  var RE_DATE_SIGNATURE_ETAT_DATE = /date\s+de\s+signature\s+le\s*:?\s*(\d{2}\/\d{2}\/\d{4})/i;

  function fondsTravauxDepuisEtatDate(texte) {
    const plat = String(texte || '').replace(/\s+/g, ' ');
    const out = { montant: null, absent: false, source: null, extrait: '', cotisation: null, dateSignature: null };
    if (!plat) return out;
    for (const motif of RE_FONDS_ETAT_DATE) {
      const m = motif.re.exec(plat);
      if (!m) continue;
      const n = montantSyndicDepuisTexte(m[1]);
      if (n == null) continue;
      out.montant = n; out.source = motif.source;
      out.extrait = plat.slice(Math.max(0, m.index), m.index + m[0].length).trim();
      break;
    }
    if (out.montant == null && RE_SANS_FONDS_ETAT_DATE.test(plat)) { out.absent = true; out.montant = 0; out.source = 'aucun fonds de travaux'; }
    const c = RE_DERNIERE_COTISATION_ETAT_DATE.exec(plat);
    if (c) out.cotisation = montantSyndicDepuisTexte(c[1]);
    const d = RE_DATE_SIGNATURE_ETAT_DATE.exec(plat);
    if (d) out.dateSignature = isoDepuisJjMmAaaa(d[1]);
    return out;
  }

  // --- relevé de compte client (JurisWeb) -----------------------------------------------------
  // Une ligne par écriture : date, libellé, puis UN montant dans la colonne Débit ou Crédit.
  // Reconstruit en texte, un seul montant ne dit plus sa colonne : elle est retrouvée par la
  // position horizontale de l'item (en-tête « Débit » / « Crédit ») quand les positions sont
  // fournies, sinon par le libellé (« VIR INST RECU » = reçu du client, « VIREMENT A … » = sorti).
  var RE_LIGNE_RELEVE_COMPTE = /^(\d{2}\/\d{2}\/\d{4})\s+(.+)$/;
  var RE_MONTANT_RELEVE_G = /\d{1,3}(?:[   ]\d{3})*,\d{2}(?!\d)/g;
  var RE_ECRITURE_RECUE = /\bRE[CÇ]US?\b|\bREMISE\b|\bCH[EÈ]QUE\b|\bCHQ\b|\bVERSEMENT\b|\bENCAISS/i;
  var RE_ECRITURE_SORTIE = /^VIR(?:EMENT)?\s+(?:A|[ÀÁ]|VERS|EMIS)\b|\bREMBOURS|\bRESTITUTION\b|\bR[ÈE]GLEMENT\b|\bPAIEMENT\b/i;
  var RE_NATURE_FRAIS = /PROVISION\s+(?:SUR\s+)?FRAIS|PROV\.?\s*(?:SUR\s+)?FRAIS|\bFRAIS\b/i;
  var RE_NATURE_PRIX = /INDEMNIT|IMMOBILISATION|D[ÉE]P[ÔO]T\s+DE\s+GARANTIE|S[ÉE]QUESTRE|ACOMPTE|\bPRIX\b|\bAPPORT\b|\bFONDS\b/i;
  var RE_TIERS_VIREMENT = /^VIR(?:EMENT)?\s+(?:A|[ÀÁ]|VERS)\s+(.+?)(?:\s+(?:INDEMNIT|PROVISION|D[ÉE]P[ÔO]T|S[ÉE]QUESTRE|ACOMPTE|VTE|VENTE|FRAIS)\b|$)/i;

  function natureEcritureReleve(libelle) {
    if (RE_NATURE_FRAIS.test(libelle)) return 'frais';
    if (RE_NATURE_PRIX.test(libelle)) return 'prix';
    return 'autre';
  }

  // `lignes` : chaînes (texte collé) ou objets { texte, items:[{ x, str }] } (PDF avec positions).
  function analyserReleveCompteClient(lignes) {
    const out = { titre: false, nature: null, ecritures: [], recu: { prix: 0, frais: 0, autre: 0 }, reverse: { prix: 0, frais: 0, autre: 0 },
      tiers: [], totalDebit: 0, totalCredit: 0, solde: null, ambigues: 0 };
    let xDebit = null, xCredit = null;
    (lignes || []).forEach(l => {
      const texte = (typeof l === 'string' ? l : (l && l.texte) || '').trim();
      const items = typeof l === 'string' ? null : (l && l.items) || null;
      if (!texte) return;
      if (/Relev[ée]\s+de\s+compte/i.test(texte)) out.titre = true;
      const mNature = /Nature\s+du\s+compte\s*:\s*(.+?(?:\)|$))/i.exec(texte);
      if (mNature) out.nature = mNature[1].trim();
      if (xDebit == null && items && /\bD[ée]bit\b/.test(texte) && /\bCr[ée]dit\b/.test(texte)) {
        items.forEach(it => {
          if (/\bD[ée]bit\b/i.test(it.str)) xDebit = it.x;
          if (/\bCr[ée]dit\b/i.test(it.str)) xCredit = it.x;
        });
        return;
      }
      const mSolde = /^Solde(?:\s+(?:cr[ée]diteur|d[ée]biteur))?\s*:?\s*(\d{1,3}(?:[   ]\d{3})*,\d{2})/i.exec(texte);
      if (mSolde) { out.solde = montantDepuisTexteFr(mSolde[1]); if (/d[ée]biteur/i.test(texte)) out.solde = -out.solde; return; }
      const m = RE_LIGNE_RELEVE_COMPTE.exec(texte);
      if (!m) return;
      const montants = Array.from(m[2].matchAll(RE_MONTANT_RELEVE_G));
      if (!montants.length) return;
      const libelle = m[2].slice(0, montants[0].index).trim();
      let debit = 0, credit = 0;
      if (montants.length >= 2) {
        debit = montantDepuisTexteFr(montants[0][0]); credit = montantDepuisTexteFr(montants[1][0]);
      } else {
        const n = montantDepuisTexteFr(montants[0][0]);
        let colonne = null;
        if (items && xDebit != null && xCredit != null) {
          const chaine = montants[0][0].replace(/[   ]/g, '');
          const item = items.find(it => it.str.replace(/[   ]/g, '').endsWith(chaine));
          if (item) colonne = Math.abs(item.x - xCredit) < Math.abs(item.x - xDebit) ? 'credit' : 'debit';
        }
        if (!colonne) {
          if (RE_ECRITURE_SORTIE.test(libelle)) colonne = 'debit';
          else if (RE_ECRITURE_RECUE.test(libelle)) colonne = 'credit';
          else { colonne = 'credit'; out.ambigues++; }
        }
        if (colonne === 'credit') credit = n; else debit = n;
      }
      const nature = natureEcritureReleve(libelle);
      const ecriture = { date: isoDepuisJjMmAaaa(m[1]), libelle, debit, credit, nature };
      if (debit > 0) {
        const t = RE_TIERS_VIREMENT.exec(libelle);
        if (t) { ecriture.tiers = t[1].trim(); if (!out.tiers.includes(ecriture.tiers)) out.tiers.push(ecriture.tiers); }
        out.reverse[nature] = arrondiCentimes(out.reverse[nature] + debit);
      }
      if (credit > 0) out.recu[nature] = arrondiCentimes(out.recu[nature] + credit);
      out.totalDebit = arrondiCentimes(out.totalDebit + debit);
      out.totalCredit = arrondiCentimes(out.totalCredit + credit);
      out.ecritures.push(ecriture);
    });
    if (out.solde == null && out.ecritures.length) out.solde = arrondiCentimes(out.totalCredit - out.totalDebit);
    return out;
  }
  // --- fin du socle pur -------------------------------------------------------------------------

  // --- état de l'écran (non persisté : cet outil ne crée ni ne modifie aucun dossier) ---------
  var afDossierLie = null;        // id du dossier CLAIRE repris, ou null
  var afClients = [];             // [{civilite, prenom, nom}]
  var afLignes = { debit: [], credit: [] };
  var afModeleCharge = false;     // le modèle .docx + les images ont-ils été chargés ?
  var afModeleEnCours = null;     // promesse de chargement en cours, pour ne pas la lancer deux fois

  var AF_CIVILITES = ['M', 'Mme', 'SCI', 'Indivision'];

  // Le nom de fichier du .docx : « Convocation … - DUPONT et MARTIN.docx ». Les caractères
  // interdits par Windows sont remplacés plutôt que retirés — « M/Mme » ne doit pas devenir
  // « MMme ».
  function afNomFichierDocx(clients) {
    const noms = (clients || []).map(c => (c.civilite === 'SCI' || c.civilite === 'Indivision')
      ? String(c.nom || '').trim()
      : String(c.nom || '').trim().toUpperCase()).filter(Boolean);
    const base = noms.join(' et ') || 'CLIENT';
    return "Convocation au rendez-vous contenant l'appel de fonds - " + base.replace(/[\\/:*?"<>|]/g, '-') + '.docx';
  }

  // La phrase du rendez-vous telle qu'elle s'écrit dans le courrier : « le mardi 29 septembre, à
  // 11 heures, en l'étude ». Sans date, on écrit ce qu'on sait plutôt qu'une date inventée.
  function phraseRdvAppelFonds(iso, heure, lieu) {
    const lieuTexte = String(lieu || '').trim();
    if (!iso) return lieuTexte ? 'à une date à fixer, ' + lieuTexte : 'à une date à fixer';
    const d = new Date(iso + 'T00:00:00');
    const jour = d.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' });
    let phrase = 'le ' + jour;
    if (heure) {
      const [h, m] = String(heure).split(':');
      const hn = parseInt(h, 10);
      phrase += ', à ' + hn + (m && m !== '00' ? ' h ' + m : ' heures');
    }
    if (lieuTexte) phrase += ', ' + lieuTexte;
    return phrase;
  }

  function afEl(id) { return document.getElementById(id); }
  function afValeur(id) { const e = afEl(id); return e ? String(e.value || '').trim() : ''; }

  // --- lien vers un dossier suivi (Outil 1) ---------------------------------------------------
  //
  // Lecture SEULE du dossier : cet outil ne l'écrit jamais, il n'en reprend que ce qui est déjà
  // vérifié. Même patron de recherche que le Tableau de bord et Outil 2 (normaliserPourRecherche,
  // dossiers actifs uniquement, 8 résultats).
  function rechercherDossierAppelFonds(valeur) {
    const boite = afEl('af-dossier-resultats');
    if (!boite) return;
    const q = normaliserPourRecherche(String(valeur || '').trim());
    if (!q) { boite.style.display = 'none'; boite.innerHTML = ''; return; }
    const trouves = dossiers.filter(d => !d.archive &&
      (normaliserPourRecherche(libelleDossierAffiche(d)).includes(q) || normaliserPourRecherche(d.responsable || '').includes(q)))
      .slice(0, 8);
    if (!trouves.length) {
      boite.innerHTML = '<div class="dash-recherche-vide">Aucun dossier ne correspond.</div>';
      boite.style.display = 'block';
      return;
    }
    // `.dash-recherche-ligne`/`.dash-recherche-resp` et pas `-item`/`-meta` : ces deux dernières
    // n'existent nulle part dans style.css, le menu s'affichait donc en boutons natifs bruts (ni
    // séparateur, ni survol). Corrigé en même temps que l'ajout des suggestions d'adresse, qui
    // réutilisent le même gabarit juste en dessous.
    boite.innerHTML = trouves.map(d => `<button type="button" class="dash-recherche-ligne" onclick="choisirDossierAppelFonds('${escapeOnclickArg(d.id)}')">
      <span class="dash-recherche-nom">${escapeHtml(libelleDossierAffiche(d))}</span>
      <span class="dash-recherche-resp">${escapeHtml(d.responsable || '')}</span>
    </button>`).join('');
    boite.style.display = 'block';
  }

  function choisirDossierAppelFonds(id) {
    const d = dossiers.find(x => x.id === id);
    if (!d) return;
    const champ = afEl('af-dossier-recherche');
    if (champ) champ.value = '';
    const boite = afEl('af-dossier-resultats');
    if (boite) { boite.style.display = 'none'; boite.innerHTML = ''; }
    appliquerPrefillAppelFonds(d);
  }

  function retirerDossierAppelFonds() {
    afDossierLie = null;
    renderPillDossierAppelFonds();
    const recap = afEl('af-recap-prefill');
    if (recap) { recap.className = 'af-recap'; recap.innerHTML = ''; }
  }

  function renderPillDossierAppelFonds() {
    majActionBrouillonAppelFonds();
    const cible = afEl('af-dossier-pill');
    if (!cible) return;
    const d = afDossierLie ? dossiers.find(x => x.id === afDossierLie) : null;
    if (!d) { cible.innerHTML = ''; return; }
    cible.innerHTML = `<div class="dash-recherche-pill">
      <span class="dot-label dl-success"><span class="dot"></span>${escapeHtml(libelleDossierAffiche(d))}</span>
      <button type="button" class="action-rapide" onclick="retirerDossierAppelFonds()">Détacher</button>
    </div>`;
  }

  // Le bouton « Email (courrier joint) » n'a de sens que si un dossier est relié ET que l'email de
  // son destinataire (client, ou confrère) est connu : c'est de là que vient l'adresse.
  function majActionBrouillonAppelFonds() {
    const bouton = afEl('af-brouillon-outlook');
    if (!bouton) return;
    const d = afDossierLie ? dossiers.find(x => x.id === afDossierLie) : null;
    bouton.style.display = (d && emailDestinataireRelance(d)) ? '' : 'none';
  }

  // --- adresse du bien : reprise du dossier, ou suggestions de la Base Adresse Nationale --------
  //
  // Deux sources, jamais en même temps, demandé ainsi par l'étude : quand un dossier est rattaché,
  // son adresse est reprise telle quelle (elle a déjà été relue et corrigée à la création du
  // dossier, la redemander à un service extérieur n'apporterait rien) ; sans dossier rattaché, le
  // champ propose les adresses officielles de la Base Adresse Nationale (api-adresse.data.gouv.fr).
  //
  // **Seul appel réseau vers un service tiers de tout CLAIRE.** Ce qui part est le texte tapé dans
  // ce champ, rien d'autre — jamais le nom du dossier, des parties ni aucune autre donnée client.
  // L'API est un service public de l'État, sans compte ni clé. Si le poste n'a pas d'accès
  // internet, l'appel échoue silencieusement et le champ reste une saisie libre : la génération du
  // courrier ne dépend à aucun moment de ce service.
  var API_ADRESSE_DATA_GOUV = 'https://api-adresse.data.gouv.fr/search/';
  var MIN_CARACTERES_SUGGESTION_ADRESSE = 4;
  var DELAI_SUGGESTION_ADRESSE_MS = 250;
  var afAdresseBienDepuisDossier = false;
  var afSuggestionsAdresseMinuteur = null;
  var afGenerationSuggestionAdresse = 0;

  function urlRechercheAdresseDataGouv(requete) {
    return API_ADRESSE_DATA_GOUV + '?q=' + encodeURIComponent(String(requete || '').trim()) + '&limit=5&autocomplete=1';
  }

  // La BAN renvoie du GeoJSON : `label` est l'adresse complète (« 5 rue des Lilas 41000 Blois »),
  // `context` le département et la région. Tout ce qui n'a pas de `label` exploitable est écarté
  // plutôt que rendu sous forme de ligne vide.
  function adressesDepuisReponseDataGouv(json) {
    const features = (json && Array.isArray(json.features)) ? json.features : [];
    return features
      .map(f => (f && f.properties) ? { label: String(f.properties.label || '').trim(), contexte: String(f.properties.context || '').trim() } : null)
      .filter(a => a && a.label);
  }

  function masquerSuggestionsAdresseBien() {
    // Un clic sur une suggestion déclenche d'abord le `blur` du champ : masquer tout de suite
    // ferait disparaître le bouton avant que son `click` ne parte. D'où le petit délai.
    setTimeout(() => {
      const boite = afEl('af-adresse-bien-resultats');
      if (boite) { boite.style.display = 'none'; boite.innerHTML = ''; }
    }, 180);
  }

  function renderSuggestionsAdresseBien(liste) {
    const boite = afEl('af-adresse-bien-resultats');
    if (!boite) return;
    if (!liste.length) { boite.style.display = 'none'; boite.innerHTML = ''; return; }
    boite.innerHTML = liste.map(a => `<button type="button" class="dash-recherche-ligne" onclick="choisirAdresseBienAppelFonds('${codifierPourAttribut(a.label)}')">
      <span class="dash-recherche-nom">${escapeHtml(a.label)}</span>
      <span class="dash-recherche-resp">${escapeHtml(a.contexte)}</span>
    </button>`).join('');
    boite.style.display = 'block';
  }

  function rechercherAdresseBienAppelFonds(valeur) {
    const q = String(valeur || '').trim();
    if (afSuggestionsAdresseMinuteur) clearTimeout(afSuggestionsAdresseMinuteur);
    // Dès que l'étude tape, l'adresse n'est plus celle reprise du dossier : l'indication sous le
    // champ doit le dire, sinon elle affirmerait une provenance fausse.
    if (afAdresseBienDepuisDossier) majSourceAdresseBien(false);
    if (q.length < MIN_CARACTERES_SUGGESTION_ADRESSE) { renderSuggestionsAdresseBien([]); return; }
    const generation = ++afGenerationSuggestionAdresse;
    afSuggestionsAdresseMinuteur = setTimeout(async () => {
      try {
        const rep = await fetch(urlRechercheAdresseDataGouv(q));
        if (!rep.ok) throw new Error('reponse ' + rep.status);
        const json = await rep.json();
        // Une réponse arrivée après que l'étude a continué de taper décrirait une requête
        // périmée : on l'ignore plutôt que de proposer des adresses sans rapport avec le champ.
        if (generation !== afGenerationSuggestionAdresse) return;
        renderSuggestionsAdresseBien(adressesDepuisReponseDataGouv(json));
      } catch (e) {
        // Poste sans accès internet, service indisponible : aucun message, le champ reste une
        // saisie libre. Une erreur ici ne doit jamais gêner la rédaction du courrier.
        if (generation === afGenerationSuggestionAdresse) renderSuggestionsAdresseBien([]);
      }
    }, DELAI_SUGGESTION_ADRESSE_MS);
  }

  function choisirAdresseBienAppelFonds(b64) {
    const champ = afEl('af-adresse-bien');
    if (champ) champ.value = decoderAttribut(b64);
    renderSuggestionsAdresseBien([]);
    majSourceAdresseBien(false);
    majApercuAppelFonds();
  }

  function majSourceAdresseBien(depuisDossier) {
    afAdresseBienDepuisDossier = !!depuisDossier;
    const note = afEl('af-adresse-bien-source');
    if (!note) return;
    note.textContent = afAdresseBienDepuisDossier
      ? 'Adresse reprise du dossier rattaché. Modifiez-la pour obtenir des suggestions officielles.'
      : "Tapez l'adresse : des suggestions officielles (Base Adresse Nationale) s'affichent.";
  }

  // Écrit dans le formulaire tout ce que le dossier permet, puis AFFICHE ce qu'il n'a pas permis.
  // Le second point est le plus important : un champ laissé vide sur un courrier adressé à un
  // client se voit, et rien dans l'outil ne dirait pourquoi sans ce récapitulatif.
  function appliquerPrefillAppelFonds(d) {
    const p = prefillAppelFonds(d);
    if (!p) return;
    afDossierLie = p.dossierId;

    afClients = p.clients.map(c => ({ civilite: c.civilite, prenom: c.prenom, nom: c.nom }));
    if (!afClients.length) afClients = [{ civilite: 'M', prenom: '', nom: '' }];

    const ecrire = (id, v) => { const e = afEl(id); if (e && v) e.value = v; };
    ecrire('af-ref', p.dossierNom);
    ecrire('af-designation', p.designation);
    ecrire('af-adresse-bien', p.adresseBien);
    // L'adresse vient de la fiche : on le dit sous le champ, et les suggestions extérieures
    // n'ont plus lieu d'être tant que l'étude ne la retouche pas.
    majSourceAdresseBien(!!p.adresseBien);
    ecrire('af-date-rdv', p.dateRdv);
    const casePret = afEl('af-pret-hypothecaire');
    if (casePret) casePret.checked = !!p.pretHypothecaire;
    const caseSansPret = afEl('af-sans-pret');
    if (caseSansPret) caseSansPret.checked = !!p.sansPret;
    // Préremplis seulement quand le dossier tranche : un département ambigu (69) ou un type de
    // vente absent laisse le select vide, donc le contrôle silencieux, plutôt qu'un barème deviné.
    ecrire('af-frais-departement', p.departementFrais);
    ecrire('af-frais-type', p.typeBienFrais);
    ecrire('af-prix-mobilier', p.prixMobilier ? String(p.prixMobilier) : '');

    afLignes = lignesDecompteDepuisPrefill(p);
    definirModeDecompteAppelFonds(p.modeDecompte);
    if (tfAvis.af) majLigneTfAppelFonds();
    ['charges', 'etatDate', 'releve'].forEach(type => { if (afPieces[type]) appliquerPieceAppelFonds(type); });

    renderPillDossierAppelFonds();
    renderClientsAppelFonds();
    renderTableAppelFonds();
    majApercuAppelFonds();

    const recap = afEl('af-recap-prefill');
    if (recap) {
      const bloc = (titre, items, cls) => items.length
        ? `<div class="af-recap-bloc"><div class="af-recap-titre">${titre}</div><ul class="${cls}">${items.map(t => `<li>${escapeHtml(t)}</li>`).join('')}</ul></div>`
        : '';
      recap.innerHTML = bloc('Repris du dossier', p.repris, '') + bloc('À compléter vous-même', p.aCompleter, 'af-recap-manquant');
      recap.className = 'af-recap af-recap-visible';
    }
  }

  // Bouton « Préparer l'appel de fonds » de la fiche dossier : bascule vers l'onglet avec le
  // dossier déjà repris. Le tiroir se ferme — on quitte le Suivi, le laisser ouvert par-dessus un
  // autre écran n'aurait pas de sens.
  function preparerAppelFondsDepuisDossier(id) {
    const d = dossiers.find(x => x.id === id);
    if (!d) return;
    fermerDossierDrawer();
    definirOnglet('appel-fonds');
    appliquerPrefillAppelFonds(d);
  }

  // --- clients ---------------------------------------------------------------------------------
  function renderClientsAppelFonds() {
    const cible = afEl('af-clients');
    if (!cible) return;
    if (!afClients.length) afClients = [{ civilite: 'M', prenom: '', nom: '' }];
    cible.innerHTML = afClients.map((c, i) => `<div class="af-client">
      <select onchange="changerClientAppelFonds(${i}, 'civilite', this.value)">
        ${AF_CIVILITES.map(v => `<option value="${v}"${c.civilite === v ? ' selected' : ''}>${v}</option>`).join('')}
      </select>
      <input type="text" placeholder="Prénom" value="${escapeAttr(c.prenom || '')}" oninput="changerClientAppelFonds(${i}, 'prenom', this.value)">
      <input type="text" placeholder="Nom" value="${escapeAttr(c.nom || '')}" oninput="changerClientAppelFonds(${i}, 'nom', this.value)">
      <button type="button" class="af-client-suppr" title="Retirer ce client" onclick="supprimerClientAppelFonds(${i})">${icone('x')}</button>
    </div>`).join('');
  }

  function changerClientAppelFonds(i, champ, valeur) {
    if (!afClients[i]) return;
    afClients[i][champ] = valeur;
    majApercuAppelFonds();
  }

  function ajouterClientAppelFonds() {
    afClients.push({ civilite: 'M', prenom: '', nom: '' });
    renderClientsAppelFonds();
    majApercuAppelFonds();
  }

  function supprimerClientAppelFonds(i) {
    afClients.splice(i, 1);
    if (!afClients.length) afClients = [{ civilite: 'M', prenom: '', nom: '' }];
    renderClientsAppelFonds();
    majApercuAppelFonds();
  }

  // --- tableau du décompte ---------------------------------------------------------------------
  //
  // Trois colonnes comme sur le courrier papier : libellé | à déduire | débit. Chaque ligne ne
  // remplit que la colonne de son côté, l'autre reste vide — c'est la mise en page du modèle,
  // pas une colonne oubliée.
  // Base du contrôle des frais : la ligne de PRIX du décompte affiché — celle du dossier comme
  // celle d'un décompte de confrère collé, toutes deux nommées « prix ». Prendre le prix du
  // dossier lié ne conviendrait pas : le courrier peut avoir été corrigé à la main entre-temps.
  function prixPourControleFraisActe() {
    const ligne = afLignes.debit.find(l => /\bprix\b/i.test(l.libelle || '') && (l.montant || 0) > 0);
    return ligne ? ligne.montant : null;
  }

  // La fourchette applicable à l'état actuel du formulaire, ou null si l'étude n'a pas encore
  // choisi le département et la nature du bien — sans eux, aucun contrôle n'est affiché.
  // Mobilier compris dans le prix : sort de l'assiette des droits de mutation (art. 735 CGI).
  // Sans le retirer, un décompte qui l'a correctement déduit paraîtrait « sous le barème ».
  function mobilierPourControleFraisActe() {
    const n = eurosDepuisSaisie(afValeur('af-prix-mobilier')) || 0;
    return Number.isFinite(n) && n > 0 ? n : 0;
  }

  function fourchetteFraisActeFormulaire() {
    const dept = afValeur('af-frais-departement');
    const type = afValeur('af-frais-type');
    const prix = assietteImmobiliere(prixPourControleFraisActe(), mobilierPourControleFraisActe());
    if (!dept || !type || !prix) return null;
    return fourchetteFraisActe(prix, dept, type);
  }

  function renderTableAppelFonds() {
    const fourchette = fourchetteFraisActeFormulaire();
    const rendu = (section) => {
      const tbody = afEl(section === 'debit' ? 'af-tbody-debit' : 'af-tbody-credit');
      if (!tbody) return 0;
      let html = '';
      if (section === 'credit') html += '<tr><td colspan="3" style="padding:2px"></td></tr><tr><td>À déduire</td><td></td><td></td></tr>';
      let total = 0;
      afLignes[section].forEach((l, i) => {
        if (!l.memoire) total += (l.montant || 0);
        const v = (!l.memoire && l.formule) ? verifierProrataLigne(l) : null;
        let badge = '';
        if (v && v.statut === 'ok') badge = '<span class="af-verif af-verif-ok" title="Prorata recalculé : conforme">✓ prorata vérifié</span>';
        else if (v && v.statut === 'ecart') badge = `<span class="af-verif af-verif-ecart" title="Recalcul attendu : ${escapeAttr(montantVersTexteFr(v.attendu))}">⚠ écart de calcul</span>`;
        // Contrôle des frais d'acte : indicatif, jamais une correction automatique du montant.
        if (!badge && section === 'debit' && !l.memoire && fourchette && estLigneFraisActeVente(l.libelle)) {
          const f = verifierFraisActeLigne(l.montant || 0, fourchette);
          const plage = `Barème CLAIRE pour ce bien : de ${montantVersTexteFr(f.min || 0)} à ${montantVersTexteFr(f.max || 0)} selon le régime de l'acquéreur.`;
          if (f.statut === 'ok') badge = `<span class="af-verif af-verif-ok" title="${escapeAttr(plage)}">✓ conforme au barème</span>`;
          else if (f.statut === 'sous') badge = `<span class="af-verif af-verif-ecart" title="${escapeAttr(plage)}">↓ ${escapeHtml(montantVersTexteFr(f.ecart))} sous le barème</span>`;
          else if (f.statut === 'sur') badge = `<span class="af-verif af-verif-ecart" title="${escapeAttr(plage)}">↑ ${escapeHtml(montantVersTexteFr(f.ecart))} au-dessus du barème</span>`;
        }
        const montantTexte = l.memoire ? 'Mémoire' : montantVersTexteFr(l.montant || 0);
        const cellMontant = `<span class="af-champ" data-af-section="${section}" data-af-index="${i}" data-af-champ="montant">${escapeHtml(montantTexte)}</span>`;
        const cellLibelle = `<td><span class="af-champ" data-af-section="${section}" data-af-index="${i}" data-af-champ="libelle">${escapeHtml(l.libelle)}</span>${badge}${l.formule ? `<span class="af-formule">${escapeHtml(l.formule)}</span>` : ''}</td>`;
        html += `<tr title="Double-cliquez pour supprimer cette ligne" ondblclick="supprimerLigneAppelFonds('${section}', ${i})">` + (section === 'debit'
          ? `${cellLibelle}<td class="af-montant"></td><td class="af-montant">${cellMontant}</td>`
          : `${cellLibelle}<td class="af-montant">${cellMontant}</td><td class="af-montant"></td>`) + '</tr>';
      });
      html += `<tr class="af-sous-total">` + (section === 'debit'
        ? `<td>Soit au total</td><td class="af-montant"></td><td class="af-montant">${escapeHtml(montantVersTexteFr(total))}</td>`
        : `<td>Soit au total</td><td class="af-montant">${escapeHtml(montantVersTexteFr(total))}</td><td class="af-montant"></td>`) + '</tr>';
      tbody.innerHTML = html;
      return total;
    };
    const debit = rendu('debit');
    const credit = rendu('credit');
    const solde = afEl('af-p-solde');
    if (solde) solde.textContent = montantVersTexteFr(debit - credit);
  }

  // Le montant est modifié DANS le tableau : on met le modèle à jour et on recalcule les totaux,
  // sans redessiner le tableau — un redraw ferait perdre le curseur en pleine frappe.
  function modifierMontantAppelFonds(span) {
    const section = span.getAttribute('data-af-section');
    const i = parseInt(span.getAttribute('data-af-index'), 10);
    const ligne = afLignes[section] && afLignes[section][i];
    if (!ligne) return;
    const texte = span.textContent || '';
    if (AF_MEMOIRE_RE.test(texte)) { ligne.memoire = true; ligne.montant = 0; }
    else { ligne.memoire = false; ligne.montant = montantDepuisTexteFr(texte) || 0; }
    recalculerTotauxAppelFonds();
  }

  function modifierLibelleAppelFonds(span) {
    const section = span.getAttribute('data-af-section');
    const i = parseInt(span.getAttribute('data-af-index'), 10);
    if (afLignes[section] && afLignes[section][i]) afLignes[section][i].libelle = span.textContent || '';
  }

  function recalculerTotauxAppelFonds() {
    const somme = (section) => afLignes[section].reduce((t, l) => t + (l.memoire ? 0 : (l.montant || 0)), 0);
    const debit = somme('debit');
    const credit = somme('credit');
    const majSousTotal = (id, colonne, valeur) => {
      const tbody = afEl(id);
      if (!tbody) return;
      const tr = tbody.querySelector('tr.af-sous-total');
      if (!tr) return;
      const cellules = tr.querySelectorAll('td');
      if (cellules[colonne]) cellules[colonne].textContent = montantVersTexteFr(valeur);
    };
    majSousTotal('af-tbody-debit', 2, debit);
    majSousTotal('af-tbody-credit', 1, credit);
    const solde = afEl('af-p-solde');
    if (solde) solde.textContent = montantVersTexteFr(debit - credit);
  }

  // Le courrier entier est UN bloc modifiable (#af-lettre, contenteditable) : le navigateur n'y
  // signale une frappe qu'au bloc, jamais à la cellule du décompte — un `oninput` posé sur la
  // cellule ne se déclenchait donc pas, le modèle gardait l'ancien texte, et le tableau redessiné
  // (suppression d'une autre ligne, ajout, contrôle des frais) le faisait réapparaître (signalé
  // par l'étude le 29/09). Chaque frappe dans le courrier relit donc toutes les cellules.
  function synchroniserDecompteDepuisApercu() {
    ['af-tbody-debit', 'af-tbody-credit'].forEach(id => {
      const tbody = afEl(id);
      if (!tbody) return;
      tbody.querySelectorAll('.af-champ[data-af-champ]').forEach(span => {
        if (span.getAttribute('data-af-champ') === 'montant') modifierMontantAppelFonds(span);
        else modifierLibelleAppelFonds(span);
      });
    });
  }
  function saisieApercuAppelFonds() {
    synchroniserDecompteDepuisApercu();
    recalculerTotauxAppelFonds();
  }

  function ajouterLigneAppelFonds(section) {
    synchroniserDecompteDepuisApercu();
    afLignes[section].push({ libelle: 'Nouvelle ligne', montant: 0, formule: null, id: afIdLigne() });
    renderTableAppelFonds();
  }

  function supprimerLigneAppelFonds(section, i) {
    synchroniserDecompteDepuisApercu();
    if (!afLignes[section] || !afLignes[section][i]) return;
    afLignes[section].splice(i, 1);
    renderTableAppelFonds();
  }

  // --- report du formulaire vers le courrier ---------------------------------------------------
  function majLieuAppelFonds() {
    const select = afEl('af-lieu');
    const autre = afEl('af-lieu-autre');
    if (select && autre) autre.style.display = select.value === '__autre' ? 'block' : 'none';
    majApercuAppelFonds();
  }

  function lieuAppelFonds() {
    const select = afEl('af-lieu');
    if (!select) return "en l'étude";
    return select.value === '__autre' ? afValeur('af-lieu-autre') : select.value;
  }

  function majApercuAppelFonds() {
    const poser = (id, texte) => { const e = afEl(id); if (e && texte) e.textContent = texte; };

    // L'adresse et la désignation du bien alimentent aussi le contrôle des frais, juste en dessous
    // (voir majFraisDepuisBienAppelFonds) : c'est le seul endroit par où passent TOUS les chemins
    // qui les modifient — la frappe, le clic sur une suggestion d'adresse, et le préremplissage
    // depuis un dossier — donc le seul où le brancher une fois pour toutes.
    if (majFraisDepuisBienAppelFonds()) renderTableAppelFonds();

    const clientsRemplis = afClients.filter(c => String(c.nom || '').trim());
    const adresse = afValeur('af-adresse-clients');
    const bloc = afEl('af-p-adresse');
    if (bloc) {
      const lignes = clientsRemplis.map(ligneClientComplete).filter(Boolean);
      if (adresse) adressePostaleCourrier(adresse).forEach(l => lignes.push(l));
      bloc.innerHTML = lignes.length ? '<u>' + lignes.map(escapeHtml).join('<br>') + '</u>' : '<u>Destinataire à compléter</u>';
    }
    const ligneMention = afEl('af-p-mention-ligne');
    if (ligneMention) ligneMention.style.display = adresse ? 'none' : '';

    const salut = salutationAppelFonds(clientsRemplis);
    poser('af-p-salut1', salut);
    poser('af-p-salut2', salut);
    poser('af-p-ref', afValeur('af-ref') || 'RÉF. DOSSIER');
    poser('af-p-datelettre', formatDateFr(afValeur('af-date-lettre')));
    poser('af-p-designation', afValeur('af-designation') || 'un bien');
    poser('af-p-adressebien', normaliserAdresse(afValeur('af-adresse-bien')) || 'adresse à compléter');
    poser('af-p-rdv', phraseRdvAppelFonds(afValeur('af-date-rdv'), afValeur('af-heure-rdv'), lieuAppelFonds()));
    const sansPret = afEl('af-sans-pret');
    poser('af-p-deblocage', phraseDeblocageAppelFonds(!!(sansPret && sansPret.checked)));
  }

  // Dernière phrase du paragraphe « À cet effet… R.I.B. de l'étude » : sans prêt, texte donné par
  // l'étude le 29/09, mot pour mot. Pure.
  function phraseDeblocageAppelFonds(sansPret) {
    return sansPret
      ? 'Je vous invite à vous rapprocher de votre établissement bancaire afin de faire le point sur le déblocage, correspondant à votre apport personnel.'
      : 'Je vous invite à vous rapprocher de votre établissement bancaire afin de faire le point sur le déblocage de votre prêt (total ou partiel si vous financez des travaux), ainsi que sur le virement du solde correspondant à votre apport personnel.';
  }

  // --- import du décompte du confrère -----------------------------------------------------------
  function gererSurvolDepotAppelFonds(e) { e.preventDefault(); const z = afEl('af-dropzone'); if (z) z.classList.add('dragover'); }
  function gererQuitteDepotAppelFonds(e) { e.preventDefault(); const z = afEl('af-dropzone'); if (z) z.classList.remove('dragover'); }
  function gererDepotAppelFonds(e) {
    e.preventDefault();
    const z = afEl('af-dropzone');
    if (z) z.classList.remove('dragover');
    const f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
    if (f) importerDecompteAppelFonds(f);
  }

  // ---- Décompte établi par l'office, ou repris d'un confrère (29/09) ----
  var afModeDecompte = 'office';
  function definirModeDecompteAppelFonds(mode) {
    afModeDecompte = mode === 'confrere' ? 'confrere' : 'office';
    const office = afEl('af-mode-office'), confrere = afEl('af-mode-confrere');
    if (office) office.style.display = afModeDecompte === 'office' ? '' : 'none';
    if (confrere) confrere.style.display = afModeDecompte === 'confrere' ? '' : 'none';
    const bOffice = afEl('af-mode-btn-office'), bConfrere = afEl('af-mode-btn-confrere');
    if (bOffice) bOffice.classList.toggle('actif', afModeDecompte === 'office');
    if (bConfrere) bConfrere.classList.toggle('actif', afModeDecompte === 'confrere');
  }

  // ---- Avis de taxe foncière : prorata et appel de fonds (29/09) ----
  // `cible` : 'prorata' (outil Prorata) ou 'af' (appel de fonds). Rien n'est enregistré.
  var tfAvis = { prorata: null, af: null };

  // Deux sources sur l'avis réel : « Montant de vos taxes foncières » en page 1 (retenue en
  // premier) et le total en bas à droite de la page 2 (contrôle) — quand elles divergent, c'est
  // dit à l'écran plutôt que tranché en silence.
  async function lireAvisTaxeFonciere(fichier) {
    const buffer = await fichier.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
    const page1 = await pdf.getPage(1);
    const enTete = montantAvisTaxeFonciereEnTete(lignesDepuisItemsPdf((await page1.getTextContent()).items));
    const page = await pdf.getPage(Math.min(2, pdf.numPages));
    const contenu = await page.getTextContent();
    const items = contenu.items.map(it => ({ str: it.str, x: it.transform[4], y: it.transform[5] }));
    const basDroite = montantBasDroitePage(items);
    const detail = biensAvisTaxeFonciere(items);
    return { montant: enTete || basDroite, enTete, basDroite, pages: pdf.numPages, biens: detail.biens, fraisGestion: detail.fraisGestion };
  }

  async function importerAvisTaxeFonciere(cible, fichier) {
    if (!fichier) return;
    if (typeof pdfjsLib === 'undefined') { afficherToast('Le lecteur PDF n\'est pas disponible.', 'OK', null); return; }
    try {
      const lu = await lireAvisTaxeFonciere(fichier);
      if (!lu.montant) {
        tfAvis[cible] = { fichier: fichier.name, montantAvis: null, retenu: null, erreur: true };
      } else {
        const divergence = lu.enTete && lu.basDroite && Math.abs(lu.enTete - lu.basDroite) > 0.5;
        tfAvis[cible] = { fichier: fichier.name, montantAvis: lu.montant, retenu: lu.montant, enTete: lu.enTete, basDroite: lu.basDroite, divergence };
        // Plusieurs biens sur l'avis : rien n'est retenu tant que le bien vendu n'est pas choisi
        // (étude, 30/09 : « si deux biens demander lequel prendre ») — sauf si l'adresse du dossier
        // de l'appel de fonds désigne sans doute l'un d'eux.
        if (lu.biens && lu.biens.length > 1) {
          const t = tfAvis[cible];
          t.biens = lu.biens; t.fraisGestion = lu.fraisGestion;
          const d = cible === 'af' && afDossierLie ? (dossiers || []).find(x => x.id === afDossierLie) : null;
          const i = d ? bienAvisPourAdresse(lu.biens, d.adresseBien) : null;
          choisirBienAvis(cible, i, true);
        }
      }
    } catch (e) {
      console.error(e);
      tfAvis[cible] = { fichier: fichier.name, montantAvis: null, retenu: null, erreur: true };
    }
    renderBlocTaxeFonciere(cible);
    appliquerTaxeFonciere(cible);
  }

  function renderBlocTaxeFonciere(cible) {
    const zone = document.getElementById(cible + '-tf-bloc');
    const t = tfAvis[cible];
    if (!zone) return;
    if (!t) { zone.innerHTML = ''; return; }
    if (t.erreur) {
      zone.innerHTML = `<p class="hint">${icone('alert-triangle')} ${escapeHtml(t.fichier)} : montant introuvable en bas de la page 2 — saisissez-le.</p>`;
      return;
    }
    const retenu = t.retenu && t.retenu !== t.montantAvis
      ? ` · retenu : <strong>${formaterPrixCentimes(t.retenu)}</strong>` : '';
    const divergence = t.divergence
      ? `<p class="hint">${icone('alert-triangle')} Page 1 : ${escapeHtml(formaterPrixCentimes(t.enTete))} · bas de la page 2 : ${escapeHtml(formaterPrixCentimes(t.basDroite))} — le montant de la page 1 est retenu, à vérifier sur l'avis.</p>`
      : '';
    zone.innerHTML = `
      <p class="hint tf-lu">${escapeHtml(t.fichier)} : <strong>${formaterPrixCentimes(t.montantAvis)}</strong>${retenu}
        <button type="button" class="icon-btn" onclick="effacerTaxeFonciere('${cible}')" title="Retirer l'avis" aria-label="Retirer l'avis">${icone('x')}</button></p>${divergence}
      ${t.biens && t.biens.length > 1 ? renderChoixBienAvis(cible, t) : `<details class="tf-multi"${t.multi ? ' open' : ''}>
        <summary>L'avis porte sur plusieurs biens</summary>
        <div class="calc-champs tf-multi-champs">
          <div class="calc-champ"><label for="${cible}-tf-bien">Taxe foncière du bien vendu (€)</label>
            <input type="text" inputmode="decimal" id="${cible}-tf-bien" value="${t.tfBien ? escapeAttr(String(t.tfBien).replace('.', ',')) : ''}" oninput="majTaxeFonciereMulti('${cible}')"></div>
          <div class="calc-champ"><label for="${cible}-tf-total">Taxe foncière de tous les biens (€)</label>
            <input type="text" inputmode="decimal" id="${cible}-tf-total" value="${t.tfTotal ? escapeAttr(String(t.tfTotal).replace('.', ',')) : ''}" oninput="majTaxeFonciereMulti('${cible}')"></div>
          <div class="calc-champ"><label for="${cible}-tf-frais">Frais de gestion de l'avis (€)</label>
            <input type="text" inputmode="decimal" id="${cible}-tf-frais" value="${t.frais ? escapeAttr(String(t.frais).replace('.', ',')) : ''}" oninput="majTaxeFonciereMulti('${cible}')"></div>
        </div>
        <p class="hint" id="${cible}-tf-multi-resultat"></p>
      </details>`}`;
    if (!(t.biens && t.biens.length > 1)) majTaxeFonciereMulti(cible, true);
  }

  // Choix du bien vendu quand l'avis en porte plusieurs : une ligne par bien, avec sa taxe foncière
  // et le montant retenu (sa part des frais de gestion ajoutée).
  function renderChoixBienAvis(cible, t) {
    const lignes = t.biens.map((b, i) => {
      const r = montantTfBienAvecFrais(b.tf, t.biens.reduce((s, x) => s + x.tf, 0), t.fraisGestion);
      return `<label class="tf-bien-choix"><input type="radio" name="${cible}-tf-bien-choix" value="${i}"${t.bienChoisi === i ? ' checked' : ''} onchange="choisirBienAvis('${cible}', ${i})">
        <span class="tf-bien-adresse">${escapeHtml(b.adresse)}</span>
        <span class="tf-bien-montant">${formaterPrixCentimes(b.tf)}${r && r.frais ? ` + ${formaterPrixCentimes(r.frais)} de frais = <strong>${formaterPrixCentimes(r.total)}</strong>` : ''}</span></label>`;
    }).join('');
    return `<div class="tf-biens">
        <p class="hint">${t.bienChoisi === null || t.bienChoisi === undefined ? `${icone('alert-triangle')} ` : ''}L'avis porte sur ${t.biens.length} biens : lequel est vendu ?
          ${infoBulle(`Frais de gestion de la fiscalité directe locale (${formaterPrixCentimes(t.fraisGestion || 0)}) répartis au prorata de la taxe foncière de chaque bien, puis ajoutés à celle du bien vendu.`)}</p>
        ${lignes}
      </div>`;
  }

  function choisirBienAvis(cible, index, sansRendu) {
    const t = tfAvis[cible];
    if (!t || !t.biens) return;
    const b = Number.isInteger(index) ? t.biens[index] : null;
    t.bienChoisi = b ? index : null;
    const r = b ? montantTfBienAvecFrais(b.tf, t.biens.reduce((s, x) => s + x.tf, 0), t.fraisGestion) : null;
    t.retenu = r ? r.total : null;
    if (sansRendu) return;
    renderBlocTaxeFonciere(cible);
    appliquerTaxeFonciere(cible);
  }

  function majTaxeFonciereMulti(cible, sansAppliquer) {
    const t = tfAvis[cible];
    if (!t) return;
    const lire = (id) => { const e = document.getElementById(`${cible}-tf-${id}`); return e ? montantDepuisTexteFr(e.value) : null; };
    t.tfBien = lire('bien'); t.tfTotal = lire('total'); t.frais = lire('frais');
    const r = montantTfBienAvecFrais(t.tfBien, t.tfTotal, t.frais);
    t.multi = !!(t.tfBien || t.tfTotal || t.frais);
    const sortie = document.getElementById(`${cible}-tf-multi-resultat`);
    if (sortie) sortie.innerHTML = r
      ? `Montant retenu : <strong>${formaterPrixCentimes(r.total)}</strong> (taxe foncière ${formaterPrixCentimes(r.tf)} + frais de gestion ${formaterPrixCentimes(r.frais)})`
      : (t.multi ? 'Renseignez la taxe foncière du bien et celle de tous les biens.' : '');
    t.retenu = r ? r.total : t.montantAvis;
    if (!sansAppliquer) appliquerTaxeFonciere(cible);
  }

  function effacerTaxeFonciere(cible) {
    tfAvis[cible] = null;
    renderBlocTaxeFonciere(cible);
    appliquerTaxeFonciere(cible);
  }

  function appliquerTaxeFonciere(cible) {
    const t = tfAvis[cible];
    if (cible === 'prorata') {
      if (!t || !t.retenu) return;
      const montant = document.getElementById('prorata-montant');
      const periode = document.getElementById('prorata-periode');
      if (montant) montant.value = String(t.retenu);
      if (periode && periode.value !== 'annee') { periode.value = 'annee'; majPeriodeProrata(); }
      calculerProrataAffichage();
      return;
    }
    majLigneTfAppelFonds();
  }

  // La ligne « Prorata de taxe foncière » du décompte : recalculée quand l'avis ou la date du
  // rendez-vous change, retirée quand l'avis est retiré.
  var AF_ID_LIGNE_TF = 'af-ligne-tf';
  function majLigneTfAppelFonds() {
    const t = tfAvis.af;
    const avant = afLignes.debit.findIndex(l => l.id === AF_ID_LIGNE_TF);
    const date = afValeur('af-date-rdv');
    const ligne = t && t.retenu ? ligneProrataTaxeFonciere(t.retenu, date) : null;
    if (avant !== -1) afLignes.debit.splice(avant, 1);
    if (ligne) afLignes.debit.push({ libelle: ligne.libelle, montant: ligne.montant, formule: null, id: AF_ID_LIGNE_TF });
    const zone = document.getElementById('af-tf-bloc');
    const note = zone && zone.querySelector('.tf-date-manquante');
    if (t && t.retenu && !date && zone && !note) zone.insertAdjacentHTML('beforeend', '<p class="hint tf-date-manquante">Date du rendez-vous nécessaire pour le prorata.</p>');
    if (note && (date || !t)) note.remove();
    renderTableAppelFonds();
    majApercuAppelFonds();
  }

  // ---- Appel de charges, état daté, relevé de compte client (exemples réels du 30/09) ----------
  // Même principe que l'avis de taxe foncière : la pièce est lue dans le navigateur, rien n'est
  // enregistré, et chaque pièce ajoute ou remplit UNE ligne du décompte (ou dit pourquoi elle ne
  // le fait pas). État par pièce : { fichier, analyse, … } ou { fichier, erreur: true }.
  var afPieces = { charges: null, etatDate: null, releve: null };
  var AF_ID_LIGNE_CHARGES = 'af-ligne-charges';
  var RE_LIBELLE_FONDS_TRAVAUX_AF = /fonds\s+de\s+travaux/i;
  var RE_LIBELLE_ACOMPTE_PRIX = /acompte\s+sur\s+prix/i;
  var RE_LIBELLE_ACOMPTE_FRAIS = /acompte\s+sur\s+frais/i;

  // Texte en lignes (positions gardées pour la colonne Débit/Crédit d'un relevé) ; document
  // scanné sans texte → repli OCR, en lignes mais sans positions.
  async function lireTexteEtItemsPdf(fichier) {
    const buffer = await fichier.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
    const lignesPositions = [];
    for (let p = 1; p <= Math.min(pdf.numPages, PLAFOND_PAGES_VERIFICATION); p++) {
      const page = await pdf.getPage(p);
      const contenu = await page.getTextContent();
      lignesAvecPositionsDepuisItems(contenu.items).forEach(l => lignesPositions.push(l));
    }
    let texte = lignesPositions.map(l => l.texte).join('\n');
    let ocr = false;
    if (texte.trim().length < 40) { texte = await lireTextePdfVerification(pdf); ocr = true; }
    return { texte, lignesPositions: ocr ? null : lignesPositions };
  }

  async function importerPieceAppelFonds(type, fichier) {
    if (!fichier || !Object.prototype.hasOwnProperty.call(afPieces, type)) return;
    if (typeof pdfjsLib === 'undefined') { afficherToast('Le lecteur PDF n\'est pas disponible.', 'OK', null); return; }
    effacerPieceAppelFonds(type, true);
    try {
      const lu = await lireTexteEtItemsPdf(fichier);
      if (type === 'charges') afPieces.charges = { fichier: fichier.name, analyse: analyserAppelCharges(lu.texte), horsFondsTravaux: true };
      else if (type === 'etatDate') afPieces.etatDate = { fichier: fichier.name, analyse: fondsTravauxDepuisEtatDate(lu.texte) };
      else afPieces.releve = { fichier: fichier.name, analyse: analyserReleveCompteClient(lu.lignesPositions || lu.texte.split('\n')) };
    } catch (e) {
      console.error(e);
      afPieces[type] = { fichier: fichier.name, erreur: true };
    }
    appliquerPieceAppelFonds(type);
  }

  // `pourRemplacer` : la pièce est retirée parce qu'une autre arrive — le bloc n'est pas redessiné.
  function effacerPieceAppelFonds(type, pourRemplacer) {
    const piece = afPieces[type];
    afPieces[type] = null;
    if (piece && !piece.erreur) {
      if (type === 'charges') afLignes.debit = afLignes.debit.filter(l => l.id !== AF_ID_LIGNE_CHARGES);
      else if (type === 'etatDate' && piece.ligne) {
        const i = afLignes.debit.findIndex(l => l.id === piece.ligne.id);
        if (i !== -1) { if (piece.ligne.inseree) afLignes.debit.splice(i, 1); else afLignes.debit[i].montant = piece.ligne.avant; }
      } else if (type === 'releve' && piece.lignes) {
        piece.lignes.forEach(m => {
          const i = afLignes.credit.findIndex(l => l.id === m.id);
          if (i === -1) return;
          if (m.inseree) afLignes.credit.splice(i, 1); else afLignes.credit[i].montant = m.avant;
        });
      }
    }
    if (pourRemplacer) return;
    renderBlocPieceAppelFonds(type);
    renderTableAppelFonds();
    majApercuAppelFonds();
  }

  function appliquerPieceAppelFonds(type) {
    if (type === 'charges') majLigneChargesAppelFonds();
    else if (type === 'etatDate') majLigneFondsTravauxAppelFonds();
    else majLignesAcomptesAppelFonds();
    renderBlocPieceAppelFonds(type);
    renderTableAppelFonds();
    majApercuAppelFonds();
  }

  // Toutes les lignes qui dépendent de la date du rendez-vous (prorata de taxe foncière et de
  // charges) : appelé quand la date change, et après le préremplissage depuis un dossier.
  function majLignesProrataAppelFonds() {
    majLigneTfAppelFonds();
    if (afPieces.charges) appliquerPieceAppelFonds('charges');
  }

  function afDateFr(iso) { return iso ? formatDateFr(iso) : ''; }

  function majLigneChargesAppelFonds() {
    const piece = afPieces.charges;
    afLignes.debit = afLignes.debit.filter(l => l.id !== AF_ID_LIGNE_CHARGES);
    if (!piece || piece.erreur) return;
    const a = piece.analyse;
    const retenu = piece.horsFondsTravaux && a.fondsTravaux > 0 ? a.montantHorsFondsTravaux : a.montant;
    piece.retenu = retenu;
    const date = afValeur('af-date-rdv');
    piece.note = null;
    if (a.montant == null) piece.note = 'Montant de l’appel introuvable : saisissez la ligne à la main.';
    else if (!a.periode) piece.note = 'Période de l’appel introuvable (« Période du … au … ») : saisissez la ligne à la main.';
    else if (!date) piece.note = 'Date du rendez-vous nécessaire pour le prorata.';
    else {
      const ligne = ligneProrataCharges(retenu, a.periode, date);
      if (!ligne) piece.note = `Le rendez-vous (${afDateFr(date)}) n’est pas dans la période appelée (du ${afDateFr(a.periode.debut)} au ${afDateFr(a.periode.fin)}) : rien à répartir — demandez l’appel de la période du rendez-vous.`;
      else {
        afLignes.debit.push({ libelle: ligne.libelle, montant: ligne.montant, formule: null, id: AF_ID_LIGNE_CHARGES });
        piece.note = `Ligne ajoutée : ${formaterPrixCentimes(ligne.montant)} (${formaterPrixCentimes(retenu)} × ${ligne.detail.joursAcquereur} / ${ligne.detail.joursPeriode} jours).`;
        piece.ok = true;
      }
    }
  }

  function basculerHorsFondsTravauxCharges(cible, coche) {
    if (cible === 'prorata') {
      if (!prorataCharges) return;
      prorataCharges.horsFondsTravaux = !!coche;
      appliquerChargesProrata();
      return;
    }
    if (!afPieces.charges) return;
    afPieces.charges.horsFondsTravaux = !!coche;
    appliquerPieceAppelFonds('charges');
  }

  // Le fonds de travaux n'entre au décompte que si l'avant-contrat prévoit son remboursement par
  // l'acquéreur (règle détectée dans detecterFondsTravaux) : sans dossier, la ligne est posée mais
  // signalée « à confirmer ».
  function majLigneFondsTravauxAppelFonds() {
    const piece = afPieces.etatDate;
    if (!piece || piece.erreur) return;
    const a = piece.analyse;
    const d = afDossierLie ? dossiers.find(x => x.id === afDossierLie) : null;
    const regle = d && d.fondsTravaux && typeof d.fondsTravaux.rembourse === 'boolean' ? d.fondsTravaux.rembourse : null;
    const i = afLignes.debit.findIndex(l => RE_LIBELLE_FONDS_TRAVAUX_AF.test(l.libelle));
    piece.note = null; piece.ok = false;
    if (a.montant == null) { piece.note = 'Montant du fonds de travaux introuvable dans cette pièce.'; return; }
    if (a.absent) {
      if (i !== -1 && !(afLignes.debit[i].montant > 0)) { piece.ligne = { id: afLignes.debit[i].id, avant: 0, inseree: true }; afLignes.debit.splice(i, 1); }
      piece.note = 'L’état daté indique qu’il n’y a pas de fonds de travaux : aucune ligne.'; piece.ok = true;
      return;
    }
    if (regle === false) { piece.note = 'L’avant-contrat prévoit que l’acquéreur ne rembourse pas le fonds de travaux : aucune ligne ajoutée.'; piece.ok = true; return; }
    if (i !== -1) {
      piece.ligne = { id: afLignes.debit[i].id, avant: afLignes.debit[i].montant || 0, inseree: false };
      afLignes.debit[i].montant = a.montant;
    } else {
      const id = afIdLigne();
      afLignes.debit.push({ libelle: 'Remboursement du fonds de travaux (loi ALUR)', montant: a.montant, formule: null, id });
      piece.ligne = { id, avant: 0, inseree: true };
    }
    piece.ok = true;
    piece.note = regle === true
      ? `Ligne « Remboursement du fonds de travaux » : ${formaterPrixCentimes(a.montant)}, remboursement prévu par l’avant-contrat.`
      : `Ligne « Remboursement du fonds de travaux » : ${formaterPrixCentimes(a.montant)} — à confirmer : l’avant-contrat doit prévoir son remboursement par l’acquéreur.`;
  }

  // Sommes déjà versées à l'étude par le client : acompte sur prix (indemnité d'immobilisation,
  // dépôt de garantie, séquestre) et provision sur frais. Le relevé est la vérité comptable : il
  // REMPLACE le montant de la ligne d'acompte déjà déduite depuis le dossier (le dépôt de garantie
  // de l'avant-contrat et l'indemnité reçue sont la même somme — deux lignes la déduiraient deux
  // fois), et le dit quand les deux chiffres diffèrent.
  function majLignesAcomptesAppelFonds() {
    const piece = afPieces.releve;
    if (!piece || piece.erreur) return;
    const a = piece.analyse;
    piece.lignes = [];
    piece.notes = [];
    piece.ok = false;
    if (!a.ecritures.length) { piece.notes.push(a.titre ? 'Aucune écriture lue sur ce relevé.' : 'Ce document ne ressemble pas à un relevé de compte client (aucune écriture datée).'); return; }
    const poser = (re, libelle, montant, quoi) => {
      if (!(montant > 0)) return;
      const i = afLignes.credit.findIndex(l => re.test(l.libelle));
      if (i !== -1) {
        const avant = afLignes.credit[i].montant || 0;
        piece.lignes.push({ id: afLignes.credit[i].id, avant, inseree: false });
        afLignes.credit[i].montant = montant;
        if (avant > 0 && Math.abs(avant - montant) > 0.01) piece.notes.push(`${quoi} : ${formaterPrixCentimes(avant)} sur le dossier, ${formaterPrixCentimes(montant)} reçus d’après le relevé — le relevé est retenu.`);
      } else {
        const id = afIdLigne();
        afLignes.credit.push({ libelle, montant, formule: null, id });
        piece.lignes.push({ id, avant: 0, inseree: true });
      }
    };
    poser(RE_LIBELLE_ACOMPTE_PRIX, 'Acompte sur prix versé à l’étude', a.recu.prix, 'Acompte sur prix');
    poser(RE_LIBELLE_ACOMPTE_FRAIS, 'Acompte sur frais versé à l’étude', a.recu.frais, 'Acompte sur frais');
    piece.ok = a.recu.prix > 0 || a.recu.frais > 0;
    if (!piece.ok) piece.notes.push('Aucun versement du client reconnu (acompte sur prix ou provision sur frais).');
    if (a.recu.autre > 0) piece.notes.push(`${formaterPrixCentimes(a.recu.autre)} reçus sans nature reconnue (ni prix, ni frais) : non repris, à vérifier sur le relevé.`);
    const reverse = arrondiCentimes(a.reverse.prix + a.reverse.frais + a.reverse.autre);
    if (reverse > 0) piece.notes.push(`${formaterPrixCentimes(reverse)} reversés${a.tiers.length ? ' à ' + a.tiers.join(', ') : ''} : ces sommes ne sont plus détenues par l’étude (solde du compte : ${formaterPrixCentimes(a.solde || 0)}). Si le confrère reçoit l’acte, reprenez son décompte.`);
    if (a.ambigues > 0) piece.notes.push(`${a.ambigues} écriture(s) dont la colonne (débit ou crédit) n’a pas pu être lue avec certitude.`);
  }

  function renderBlocPieceAppelFonds(type) {
    const zone = afEl('af-' + type + '-bloc');
    if (!zone) return;
    const piece = afPieces[type];
    if (!piece) { zone.innerHTML = ''; return; }
    const croix = `<button type="button" class="icon-btn" onclick="effacerPieceAppelFonds('${type}')" title="Retirer la pièce" aria-label="Retirer la pièce">${icone('x')}</button>`;
    if (piece.erreur) { zone.innerHTML = `<p class="hint tf-lu">${icone('alert-triangle')} ${escapeHtml(piece.fichier)} : ce PDF n’a pas pu être lu. ${croix}</p>`; return; }
    const a = piece.analyse;
    const ligneNote = (texte, ok) => texte ? `<p class="hint">${ok ? '' : icone('alert-triangle') + ' '}${escapeHtml(texte)}</p>` : '';
    let tete = '';
    let corps = '';
    if (type === 'charges') {
      const periode = a.periode ? ` du ${afDateFr(a.periode.debut)} au ${afDateFr(a.periode.fin)}` : '';
      tete = `${escapeHtml(piece.fichier)} : ${a.montant != null ? `<strong>${formaterPrixCentimes(a.montant)}</strong>${escapeHtml(periode)}` : 'montant introuvable'}`
        + (a.fondsTravaux > 0 ? ` · dont fonds de travaux ${escapeHtml(formaterPrixCentimes(a.fondsTravaux))}` : '');
      if (a.fondsTravaux > 0) corps += `<label class="tf-case"><input type="checkbox"${piece.horsFondsTravaux ? ' checked' : ''} onchange="basculerHorsFondsTravauxCharges('af', this.checked)"> Hors fonds de travaux ${infoBulle('La cotisation au fonds de travaux est attachée au lot : son remboursement est réglé par l’avant-contrat (état daté), pas par le prorata de charges.')}</label>`;
      corps += ligneNote(piece.note, piece.ok);
    } else if (type === 'etatDate') {
      tete = `${escapeHtml(piece.fichier)} : ` + (a.montant == null ? 'fonds de travaux introuvable'
        : a.absent ? 'pas de fonds de travaux'
        : `fonds de travaux attaché au lot <strong>${formaterPrixCentimes(a.montant)}</strong> (${escapeHtml(a.source)})`);
      if (a.cotisation) tete += ` · dernière cotisation ${escapeHtml(formaterPrixCentimes(a.cotisation))}`;
      corps += ligneNote(piece.note, piece.ok);
      const date = afValeur('af-date-rdv');
      if (a.dateSignature && date && a.dateSignature !== date) corps += ligneNote(`État daté établi pour une signature le ${afDateFr(a.dateSignature)}, le rendez-vous est le ${afDateFr(date)} : demandez sa mise à jour au syndic si l’écart compte.`, false);
    } else {
      const recu = [];
      if (a.recu.prix > 0) recu.push(`${formaterPrixCentimes(a.recu.prix)} sur le prix`);
      if (a.recu.frais > 0) recu.push(`${formaterPrixCentimes(a.recu.frais)} sur frais`);
      tete = `${escapeHtml(piece.fichier)} : ${recu.length ? 'reçu du client <strong>' + escapeHtml(recu.join(', ')) + '</strong>' : 'aucun versement du client lu'}`
        + (a.nature ? ` · ${escapeHtml(a.nature)}` : '');
      (piece.notes || []).forEach(n => { corps += ligneNote(n, false); });
    }
    zone.innerHTML = `<p class="hint tf-lu">${tete} ${croix}</p>${corps}`;
  }

  // ---- Glisser-déposer des pièces (Appel de fonds, Prorata — 30/09) ---------------------------
  // Une pièce déposée sur un bouton est lue comme cette pièce ; déposée ailleurs dans la zone, son
  // type est reconnu sur le haut de la page 1 comme pour un scan du copieur (typePieceScan).
  // Rôle de chaque type de pièce dans chaque outil, ou null s'il n'y sert pas. Pure.
  var PIECES_DEPOT_OUTILS = {
    af: { avisTaxeFonciere: 'tf', appelCharges: 'charges', etatDate: 'etatDate', releveCompte: 'releve' },
    prorata: { avisTaxeFonciere: 'tf', appelCharges: 'charges' }
  };
  function destinationPieceDeposee(outil, cleType) {
    const table = PIECES_DEPOT_OUTILS[outil];
    return (table && cleType && table[cleType]) || null;
  }

  // Haut de la page 1 d'un PDF déposé (OCR de la seule page 1 s'il n'a pas de texte).
  async function textePage1Depose(fichier) {
    const pdf = await pdfjsLib.getDocument({ data: await fichier.arrayBuffer() }).promise;
    const page = await pdf.getPage(1);
    let texte = lignesDepuisItemsPdf((await page.getTextContent()).items).join('\n');
    if (texte.trim().length < 40) {
      const worker = await creerWorkerOcr();
      if (!worker) return texte;
      try { texte = await ocrPage(pdf, 1, worker); } finally { await worker.terminate(); }
    }
    return texte;
  }

  function zoneDepotPieces(e) { return e.currentTarget && e.currentTarget.classList ? e.currentTarget : null; }
  function survolDepotPieces(e) {
    e.preventDefault();
    const z = zoneDepotPieces(e);
    if (z) z.classList.add('survol');
  }
  function quitteDepotPieces(e) {
    const z = zoneDepotPieces(e);
    if (z && !(e.relatedTarget && z.contains(e.relatedTarget))) z.classList.remove('survol');
  }
  async function deposerPiecesOutil(e, outil) {
    e.preventDefault();
    const z = zoneDepotPieces(e);
    if (z) z.classList.remove('survol');
    const fichiers = Array.from((e.dataTransfer && e.dataTransfer.files) || []);
    if (!fichiers.length) return;
    if (typeof pdfjsLib === 'undefined') { afficherToast('Le lecteur PDF n\'est pas disponible.', 'OK', null); return; }
    const cible = e.target && e.target.closest ? e.target.closest('[data-piece]') : null;
    const imposee = cible && fichiers.length === 1 ? cible.getAttribute('data-piece') : null;
    for (const fichier of fichiers) {
      if (!/\.pdf$/i.test(fichier.name) && fichier.type !== 'application/pdf') {
        afficherToast(`${fichier.name} : seuls les PDF sont lus.`, 'OK', null);
        continue;
      }
      let role = imposee;
      if (!role) {
        let type = null;
        try { type = typePieceScan(enTeteScan(await textePage1Depose(fichier))); } catch (err) { console.error(err); }
        role = type ? destinationPieceDeposee(outil, type.cle) : null;
        if (!role) {
          afficherToast(type
            ? `${fichier.name} : ${type.label.toLowerCase()} — pièce non utilisée ici.`
            : `${fichier.name} : pièce non reconnue — déposez-la sur le bouton qui lui correspond.`, 'OK', null);
          continue;
        }
      }
      if (role === 'tf') await importerAvisTaxeFonciere(outil, fichier);
      else if (outil === 'prorata') { if (role === 'charges') await importerAppelChargesProrata(fichier); }
      else await importerPieceAppelFonds(role, fichier);
    }
  }

  // ---- Prorata : appel de charges (30/09) ------------------------------------------------------
  var prorataCharges = null;

  async function importerAppelChargesProrata(fichier) {
    if (!fichier) return;
    if (typeof pdfjsLib === 'undefined') { afficherToast('Le lecteur PDF n\'est pas disponible.', 'OK', null); return; }
    try {
      const lu = await lireTexteEtItemsPdf(fichier);
      prorataCharges = { fichier: fichier.name, analyse: analyserAppelCharges(lu.texte), horsFondsTravaux: true };
    } catch (e) {
      console.error(e);
      prorataCharges = { fichier: fichier.name, erreur: true };
    }
    renderBlocChargesProrata();
    appliquerChargesProrata();
  }

  function effacerChargesProrata() {
    prorataCharges = null;
    renderBlocChargesProrata();
  }

  function renderBlocChargesProrata() {
    const zone = document.getElementById('prorata-charges-bloc');
    if (!zone) return;
    const t = prorataCharges;
    if (!t) { zone.innerHTML = ''; return; }
    const croix = `<button type="button" class="icon-btn" onclick="effacerChargesProrata()" title="Retirer l'appel" aria-label="Retirer l'appel">${icone('x')}</button>`;
    if (t.erreur) { zone.innerHTML = `<p class="hint tf-lu">${icone('alert-triangle')} ${escapeHtml(t.fichier)} : ce PDF n’a pas pu être lu. ${croix}</p>`; return; }
    const a = t.analyse;
    if (a.montant == null || !a.periode) {
      zone.innerHTML = `<p class="hint tf-lu">${icone('alert-triangle')} ${escapeHtml(t.fichier)} : ${a.montant == null ? 'montant de l’appel' : 'période'} introuvable — saisissez-les. ${croix}</p>`;
      return;
    }
    const retenu = t.horsFondsTravaux && a.fondsTravaux > 0 ? a.montantHorsFondsTravaux : a.montant;
    zone.innerHTML = `<p class="hint tf-lu">${escapeHtml(t.fichier)} : <strong>${formaterPrixCentimes(a.montant)}</strong> du ${escapeHtml(afDateFr(a.periode.debut))} au ${escapeHtml(afDateFr(a.periode.fin))}`
      + (a.fondsTravaux > 0 ? ` · dont fonds de travaux ${escapeHtml(formaterPrixCentimes(a.fondsTravaux))} · retenu <strong>${formaterPrixCentimes(retenu)}</strong>` : '')
      + ` ${croix}</p>`
      + (a.fondsTravaux > 0 ? `<label class="tf-case"><input type="checkbox"${t.horsFondsTravaux ? ' checked' : ''} onchange="basculerHorsFondsTravauxCharges('prorata', this.checked)"> Hors fonds de travaux ${infoBulle('La cotisation au fonds de travaux est attachée au lot : son remboursement est réglé par l’avant-contrat (état daté), pas par le prorata de charges.')}</label>` : '');
  }

  function appliquerChargesProrata() {
    const t = prorataCharges;
    if (!t || t.erreur) return;
    const a = t.analyse;
    if (a.montant == null || !a.periode) return;
    const retenu = t.horsFondsTravaux && a.fondsTravaux > 0 ? a.montantHorsFondsTravaux : a.montant;
    const montant = document.getElementById('prorata-montant');
    const periode = document.getElementById('prorata-periode');
    const debut = document.getElementById('prorata-debut');
    const fin = document.getElementById('prorata-fin');
    if (montant) montant.value = String(retenu);
    if (periode && ['annee', 'trimestre', 'mois'].includes(a.typePeriode)) periode.value = a.typePeriode;
    if (debut) debut.value = a.periode.debut;
    if (fin) fin.value = a.periode.fin;
    renderBlocChargesProrata();
    calculerProrataAffichage();
  }

  async function importerDecompteAppelFonds(fichier) {
    if (!fichier) return;
    if (typeof pdfjsLib === 'undefined') { afficherToast('Le lecteur PDF n\'est pas disponible.', 'OK', null); return; }
    afficherRapportAppelFonds('Lecture du PDF…', [], false);
    try {
      const buffer = await fichier.arrayBuffer();
      const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
      // Deux bugs se cumulaient ici. D'abord `lu.texte` : lireTextePdfVerification renvoie une
      // CHAÎNE, pas un objet — la propriété valait donc undefined et le parseur recevait une
      // chaîne vide, quel que soit le PDF. Ensuite, même corrigé, ce lecteur aplatit chaque page
      // en une seule ligne, alors qu'un décompte est un TABLEAU et que ce parseur travaille ligne
      // par ligne (voir lireTextePdfEnLignes pour le détail du piège).
      let texte = await lireTextePdfEnLignes(pdf);
      // Décompte scanné, sans texte extractible : repli sur la lecture OCR, dont la sortie est
      // naturellement découpée en lignes.
      if (texte.trim().length < 40) texte = await lireTextePdfVerification(pdf);
      appliquerDecompteAppelFonds(texte || '');
    } catch (e) {
      console.error(e);
      afficherRapportAppelFonds('Ce PDF n\'a pas pu être lu.', ['Collez son texte dans le champ ci-dessous.'], true);
    }
  }

  function importerDecompteColle() {
    const zone = afEl('af-coller-texte');
    if (!zone) return;
    appliquerDecompteAppelFonds(zone.value || '');
  }

  // Reprend le rendez-vous lu dans le document, SANS jamais écraser ce qui est déjà saisi — même
  // règle que la référence de dossier juste en dessous, et que tout le reste de l'outil. Une date
  // déjà saisie qui diffère de celle du document n'est donc pas corrigée en silence : elle est
  // signalée, comme le solde déclaré par le confrère. Renvoie les notes à joindre au rapport.
  function appliquerRendezVousDetecte(texte) {
    const rdv = detecterRendezVousDecompte(texte);
    if (!rdv.date) return [];
    const notes = [];
    const champD = afEl('af-date-rdv');
    const champH = afEl('af-heure-rdv');
    const repris = [];
    // Une date saisie qui diffère de celle du document n'est pas corrigée en silence : elle est
    // signalée. Et dans ce cas l'heure n'est PAS reprise non plus — elle se rapporte au jour du
    // document, la coller sur un autre jour marierait une heure à une date qui n'est pas la
    // sienne (le défaut même qu'afZoneHeureAutourDate écarte à la lecture).
    const memeJour = champD && champD.value === rdv.date;
    const dateDiverge = champD && champD.value && !memeJour;
    if (champD && !champD.value) { champD.value = rdv.date; repris.push('la date'); }
    else if (dateDiverge) {
      notes.push(`Le document annonce un rendez-vous le ${formatDateFr(rdv.date)}, alors que la date saisie est le ${formatDateFr(champD.value)} : à vérifier.`);
    }
    if (rdv.heure && champH && !champH.value && !dateDiverge) { champH.value = rdv.heure; repris.push('l’heure'); }
    if (repris.length) {
      notes.push(`Rendez-vous repris du document (${repris.join(' et ')}) : ${phraseRdvAppelFonds(afValeur('af-date-rdv'), afValeur('af-heure-rdv'), '')} — à vérifier.`);
      majApercuAppelFonds();
    }
    return notes;
  }

  // Les lignes du confrère REMPLACENT le tableau : mélanger son décompte avec celui déduit du
  // dossier ferait compter deux fois le prix ou les frais.
  function appliquerDecompteAppelFonds(texte) {
    const res = parserDecompteConfrere(texte);
    const total = res.lignes.debit.length + res.lignes.credit.length;
    // Le rendez-vous est cherché AVANT le retour sur décompte vide : une convocation dont le
    // tableau n'a pas été reconnu porte quand même le jour et l'heure, et c'est déjà ça de pris.
    const notesRdv = appliquerRendezVousDetecte(texte);
    if (!total) {
      afficherRapportAppelFonds('Aucune ligne de décompte reconnue dans ce document.',
        res.meta.avertissements.concat(notesRdv), true);
      return;
    }
    afLignes = res.lignes;
    renderTableAppelFonds();
    const notes = res.meta.avertissements.concat(notesRdv);
    if (res.meta.refTrouvee) {
      const champ = afEl('af-ref');
      if (champ && !champ.value) { champ.value = res.meta.refTrouvee; majApercuAppelFonds(); }
    }
    // Le solde annoncé par le confrère sert de CONTRÔLE, jamais de valeur reprise : s'il diffère
    // du recalcul, c'est une ligne mal lue — le dire plutôt que de recopier son chiffre.
    if (res.meta.soldeDeclare != null) {
      const somme = (s) => res.lignes[s].reduce((t, l) => t + (l.memoire ? 0 : (l.montant || 0)), 0);
      const recalcul = somme('debit') - somme('credit');
      if (Math.abs(recalcul - res.meta.soldeDeclare) > 0.02) {
        notes.push(`Le solde annoncé par le confrère (${montantVersTexteFr(res.meta.soldeDeclare)}) ne correspond pas au recalcul (${montantVersTexteFr(recalcul)}) : une ligne a probablement été mal lue.`);
      }
    }
    // Le contrôle du barème a besoin du département et de la nature du bien, qu'un décompte ou une
    // convocation ne portent presque jamais (ils décrivent une somme à virer, pas le bien). Sans
    // eux il se tait — et se taire sans rien dire laisse croire que la ligne a été vérifiée et
    // jugée conforme. On le dit donc, mais seulement quand il y a bien une ligne à contrôler.
    if (!fourchetteFraisActeFormulaire() && afLignes.debit.some(l => !l.memoire && estLigneFraisActeVente(l.libelle))) {
      notes.push('Les frais d’acte n’ont pas été contrôlés : renseignez l’adresse du bien et sa désignation (ou directement le département et la nature du bien, juste sous le tableau).');
    }
    afficherRapportAppelFonds(`${total} ligne(s) reprises du décompte.`, notes, notes.length > 0);
  }

  function afficherRapportAppelFonds(titre, notes, alerte) {
    const cible = afEl('af-rapport-parse');
    if (!cible) return;
    cible.className = 'af-rapport af-rapport-visible ' + (alerte ? 'af-rapport-alerte' : 'af-rapport-ok');
    cible.innerHTML = `<strong>${escapeHtml(titre)}</strong>` +
      ((notes && notes.length) ? `<ul>${notes.map(n => `<li>${escapeHtml(n)}</li>`).join('')}</ul>` : '');
  }

  // --- modèle Word, chargé à la demande ---------------------------------------------------------
  //
  // Le modèle (≈350 Ko) et les deux bibliothèques ne servent qu'à cet écran : les charger dans
  // index.html ralentirait CHAQUE ouverture de CLAIRE pour rien.
  function afChargerScript(src) {
    return new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = src;
      s.onload = resolve;
      s.onerror = () => reject(new Error('Chargement impossible : ' + src));
      document.head.appendChild(s);
    });
  }

  function chargerModeleAppelFonds() {
    if (afModeleCharge) return Promise.resolve();
    if (afModeleEnCours) return afModeleEnCours;
    afModeleEnCours = (async () => {
      if (!window.APPEL_FONDS_MODELE) await afChargerScript('appel-de-fonds-modele.js');
      // Les logos sont posés DÈS QUE le modèle est là, avant les deux bibliothèques : celles-ci
      // viennent d'un CDN, et un poste sans accès internet afficherait sinon un aperçu sans
      // en-tête alors que les images, elles, sont servies par le serveur de l'étude.
      appliquerImagesAppelFonds();
      if (!window.PizZip) await afChargerScript('https://cdn.jsdelivr.net/npm/pizzip@3/dist/pizzip.js');
      if (!window.docxtemplater) await afChargerScript('https://cdn.jsdelivr.net/npm/docxtemplater@3/build/docxtemplater.js');
      afModeleCharge = true;
    })();
    afModeleEnCours.catch(() => { afModeleEnCours = null; });
    return afModeleEnCours;
  }

  // Les logos de l'en-tête viennent du même fichier que le modèle Word : l'aperçu n'a donc ses
  // images qu'une fois ce fichier chargé. Sans lui, la mise en page tient quand même (les <img>
  // restent vides), ce qui vaut mieux qu'un aperçu qui refuse de s'afficher.
  function appliquerImagesAppelFonds() {
    const a = window.APPEL_FONDS_MODELE && window.APPEL_FONDS_MODELE.assets;
    if (!a) return;
    const poser = (id, src) => { const e = afEl(id); if (e && src) e.src = src; };
    poser('af-logo-notaires', a.logoNotaires);
    poser('af-logo-office', a.logoOffice);
    poser('af-icone-visio', a.iconVisio);
    poser('af-icone-facebook', a.iconFacebook);
    poser('af-icone-instagram', a.iconInstagram);
  }

  // Mention du mode d'envoi. Elle REMPLACE l'adresse postale du destinataire tant qu'aucune
  // adresse n'est saisie ; dès qu'une adresse l'est, c'est elle qui s'affiche et la mention
  // disparaît (une adresse postale et « envoi par e-mail uniquement » se contrediraient).
  // Éditable dans l'aperçu comme le reste du courrier, et reprise dans le .docx via `addrLines` :
  // c'est le seul champ du modèle Word qui accepte des lignes libres (le modèle est stocké en
  // base64 dans appel-de-fonds-modele.js, un placeholder dédié obligerait à le régénérer).
  // Elle vit dans son PROPRE élément, hors de #af-p-adresse : majApercuAppelFonds() réécrit ce
  // dernier en entier à chaque frappe, une mention placée dedans serait effacée à la saisie
  // suivante.
  var MENTION_ENVOI_APPEL_FONDS = "Envoi par e-mail uniquement";

  function composerAdresseCourrier(lignesAdresse, mention) {
    const lignes = [];
    String(lignesAdresse || '').split('\n').forEach(l => { if (l.trim()) lignes.push(l.trim()); });
    const m = String(mention || '').trim();
    if (m) lignes.push(m);
    return lignes.join('\n');
  }

  // Relit le courrier TEL QU'IL EST AFFICHÉ (et non le modèle interne) : une correction faite
  // directement dans l'aperçu doit se retrouver dans le .docx.

  function donneesCourrierAppelFonds() {
    const lire = (id) => { const e = afEl(id); return e ? e.textContent.trim() : ''; };
    const mentionAffichee = () => { const e = afEl('af-p-mention-ligne'); return !!e && e.style.display !== 'none'; };
    const lignes = (id) => {
      const tbody = afEl(id);
      if (!tbody) return [];
      return [...tbody.querySelectorAll('tr')].map(tr => {
        if (tr.classList.contains('af-sous-total')) return null;
        const champs = tr.querySelectorAll('.af-champ');
        if (champs.length < 2) return null;
        const formule = tr.querySelector('.af-formule');
        return { label: champs[0].textContent.trim(), formula: formule ? formule.textContent.trim() : undefined, amount: champs[1].textContent.trim() };
      }).filter(Boolean);
    };
    const sousTotal = (id, colonne) => {
      const tr = afEl(id) && afEl(id).querySelector('tr.af-sous-total');
      if (!tr) return '';
      const c = tr.querySelectorAll('td')[colonne];
      return c ? c.textContent.trim() : '';
    };
    const blocAdresse = afEl('af-p-adresse');
    return {
      ref: afValeur('af-ref'),
      addrLines: composerAdresseCourrier(
        blocAdresse ? blocAdresse.innerHTML.split('<br>').map(s => s.replace(/<[^>]+>/g, '').trim()).filter(Boolean).join('\n') : '',
        mentionAffichee() ? lire('af-p-mention') : ''
      ),
      ville: lire('af-p-ville'),
      dateLettre: lire('af-p-datelettre'),
      salut1: lire('af-p-salut1'),
      designation: lire('af-p-designation'),
      adresseBien: lire('af-p-adressebien'),
      rdvPhrase: lire('af-p-rdv'),
      debitRows: lignes('af-tbody-debit'),
      totalDebit: sousTotal('af-tbody-debit', 2),
      creditRows: lignes('af-tbody-credit'),
      totalCredit: sousTotal('af-tbody-credit', 1),
      solde: lire('af-p-solde'),
      salut2: lire('af-p-salut2'),
      phraseDeblocage: lire('af-p-deblocage'),
      notaire: lire('af-p-notaire')
    };
  }

  function afBase64VersOctets(b64) {
    const bin = atob(b64);
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    return arr;
  }

  // Génère le .docx du courrier et renvoie { blob, nom } — partagé par le téléchargement et la
  // création d'un brouillon Outlook (pièce jointe). Lève si les bibliothèques ne sont pas chargées.
  async function genererBlobAppelFonds() {
    await chargerModeleAppelFonds();
    const Ctor = window.docxtemplater.default || window.docxtemplater;
    const zip = new window.PizZip(afBase64VersOctets(window.APPEL_FONDS_MODELE.docxB64));
    const doc = new Ctor(zip, { paragraphLoop: true, linebreaks: true });
    doc.render(donneesCourrierAppelFonds());
    const blob = doc.getZip().generate({ type: 'blob', mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
    return { blob, nom: afNomFichierDocx(afClients.filter(c => String(c.nom || '').trim())) };
  }

  async function telechargerAppelFondsDocx(btn) {
    const libelleInitial = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = 'Génération…'; }
    try {
      const { blob, nom } = await genererBlobAppelFonds();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = nom;
      a.click();
      ouvrirApresTelechargement(nom);
      setTimeout(() => URL.revokeObjectURL(url), 2000);
    } catch (e) {
      console.error(e);
      afficherToast('Le courrier n\'a pas pu être généré. Vérifiez que le poste a accès au réseau la première fois (deux bibliothèques sont téléchargées une seule fois).', 'OK', null);
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = libelleInitial; }
    }
  }

  // Prépare l'email du courrier d'appel de fonds, le .docx DÉJÀ joint (ce qu'un mailto: ne sait pas
  // faire), au destinataire du dossier relié : le client, ou le confrère quand un autre office
  // représente l'acquéreur (formules adaptées, voir livrerEmailDossier). En mode messagerie par
  // défaut, le .docx est téléchargé à côté, à joindre à la main.
  async function preparerEmailAppelFonds(btn) {
    const d = afDossierLie ? dossiers.find(x => x.id === afDossierLie) : null;
    const destinataire = d ? emailDestinataireRelance(d) : '';
    if (!destinataire) {
      afficherToast("Reliez un dossier dont l'email du destinataire est renseigné pour préparer l'email.", 'OK', null);
      return;
    }
    const libelleInitial = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = 'Préparation…'; }
    try {
      const { blob, nom } = await genererBlobAppelFonds();
      const contenuBase64 = await blobVersBase64(blob);
      const confrere = notaireParticipantRepresenteAcquereur(d);
      const r = await livrerEmailDossier({
        destinataire,
        confrere,
        responsableSignature: d.responsable,
        sujet: `Appel de fonds — rendez-vous de signature — ${libelleDossierAffiche(d)}`,
        corps: confrere
          ? 'Veuillez trouver ci-joint le courrier de convocation et d’appel de fonds destiné à votre client, en vue du rendez-vous de signature.'
          : 'Madame, Monsieur,\n\nVeuillez trouver ci-joint le courrier de convocation et d’appel de fonds relatif à votre acquisition.',
        pieces: [{ nom, type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', contenuBase64 }]
      });
      if (!r.ok) { afficherToast(r.message || "L'email n'a pas pu être préparé.", 'OK', null); return; }
      if (r.mode === 'mailto') telechargerFichier(blob, nom);
      ajouterHistorique(d, 'Email du courrier d’appel de fonds préparé');
      sauvegarder(d);
      annoncerEmailPret(r, false, r.mode === 'mailto' ? 'Joignez le courrier, qui vient d’être téléchargé.' : '');
    } catch (e) {
      console.error(e);
      afficherToast('Le courrier n\'a pas pu être généré (accès réseau requis la première fois).', 'OK', null);
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = libelleInitial; }
    }
  }

  function reinitialiserAppelFonds() {
    afDossierLie = null;
    afFraisChoisiALaMain = { departement: false, type: false };
    afClients = [{ civilite: 'M', prenom: '', nom: '' }];
    afLignes = lignesDecompteDepuisPrefill(null);
    tfAvis.af = null;
    renderBlocTaxeFonciere('af');
    ['charges', 'etatDate', 'releve'].forEach(type => { afPieces[type] = null; renderBlocPieceAppelFonds(type); });
    definirModeDecompteAppelFonds('office');
    ['af-ref', 'af-designation', 'af-adresse-bien', 'af-adresse-clients', 'af-date-rdv', 'af-heure-rdv', 'af-lieu-autre', 'af-coller-texte', 'af-frais-departement', 'af-frais-type', 'af-prix-mobilier'].forEach(id => {
      const e = afEl(id);
      if (e) e.value = '';
    });
    const casePret = afEl('af-pret-hypothecaire');
    if (casePret) casePret.checked = false;
    const caseSansPret = afEl('af-sans-pret');
    if (caseSansPret) caseSansPret.checked = false;
    const lieu = afEl('af-lieu');
    if (lieu) lieu.value = "en l'étude";
    const mention = afEl('af-p-mention');
    if (mention) mention.textContent = MENTION_ENVOI_APPEL_FONDS;
    majSourceAdresseBien(false);
    renderSuggestionsAdresseBien([]);
    const rapport = afEl('af-rapport-parse');
    if (rapport) { rapport.className = 'af-rapport'; rapport.innerHTML = ''; }
    const recap = afEl('af-recap-prefill');
    if (recap) { recap.className = 'af-recap'; recap.innerHTML = ''; }
    renderPillDossierAppelFonds();
    renderClientsAppelFonds();
    renderTableAppelFonds();
    majLieuAppelFonds();
  }

  var appelFondsInitialise = false;
  function initAppelFonds() {
    // Le modèle est chargé dès l'arrivée sur l'onglet (et non au clic sur « Télécharger ») : les
    // logos de l'en-tête en viennent aussi, l'aperçu serait sinon sans images jusqu'au premier
    // téléchargement. Un échec de chargement est silencieux ici — la mise en page tient sans les
    // images, et le message d'erreur a sa place au moment où on demande vraiment le fichier.
    chargerModeleAppelFonds().catch(() => {});
    if (appelFondsInitialise) return;
    appelFondsInitialise = true;
    const dateLettre = afEl('af-date-lettre');
    if (dateLettre && !dateLettre.value) dateLettre.value = new Date().toISOString().slice(0, 10);
    afLignes = lignesDecompteDepuisPrefill(null);
    renderClientsAppelFonds();
    renderTableAppelFonds();
    majApercuAppelFonds();
  }

  // ==== RÉGLAGES : rappels automatiques par email ====
  //
  // Remplace le DÉCLENCHEMENT AUTOMATIQUE des rappels (voir server/src/jobs/rappels.js) — le
  // rappel générique par email ("Rappel email" sur la fiche dossier, `ouvrirEmailRappel()`) a
  // depuis été retiré définitivement, à la demande de l'étude : ces rappels automatiques, avec
  // copie systématique vers `copieEmail`, couvrent désormais ce besoin sans geste manuel. L'étude
  // a explicitement demandé un écran dans la sidebar pour saisir elle-même ces réglages, plutôt
  // qu'un tableau figé dans le code ou un fichier de configuration à éditer à la main.
  //
  // TROISIÈME architecture d'envoi, et la seule en service (voir server/src/envoiEmail.js pour le
  // détail) : CLAIRE envoie elle-même un email SMTP vers une boîte-passerelle, dont l'ARRIVÉE
  // déclenche le flux Power Automate qui poste ensuite le message dans Teams. Le déclencheur HTTP
  // des deux versions précédentes n'existe plus — d'où la disparition du champ « URL du flux » de
  // cet écran, remplacé par le serveur d'envoi SMTP et la boîte-passerelle.
  //
  // Le mot de passe SMTP (quand l'étude en pose un — l'envoi direct Microsoft 365 n'en demande
  // aucun) ne redescend JAMAIS ici : la route renvoie `smtpMotDePasseEnregistre`, un simple
  // booléen. Le champ reste donc vide à l'ouverture, et n'est envoyé au serveur que si quelqu'un y
  // tape réellement quelque chose — sans quoi un enregistrement ordinaire l'effacerait.
  //
  // `copieEmail` (adresse recevant une copie de CHAQUE rappel envoyé, quel que soit le
  // responsable destinataire) a été ajoutée sur une demande antérieure : l'étude veut être tenue
  // au courant de tous les envois, pas seulement ceux qui lui sont personnellement adressés en
  // tant que responsable d'un dossier. Envoyée par `executerTacheRappels()` en plus du
  // destinataire habituel, jamais à sa place — un échec d'envoi de la copie n'empêche jamais le
  // rappel principal d'être marqué comme envoyé (voir jobs/rappels.js).
  //
  // Liste fermée des 3 responsables (voir CLAUDE.md, "Responsables du dossier : liste fermée") —
  // reprise ici telle quelle plutôt que de refactoriser les <select> existants du formulaire/de la
  // fiche dossier, qui n'ont pas besoin de cette liste sous forme de variable.
  var RESPONSABLES = ['Bastien ANGLUMENT', 'Julie VASSELIN', 'Jérémy SAUJOT'];

  // Seul transport d'envoi proposé depuis l'écran Réglages : un compte Gmail avec mot de passe
  // d'application, port 587 en STARTTLS. Microsoft 365 est écarté (pas de droits d'administration
  // pour autoriser le SMTP authentifié, et le SPF du domaine interdit l'envoi sans compte).
  var GMAIL_SMTP = { hote: 'smtp.gmail.com', port: 587, securise: false };

  // Réglages tels qu'ils sont ENREGISTRÉS côté serveur (dernière lecture ou dernier enregistrement).
  // Le bouton « Tester » envoie à l'adresse enregistrée, pas à celle du champ : il doit donc savoir
  // si les deux diffèrent, sans quoi on teste une adresse que personne ne voit plus à l'écran.
  let reglagesEnregistres = { emailPasserelle: '', emailsResponsables: {} };

  // Contrôle d'une adresse AVANT le message de test (pure, testable). Deux niveaux :
  // - `erreur` : l'adresse ne peut pas être une adresse email — rien n'est envoyé ;
  // - `avertissement` : l'adresse est bien formée mais son domaine diffère de celui de la
  //   boîte-passerelle. C'est la faute qu'aucun contrôle de format ne voit (« notaire.fr » pour
  //   « notaires.fr ») et qui ne se révèle qu'au bout de la chaîne, dans l'erreur du flux Power
  //   Automate. Un simple avertissement : un locataire Microsoft 365 peut porter plusieurs domaines.
  function controlerAdresseEnvoi(adresse, adresseReference) {
    const a = typeof adresse === 'string' ? adresse.trim() : '';
    if (!a) return { erreur: 'Aucune adresse enregistrée.' };
    if (/\s/.test(a)) return { erreur: `« ${a} » contient une espace.` };
    if (!/^[^@]+@[^@]+$/.test(a)) return { erreur: `« ${a} » doit contenir un seul @.` };
    const [local, domaine] = a.split('@');
    if (!local) return { erreur: `« ${a} » : rien avant le @.` };
    if (!/^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$/.test(domaine)) {
      return { erreur: `« ${a} » : le domaine « ${domaine} » n'est pas valide (point manquant, en double ou en fin d'adresse ?).` };
    }
    const ref = typeof adresseReference === 'string' ? adresseReference.trim() : '';
    const domaineRef = ref.includes('@') ? ref.split('@').pop().toLowerCase() : '';
    if (domaineRef && domaine.toLowerCase() !== domaineRef) {
      return { avertissement: `Le domaine « ${domaine} » diffère de celui de la boîte-passerelle (« ${domaineRef} ») : vérifiez l'orthographe.` };
    }
    return {};
  }

  async function chargerReglages() {
    initReglagesNotifNavigateur();
    const version = document.getElementById('reglages-version');
    if (version) version.textContent = VERSION_APP;
    const inter = document.getElementById('reglages-theme-sombre');
    if (inter) inter.checked = document.documentElement.getAttribute('data-theme') === 'dark';
    appliquerAccent(document.documentElement.getAttribute('data-accent') || 'bordeaux', false);
    try {
      const reponse = await fetchAvecAuth('/api/reglages');
      const reglages = await reponse.json();
      document.getElementById('reglages-envoi-actif').checked = !!reglages.emailActif;
      document.getElementById('reglages-passerelle').value = reglages.emailPasserelle || '';
      document.getElementById('reglages-smtp-utilisateur').value = reglages.smtpUtilisateur || '';
      // Jamais la valeur elle-même : le serveur ne la renvoie pas. Le champ reste vide, et son
      // texte d'invite dit si un mot de passe est déjà en place.
      const champSecret = document.getElementById('reglages-smtp-motdepasse');
      champSecret.value = '';
      champSecret.placeholder = reglages.smtpMotDePasseEnregistre
        ? 'Déjà enregistré — laisser vide pour le conserver'
        : '16 caractères';
      document.getElementById('reglages-copie-email').value = reglages.copieEmail || '';
      memoriserReglagesEnregistres(reglages);
      renderReglagesEmails(reglages.emailsResponsables || {}, reglages.fonctionsResponsables || {});
      document.getElementById('reglages-etat').style.display = 'none';
      chargerDernierTourRappels();
      chargerReglagesAgenda();
      chargerEtatSauvegarde();
      chargerMiseAJour();
      chargerRapportTechnique();
    } catch (e) {
      // Session expirée : déjà géré par fetchAvecAuth (écran de connexion réaffiché).
    }
  }

  // Case à cocher "Notifications sur ce poste" : reflète à la fois le choix de l'étude
  // (localStorage) et l'état RÉEL de la permission navigateur, qui peut avoir été révoquée depuis
  // en dehors de CLAIRE (réglages Chrome) — sans ce second contrôle, la case resterait cochée alors
  // que plus aucune notification ne peut réellement s'afficher.
  function initReglagesNotifNavigateur() {
    const cb = document.getElementById('reglages-notif-navigateur');
    const etat = document.getElementById('reglages-notif-navigateur-etat');
    if (!cb) return;
    const supporte = typeof Notification !== 'undefined';
    cb.disabled = !supporte;
    cb.checked = supporte && notificationsNavigateurActivees() && Notification.permission === 'granted';
    if (etat) {
      etat.textContent = !supporte
        ? "Ce navigateur ne prend pas en charge les notifications."
        : Notification.permission === 'denied'
          ? "Bloquée par le navigateur : à réautoriser via l'icône à gauche de l'adresse."
          : '';
    }
  }

  function basculerNotifNavigateur(active) {
    const etat = document.getElementById('reglages-notif-navigateur-etat');
    if (!active) {
      try { localStorage.removeItem(CLE_LOCALSTORAGE_NOTIF_NAVIGATEUR); } catch (e) { /* pas bloquant */ }
      if (etat) etat.textContent = '';
      return;
    }
    if (typeof Notification === 'undefined') return;
    Notification.requestPermission().then((permission) => {
      if (permission === 'granted') {
        try { localStorage.setItem(CLE_LOCALSTORAGE_NOTIF_NAVIGATEUR, '1'); } catch (e) { /* pas bloquant */ }
        if (etat) etat.textContent = '✓ Notifications activées sur ce poste.';
      } else {
        document.getElementById('reglages-notif-navigateur').checked = false;
        if (etat) etat.textContent = "Autorisation refusée — rien ne sera notifié tant qu'elle n'est pas accordée.";
      }
    });
  }

  function memoriserReglagesEnregistres(reglages) {
    reglagesEnregistres = {
      emailPasserelle: (reglages && reglages.emailPasserelle) || '',
      emailsResponsables: (reglages && reglages.emailsResponsables) || {},
      fonctionsResponsables: (reglages && reglages.fonctionsResponsables) || {}
    };
    reglagesSignatureCache = null;
  }

  // Réglages › Signature des emails : la carte de l'office et la bannière Visio, déposées en PNG ou
  // JPEG (demandé par l'étude le 29/09 : « les png seront toujours les mêmes pour les emails envoyés
  // par CLAIRE »). Un aperçu, « Déposer une image », et × pour revenir à la version composée.
  var EMPLACEMENTS_SIGNATURE = [
    { cle: 'carte', libelle: 'Carte de l’office', aide: 'Carte complète (façade, coordonnées, logos), environ 624 × 208 px.' },
    { cle: 'visio', libelle: 'Bannière Visio', aide: '« Pas le temps de passer chez votre notaire ? », environ 620 × 70 px.' }
  ];

  async function renderReglagesSignatureImages(forcer) {
    const zone = document.getElementById('reglages-signature-images');
    if (!zone) return;
    const images = await chargerImagesSignatureDeposees(forcer);
    zone.innerHTML = EMPLACEMENTS_SIGNATURE.map(e => {
      const img = images && images[e.cle];
      return `<div class="signature-image-ligne">
        <div class="signature-image-tete">
          <span class="reglages-option-titre">${e.libelle}</span>
          ${img ? `<button type="button" class="ech-ico ech-ico-suppr" onclick="retirerImageSignature('${e.cle}')" title="Retirer l’image" aria-label="Retirer l’image : ${escapeAttr(e.libelle)}">${icone('x')}</button>` : ''}
        </div>
        ${img
          ? `<img class="signature-image-apercu" src="data:${img.type};base64,${img.base64}" alt="${escapeAttr(e.libelle)}">`
          : `<span class="hint">${e.aide} Aucune image : version composée par CLAIRE.</span>`}
        <input type="file" id="signature-image-${e.cle}" accept="image/png,image/jpeg" hidden onchange="deposerImageSignature('${e.cle}', this)">
        <button type="button" class="bouton-ajout bouton-ajout-court" onclick="document.getElementById('signature-image-${e.cle}').click()">${img ? 'Remplacer l’image' : 'Déposer une image'}</button>
      </div>`;
    }).join('');
  }

  function lireImageFichier(fichier) {
    return new Promise((resolve, reject) => {
      const lecteur = new FileReader();
      lecteur.onerror = () => reject(new Error('lecture impossible'));
      lecteur.onload = () => {
        const url = String(lecteur.result || '');
        const image = new Image();
        image.onload = () => resolve({ url, largeur: image.naturalWidth, hauteur: image.naturalHeight });
        image.onerror = () => reject(new Error('image illisible'));
        image.src = url;
      };
      lecteur.readAsDataURL(fichier);
    });
  }

  async function deposerImageSignature(cle, input) {
    const fichier = input && input.files && input.files[0];
    if (!fichier) return;
    if (!/^image\/(png|jpeg)$/.test(fichier.type)) { afficherToast('Choisissez une image PNG ou JPEG.', 'OK', null); return; }
    if (fichier.size > 1.5 * 1024 * 1024) { afficherToast('Image trop lourde : 1,5 Mo au plus.', 'OK', null); return; }
    try {
      const { url, largeur, hauteur } = await lireImageFichier(fichier);
      const r = await fetchAvecAuth('/api/signature-images/' + cle, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: fichier.type, base64: url.replace(/^data:[^,]*,/, ''), largeur, hauteur })
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.erreur || 'enregistrement refusé');
      imagesSignatureDeposees = j;
      await renderReglagesSignatureImages();
      afficherToast('Image enregistrée : elle figure désormais dans les emails préparés par CLAIRE.', 'OK', null);
    } catch (e) {
      afficherToast('Image non enregistrée : ' + e.message, 'OK', null);
    } finally {
      input.value = '';
    }
  }

  function retirerImageSignature(cle) {
    const e = EMPLACEMENTS_SIGNATURE.find(x => x.cle === cle);
    demanderConfirmation(`Retirer l’image « ${e ? e.libelle : cle} » de la signature ?`, async () => {
      try {
        const r = await fetchAvecAuth('/api/signature-images/' + cle, { method: 'DELETE' });
        if (!r.ok) throw new Error('statut ' + r.status);
        imagesSignatureDeposees = await r.json();
        await renderReglagesSignatureImages();
      } catch (err) { afficherToast('Retrait impossible : ' + err.message, 'OK', null); }
    });
  }

  // Adresse de chaque collaborateur (rappels Teams, et adresse de sa carte de signature) et sa
  // fonction, écrite sous son nom dans la signature de ses emails.
  function renderReglagesEmails(emailsResponsables, fonctionsResponsables) {
    const fonctions = fonctionsResponsables || {};
    document.getElementById('reglages-emails-liste').innerHTML = RESPONSABLES.map((nom, i) => `
      <div class="reglages-champ reglages-champ-haut">
        <div class="reglages-champ-libelle"><label for="reglages-email-${i}">${escapeHtml(nom)}</label></div>
        <div class="reglages-champ-pile">
          <div class="reglages-champ-ligne">
            <input type="email" id="reglages-email-${i}" data-responsable="${escapeAttr(nom)}" placeholder="prenom.nom@notaires.fr" value="${escapeAttr(emailsResponsables[nom] || '')}">
            <button type="button" class="secondary" onclick="testerEnvoiResponsable('${escapeOnclickArg(nom)}')">Tester</button>
          </div>
          <input type="text" id="reglages-fonction-${i}" class="reglages-fonction" aria-label="Fonction de ${escapeAttr(nom)} dans la signature" placeholder="Fonction dans la signature : ${escapeAttr(FONCTIONS_SIGNATURE_DEFAUT[nom] || 'Collaborateur')}" value="${escapeAttr(fonctions[nom] || '')}">
          <p class="hint reglages-email-resultat" id="reglages-email-resultat-${i}"></p>
        </div>
      </div>
    `).join('');
  }

  function reglagesFormulaireVersObjet() {
    const emailsResponsables = {};
    const fonctionsResponsables = {};
    RESPONSABLES.forEach((nom, i) => {
      const champ = document.getElementById(`reglages-email-${i}`);
      const valeur = champ ? champ.value.trim() : '';
      if (valeur) emailsResponsables[nom] = valeur;
      const fonction = document.getElementById(`reglages-fonction-${i}`);
      if (fonction && fonction.value.trim()) fonctionsResponsables[nom] = fonction.value.trim();
    });
    const objet = {
      emailActif: document.getElementById('reglages-envoi-actif').checked,
      emailPasserelle: document.getElementById('reglages-passerelle').value.trim(),
      // Gmail uniquement (décision de l'étude) : serveur, port et chiffrement sont fixes, et
      // l'expéditeur reste vide pour que le compte authentifié soit utilisé — Gmail refuse tout
      // autre nom. Le serveur garde un transport SMTP générique, seul ce formulaire est fermé.
      smtpHote: GMAIL_SMTP.hote,
      smtpPort: GMAIL_SMTP.port,
      smtpSecurise: GMAIL_SMTP.securise,
      smtpUtilisateur: document.getElementById('reglages-smtp-utilisateur').value.trim(),
      smtpExpediteur: '',
      copieEmail: document.getElementById('reglages-copie-email').value.trim(),
      emailsResponsables,
      fonctionsResponsables
    };
    // Le mot de passe n'accompagne l'enregistrement QUE si quelqu'un vient d'en taper un : la clé
    // absente veut dire « garde celui qui est en base » (voir assainirReglages côté serveur).
    // Deux exceptions où on l'envoie vide, pour l'effacer explicitement : quand le compte SMTP est
    // lui-même vidé (retour à l'envoi anonyme, un mot de passe orphelin n'aurait plus de sens).
    const secret = document.getElementById('reglages-smtp-motdepasse').value;
    if (secret) objet.smtpMotDePasse = secret;
    else if (!objet.smtpUtilisateur) objet.smtpMotDePasse = '';
    return objet;
  }

  async function enregistrerReglages() {
    const zone = document.getElementById('reglages-etat');
    try {
      const reponse = await fetchAvecAuth('/api/reglages', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(reglagesFormulaireVersObjet())
      });
      const reglages = await reponse.json();
      memoriserReglagesEnregistres(reglages);
      renderReglagesEmails(reglages.emailsResponsables || {}, reglages.fonctionsResponsables || {});
      zone.style.display = 'flex';
      zone.className = 'analyse-ia-dispo dispo-ok';
      zone.innerHTML = `${icone('check')}Réglages enregistrés.`;
    } catch (e) {
      zone.style.display = 'flex';
      zone.className = 'analyse-ia-dispo dispo-off';
      zone.innerHTML = `${icone('alert-triangle')}Impossible d'enregistrer — vérifiez la connexion au serveur intranet.`;
    }
  }

  // Envoie un message de test à UN collaborateur, avec les réglages déjà ENREGISTRÉS côté serveur
  // (voir routes/reglages.js) — pas ceux du formulaire pas encore validés : on veut vérifier ce que
  // le job de rappels utilisera réellement. Si le formulaire contient une modification non
  // enregistrée, on le signale plutôt que de tester une valeur qui n'est pas encore la bonne.
  function afficherResultatTest(resultat, texte, classe) {
    if (!resultat) return;
    resultat.textContent = texte;
    resultat.className = `hint reglages-email-resultat${classe ? ' ' + classe : ''}`;
  }

  async function testerEnvoiResponsable(nom, malgreAvertissement) {
    const i = RESPONSABLES.indexOf(nom);
    const resultat = document.getElementById(`reglages-email-resultat-${i}`);
    const champ = document.getElementById(`reglages-email-${i}`);
    const saisie = champ ? champ.value.trim() : '';
    const enregistree = (reglagesEnregistres.emailsResponsables[nom] || '').trim();

    // Vérifications AVANT tout envoi : le message part vers l'adresse ENREGISTRÉE, il faut donc
    // d'abord s'assurer que c'est bien celle que l'on a sous les yeux, puis qu'elle tient debout.
    if (saisie !== enregistree) {
      afficherResultatTest(resultat, enregistree
        ? `Adresse modifiée mais pas enregistrée : le test partirait encore vers « ${enregistree} ». Cliquez sur « Enregistrer » d'abord.`
        : "Adresse pas encore enregistrée : cliquez sur « Enregistrer » d'abord.", 'reglages-email-echec');
      return;
    }
    const controle = controlerAdresseEnvoi(enregistree, reglagesEnregistres.emailPasserelle);
    if (controle.erreur) {
      afficherResultatTest(resultat, `${controle.erreur} Rien n'a été envoyé.`, 'reglages-email-echec');
      return;
    }
    const controlePasserelle = controlerAdresseEnvoi(reglagesEnregistres.emailPasserelle, '');
    if (controlePasserelle.erreur) {
      afficherResultatTest(resultat, `Boîte-passerelle : ${controlePasserelle.erreur} Rien n'a été envoyé.`, 'reglages-email-echec');
      return;
    }
    if (controle.avertissement && !malgreAvertissement) {
      if (resultat) {
        resultat.className = 'hint reglages-email-resultat reglages-email-echec';
        resultat.innerHTML = `${escapeHtml(controle.avertissement)} <button type="button" class="lien-dossier-local" onclick="testerEnvoiResponsable('${escapeOnclickArg(nom)}', true)">Envoyer quand même</button>`;
      }
      return;
    }

    afficherResultatTest(resultat, `Envoi du message de test à « ${enregistree} »…`, '');
    try {
      const reponse = await fetchAvecAuth('/api/reglages/tester-email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ responsable: nom })
      });
      const corps = await reponse.json();
      if (!resultat) return;
      if (reponse.ok && corps.ok) {
        // Volontairement pas « ✓ Message reçu » : cette réponse ne dit QUE ceci — le serveur
        // d'envoi a accepté le message. Elle ne prouve ni son arrivée dans la boîte-passerelle,
        // ni le déclenchement du flux, ni le message Teams. Laisser croire l'inverse ferait
        // conclure à tort que la chaîne fonctionne, et chercher le problème au mauvais endroit.
        const destinataire = corps.destinataire || enregistree;
        const passerelle = corps.passerelle || reglagesEnregistres.emailPasserelle;
        // Compte Gmail : la copie rangée dans « Messages envoyés » n'est effacée qu'après un délai,
        // le flux Power Automate devant d'abord lire ce même message. Un échec d'effacement
        // apparaîtra en avertissement dans « Dernier tour de rappels ».
        let copie = '';
        if (corps.copieGmail && corps.copieGmail.differee) {
          copie = ` La copie gardée par Gmail sera effacée dans environ ${corps.copieGmail.delaiHeures || 2} h, une fois le flux passé.`;
        }
        afficherResultatTest(resultat,
          `✓ Remis au serveur d'envoi — boîte-passerelle « ${passerelle} », objet (destinataire Teams) « ${destinataire} ». Vérifiez maintenant dans Teams.${copie}`,
          'reglages-email-ok');
      } else {
        resultat.textContent = corps.erreur || "Échec de l'envoi.";
        resultat.className = 'hint reglages-email-resultat reglages-email-echec';
      }
    } catch (e) {
      // Session expirée : déjà géré par fetchAvecAuth (écran de connexion réaffiché).
    }
  }

  // ---- Compte rendu du dernier tour de rappels (voir server/src/jobs/rappels.js) ----
  // La tâche construisait son `resultat.erreurs` depuis toujours sans que personne ne le lise, et
  // le serveur tourne sans fenêtre : un envoi cassé arrêtait les rappels en silence. Ces deux
  // fonctions sont la seule fenêtre sur cet état.

  // « 2 dus », pas « 2 dûs » : le circonflexe de « dû » ne sert qu'à le distinguer de l'article
  // « du » au masculin singulier, il disparaît au pluriel comme au féminin. Sorti en fonction pure
  // parce que la même phrase est écrite à deux endroits (l'encart et le bandeau de confirmation) —
  // deux copies finiraient par diverger, et c'est un texte que l'étude lit.
  function libelleRappelsTour(envoyes, dus) {
    const n = Number.isFinite(envoyes) && envoyes > 0 ? Math.floor(envoyes) : 0;
    const d = Number.isFinite(dus) && dus > 0 ? Math.floor(dus) : 0;
    const pluriel = n > 1 ? 's' : '';
    return `${n} rappel${pluriel} envoyé${pluriel} sur ${d} ${d > 1 ? 'dus' : 'dû'}`;
  }

  function renderDernierTourRappels(tour) {
    const zone = document.getElementById('reglages-dernier-tour');
    if (!zone) return;
    if (!tour || !tour.at) {
      zone.className = 'reglages-dernier-tour';
      zone.innerHTML = '<p class="hint" style="margin:0;">Aucun tour pour l\'instant.</p>';
      return;
    }
    const quand = new Date(tour.at);
    const quandTexte = isNaN(quand.getTime())
      ? tour.at
      : quand.toLocaleString('fr-FR', { dateStyle: 'long', timeStyle: 'short' });
    const origine = tour.declenche === 'manuel' ? 'déclenché à la main' : 'tour automatique';
    const erreurs = Array.isArray(tour.erreurs) ? tour.erreurs : [];
    // Un tour sans erreur ET sans envoi n'est pas un problème : la plupart des tours n'ont
    // simplement aucun rappel dû ce jour-là. C'est la présence d'erreurs qui fait basculer en
    // alerte, jamais un compteur à zéro.
    zone.className = 'reglages-dernier-tour ' + (erreurs.length ? 'dernier-tour-alerte' : 'dernier-tour-ok');
    let html = `<div class="dernier-tour-ligne">${icone(erreurs.length ? 'alert-triangle' : 'check')}`;
    html += `<span><strong>${escapeHtml(quandTexte)}</strong> — ${escapeHtml(origine)} · `;
    html += `${escapeHtml(libelleRappelsTour(tour.rappelsEnvoyes, tour.rappelsDus))}.</span></div>`;
    if (erreurs.length) {
      html += '<ul class="dernier-tour-erreurs">' + erreurs.map((e) => `<li>${escapeHtml(e)}</li>`).join('') + '</ul>';
    }
    // Avertissements (copie Gmail non effacée) : les rappels sont partis, l'encart ne passe donc
    // pas en alerte — mais une copie restée chez Google doit se voir.
    const avertissements = Array.isArray(tour.avertissements) ? tour.avertissements : [];
    if (avertissements.length) {
      html += '<ul class="dernier-tour-avertissements">' + avertissements.map((e) => `<li>${escapeHtml(e)}</li>`).join('') + '</ul>';
    }
    zone.innerHTML = html;
  }

  // ---- Agenda de l'office : lecture automatique du calendrier partagé de Sophie par EWS (voir
  // server/src/agendaWatch.js / agendaOffice.js), avec la connexion Exchange de la même rubrique.
  // Un rendez-vous « VTE - NOM DU DOSSIER » remplit le rendez-vous de signature ; une mention
  // « appel de fonds / projet envoyé » dans son lieu reporte la date sur le dossier, jamais si elle
  // est déjà renseignée. ----

  async function chargerReglagesAgenda() {
    try {
      const reponse = await fetchAvecAuth('/api/agenda');
      const corps = await reponse.json();
      if (Array.isArray(corps.absences)) absencesOffice = corps.absences;
      if (corps.agendaDuJour !== undefined) agendaDuJourOffice = corps.agendaDuJour || null;
      renderSourceAgenda(corps.source);
      renderDernierTourAgenda(corps.dernierTour, corps.source);
    } catch (e) {
      // Session expirée : déjà géré par fetchAvecAuth (écran de connexion réaffiché).
    }
  }

  // Le calendrier lu (adresse de la boîte, jamais un identifiant) ou ce qui manque pour le lire.
  function renderSourceAgenda(source) {
    const zone = document.getElementById('reglages-agenda-source');
    if (!zone) return;
    const s = source || {};
    const configuree = Boolean(s.configuree);
    zone.textContent = configuree
      ? (s.calendrier || 'Calendrier du compte de connexion')
      : 'Connexion à configurer ci-dessus';
    zone.className = 'reglages-valeur' + (configuree ? '' : ' reglages-valeur-vide');
    const bouton = document.getElementById('reglages-agenda-lancer');
    if (bouton && !bouton.dataset.enCours) bouton.disabled = !configuree;
  }

  function libelleActionAgenda(action) {
    if (action === 'rendezVousSignature') return 'Rendez-vous de signature';
    return action === 'projetEnvoye' ? 'Envoi projet' : 'Envoi appel de fonds';
  }

  function renderDernierTourAgenda(tour, source) {
    const zone = document.getElementById('reglages-agenda-dernier-tour');
    if (!zone) return;
    if (!tour || !tour.at) {
      zone.className = 'reglages-dernier-tour';
      zone.innerHTML = '<p class="hint" style="margin:0;">Aucune lecture pour l\'instant.</p>';
      return;
    }
    const quand = new Date(tour.at);
    const quandTexte = isNaN(quand.getTime())
      ? tour.at
      : quand.toLocaleString('fr-FR', { dateStyle: 'long', timeStyle: 'short' });
    const origine = tour.declenche === 'manuel' ? 'déclenché à la main' : 'tour automatique';
    const misAJour = Array.isArray(tour.misAJour) ? tour.misAJour : [];
    const sansCorrespondance = Array.isArray(tour.sansCorrespondance) ? tour.sansCorrespondance : [];
    // En erreur seulement si le calendrier n'a pas pu être lu du tout (identifiants, partage, réseau)
    // — aucune correspondance trouvée n'est pas un problème, c'est le cas normal la plupart du temps.
    const enErreur = !tour.ok && !!tour.erreur;
    zone.className = 'reglages-dernier-tour ' + (enErreur ? 'dernier-tour-alerte' : 'dernier-tour-ok');
    let html = `<div class="dernier-tour-ligne">${icone(enErreur ? 'alert-triangle' : 'check')}`;
    html += `<span><strong>${escapeHtml(quandTexte)}</strong> — ${escapeHtml(origine)} · `;
    html += enErreur
      ? escapeHtml(String(tour.erreur).replace(/\.\s*$/, ''))
      : `${tour.dossiersVerifies} dossier${tour.dossiersVerifies > 1 ? 's' : ''} vérifié${tour.dossiersVerifies > 1 ? 's' : ''}, ${misAJour.length} mis à jour`;
    html += '.</span></div>';
    // Disjoncteur (voir agendaWatch.js) : après un refus d'identifiants, plus aucun tour automatique
    // tant que le mot de passe n'a pas changé — sinon le compte de messagerie serait verrouillé.
    if (source && source.suspendue) {
      html += '<p class="hint" style="margin:6px 0 0;">Lecture automatique suspendue : corrigez le mot de passe ci-dessus, elle reprendra d\'elle-même.</p>';
    }
    // Dates butoir posées (ou retrouvées) dans l'agenda par le serveur à ce tour.
    const posees = Array.isArray(tour.echeancesPosees) ? tour.echeancesPosees : [];
    if (posees.length) {
      html += '<ul class="dernier-tour-erreurs" style="color:inherit;">' + posees.map((p) =>
        `<li>${escapeHtml(libelleDossierParNom(p.dossierNom || '', p.dossierId))} — ${p.type === 'ventebien' ? 'Vente préalable' : 'Obtention du prêt'} ${p.adoptee ? 'retrouvée dans' : 'posée dans'} l'agenda (${escapeHtml(formatDateFr(p.date))})</li>`
      ).join('') + '</ul>';
    }
    if (tour.ok && tour.erreurEcheances) {
      html += `<p class="hint" style="margin:6px 0 0;">Dates butoir non posées : ${escapeHtml(tour.erreurEcheances)}</p>`;
    }
    if (misAJour.length) {
      html += '<ul class="dernier-tour-erreurs" style="color:inherit;">' + misAJour.map((m) =>
        `<li>${escapeHtml(libelleDossierParNom(m.dossierNom || '', m.dossierId))} — ${escapeHtml(libelleActionAgenda(m.action))} (${escapeHtml(formatDateFr(m.dateIso))}${m.ancienneDate ? ', au lieu du ' + escapeHtml(formatDateFr(m.ancienneDate)) : ''})</li>`
      ).join('') + '</ul>';
    }
    // Un rendez-vous de l'agenda qui ne correspond pas à la date saisie à la main sur la fiche :
    // CLAIRE ne l'écrase pas, elle le signale.
    const ecartsRdv = (Array.isArray(tour.dejaRenseignes) ? tour.dejaRenseignes : [])
      .filter((m) => m.action === 'rendezVousSignature' && m.dateFiche);
    if (ecartsRdv.length) {
      html += '<ul class="dernier-tour-avertissements">' + ecartsRdv.map((m) =>
        `<li>${escapeHtml(libelleDossierParNom(m.dossierNom || '', m.dossierId))} — rendez-vous du ${escapeHtml(formatDateFr(m.dateIso))} dans l'agenda, ${escapeHtml(formatDateFr(m.dateFiche))} saisi sur la fiche : la fiche n'est pas modifiée.</li>`
      ).join('') + '</ul>';
    }
    if (sansCorrespondance.length) {
      html += '<ul class="dernier-tour-avertissements">' + sansCorrespondance.map((m) =>
        `<li>« ${escapeHtml(m.reference || '')} » — aucun dossier correspondant trouvé.</li>`
      ).join('') + '</ul>';
    }
    zone.innerHTML = html;
  }

  // Lance un VRAI tour de lecture tout de suite, sans attendre le prochain passage automatique.
  async function lancerTourAgenda() {
    const bouton = document.getElementById('reglages-agenda-lancer');
    const resultat = document.getElementById('reglages-agenda-resultat');
    if (bouton) { bouton.disabled = true; bouton.dataset.enCours = '1'; bouton.textContent = 'Lecture en cours…'; }
    try {
      const reponse = await fetchAvecAuth('/api/agenda/tester', { method: 'POST' });
      const corps = await reponse.json();
      if (resultat) {
        if (reponse.ok && corps.ok) {
          resultat.textContent = `${corps.evenementsLus || 0} rendez-vous lus, ${(corps.misAJour || []).length} dossier(s) mis à jour.`;
          resultat.className = 'hint';
        } else {
          resultat.textContent = corps.erreur || "La lecture de l'agenda a échoué.";
          resultat.className = 'hint reglages-email-resultat reglages-email-echec';
        }
      }
    } catch (e) {
      if (resultat) { resultat.textContent = 'Serveur injoignable.'; resultat.className = 'hint reglages-email-resultat reglages-email-echec'; }
    } finally {
      // Le compte rendu persisté (avec sa date et son origine) n'est disponible qu'en relisant
      // /api/agenda — la réponse de /api/agenda/tester ne porte que le résultat brut du tour.
      if (bouton) { delete bouton.dataset.enCours; bouton.disabled = false; bouton.textContent = 'Tester maintenant'; }
      await chargerReglagesAgenda();
    }
  }

  // ---- Connexion à l'agenda Outlook de l'office (voir server/src/exchange/ews.js) ----
  // CLAIRE enregistre les identifiants de messagerie (le mot de passe ne ressort jamais du serveur)
  // pour créer les rendez-vous de signature dans l'agenda Outlook depuis la fiche dossier.

  // État partagé, chargé au démarrage : la fiche dossier n'affiche le bouton « Créer dans l'agenda »
  // que si la connexion est activée ET configurée (identifiants enregistrés).
  let exchangeReglages = { actif: false, motDePasseEnregistre: false, email: '' };

  function exchangeAgendaPret() {
    return !!(exchangeReglages && exchangeReglages.actif && exchangeReglages.email && exchangeReglages.motDePasseEnregistre);
  }

  // Un Blob (ex. le .docx d'appel de fonds généré côté client) → base64 sans le préfixe data:.
  function blobVersBase64(blob) {
    return new Promise((resolve, reject) => {
      const lecteur = new FileReader();
      lecteur.onload = () => resolve(String(lecteur.result || '').replace(/^data:[^,]*,/, ''));
      lecteur.onerror = () => reject(lecteur.error || new Error('lecture du fichier'));
      lecteur.readAsDataURL(blob);
    });
  }

  async function chargerReglagesExchange() {
    try {
      const reponse = await fetchAvecAuth('/api/exchange/reglages');
      const corps = await reponse.json();
      exchangeReglages = corps || { actif: false };
      // Ne remplir les champs que si l'écran Réglages est présent (chargé aussi au démarrage, où il
      // ne l'est peut-être pas encore) et hors saisie en cours.
      const actif = document.getElementById('exchange-actif');
      const email = document.getElementById('exchange-email');
      const url = document.getElementById('exchange-url');
      const partage = document.getElementById('exchange-calendrier-partage');
      const note = document.getElementById('exchange-mdp-note');
      if (actif) actif.checked = !!corps.actif;
      if (email && document.activeElement !== email) email.value = corps.email || '';
      if (url && document.activeElement !== url) url.value = corps.url || '';
      if (partage && document.activeElement !== partage) partage.value = corps.calendrierPartage || '';
      const cats = corps.categoriesRdv || {};
      for (const cle of Object.keys(TYPES_RDV)) {
        const champ = document.getElementById(`exchange-cat-${cle}`);
        if (champ && document.activeElement !== champ) champ.value = cats[cle] || '';
      }
      chargerCategoriesAgendaVues();
      if (note) {
        definirInfoBulle(note, corps.motDePasseEnregistre
          ? 'Un mot de passe est déjà enregistré : laisser le champ vide le conserve. Un mot de passe erroné compte comme une tentative échouée — CLAIRE ne réessaie jamais toute seule.'
          : 'Un mot de passe erroné compte comme une tentative échouée. CLAIRE ne réessaie jamais toute seule.');
      }
    } catch (e) {
      // Session expirée : déjà géré par fetchAvecAuth.
    }
  }

  // Noms des catégories Outlook vus dans le flux de l'agenda : proposés dans les champs de couleur,
  // pour ne pas avoir à deviner le nom exact que porte chaque couleur dans la boîte de l'office.
  async function chargerCategoriesAgendaVues() {
    const liste = document.getElementById('exchange-categories-vues');
    const note = document.getElementById('exchange-categories-note');
    if (!liste) return;
    try {
      const corps = await (await fetchAvecAuth('/api/agenda')).json();
      const vues = Array.isArray(corps.categories) ? corps.categories : [];
      liste.innerHTML = vues.map((c) => `<option value="${escapeAttr(c)}"></option>`).join('');
      if (note) {
        definirInfoBulle(note, vues.length
          ? `Catégories vues dans l'agenda de l'office : ${vues.join(', ')}. Un nom que la boîte ne connaît pas s'affiche sans couleur.`
          : "Nom exact de la catégorie dans Outlook. Un nom que la boîte ne connaît pas s'affiche sans couleur.");
      }
    } catch (e) {
      // Sans agenda lu, les champs restent libres.
    }
  }

  async function enregistrerReglagesExchange() {
    const bouton = document.getElementById('exchange-enregistrer-btn');
    const resultat = document.getElementById('exchange-resultat');
    const actif = document.getElementById('exchange-actif');
    const champEmail = document.getElementById('exchange-email');
    const champMdp = document.getElementById('exchange-motdepasse');
    const champUrl = document.getElementById('exchange-url');
    const champPartage = document.getElementById('exchange-calendrier-partage');
    const corpsEnvoye = {
      actif: !!(actif && actif.checked),
      email: champEmail ? champEmail.value.trim() : '',
      url: champUrl ? champUrl.value.trim() : '',
      calendrierPartage: champPartage ? champPartage.value.trim() : '',
      categoriesRdv: Object.fromEntries(Object.keys(TYPES_RDV).map((cle) => {
        const champ = document.getElementById(`exchange-cat-${cle}`);
        return [cle, champ ? champ.value.trim() : ''];
      }))
    };
    // N'envoyer le mot de passe que s'il a été saisi : un champ vide conserve celui déjà enregistré.
    if (champMdp && champMdp.value) corpsEnvoye.motDePasse = champMdp.value;
    if (bouton) bouton.disabled = true;
    if (resultat) { resultat.textContent = ''; resultat.className = 'hint'; }
    try {
      const reponse = await fetchAvecAuth('/api/exchange/reglages', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(corpsEnvoye)
      });
      const corps = await reponse.json();
      exchangeReglages = corps || exchangeReglages;
      if (resultat) { resultat.textContent = 'Enregistré.'; resultat.className = 'hint'; }
      // Vider le champ mot de passe et rafraîchir la note « déjà enregistré ».
      if (champMdp) champMdp.value = '';
      chargerReglagesExchange();
      // Le calendrier lu et la suspension éventuelle de la lecture dépendent de ces identifiants.
      chargerReglagesAgenda();
      render();
    } catch (e) {
      if (resultat) { resultat.textContent = 'Serveur injoignable.'; resultat.className = 'hint reglages-email-resultat reglages-email-echec'; }
    } finally {
      if (bouton) bouton.disabled = false;
    }
  }

  // Teste la connexion (lecture seule). Envoie les identifiants saisis s'ils sont là, sinon le
  // serveur retombe sur ceux enregistrés — ce qui permet de retester une config stockée sans
  // retaper le mot de passe. Ne conserve jamais le mot de passe côté client.
  async function testerConnexionExchange() {
    const bouton = document.getElementById('exchange-tester-btn');
    const resultat = document.getElementById('exchange-resultat');
    const champEmail = document.getElementById('exchange-email');
    const champMdp = document.getElementById('exchange-motdepasse');
    const champUrl = document.getElementById('exchange-url');
    const corpsEnvoye = {};
    if (champEmail && champEmail.value.trim()) corpsEnvoye.email = champEmail.value.trim();
    if (champMdp && champMdp.value) corpsEnvoye.motDePasse = champMdp.value;
    if (champUrl && champUrl.value.trim()) corpsEnvoye.url = champUrl.value.trim();
    if (bouton) { bouton.disabled = true; bouton.textContent = 'Connexion en cours…'; }
    if (resultat) { resultat.textContent = ''; resultat.className = 'hint'; }
    try {
      const reponse = await fetchAvecAuth('/api/exchange/test', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(corpsEnvoye)
      });
      const corps = await reponse.json();
      if (resultat) {
        resultat.textContent = (corps.ok ? '✓ ' : '') + (corps.message || (corps.ok ? 'Connexion réussie.' : 'Échec de la connexion.'));
        resultat.className = corps.ok ? 'hint' : 'hint reglages-email-resultat reglages-email-echec';
      }
    } catch (e) {
      if (resultat) { resultat.textContent = 'Serveur injoignable.'; resultat.className = 'hint reglages-email-resultat reglages-email-echec'; }
    } finally {
      // Ne jamais garder le mot de passe en mémoire une fois le test fait.
      if (champMdp) champMdp.value = '';
      if (bouton) { bouton.disabled = false; bouton.textContent = 'Tester la connexion'; }
    }
  }

  // ---- Sauvegarde automatique de la base (voir server/src/sauvegarde.js) ----

  let etatSauvegarde = null;

  // Pure et testable : ce que l'écran dit de l'état des sauvegardes. `niveau` : 'ok', 'alerte'
  // (en retard ou échec — c'est lui qui fait aussi apparaître le bandeau du Tableau de bord), ou
  // 'neutre' (fonction sans objet, ou première sauvegarde pas encore faite). `emplacement` dit où
  // partent les copies, et signale un dossier local qui ne protège pas d'une panne du disque.
  function messageEtatSauvegarde(etat) {
    if (!etat || !etat.actif) return { niveau: 'neutre', titre: 'Sauvegarde sans objet ici (base en mémoire).', detail: '', emplacement: '' };
    const dest = etat.destination || {};
    const emplacement = dest.locale
      ? `Copies rangées sur ce poste (${dest.dossier}) : choisissez un dossier du NAS ci-dessous.`
      : `Copies rangées dans ${dest.dossier}.`;
    const t = etat.derniereTentative;
    const jours = etat.joursDepuisDerniere;
    const seuil = etat.joursAvantAlerte || 3;
    if (!etat.derniereReussie) {
      if (t && !t.ok) return { niveau: 'alerte', titre: 'La sauvegarde n\'a jamais réussi.', detail: t.erreur || '', emplacement };
      return { niveau: 'neutre', titre: 'Première sauvegarde dans quelques minutes (ou « Sauvegarder maintenant »).', detail: '', emplacement };
    }
    const quand = new Date(etat.derniereReussie);
    const quandTexte = isNaN(quand.getTime()) ? etat.derniereReussie : quand.toLocaleString('fr-FR', { dateStyle: 'long', timeStyle: 'short' });
    const nb = t && t.ok && Number.isFinite(t.nbDossiers) ? ` — ${t.nbDossiers} dossier${t.nbDossiers > 1 ? 's' : ''}` : '';
    if (t && !t.ok) {
      return { niveau: 'alerte', titre: `Dernière sauvegarde réussie : ${quandTexte}. La suivante a échoué.`, detail: t.erreur || '', emplacement };
    }
    if (Number.isFinite(jours) && jours >= seuil) {
      return { niveau: 'alerte', titre: `Aucune sauvegarde depuis ${jours} jours (dernière : ${quandTexte}).`, detail: 'Le serveur était-il arrêté ?', emplacement };
    }
    return { niveau: 'ok', titre: `Dernière sauvegarde : ${quandTexte}${nb}.`, detail: '', emplacement };
  }

  function renderEtatSauvegarde() {
    const zone = document.getElementById('reglages-sauvegarde-etat');
    if (zone && etatSauvegarde) {
      const m = messageEtatSauvegarde(etatSauvegarde);
      zone.className = 'reglages-dernier-tour' + (m.niveau === 'ok' ? ' dernier-tour-ok' : m.niveau === 'alerte' ? ' dernier-tour-alerte' : '');
      zone.innerHTML = `<div class="dernier-tour-ligne">${icone(m.niveau === 'alerte' ? 'alert-triangle' : m.niveau === 'ok' ? 'check' : 'info')}<span><strong>${escapeHtml(m.titre)}</strong>${m.detail ? ' ' + escapeHtml(m.detail) : ''}</span></div>`
        + (m.emplacement ? `<p class="hint" style="margin:6px 0 0;">${escapeHtml(m.emplacement)}</p>` : '');
    }
    const champ = document.getElementById('reglages-sauvegarde-dossier');
    if (champ && etatSauvegarde && document.activeElement !== champ) champ.value = etatSauvegarde.dossier || '';
    renderAlerteSauvegardeDashboard();
  }

  function renderAlerteSauvegardeDashboard() {
    const zone = document.getElementById('dash-alerte-sauvegarde');
    if (!zone) return;
    const m = etatSauvegarde ? messageEtatSauvegarde(etatSauvegarde) : null;
    if (!m || m.niveau !== 'alerte') { zone.style.display = 'none'; zone.innerHTML = ''; return; }
    zone.style.display = '';
    zone.innerHTML = `${icone('alert-triangle')}<span><strong>Sauvegarde de la base :</strong> ${escapeHtml(m.titre)}${m.detail ? ' ' + escapeHtml(m.detail) : ''}</span>
      <button type="button" class="action-rapide" onclick="definirOnglet('reglages'); definirSousOngletReglages('systeme')">Voir les Réglages</button>`;
  }

  async function chargerEtatSauvegarde() {
    try {
      const reponse = await fetchAvecAuth('/api/sauvegarde');
      if (!reponse.ok) return;
      etatSauvegarde = await reponse.json();
      renderEtatSauvegarde();
    } catch (e) {
      // Serveur injoignable ou session expirée : déjà signalés ailleurs.
    }
  }

  async function enregistrerDossierSauvegarde() {
    const champ = document.getElementById('reglages-sauvegarde-dossier');
    const resultat = document.getElementById('reglages-sauvegarde-resultat');
    try {
      const reponse = await fetchAvecAuth('/api/sauvegarde', {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dossier: champ ? champ.value : '' })
      });
      const corps = await reponse.json();
      if (!reponse.ok) { if (resultat) resultat.textContent = corps.erreur || 'Enregistrement impossible.'; return; }
      etatSauvegarde = corps;
      renderEtatSauvegarde();
      if (resultat) resultat.textContent = 'Enregistré. Cliquez « Sauvegarder maintenant » pour vérifier que ce dossier est accessible.';
    } catch (e) {
      if (resultat) resultat.textContent = 'Serveur injoignable.';
    }
  }

  async function lancerSauvegarde() {
    const bouton = document.getElementById('reglages-sauvegarde-lancer');
    const resultat = document.getElementById('reglages-sauvegarde-resultat');
    if (bouton) { bouton.disabled = true; bouton.textContent = 'Sauvegarde en cours…'; }
    if (resultat) resultat.textContent = '';
    try {
      const reponse = await fetchAvecAuth('/api/sauvegarde/lancer', { method: 'POST' });
      const corps = await reponse.json();
      if (!reponse.ok) { if (resultat) resultat.textContent = corps.erreur || 'Sauvegarde impossible.'; return; }
      etatSauvegarde = corps;
      renderEtatSauvegarde();
      const t = corps.derniereTentative;
      if (resultat) resultat.textContent = t && t.ok ? `✓ ${t.fichier} écrit.` : `Échec : ${(t && t.erreur) || 'erreur inconnue'}`;
    } catch (e) {
      if (resultat) resultat.textContent = 'Serveur injoignable.';
    } finally {
      if (bouton) { bouton.disabled = false; bouton.textContent = 'Sauvegarder maintenant'; }
    }
  }

  // ===== Mise à jour de CLAIRE en un clic (server/src/miseAJour.js) =====
  // Rien ne s'installe sans le clic « Mettre à jour maintenant » : « Vérifier » ne fait que
  // comparer le build installé à la dernière publication GitHub.
  let etatMiseAJour = null;
  let verificationMiseAJour = null;

  // Texte de l'encart, pur et testable. `etat` : GET /api/mise-a-jour ; `verif` : réponse de
  // « Vérifier » (ou null tant qu'on n'a pas vérifié).
  function messageMiseAJour(etat, verif) {
    const installe = etat && etat.installe && Number.isInteger(etat.installe.build) ? etat.installe.build : null;
    const libInstalle = installe ? `build ${installe}` : 'version inconnue';
    if (!etat) return { niveau: 'neutre', titre: 'État de la mise à jour indisponible.', detail: '', installable: false };
    if (!etat.modeExe) {
      return { niveau: 'neutre', titre: 'Serveur en mode développement : la mise à jour ne concerne que CLAIRE-serveur.exe.', detail: '', installable: false };
    }
    if (!verif) return { niveau: 'neutre', titre: `Version installée : ${libInstalle}.`, detail: 'Cliquez « Vérifier » pour voir s\'il existe une version plus récente.', installable: false };
    if (verif.erreur) return { niveau: 'alerte', titre: 'Vérification impossible.', detail: verif.erreur, installable: false };
    const dispo = verif.disponible || {};
    const quand = dispo.publieLe ? ` (publiée le ${formatDateFr(String(dispo.publieLe).slice(0, 10))})` : '';
    if (verif.etat === 'a-jour') return { niveau: 'ok', titre: `CLAIRE est à jour (${libInstalle}).`, detail: '', installable: false };
    if (verif.etat === 'disponible') {
      return { niveau: 'alerte', titre: `Nouvelle version disponible : build ${dispo.build}${quand}.`, detail: `Installée : ${libInstalle}.`, installable: true };
    }
    return {
      niveau: 'neutre',
      titre: `Dernière version publiée : build ${dispo.build || '?'}${quand}.`,
      detail: `Installée : ${libInstalle} — impossible de dire si elle est plus récente. L'installer reste possible.`,
      installable: true
    };
  }

  function renderMiseAJour() {
    const zone = document.getElementById('reglages-maj-etat');
    if (!zone) return;
    const m = messageMiseAJour(etatMiseAJour, verificationMiseAJour);
    zone.className = 'reglages-dernier-tour' + (m.niveau === 'ok' ? ' dernier-tour-ok' : m.niveau === 'alerte' ? ' dernier-tour-alerte' : '');
    zone.innerHTML = `<div class="dernier-tour-ligne">${icone(m.niveau === 'ok' ? 'check' : m.niveau === 'alerte' ? 'alert-triangle' : 'info')}<span><strong>${escapeHtml(m.titre)}</strong>${m.detail ? ' ' + escapeHtml(m.detail) : ''}</span></div>`;
    const installer = document.getElementById('reglages-maj-installer');
    if (installer) installer.style.display = m.installable ? '' : 'none';
    const verifier = document.getElementById('reglages-maj-verifier');
    if (verifier) verifier.disabled = !(etatMiseAJour && etatMiseAJour.modeExe);
    const champ = document.getElementById('reglages-maj-jeton');
    if (champ && etatMiseAJour) {
      champ.placeholder = etatMiseAJour.jetonEnregistre ? 'Déjà enregistré — laisser vide pour le conserver' : 'github_pat_…';
    }
  }

  async function chargerMiseAJour() {
    try {
      const reponse = await fetchAvecAuth('/api/mise-a-jour');
      if (!reponse.ok) return;
      etatMiseAJour = await reponse.json();
      renderMiseAJour();
    } catch (e) {
      // Serveur injoignable ou session expirée : déjà signalés ailleurs.
    }
  }

  async function verifierMiseAJour() {
    const bouton = document.getElementById('reglages-maj-verifier');
    if (bouton) { bouton.disabled = true; bouton.textContent = 'Vérification…'; }
    try {
      const reponse = await fetchAvecAuth('/api/mise-a-jour/verifier', { method: 'POST' });
      const corps = await reponse.json();
      etatMiseAJour = Object.assign({}, etatMiseAJour, corps);
      verificationMiseAJour = corps;
    } catch (e) {
      verificationMiseAJour = { erreur: 'Serveur injoignable.' };
    } finally {
      if (bouton) bouton.textContent = 'Vérifier';
      renderMiseAJour();
    }
  }

  // ===== Rapport technique (server/src/rapportTechnique.js) =====
  // Déposé sur GitHub à 12 h et 17 h les jours ouvrés, anonymisé par le serveur ; « Voir ce qui
  // part » montre le texte exact avant tout envoi.
  let etatRapportTechnique = null;

  // Pure et testable : l'encart d'état. `etat` : GET /api/rapport-technique.
  function messageRapportTechnique(etat) {
    if (!etat) return { niveau: 'neutre', titre: 'État du rapport technique indisponible.', detail: '' };
    if (!etat.actif) return { niveau: 'neutre', titre: 'Rapport technique désactivé.', detail: 'Rien n’est envoyé sur GitHub.' };
    if (!etat.jetonEnregistre) return { niveau: 'alerte', titre: 'Aucun jeton GitHub enregistré.', detail: 'Enregistrez-en un ci-dessus, avec le droit « Issues : Read and write ».' };
    const envoi = etat.dernierEnvoi;
    const quand = (iso) => {
      const d = new Date(iso);
      return isNaN(d) ? '' : `${formatDateFr(isoLocalDepuisDate(d))} à ${String(d.getHours()).padStart(2, '0')} h ${String(d.getMinutes()).padStart(2, '0')}`;
    };
    if (etat.derniereErreur) {
      return { niveau: 'alerte', titre: 'Le dernier rapport n’est pas parti.', detail: etat.derniereErreur + (envoi ? ` Dernier envoi réussi : ${quand(envoi.at)}.` : '') };
    }
    if (envoi) {
      return { niveau: 'ok', titre: `Dernier rapport envoyé le ${quand(envoi.at)}${envoi.numero ? ` (n° ${envoi.numero})` : ''}.`, detail: envoi.calme ? 'Rien à signaler.' : `${envoi.points} point(s) à examiner.`, url: envoi.url || '' };
    }
    return { niveau: 'neutre', titre: 'Aucun rapport envoyé pour l’instant.', detail: 'Prochain envoi à 12 h ou 17 h (jours ouvrés).' };
  }

  function renderRapportTechnique() {
    const zone = document.getElementById('reglages-rapport-etat');
    if (!zone) return;
    const m = messageRapportTechnique(etatRapportTechnique);
    zone.className = 'reglages-dernier-tour' + (m.niveau === 'ok' ? ' dernier-tour-ok' : m.niveau === 'alerte' ? ' dernier-tour-alerte' : '');
    zone.innerHTML = `<div class="dernier-tour-ligne">${icone(m.niveau === 'ok' ? 'check' : m.niveau === 'alerte' ? 'alert-triangle' : 'info')}<span><strong>${escapeHtml(m.titre)}</strong>${m.detail ? ' ' + escapeHtml(m.detail) : ''}${m.url ? ` <a href="${escapeAttr(m.url)}" target="_blank" rel="noopener">Ouvrir sur GitHub</a>` : ''}</span></div>`;
    const actif = document.getElementById('reglages-rapport-actif');
    if (actif && etatRapportTechnique) actif.checked = !!etatRapportTechnique.actif;
  }

  async function chargerRapportTechnique() {
    try {
      const reponse = await fetchAvecAuth('/api/rapport-technique');
      if (!reponse.ok) return;
      etatRapportTechnique = await reponse.json();
      renderRapportTechnique();
    } catch (e) { /* serveur injoignable : déjà signalé ailleurs */ }
  }

  async function basculerRapportTechnique(actif) {
    try {
      const reponse = await fetchAvecAuth('/api/rapport-technique', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ actif: !!actif }) });
      if (reponse.ok) etatRapportTechnique = await reponse.json();
    } catch (e) { /* on réaffiche l'état connu */ }
    renderRapportTechnique();
  }

  async function afficherApercuRapportTechnique() {
    const zone = document.getElementById('reglages-rapport-apercu');
    if (!zone) return;
    if (zone.style.display !== 'none') { zone.style.display = 'none'; return; }
    zone.style.display = '';
    zone.textContent = 'Préparation de l’aperçu…';
    try {
      const reponse = await fetchAvecAuth('/api/rapport-technique/apercu');
      const corps = await reponse.json();
      zone.textContent = reponse.ok ? `${corps.titre}\n\n${corps.corps}` : (corps.erreur || 'Aperçu impossible.');
    } catch (e) {
      zone.textContent = 'Serveur injoignable.';
    }
  }

  async function envoyerRapportTechnique() {
    const bouton = document.getElementById('reglages-rapport-envoyer');
    if (bouton) { bouton.disabled = true; bouton.textContent = 'Envoi…'; }
    try {
      const reponse = await fetchAvecAuth('/api/rapport-technique/envoyer', { method: 'POST' });
      const corps = await reponse.json();
      if (corps && typeof corps.actif === 'boolean') etatRapportTechnique = corps;
      else if (corps && corps.erreur) etatRapportTechnique = Object.assign({}, etatRapportTechnique, { derniereErreur: corps.erreur });
    } catch (e) {
      etatRapportTechnique = Object.assign({}, etatRapportTechnique, { derniereErreur: 'Serveur injoignable.' });
    } finally {
      if (bouton) { bouton.disabled = false; bouton.textContent = 'Envoyer maintenant'; }
      renderRapportTechnique();
    }
  }

  async function enregistrerJetonMiseAJour() {
    const champ = document.getElementById('reglages-maj-jeton');
    const resultat = document.getElementById('reglages-maj-jeton-resultat');
    const valeur = champ ? champ.value.trim() : '';
    if (!valeur) { if (resultat) resultat.textContent = 'Collez le jeton dans le champ avant d\'enregistrer.'; return; }
    try {
      const reponse = await fetchAvecAuth('/api/mise-a-jour/jeton', {
        method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ jetonGithub: valeur })
      });
      const corps = await reponse.json();
      if (!reponse.ok) { if (resultat) resultat.textContent = corps.erreur || 'Enregistrement impossible.'; return; }
      etatMiseAJour = corps;
      if (champ) champ.value = '';
      if (resultat) resultat.textContent = 'Jeton enregistré. Cliquez « Vérifier » pour contrôler qu\'il donne bien accès au dépôt.';
      renderMiseAJour();
    } catch (e) {
      if (resultat) resultat.textContent = 'Serveur injoignable.';
    }
  }

  function afficherProgressionMiseAJour(titre, detail) {
    const overlay = document.getElementById('maj-overlay');
    if (!overlay) return;
    document.getElementById('maj-overlay-titre').textContent = titre;
    document.getElementById('maj-overlay-detail').textContent = detail || '';
    overlay.style.display = 'flex';
  }

  function demanderInstallationMiseAJour() {
    const m = messageMiseAJour(etatMiseAJour, verificationMiseAJour);
    if (!m.installable) return;
    const dispo = (verificationMiseAJour && verificationMiseAJour.disponible) || {};
    demanderConfirmation(
      `Installer CLAIRE build ${dispo.build || '?'} ? La base est sauvegardée d'abord, puis le serveur redémarre : CLAIRE sera indisponible environ une minute sur tous les postes, et il faudra se reconnecter.`,
      installerMiseAJour,
      { bouton: 'Mettre à jour', ton: 'valider' }
    );
  }

  // Après la réponse du serveur, il s'arrête et relance la nouvelle version : on attend qu'il ait
  // disparu PUIS qu'il réponde de nouveau, et on recharge la page (le nouveau script.js vient avec).
  async function installerMiseAJour() {
    afficherProgressionMiseAJour('Mise à jour en cours…', 'Sauvegarde de la base puis téléchargement de la nouvelle version (environ 90 Mo). Ne fermez pas cette fenêtre.');
    let corps;
    try {
      const reponse = await fetchAvecAuth('/api/mise-a-jour/installer', { method: 'POST' });
      corps = await reponse.json();
      if (!reponse.ok) throw new Error(corps.erreur || 'Mise à jour impossible.');
    } catch (e) {
      document.getElementById('maj-overlay').style.display = 'none';
      verificationMiseAJour = { erreur: e.message };
      renderMiseAJour();
      afficherInfoAction('Mise à jour non installée', `${e.message} CLAIRE continue de fonctionner avec la version actuelle.`);
      return;
    }
    afficherProgressionMiseAJour('Redémarrage de CLAIRE…', `Build ${corps.build} installé. La page se rechargera d'elle-même dès que le serveur sera revenu.`);
    const debut = Date.now();
    let disparu = false;
    const attendre = (ms) => new Promise((ok) => setTimeout(ok, ms));
    while (Date.now() - debut < 3 * 60 * 1000) {
      await attendre(2000);
      let repond = false;
      try { repond = (await fetch('/api/health', { cache: 'no-store' })).ok; } catch (e) { repond = false; }
      if (!repond) disparu = true;
      if (repond && (disparu || Date.now() - debut > 20000)) { location.reload(); return; }
    }
    afficherProgressionMiseAJour(
      'Le serveur ne répond pas.',
      `Sur le poste serveur, vérifiez le fichier erreur-demarrage.txt à côté de CLAIRE-serveur.exe. Pour revenir à la version précédente : lancez Arreter-CLAIRE.bat, supprimez CLAIRE-serveur.exe, renommez ${corps.ancien || 'CLAIRE-serveur.ancien.exe'} en CLAIRE-serveur.exe, puis relancez-le.`
    );
  }

  async function chargerDernierTourRappels() {
    try {
      const reponse = await fetchAvecAuth('/api/reglages/dernier-tour');
      const corps = await reponse.json();
      renderDernierTourRappels(corps.dernierTour);
    } catch (e) {
      // Session expirée : déjà géré par fetchAvecAuth (écran de connexion réaffiché).
    }
  }

  // Lance un VRAI tour tout de suite. Le bouton est désactivé pendant l'appel : un tour qui envoie
  // plusieurs rappels sur un serveur SMTP lent peut durer quelques secondes, et deux tours lancés
  // en parallèle se disputeraient reminder_log.
  async function lancerTourRappels() {
    const bouton = document.getElementById('reglages-lancer-tour');
    const zone = document.getElementById('reglages-etat');
    if (bouton) { bouton.disabled = true; bouton.textContent = 'Tour en cours…'; }
    try {
      const reponse = await fetchAvecAuth('/api/reglages/lancer-rappels', { method: 'POST' });
      const corps = await reponse.json();
      zone.style.display = 'flex';
      if (reponse.ok && corps.ok) {
        renderDernierTourRappels(corps.dernierTour);
        zone.className = 'analyse-ia-dispo dispo-ok';
        zone.innerHTML = `${icone('check')}Tour terminé : ${escapeHtml(libelleRappelsTour(corps.rappelsEnvoyes, corps.rappelsDus))}. Vérifiez dans Teams.`;
      } else {
        zone.className = 'analyse-ia-dispo dispo-off';
        zone.innerHTML = `${icone('alert-triangle')}${escapeHtml(corps.erreur || 'Le tour de rappels a échoué.')}`;
      }
    } catch (e) {
      // Session expirée : déjà géré par fetchAvecAuth.
    } finally {
      if (bouton) { bouton.disabled = false; bouton.textContent = 'Lancer un tour maintenant'; }
    }
  }

  // ==== CLASSEUR DES SCANS DU COPIEUR (30/09) ====
  // Tous les scans du copieur arrivent dans UN dossier « Scan » à la racine du NAS. CLAIRE les lit
  // (pdf.js, OCR tesseract.js pour un scan sans texte), reconnaît le dossier client et le type de
  // pièce, puis demande au serveur de ranger une COPIE dans la bonne rubrique du dossier client
  // (l'original part dans l'archive du dossier Scan, voir server/src/scans.js).
  //
  // Deux leçons déjà payées, appliquées ici :
  //  - le type de pièce se lit sur le HAUT DE LA PREMIÈRE PAGE seulement (comme le titre d'une offre
  //    de prêt) : un compromis ou un état daté cite toutes les autres pièces, compter des mots-clés
  //    sur tout le document les mélange (essai du script Python fourni : 5 états datés sur 5 pris
  //    pour un règlement de copropriété) ;
  //  - la copie porte un nom que la checklist de CLAIRE reconnaît (le libellé même de la pièce), pour
  //    que la pièce passe « reçue » au parcours suivant du NAS, sans rien à cocher.
  // Tout ce bloc jusqu'à « fin du socle pur des scans » est pur (testé dans tests/scans.test.js).

  // Texte comparable : minuscules, sans accents, apostrophes droites, espaces simples. Pure.
  function texteNormaliseScan(texte) {
    return String(texte || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
      .replace(/[’`´]/g, "'").replace(/\s+/g, ' ').trim();
  }
  // Même texte réduit aux lettres et chiffres, bordé d'espaces : un mot entier se teste par
  // `includes(' mot ')`, sans les pièges de \b sur les lettres accentuées. Pure.
  function texteMotsScan(texte) {
    return ' ' + texteNormaliseScan(texte).replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
  }

  // Longueur du « haut de la première page » où se lit le type de pièce : assez pour passer
  // l'en-tête d'un courrier (« Objet : … ») ou le préambule d'un acte (« L'AN DEUX MILLE… Maître…
  // a reçu le présent acte… PROMESSE UNILATÉRALE DE VENTE »), pas assez pour atteindre le corps.
  var LONGUEUR_ENTETE_SCAN = 1500;

  // Types de pièces reconnus sur le haut de la première page, DANS L'ORDRE (le premier qui
  // correspond l'emporte : les plus spécifiques d'abord). `piece` = clé de la checklist quand la
  // copie doit la faire passer « reçue » (son libellé sert alors de nom de fichier) ; `rubriques`
  // = rubriques du dossier client essayées dans l'ordre (voir RUBRIQUES_SCANS côté serveur), la
  // racine du dossier à défaut ; `parPartie` = la rubrique dépend de la partie nommée (vendeur ou
  // acquéreur). Motifs écrits sur des en-têtes réels (voir tests/scans.test.js) ; « à confirmer
  // par l'étude » pour la rubrique de chaque type (arborescence reçue le 19/09, usage non précisé).
  var TYPES_SCAN = [
    { cle: 'preEtatDate', label: 'Pré-état daté', motif: /pre[- ]?etat date/, rubriques: ['preEtatDate', 'copro'] },
    { cle: 'etatDate', label: 'État daté', piece: 'etatDate', motif: /etat date|immeuble sis a .{0,300}coproprietaire cedant/, rubriques: ['etatDate', 'copro'] },
    { cle: 'article20', label: 'Article 20-II', piece: 'article20', motif: /certificat (de l'|prevu (a|par) l')?article 20|article 20[ -]*(ii|2) /, rubriques: ['etatDate', 'copro'] },
    // Nommé « Compromis signé » : c'est le mot que choisirAvantContratNas cherche dans le nom d'un
    // fichier du dossier quand l'avant-contrat n'a pas été importé par CLAIRE (« promesse » aussi).
    { cle: 'promesse', label: 'Promesse de vente signée', motif: /promesse (unilaterale |synallagmatique )?de vente|promesse d'achat/, rubriques: ['sru'] },
    { cle: 'avantContrat', label: 'Compromis signé', motif: /compromis de vente|vente .{0,80}sous conditions? suspensives?|entre les soussignes|information prealable .{0,200}avant[- ]contrat/, rubriques: ['sru'] },
    { cle: 'certificatUrbanisme', label: "Certificat d'urbanisme", piece: 'certificatUrbanisme', motif: /certificat d'urbanisme|note de renseignements d'urbanisme/, rubriques: ['aae'] },
    { cle: 'alignementNumerotage', label: "Certificat d'alignement et de numérotage", piece: 'certificatAlignement', piecesAussi: ['certificatNumerotage'], motif: /alignement.{0,80}numerotage|numerotage.{0,80}alignement/, rubriques: ['aae'] },
    { cle: 'certificatAlignement', label: "Certificat d'alignement", piece: 'certificatAlignement', motif: /alignement/, rubriques: ['aae'] },
    { cle: 'certificatNumerotage', label: 'Certificat de numérotage', piece: 'certificatNumerotage', motif: /numerotage/, rubriques: ['aae'] },
    { cle: 'renonciationPreemption', label: 'Renonciation au droit de préemption', piece: 'renonciationPreemption', motif: /preemption|intention d'aliener/, rubriques: ['aae'] },
    { cle: 'reponseAssainissement', label: 'Courrier réponse assainissement', piece: 'reponseAssainissement', motif: /assainissement|spanc/, rubriques: ['aae'] },
    { cle: 'erp', label: 'ERP (état des risques et pollution)', piece: 'erp', motif: /etat des risques/, rubriques: ['environnement', 'diagnostics', 'aae'] },
    { cle: 'diagnosticsTechniques', label: 'Diagnostics techniques', piece: 'diagnosticsTechniques', motif: /dossier de diagnostics? techniques?|diagnostic de performance energetique|constat de risque d'exposition au plomb|etat de l'installation interieure|presence de termites|reperage (des materiaux .{0,60})?amiante|rapport de (mission de )?(diagnostic|reperage)|attestation de (superficie|surface)|loi carrez/, rubriques: ['diagnostics', 'aae'] },
    { cle: 'etudeSol', label: 'Étude de sol', piece: 'etudeSol', motif: /etude (geotechnique|de sol)/, rubriques: ['construction', 'environnement', 'aae'] },
    { cle: 'offrePret', label: 'Offre de prêt', motif: /offre de (pret|credit)|offre prealable de credit|contrat de (pret|credit) immobilier/, rubriques: ['pret', 'comptabilite'] },
    { cle: 'decompte', label: 'Décompte', motif: /decompte (previsionnel|financier|definitif|acquereur|vendeur)/, rubriques: ['comptabilite'] },
    { cle: 'convocation', label: 'Convocation', motif: /confirmer le rendez-vous|confirme le rendez-vous|convocation/, rubriques: [] },
    { cle: 'etatHypothecaire', label: 'État hypothécaire', motif: /etat hypothecaire|renseignements sommaires|etat (hors|sur) formalites?|demande de renseignements/, rubriques: ['hypotheque'] },
    { cle: 'avisTaxeFonciere', label: 'Avis de taxe foncière', piece: 'avisTaxeFonciere', motif: /avis_tf|montant de vos taxes foncieres|avis d'impots? locaux|avis d'(impot|imposition).{0,80}foncier|taxes? foncieres? \d{4}/, rubriques: ['comptabilite'] },
    { cle: 'appelCharges', label: 'Appel de charges', motif: /appel (trimestriel|de fonds|de charges|provisionnel|de provisions?)/, exige: /coproprietaire|syndic|lot/, rubriques: ['copro'] },
    { cle: 'pvAssemblee', label: "Procès-verbal d'assemblée générale", motif: /proces[- ]verbal .{0,60}assemblee generale/, rubriques: ['copro'] },
    { cle: 'reglementCopro', label: 'Règlement de copropriété', motif: /reglement de copropriete|etat descriptif de division/, rubriques: ['copro'] },
    { cle: 'ramonage', label: 'Ramonage (attestation ou facture)', piece: 'ramonage', motif: /ramonage/, rubriques: ['aae'] },
    { cle: 'entretienChaudiere', label: 'Entretien de la chaudière', piece: 'entretienChaudiere', motif: /entretien .{0,40}chaudiere|chaudiere .{0,40}entretien/, rubriques: ['aae'] },
    { cle: 'entretienPac', label: 'Entretien de la pompe à chaleur (PAC)', piece: 'entretienPac', motif: /pompe a chaleur/, rubriques: ['aae'] },
    { cle: 'vidangeFosse', label: 'Vidange de la fosse septique', piece: 'vidangeFosse', motif: /vidange|fosse (septique|toutes eaux)/, rubriques: ['aae'] },
    { cle: 'garantieDecennale', label: 'Garantie décennale', piece: 'garantieDecennale', motif: /decennale/, rubriques: ['travaux', 'aae'] },
    { cle: 'dommageOuvrage', label: 'Assurance dommage-ouvrage', piece: 'dommageOuvrage', motif: /dommages?[- ]ouvrage/, rubriques: ['travaux', 'aae'] },
    { cle: 'titrePropriete', label: 'Titre de propriété', piece: 'titrePropriete', motif: /attestation (immobiliere|de propriete)|titre de propriete/, rubriques: ['titre'] },
    { cle: 'identite', label: "Pièce d'identité", motif: /carte nationale d'identite|passeport|titre de sejour|permis de conduire|identity card/, rubriques: [], parPartie: true },
    { cle: 'etatCivil', label: 'État civil', motif: /livret de famille|acte de (naissance|mariage|deces)|pacte civil de solidarite|contrat de mariage|jugement de divorce/, rubriques: [], parPartie: true },
    { cle: 'ribCopro', label: 'RIB de la copropriété', piece: 'ribCopro', motif: /releve d'identite bancaire|\biban\b/, exige: /syndic|copropriete/, rubriques: ['copro'] },
    { cle: 'rib', label: 'RIB', motif: /releve d'identite bancaire|\biban\b/, rubriques: [], parPartie: true },
    { cle: 'releveCompte', label: 'Relevé de compte client', motif: /releve de compte client/, rubriques: ['comptabilite'] },
    { cle: 'facture', label: 'Facture', motif: /\bfacture\b/, rubriques: ['travaux', 'aae'], faible: true }
  ];

  // Haut de la première page, normalisé. `texte` = texte de la page 1 (lignes jointes). Pure.
  function enTeteScan(textePage1) {
    return texteNormaliseScan(textePage1).slice(0, LONGUEUR_ENTETE_SCAN);
  }

  // Un acte notarié s'ouvre sur « L'AN DEUX MILLE… » : c'est un avant-contrat s'il le dit
  // (« PROMESSE UNILATÉRALE DE VENTE », « COMPROMIS »), sinon un acte de vente reçu, c'est-à-dire
  // le titre de propriété du vendeur. Son préambule nomme les parties et leur état civil (« contrat
  // de mariage », « acte de naissance ») : les autres types n'y sont donc pas cherchés.
  var RE_OUVERTURE_ACTE_SCAN = /^.{0,200}l'an (deux )?mil/;
  var RE_ACTE_DE_VENTE_SCAN = /\bvente\b|attestation (immobiliere|de propriete)/;

  // Type de pièce d'après le haut de la première page, ou null. Parmi les types qui y figurent,
  // celui mentionné LE PLUS HAUT l'emporte : c'est le titre ou l'objet ; ce qu'un courrier ou un
  // décompte cite plus bas (« prorata de taxe foncière », « la promesse de vente ») ne décide
  // rien. Un type `faible` (facture) ne compte que si aucun autre ne figure. Pure.
  function typePieceScan(enTete) {
    const t = String(enTete || '');
    if (!t) return null;
    if (RE_OUVERTURE_ACTE_SCAN.test(t)) {
      const avant = TYPES_SCAN.find(ty => (ty.cle === 'promesse' || ty.cle === 'avantContrat') && ty.motif.test(t));
      if (avant) return avant;
      return RE_ACTE_DE_VENTE_SCAN.test(t) ? TYPES_SCAN.find(ty => ty.cle === 'titrePropriete') : null;
    }
    let meilleur = null;
    let position = Infinity;
    for (const faible of [false, true]) {
      for (const ty of TYPES_SCAN) {
        if (!!ty.faible !== faible || (ty.exige && !ty.exige.test(t))) continue;
        const m = ty.motif.exec(t);
        if (m && m.index < position) { meilleur = ty; position = m.index; }
      }
      if (meilleur) return meilleur;
    }
    return null;
  }

  // Mots d'un nom de personne qui permettent de la reconnaître : trois lettres au moins, hors
  // civilités et particules. Pure.
  var MOTS_VIDES_NOM_SCAN = new Set(['monsieur', 'madame', 'mademoiselle', 'mme', 'mlle', 'epoux', 'epouse', 'veuve', 'nee', 'les', 'des', 'del', 'societe', 'sci', 'sarl', 'sas', 'selarl', 'civile', 'immobiliere', 'vendeur', 'vendeurs', 'acquereur', 'acquereurs']);
  function motsNomScan(nom) {
    return texteMotsScan(nom).trim().split(' ').filter(m => m.length >= 3 && !MOTS_VIDES_NOM_SCAN.has(m) && !/^\d+$/.test(m));
  }

  // Voie de l'adresse du bien, au format de CLAIRE (« BLOIS (41000), 12 rue des Lilas ») comme au
  // format postal (« 12 rue des Lilas 41000 BLOIS ») : « 12 rue des lilas ». Le script Python
  // fourni gardait ce qui précède le code postal, soit la commune seule sur le format de CLAIRE,
  // et ne reconnaissait donc jamais une adresse. Pure.
  function voieAdresseScan(adresse) {
    const a = String(adresse || '');
    if (!a.trim()) return '';
    let voie = /\(\d{5}\)\s*,\s*(.+)$/.exec(a) ? /\(\d{5}\)\s*,\s*(.+)$/.exec(a)[1] : a.split(/\b\d{5}\b/)[0];
    voie = texteMotsScan(voie).trim();
    return voie.length >= 8 && /[a-z]{3}/.test(voie) ? voie : '';
  }

  // Parcelles du dossier : [{ section: 'ab', numero: '123' }]. Pure.
  function parcellesScan(d) {
    const cad = d && d.bien && d.bien.cadastre;
    return (typeof clesParcelles === 'function' ? clesParcelles(cad) : []).map(c => {
      const [section, numero] = c.split(' ');
      return { section: String(section || '').toLowerCase(), numero: String(numero || '') };
    }).filter(p => /^[a-z]{1,2}$/.test(p.section) && /^\d{1,4}$/.test(p.numero));
  }

  // Personnes du dossier à chercher dans le scan : les parties (et leur nom d'usage), à défaut les
  // deux côtés du nom du dossier (« VENDEUR / ACQUÉREUR »). Pure.
  function personnesDossierScan(d) {
    const parties = Array.isArray(d && d.parties) ? d.parties : [];
    if (parties.length) {
      return parties.map(p => ({ mots: motsNomScan(p.nom), usage: p.nomUsage ? motsNomScan(p.nomUsage) : [], role: p.role, nom: p.nom }))
        .filter(p => p.mots.length);
    }
    return String((d && d.nom) || '').split(/[\/&]|\bet\b/i).map((morceau, i) => ({ mots: motsNomScan(morceau), usage: [], role: i === 0 ? 'VENDEUR' : 'ACQUEREUR', nom: morceau.trim() }))
      .filter(p => p.mots.length);
  }

  // Barème du score de dossier : celui du script Python fourni par l'étude (« j'aimais bien le
  // système de score », 30/09), moins le numéro de dossier que les dossiers clients n'ont pas.
  // Une personne compte si TOUS les mots de son nom figurent dans le scan (deux au plus) ; la voie
  // de l'adresse du bien au format de CLAIRE ; une parcelle (section et numéro rapprochés). Sûr à
  // partir du seuil ET avec une marge sur le deuxième dossier (deux dossiers d'une même famille ne
  // se départagent pas par un seul nom). Modifier ici change le rangement automatique.
  // Seuil abaissé de 6 à 4 par l'étude (30/09) : l'adresse du bien seule, ou une partie nommée avec
  // un autre indice, suffit ; une partie nommée seule (3) reste une suggestion à valider.
  // Affichée sur 6 (étude, 30/09 : « Score 7/4 » ne se lisait pas) : note plafonnée à `noteMax`,
  // seuil lu « 4/6 ». Les comparaisons (seuil, marge sur le suivant) gardent le score brut.
  var BAREME_SCORE_SCAN = { partie: 3, partiesMax: 2, adresse: 4, parcelle: 5, seuil: 4, marge: 1.3, noteMax: 6 };

  // Note affichée d'un score brut : « 6/6 » pour 7 points ou plus. Pure.
  function noteScoreScan(score) {
    const n = Math.max(0, Math.min(BAREME_SCORE_SCAN.noteMax, Number(score) || 0));
    return `${n}/${BAREME_SCORE_SCAN.noteMax}`;
  }

  // Score d'un dossier pour un scan, avec le détail des points (`raisons`, lisibles telles quelles
  // à l'écran : « 2 parties nommées +6 »). Pure.
  function scoreDossierScan(d, mots) {
    const b = BAREME_SCORE_SCAN;
    let score = 0;
    const raisons = [];
    const trouvees = [];
    for (const p of personnesDossierScan(d)) {
      const present = (liste) => liste.length && liste.every(m => mots.includes(' ' + m + ' '));
      // Nom d'usage (« épouse LEROY ») : le nom de naissance peut manquer sur la pièce ; le nom
      // d'usage ET un autre mot du nom (le prénom) suffisent alors.
      const parUsage = present(p.usage) && p.mots.some(m => !p.usage.includes(m) && mots.includes(' ' + m + ' '));
      if (present(p.mots) || parUsage) trouvees.push(p);
    }
    if (trouvees.length) {
      const n = Math.min(trouvees.length, b.partiesMax);
      score += b.partie * n;
      raisons.push(`${n > 1 ? n + ' parties nommées' : '1 partie nommée'} +${b.partie * n}`);
    }
    const voie = voieAdresseScan(d && d.adresseBien);
    if (voie && mots.includes(' ' + voie + ' ')) { score += b.adresse; raisons.push(`adresse du bien +${b.adresse}`); }
    for (const p of parcellesScan(d)) {
      const re = new RegExp(`\\s${p.section}\\s(?:\\S+\\s){0,3}?0*${p.numero}\\s`);
      if (re.test(mots)) { score += b.parcelle; raisons.push(`parcelle ${p.section.toUpperCase()} ${p.numero} +${b.parcelle}`); break; }
    }
    const roles = [...new Set(trouvees.map(p => p.role))];
    return { score, raisons, role: roles.length === 1 ? roles[0] : null, personnes: trouvees.map(p => p.nom) };
  }

  // Le dossier d'un scan parmi `dossiers` (non archivés). `sur` seulement au-dessus du seuil ET
  // nettement devant le deuxième ; sinon le meilleur reste une suggestion à confirmer. Pure.
  function identifierDossierScan(texte, dossiersCandidats) {
    const b = BAREME_SCORE_SCAN;
    const mots = texteMotsScan(texte);
    const classes = (dossiersCandidats || []).filter(d => d && !d.archive)
      .map(d => Object.assign({ dossier: d }, scoreDossierScan(d, mots)))
      .filter(c => c.score > 0)
      .sort((a, b2) => b2.score - a.score);
    if (!classes.length) return { dossier: null, sur: false, score: 0, second: 0, raisons: [], role: null, candidats: [] };
    const [premier, second] = classes;
    const sur = premier.score >= b.seuil && (!second || premier.score >= second.score * b.marge);
    return { dossier: premier.dossier, sur, score: premier.score, second: second ? second.score : 0, raisons: premier.raisons, role: premier.role, personnes: premier.personnes,
      candidats: classes.slice(0, 5).map(c => ({ id: c.dossier.id, score: c.score })) };
  }

  // « Score 6/6 : 2 parties nommées +6, adresse du bien +4 », et ce qui manque quand ce n'est pas
  // sûr (seuil de 4/6 non atteint, ou deuxième dossier trop proche). Pure.
  function explicationScoreScan(p) {
    if (!p || !p.score) return `Aucun dossier reconnu (score 0/${BAREME_SCORE_SCAN.noteMax})`;
    const b = BAREME_SCORE_SCAN;
    const detail = `Score ${noteScoreScan(p.score)} : ${p.raisons.join(', ')}`;
    if (p.score < b.seuil) return `${detail} — sous le seuil de ${noteScoreScan(b.seuil)}`;
    if (p.second && p.score < p.second * b.marge) return `${detail} — un autre dossier est à ${noteScoreScan(p.second)}`;
    return detail;
  }

  // Nom de la copie rangée : le libellé du type (celui de la pièce de la checklist quand il y en
  // a une, que CLAIRE reconnaîtra donc par son nom), la personne pour une pièce d'identité ou
  // d'état civil, puis « - Claire Scan » (étude, 30/09 : ni date ni référence du scan).
  // « Nom (2).pdf » côté serveur si le nom existe déjà. Pure.
  var SUFFIXE_NOM_SCAN = 'Claire Scan';
  function nomCibleScan(type, options) {
    const o = options || {};
    if (!type) return SUFFIXE_NOM_SCAN;
    const personne = type.parPartie && o.personne ? ' - ' + String(o.personne).replace(/\s+/g, ' ').trim() : '';
    return `${type.label}${personne} - ${SUFFIXE_NOM_SCAN}`;
  }

  // Rubriques essayées pour ce type et ce dossier (la partie reconnue décide pour une pièce
  // d'identité, un état civil ou un RIB). Pure.
  function rubriquesScan(type, role) {
    if (!type) return [];
    if (type.parPartie) return role === 'VENDEUR' ? ['vendeur'] : role === 'ACQUEREUR' ? ['acquereur'] : [];
    return type.rubriques.slice();
  }

  // Libellé lisible d'une rubrique proposée (écran « Scans à ranger »). Pure.
  var LIBELLES_RUBRIQUES_SCAN = {
    vendeur: 'Vendeur', acquereur: 'Acquéreur', titre: 'Titre de propriété', diagnostics: 'Diagnostics', environnement: 'Environnement',
    hypotheque: 'Situation hypothécaire', travaux: 'Travaux', construction: 'Construction', sru: 'SRU', aae: 'AAE', copro: 'Copropriété',
    etatDate: 'COPRO › ETAT DATE', preEtatDate: 'COPRO › PRE ETAT DATE', comptabilite: 'Comptabilité', pret: 'Comptabilité › PRET'
  };
  function libelleRubriquesScan(rubriques) {
    return rubriques && rubriques.length ? (LIBELLES_RUBRIQUES_SCAN[rubriques[0]] || rubriques[0]) : 'racine du dossier';
  }

  // Proposition complète pour un scan : dossier, type, nom de la copie, rubriques, et si elle peut
  // être rangée sans intervention (dossier sûr, relié au NAS, et type reconnu). Pure.
  function propositionScan(lecture, dossiersCandidats, dateIso) {
    const texte = (lecture && lecture.texte) || '';
    const type = typePieceScan(enTeteScan((lecture && lecture.page1) || texte));
    const id = identifierDossierScan(texte, dossiersCandidats);
    const d = id.dossier;
    const personne = id.personnes && id.personnes.length === 1 ? id.personnes[0] : '';
    const rubriques = rubriquesScan(type, id.role);
    const relie = !!(d && d.nasDossier);
    return {
      dossierId: d ? d.id : null, dossierSur: id.sur, score: id.score, second: id.second, raisons: id.raisons, candidats: id.candidats,
      type: type ? type.cle : null, rubriques, nomCible: nomCibleScan(type, { date: dateIso, personne }),
      relie, automatique: !!(id.sur && type && relie)
    };
  }
  // --- fin du socle pur des scans ---------------------------------------------------------------

  // ---- Écran « Scans à ranger » et rangement automatique ------------------------------------
  // État en mémoire : la liste du serveur, et pour chaque scan (clé nom + date) sa lecture et la
  // proposition, que l'étude peut corriger avant de ranger. Rien n'est enregistré côté poste.
  // `charge` : faux tant que le serveur n'a pas répondu une première fois — les réglages ne sont alors
  // PAS connus (et non « désactivés ») : l'interrupteur reste grisé plutôt que d'afficher un état faux
  // (étude, 30/09 : « dès que je quitte CLAIRE je suis obligé de recocher »).
  var etatScans = { charge: false, configure: false, raison: '', dossier: '', reglages: { actif: false, auto: false, depuis: null }, scans: [], ecartes: [], journal: [] };
  var lecturesScans = {};           // cle → { statut: 'lecture'|'pret'|'erreur', lecture, proposition, choix }
  var scansEnRangement = new Set();
  // Scans dont le rangement automatique a échoué : jamais retentés seuls (ils attendent un geste).
  var echecsAutoScans = new Set();
  var surveillanceScansLancee = false;
  var DELAI_SURVEILLANCE_SCANS = 2 * 60 * 1000;
  var PAGES_TEXTE_SCAN = 4;
  var PAGES_OCR_SCAN = 2;

  function cleScan(s) { return s.nom + '|' + s.date; }

  // Le rangement automatique se fait dans UNE fenêtre CLAIRE à la fois (c'est elle qui lit et fait
  // l'OCR) : le serveur accorde le relais à une fenêtre, la fenêtre du poste serveur en priorité, et
  // le passe à une autre si elle se tait (voir /api/scans/relais). Identifiant tiré au chargement.
  var fenetreScans = 'f-' + Math.random().toString(36).slice(2, 12) + Date.now().toString(36);
  var relaisScansAccorde = false;
  async function demanderRelaisScans() {
    // Pas de remise à faux AVANT la réponse : une lecture en cours (OCR) testerait le relais pendant
    // l'attente et sauterait le rangement d'un scan pourtant sûr.
    if (!etatScans.reglages.actif || !etatScans.reglages.auto) { relaisScansAccorde = false; return; }
    try {
      const r = await fetchAvecAuth('/api/scans/relais', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ fenetre: fenetreScans }) });
      relaisScansAccorde = r.ok && !!(await r.json()).accorde;
    } catch (e) { relaisScansAccorde = false; }
  }

  function dossiersCandidatsScans() {
    return (dossiers || []).filter(d => d && !d.archive);
  }

  // `fond` : appel de la surveillance (voir demarrerSurveillanceScans) — la lecture des scans (OCR,
  // parfois plusieurs minutes) part sans être attendue, pour que la liste continue d'être relue.
  // Rend vrai quand le dossier du copieur est trouvé et lu.
  async function chargerScans(fond) {
    if (!authToken) return false;
    try {
      const r = await fetchAvecAuth('/api/scans');
      if (!r.ok) return false;
      etatScans = Object.assign(etatScans, await r.json(), { charge: true });
    } catch (e) { return false; }
    majBadgeScans();
    // Carte « Dernières pièces » du tableau de bord : scans à ranger et rangés à jour.
    if (ongletActuel === 'dashboard') {
      try { renderPiecesRecuesDashboard(dossiersDuPerimetre(dossiers, utilisateurPoste, vueGlobaleDashboard()).filter(d => !d.archive)); } catch (e) { /* carte absente */ }
    }
    // Réglages affichés dès la réponse, sans attendre la lecture des scans en attente (OCR : parfois
    // plusieurs minutes, pendant lesquelles l'écran montrait l'interrupteur décoché).
    renderReglagesScans();
    await demanderRelaisScans();
    const presents = new Set((etatScans.scans || []).map(cleScan));
    Object.keys(lecturesScans).forEach(k => { if (!presents.has(k)) delete lecturesScans[k]; });
    const visible = ongletActuel === 'scans';
    if (visible) renderScans();
    if (visible || rangementAutoScansActif()) {
      const lecture = lireScansEnAttente();
      if (fond === true) lecture.catch(e => console.error('Lecture des scans', e)); else await lecture;
    }
    return !!etatScans.configure;
  }

  // Scans qui attendent quelqu'un : tous ceux du dossier Scan, sauf ceux que cette fenêtre est en
  // train de ranger seule (rangement automatique, dossier et pièce sûrs, pas d'échec). Pure.
  function nombreScansEnAttente(etat, lectures, echecs, autoActif) {
    if (!etat || !etat.reglages || !etat.reglages.actif) return 0;
    return (etat.scans || []).filter(s => {
      const l = lectures && lectures[s.nom + '|' + s.date];
      const rangeSeul = autoActif && l && l.statut === 'pret' && l.proposition && l.proposition.automatique && !(echecs && echecs.has(s.nom + '|' + s.date));
      return !rangeSeul;
    }).length;
  }

  // Pastille « Scans à ranger » (étude, 30/09) : le nombre à côté du lien, un point sur l'icône
  // quand la barre est repliée et sur le bouton du menu en largeur téléphone (voir
  // majPastilleMenuMobile).
  function majBadgeScans() {
    const badge = document.getElementById('badge-scans');
    if (!badge) return;
    const n = nombreScansEnAttente(etatScans, lecturesScans, echecsAutoScans, rangementAutoScansActif());
    badge.textContent = n > 99 ? '99+' : String(n);
    // '' et non 'inline-flex' : la barre repliée masque le nombre par sa feuille de style.
    badge.style.display = n ? '' : 'none';
    badge.title = n ? `${n} scan${n > 1 ? 's' : ''} en attente de rangement` : '';
    const lien = document.getElementById('tab-scans');
    if (lien) lien.classList.toggle('a-notif', n > 0);
    majPastilleMenuMobile();
  }

  // Un point sur le bouton du menu (téléphone) dès qu'une pastille de la barre latérale est
  // allumée : sans lui, rien ne se voit tant que le menu est fermé.
  function majPastilleMenuMobile() {
    const burger = document.getElementById('sidebar-burger');
    if (!burger) return;
    burger.classList.toggle('a-notif', !!document.querySelector('.sidebar-link.a-notif, #tab-scans.a-notif'));
  }

  // Surveillance de fond, lancée au démarrage sans rien ouvrir (étude, 30/09 : « obligé d'aller dans
  // les réglages pour que le scan se relie au dossier Scan ») : toutes les 2 minutes une fois le
  // dossier du copieur trouvé ; tant qu'il ne l'est pas (partage réseau pas encore joignable au
  // démarrage du poste, serveur qui redémarre), nouvel essai toutes les 20 secondes.
  var DELAI_REESSAI_SCANS = 20 * 1000;
  function demarrerSurveillanceScans() {
    if (surveillanceScansLancee) return;
    surveillanceScansLancee = true;
    const tour = async () => {
      let relie = false;
      try { relie = await chargerScans(true); } catch (e) { relie = false; }
      setTimeout(tour, relie ? DELAI_SURVEILLANCE_SCANS : DELAI_REESSAI_SCANS);
    };
    tour();
  }

  // Lit un scan : texte de page 1 à part (le type s'y lit), texte des premières pages (le dossier),
  // OCR des deux premières pages si le PDF n'a pas de texte.
  async function lireScan(scan) {
    if (typeof pdfjsLib === 'undefined') throw new Error('Lecteur PDF indisponible');
    const r = await fetchAvecAuth('/api/scans/fichier?nom=' + encodeURIComponent(scan.nom));
    if (!r.ok) throw new Error('Scan introuvable');
    const pdf = await pdfjsLib.getDocument({ data: await r.arrayBuffer() }).promise;
    const pages = [];
    for (let p = 1; p <= Math.min(pdf.numPages, PAGES_TEXTE_SCAN); p++) {
      const page = await pdf.getPage(p);
      pages.push(lignesDepuisItemsPdf((await page.getTextContent()).items).join('\n'));
    }
    let viaOcr = false;
    if (pages.join('').trim().length < 40) {
      const worker = await creerWorkerOcr();
      if (!worker) throw new Error('OCR indisponible');
      try {
        pages.length = 0;
        for (let p = 1; p <= Math.min(pdf.numPages, PAGES_OCR_SCAN); p++) pages.push(await ocrPage(pdf, p, worker));
        viaOcr = true;
      } finally {
        await worker.terminate();
      }
    }
    return { page1: pages[0] || '', texte: pages.join('\n'), pages: pdf.numPages, viaOcr };
  }

  // Lit les scans pas encore lus, un par un (l'OCR est lourd), et range ceux qui sont sûrs quand
  // le rangement automatique est actif sur ce poste. Le réglage est relu à CHAQUE scan : activé
  // pendant une lecture, il vaut pour la suite sans attendre le tour suivant. Un appel reçu pendant
  // une lecture relance un passage à la fin plutôt que d'être perdu.
  var lectureScansEnCours = false;
  var relancerLectureScans = false;
  function rangementAutoScansActif() {
    return !!(etatScans.reglages.actif && etatScans.reglages.auto && relaisScansAccorde);
  }
  async function lireScansEnAttente() {
    if (lectureScansEnCours) { relancerLectureScans = true; return; }
    lectureScansEnCours = true;
    relancerLectureScans = false;
    try {
      for (const scan of (etatScans.scans || []).slice()) {
        if (!scan.stable) continue;
        const cle = cleScan(scan);
        if (!lecturesScans[cle]) {
          lecturesScans[cle] = { statut: 'lecture' };
          if (ongletActuel === 'scans') renderScans();
          try {
            const debutLecture = Date.now();
            const lecture = await lireScan(scan);
            const proposition = propositionScan(lecture, dossiersCandidatsScans(), scan.date);
            noterJournalTechnique({ categorie: 'scan-lu', dureeMs: Date.now() - debutLecture, ocr: !!lecture.viaOcr, reconnu: !!(proposition && proposition.type), sur: !!(proposition && proposition.automatique), type: (proposition && proposition.type) || '' });
            lecturesScans[cle] = { statut: 'pret', lecture: { viaOcr: lecture.viaOcr, pages: lecture.pages, texte: lecture.texte }, proposition, choix: choixDepuisProposition(proposition) };
          } catch (e) {
            lecturesScans[cle] = { statut: 'erreur', erreur: e.message || 'Lecture impossible', choix: choixDepuisProposition(null, scan.date) };
          }
          if (ongletActuel === 'scans') renderScans();
          majBadgeScans();
        }
        const l = lecturesScans[cle];
        if (rangementAutoScansActif() && l && l.statut === 'pret' && l.proposition.automatique && !echecsAutoScans.has(cle)) await rangerScanChoisi(scan.nom, true);
      }
    } finally {
      lectureScansEnCours = false;
    }
    if (relancerLectureScans) { relancerLectureScans = false; await lireScansEnAttente(); }
  }

  // Ce que l'étude valide : dossier, type, nom de la copie (les rubriques suivent le type).
  function choixDepuisProposition(p, date) {
    if (!p) return { dossierId: '', type: '', nomCible: nomCibleScan(null, { date }), rubriques: [] };
    return { dossierId: p.dossierId || '', type: p.type || '', nomCible: p.nomCible, rubriques: p.rubriques.slice() };
  }

  function scanParNom(nom) { return (etatScans.scans || []).find(s => s.nom === nom) || null; }

  function changerChoixScan(nom, champ, valeur) {
    const scan = scanParNom(nom);
    if (!scan) return;
    const l = lecturesScans[cleScan(scan)];
    if (!l || !l.choix) return;
    l.choix[champ] = valeur;
    if (champ === 'type' || champ === 'dossierId') {
      // Le type ou la personne changent le nom proposé et la rubrique ; un nom retouché à la main
      // est gardé tant que ni l'un ni l'autre ne bouge.
      const type = TYPES_SCAN.find(t => t.cle === l.choix.type) || null;
      const d = (dossiers || []).find(x => x.id === l.choix.dossierId);
      const id = d ? scoreDossierScan(d, texteMotsScan((l.lecture && l.lecture.texte) || '')) : null;
      l.choix.rubriques = rubriquesScan(type, id ? id.role : null);
      l.choix.nomCible = nomCibleScan(type, { date: scan.date, personne: id && id.personnes.length === 1 ? id.personnes[0] : '' });
    }
    renderScans();
  }

  async function rangerScanChoisi(nom, auto) {
    const scan = scanParNom(nom);
    if (!scan || scansEnRangement.has(nom)) return;
    const l = lecturesScans[cleScan(scan)];
    const choix = l && l.choix;
    const d = choix && (dossiers || []).find(x => x.id === choix.dossierId);
    if (!d || !d.nasDossier) { if (auto) echecsAutoScans.add(cleScan(scan)); }
    if (!d) { if (!auto) afficherToast('Choisissez le dossier client avant de ranger ce scan.', 'OK', null); return; }
    if (!d.nasDossier) { if (!auto) afficherToast('Ce dossier n’est pas relié à son dossier du NAS : reliez-le depuis sa fiche.', 'OK', null); return; }
    scansEnRangement.add(nom);
    if (!auto) renderScans();
    try {
      const r = await fetchAvecAuth('/api/scans/ranger', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nom, dossierNas: d.nasDossier, rubriques: choix.rubriques, nomCible: choix.nomCible,
          dossierId: d.id, dossier: libelleDossierAffiche(d), type: choix.type, auteur: auto ? 'CLAIRE' : (utilisateurPoste || ''), auto: !!auto,
          score: l && l.proposition && l.proposition.dossierId === d.id ? l.proposition.score : null })
      });
      const corps = await r.json().catch(() => ({}));
      if (!r.ok) {
        if (auto) echecsAutoScans.add(cleScan(scan));
        else afficherToast(corps.erreur || 'Rangement impossible.', 'OK', null);
        return;
      }
      if (!auto) afficherToast(`Rangé dans ${libelleDossierAffiche(d)}${corps.rubrique ? ' › ' + corps.rubrique.replace(/[\\/]+/g, ' › ') : ''}.`, 'OK', null);
      // Pièce ajoutée/cochée et responsable prévenu tout de suite, sans attendre le parcours du NAS
      // (relancé ensuite pour le reste : il ne renotifie pas une pièce déjà « reçue »).
      try { await enregistrerPieceRangee(d, choix, corps, auto); } catch (e) { console.warn('Pièce rangée non enregistrée :', e.message); }
      if (typeof verifierDossierLocal === 'function') verifierDossierLocal(d.id, false).catch(() => {});
    } finally {
      scansEnRangement.delete(nom);
      await chargerScans();
    }
  }

  // Types rangés qui ne sont pas des « pièces » du dossier : l'offre de prêt et l'avant-contrat ont
  // leurs propres règles (reconnus par leur nom au parcours du NAS, qui notifie l'offre lui-même).
  var TYPES_SCAN_HORS_PIECES = ['offrePret', 'avantContrat', 'promesse'];

  // Pièce du dossier que représente un scan qu'on vient de ranger (étude, 30/09 : « la rajouter à la
  // liste des pièces et la noter cochée ») : la pièce de la checklist de ce type si elle y figure,
  // sinon une pièce personnalisée du même libellé (reprise si elle existe déjà, créée sinon). Le
  // libellé est le nom de la copie sans « - Claire Scan ». null pour l'offre et l'avant-contrat.
  // Pure.
  function pieceDepuisScanRange(d, typeCle, nomCible, checklist, maintenantIso) {
    if (TYPES_SCAN_HORS_PIECES.includes(typeCle)) return null;
    const type = TYPES_SCAN.find(t => t.cle === typeCle) || null;
    const liste = checklist || [];
    if (type && type.piece) {
      const piece = liste.find(p => p.cle === type.piece);
      if (piece) return { cle: piece.cle, label: piece.label, nouvelle: false };
    }
    const suffixe = new RegExp('\\s*-?\\s*' + SUFFIXE_NOM_SCAN + '$', 'i');
    let label = String(nomCible || '').replace(/\.pdf$/i, '').replace(suffixe, '').trim();
    if (!label) label = type ? type.label : `Scan du ${formatDateFr(String(maintenantIso || '').slice(0, 10))}`;
    const cleLabel = normaliserPourRecherche(label);
    const existante = (d && d.piecesPersonnalisees || []).find(p => normaliserPourRecherche(p.label) === cleLabel)
      || liste.find(p => normaliserPourRecherche(p.label) === cleLabel);
    if (existante) return { cle: existante.cle, label: existante.label, nouvelle: false };
    return { cle: 'perso-scan-' + String(Date.parse(maintenantIso) || Date.now()).slice(-8) + Math.random().toString(36).slice(2, 5), label, nouvelle: true };
  }

  // Après un rangement (à la main ou automatique) : la pièce est ajoutée si besoin, cochée, son
  // fichier mémorisé, et le responsable prévenu (Teams, comme une pièce trouvée sur le NAS).
  async function enregistrerPieceRangee(d, choix, corps, auto) {
    const maintenant = new Date().toISOString();
    const piece = pieceDepuisScanRange(d, choix.type, choix.nomCible, checklistPieces(d.typeVente, d), maintenant);
    if (!piece) return;
    if (piece.nouvelle) {
      d.piecesPersonnalisees = d.piecesPersonnalisees || [];
      d.piecesPersonnalisees.push({ cle: piece.cle, label: piece.label });
    }
    d.pieces = d.pieces || {};
    d.pieces[piece.cle] = 'recue';
    if (corps && corps.chemin) memoriserFichierTrouve(d, NAS_CLE_PIECE(piece.cle), String(corps.chemin).replace(/\\/g, '/'));
    // Une pièce ajoutée pour ce scan n'a pas de motif de nom : sans ce drapeau, un parcours du NAS
    // qui ne la retrouverait pas la repasserait « manquante ».
    if (piece.nouvelle || !checklistPieces(d.typeVente).some(p => p.cle === piece.cle)) {
      d.piecesValideesManuellement = Array.from(new Set([...(d.piecesValideesManuellement || []), piece.cle]));
    }
    d.piecesTrouveesLe = Object.assign({}, d.piecesTrouveesLe, { [piece.cle]: maintenant });
    d.piecesNotifications = Array.from(new Set([...(d.piecesNotifications || []), piece.cle]));
    ajouterHistorique(d, `Scan rangé ${auto ? 'automatiquement' : 'à la main'} : « ${piece.label} »${piece.nouvelle ? ' ajoutée à la liste des pièces' : ''}, reçue`);
    await sauvegarder(d);
    render();
    notifierNouvellesPiecesTrouvees(d, [piece.cle]);
    notifierNavigateurPieces(d, [piece.cle]);
    signalerSiDossierDevenuComplet(d);
  }

  async function ecarterScan(nom) {
    await fetchAvecAuth('/api/scans/ecarter', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ nom, auteur: utilisateurPoste || '' }) });
    await chargerScans();
  }

  async function retablirScan(nom) {
    await fetchAvecAuth('/api/scans/retablir', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ nom }) });
    await chargerScans();
  }

  async function ouvrirScan(nom) {
    const fenetre = window.open('', '_blank');
    try {
      const r = await fetchAvecAuth('/api/scans/fichier?nom=' + encodeURIComponent(nom));
      if (!r.ok) throw new Error();
      const url = URL.createObjectURL(await r.blob());
      if (fenetre) fenetre.location.href = url; else window.open(url, '_blank');
    } catch (e) {
      if (fenetre) fenetre.close();
      afficherToast('Ce scan n’est plus dans le dossier Scan.', 'OK', null);
    }
  }

  async function enregistrerReglagesScans(modif) {
    const r = await fetchAvecAuth('/api/scans/reglages', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(modif) });
    if (r.ok) etatScans.reglages = (await r.json()).reglages;
    renderReglagesScans();
    await chargerScans();
  }

  // Date locale (AAAA-MM-JJ) du point de départ des scans, pour le champ date des réglages.
  function dateLocaleDepuisScans(depuis) {
    if (!depuis) return '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(depuis)) return depuis;
    const d = new Date(depuis);
    return isNaN(d) ? '' : `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  }

  function renderReglagesScans() {
    const zone = document.getElementById('reglages-scans');
    if (!zone) return;
    const r = etatScans.reglages || {};
    const inconnu = !etatScans.charge;
    const etat = inconnu ? 'Lecture des réglages sur le serveur…'
      : etatScans.configure
        ? `Dossier du copieur : <strong>${escapeHtml(etatScans.dossier)}</strong>`
        : `${icone('alert-triangle')} ${escapeHtml(etatScans.raison || 'Dossier « Scan » introuvable.')}`;
    zone.innerHTML = `
      <div class="reglages-liste">
        <label class="reglages-option" for="reglages-scans-actif">
          <span class="reglages-option-texte"><span class="reglages-option-titre">Activer Claire Scan ${infoBulle('CLAIRE lit chaque scan posé dans le dossier « Scan », reconnaît le dossier client et la pièce, puis range une copie dans la rubrique du dossier. L’original est conservé dans « CLAIRE - scans rangés », à l’intérieur du dossier Scan.')}</span>
            <span class="hint">${etat}</span></span>
          <span class="switch reglages-switch"><input type="checkbox" id="reglages-scans-actif"${r.actif ? ' checked' : ''}${inconnu ? ' disabled' : ''} onchange="enregistrerReglagesScans({ actif: this.checked })"><span class="slider"></span></span>
        </label>
        <label class="reglages-option" for="reglages-scans-auto">
          <span class="reglages-option-texte"><span class="reglages-option-titre">Ranger automatiquement les scans reconnus ${infoBulle(`Sans validation, dès que la pièce est identifiée et que le dossier atteint le score de ${noteScoreScan(BAREME_SCORE_SCAN.seuil)} avec une marge sur le suivant : partie nommée ${BAREME_SCORE_SCAN.partie} points (deux au plus), adresse du bien ${BAREME_SCORE_SCAN.adresse}, parcelle ${BAREME_SCORE_SCAN.parcelle}. Il suffit qu’une fenêtre CLAIRE soit ouverte au bureau (celle du poste serveur en priorité). Les autres scans attendent dans Claire Scan.`)}</span></span>
          <span class="switch reglages-switch"><input type="checkbox" id="reglages-scans-auto"${r.auto ? ' checked' : ''}${r.actif && !inconnu ? '' : ' disabled'} onchange="enregistrerReglagesScans({ auto: this.checked })"><span class="slider"></span></span>
        </label>
        <label class="reglages-option" for="reglages-scans-depuis">
          <span class="reglages-option-texte"><span class="reglages-option-titre">Nouveaux scans à partir du ${infoBulle('Seuls les scans arrivés après ce moment sont traités (à l’activation : l’heure exacte). Les plus anciens restent dans le dossier Scan sans être touchés. Choisir une date plus ancienne pour reprendre des scans déjà présents.')}</span>
            ${r.depuis && r.depuis.length > 10 ? `<span class="hint">${escapeHtml(new Date(r.depuis).toLocaleString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' }))}</span>` : ''}</span>
          <input type="date" id="reglages-scans-depuis" value="${escapeAttr(dateLocaleDepuisScans(r.depuis))}"${r.actif && !inconnu ? '' : ' disabled'} onchange="enregistrerReglagesScans({ depuis: this.value })">
        </label>
      </div>`;
  }

  function optionsDossiersScan(choisi, proposition) {
    const candidats = dossiersCandidatsScans().slice().sort((a, b) => libelleDossierAffiche(a).localeCompare(libelleDossierAffiche(b), 'fr'));
    const scores = new Map(((proposition && proposition.candidats) || []).map(c => [c.id, c.score]));
    const suggeres = candidats.filter(d => scores.has(d.id)).sort((a, b) => scores.get(b.id) - scores.get(a.id));
    const autres = candidats.filter(d => !scores.has(d.id));
    const opt = d => `<option value="${escapeAttr(d.id)}"${d.id === choisi ? ' selected' : ''}>${escapeHtml(libelleDossierAffiche(d))}${scores.has(d.id) ? ` — score ${noteScoreScan(scores.get(d.id))}` : ''}${d.nasDossier ? '' : ' (non relié au NAS)'}</option>`;
    return `<option value=""${choisi ? '' : ' selected'}>Choisir le dossier…</option>`
      + (suggeres.length ? `<optgroup label="Reconnus dans le scan">${suggeres.map(opt).join('')}</optgroup>` : '')
      + `<optgroup label="Tous les dossiers">${autres.map(opt).join('')}</optgroup>`;
  }

  function optionsTypesScan(choisi) {
    return `<option value=""${choisi ? '' : ' selected'}>Autre pièce</option>`
      + TYPES_SCAN.map(t => `<option value="${escapeAttr(t.cle)}"${t.cle === choisi ? ' selected' : ''}>${escapeHtml(t.label)}</option>`).join('');
  }

  function renderLigneScan(scan) {
    const l = lecturesScans[cleScan(scan)] || null;
    const nomArg = escapeOnclickArg(scan.nom);
    const quand = new Date(scan.date).toLocaleString('fr-FR', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
    const tete = `<div class="scan-tete">
        <button type="button" class="scan-nom" onclick="ouvrirScan('${nomArg}')" title="Ouvrir le scan">${icone('file-text')}<span>${escapeHtml(scan.nom)}</span></button>
        <span class="scan-date">${escapeHtml(quand)}</span>
      </div>`;
    if (!scan.stable || !l || l.statut === 'lecture') {
      return `<li class="scan-ligne">${tete}<p class="hint scan-etat">${icone('spinner', null, true)} ${scan.stable ? 'Lecture du scan…' : 'Copie en cours depuis le copieur…'}</p></li>`;
    }
    const c = l.choix;
    const p = l.proposition;
    const enCours = scansEnRangement.has(scan.nom);
    let statut;
    if (l.statut === 'erreur') statut = `<span class="dot-label dl-urgent"><span class="dot"></span>${escapeHtml(l.erreur)}</span>`;
    else if (p.automatique) statut = `<span class="dot-label dl-success"><span class="dot"></span>Reconnu, rangement automatique</span>`;
    else if (p.dossierId && !p.dossierSur) statut = `<span class="dot-label dl-pret"><span class="dot"></span>Dossier à confirmer</span>`;
    else if (p.dossierId && !p.relie) statut = `<span class="dot-label dl-pret"><span class="dot"></span>Dossier non relié au NAS</span>`;
    else if (p.dossierId && !p.type) statut = `<span class="dot-label dl-pret"><span class="dot"></span>Pièce à préciser</span>`;
    else statut = `<span class="dot-label dl-neutre"><span class="dot"></span>Dossier non reconnu</span>`;
    if (l.statut !== 'erreur') statut += `<span class="scan-score">${escapeHtml(explicationScoreScan(p))}${l.lecture && l.lecture.viaOcr ? ' · texte lu par OCR' : ''}</span>`;
    return `<li class="scan-ligne">${tete}
      <div class="scan-statut">${statut}</div>
      <div class="scan-champs">
        <label class="scan-champ"><span>Dossier</span><select onchange="changerChoixScan('${nomArg}', 'dossierId', this.value)">${optionsDossiersScan(c.dossierId, p)}</select></label>
        <label class="scan-champ"><span>Pièce</span><select onchange="changerChoixScan('${nomArg}', 'type', this.value)">${optionsTypesScan(c.type)}</select></label>
        <label class="scan-champ scan-champ-large"><span>Nom de la copie</span><input type="text" value="${escapeAttr(c.nomCible)}" oninput="changerChoixScan('${nomArg}', 'nomCible', this.value)" onchange="renderScans()"></label>
      </div>
      <div class="scan-actions">
        <span class="hint">Rubrique : ${escapeHtml(libelleRubriquesScan(c.rubriques))}</span>
        <button type="button" class="secondary" onclick="ecarterScan('${nomArg}')">Laisser dans Scan</button>
        <button type="button" class="primary" onclick="rangerScanChoisi('${nomArg}', false)"${enCours || !c.dossierId ? ' disabled' : ''}>${enCours ? 'Rangement…' : 'Ranger'}</button>
      </div>
    </li>`;
  }

  function renderScans() {
    const zone = document.getElementById('scans-contenu');
    if (!zone) return;
    // Ne pas redessiner sous les doigts de quelqu'un qui tape le nom de la copie.
    if (document.activeElement && zone.contains(document.activeElement) && document.activeElement.tagName === 'INPUT') return;
    const e = etatScans;
    if (!e.configure || !e.reglages.actif) {
      zone.innerHTML = `<div class="calc-card scans-vide">
        <p>${e.configure ? 'Claire Scan n’est pas activé.' : escapeHtml(e.raison || 'Dossier « Scan » introuvable.')}</p>
        ${e.configure ? `<button type="button" class="primary" onclick="enregistrerReglagesScans({ actif: true })">Activer Claire Scan</button>` : ''}
      </div>`;
      return;
    }
    const scans = e.scans || [];
    const liste = scans.length
      ? `<ul class="scans-liste">${scans.map(renderLigneScan).join('')}</ul>`
      : `<p class="hint scans-rien">Aucun scan en attente dans le dossier du copieur.</p>`;
    const journal = (e.journal || []).slice(0, 12);
    const journalHtml = journal.length ? `<div class="calc-card scans-journal">
        <div class="dash-section-titre">Derniers rangements</div>
        <ul>${journal.map(j => `<li><span class="scan-date">${escapeHtml(new Date(j.date).toLocaleString('fr-FR', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }))}</span>
          <span>${escapeHtml(j.nom)} → <strong>${escapeHtml(j.dossier ? libelleDossierParNom(j.dossier, j.dossierId) : '')}</strong>${j.rubrique ? ' › ' + escapeHtml(j.rubrique.replace(/[\\/]+/g, ' › ')) : ''}</span>
          <span class="hint">${j.auto ? 'automatique' : escapeHtml(j.auteur || '')}${j.score != null ? ' · score ' + noteScoreScan(j.score) : ''}</span></li>`).join('')}</ul>
      </div>` : '';
    const ecartes = (e.ecartes || []);
    const ecartesHtml = ecartes.length ? `<details class="scans-ecartes"><summary>Laissés dans Scan (${ecartes.length})</summary>
        <ul>${ecartes.map(s => `<li><span>${escapeHtml(s.nom)}</span><button type="button" class="lien-action" onclick="retablirScan('${escapeOnclickArg(s.nom)}')">Reproposer</button></li>`).join('')}</ul>
      </details>` : '';
    zone.innerHTML = `<div class="calc-card">${liste}${ecartesHtml}</div>${journalHtml}`;
  }

  function initScans() {
    renderScans();
    chargerScans();
  }

  // Remplit les emplacements d'icônes du HTML statique (sidebar, burger mobile, dropzone) — le
  // reste de l'application est déjà rendu depuis script.js, ce point d'entrée unique évite de
  // dupliquer le dessin des icônes entre le HTML et ICONES.
  function initIconesStatiques() {
    const cibles = {
      'icon-burger': 'menu',
      'icon-nav-dashboard': 'layout',
      'icon-nav-suivi': 'list',
      'icon-recherche-suivi': 'search',
      'icon-nav-scans': 'bannette',
      'icon-nav-agenda': 'calendar',
      'icon-signaler': 'flag',
      'icon-install': 'download',
      'icon-dropzone': 'upload',
      'icon-intro-dates': 'calendar',
      'icon-intro-doc': 'file-text',
      'icon-intro-pieces': 'folder',
      'icon-intro-mail': 'mail',
      'icon-intro-adresse': 'map-pin',
      'icon-nav-calculateur': 'banknote',
      'icon-nav-prorata': 'part-disque',
      'icon-nav-appel-fonds': 'mail',
      'icon-nav-inventaire': 'scale',
      'icon-af-dropzone': 'upload',
      'icon-reglages-apropos': 'info',
      'icon-nav-quotites': 'users',
      'icon-nav-confreres': 'book',
      'icon-calc-warning': 'alert-triangle',
      'icon-inv-warning': 'alert-triangle',
      'icon-nav-analyse-ia': 'eye',
      'icon-analyse-ia-warning': 'alert-triangle',
      'icon-analyse-ia-dropzone': 'upload',
      'icon-relecture-cadre': 'shield',
      'icon-pdf-recherche': 'search',
      'icon-pdf-recherche-prec': 'chevron-up',
      'icon-pdf-recherche-suiv': 'chevron-down',
      'icon-nav-reglages': 'settings',
      'icon-nav-outils-groupe': 'package'
    };
    for (const [id, nom] of Object.entries(cibles)) {
      const el = document.getElementById(id);
      if (el) el.innerHTML = icone(nom);
    }
  }
  initIconesStatiques();
  // État initial de la sidebar (réduite/épinglée/groupe Outils) — pose aussi l'icône du chevron
  // de repli, qu'initIconesStatiques() ne gère pas puisqu'elle change selon l'état.
  appliquerEtatSidebar();
  initSidebarRepliee();
  initCalculateurFraisActe();
  initSelectDepartementAppelFonds();

  chargerTheme();
  chargerAccent();
  chargerApprentissage();
  chargerJournalCorrections();
  chargerMemoireAudit();
  chargerRubriquesMasquees();
  // Mode serveur intranet (voir CLAUDE.md) : l'application entière est bloquée par l'écran de
  // connexion tant que le mot de passe partagé n'a pas été validé — un jeton déjà mémorisé
  // (localStorage, valable 12h côté serveur) permet de sauter cette étape au rechargement.
  // demarrerApplication() gère elle-même le cas d'un jeton devenu invalide (401 → fetchAvecAuth
  // réaffiche l'écran de connexion), pas la peine de le vérifier au préalable ici.
  // Accès sans mot de passe (demandé par l'étude, 25/09) : le serveur délivre un jeton à tout
  // poste du bureau (voir server/src/auth.js, option `desactivee`). Sans jeton mémorisé, on le
  // demande donc tout seul ; l'écran de connexion ne s'affiche que si le serveur exige encore un
  // mot de passe ("authActive": true dans config.json).
  authToken = chargerJetonStocke();
  if (authToken) {
    demarrerApplication().catch((e) => console.error('Démarrage impossible', e));
  } else {
    connexionAutomatique();
  }
  renderChips();
  // L'analyse juridique est une étape du wizard toujours visible (voir definirEtapeWizard) : sans
  // cet appel initial, ses sections restaient affichées vides (ni contenu ni message d'état) tant
  // qu'aucun PDF n'avait encore été importé dans la session.
  afficherAnalyseJuridique();
